import React, { useState } from 'react';
import { Car, MapPin, ChevronDown, ChevronUp, Wrench, Archive } from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';
import { Veiculo, Colaborador } from '../types';
import { VehicleTopView } from './VehicleTopView';

interface VehicleCardGridProps {
  veiculos: Veiculo[];
  filtroRegional?: 'todas' | 'ribas' | 'agua_clara';
  onColaboradorClick?: (colaborador: Colaborador, veiculoId: string) => void;
}

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

const statusVeiculoConfig: Record<string, { label: string; color: string; icon: React.ElementType }> = {
  ativo: { label: 'Ativo', color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/30', icon: Car },
  manutencao: { label: 'Manutenção', color: 'text-amber-400 bg-amber-500/10 border-amber-500/30', icon: Wrench },
  reserva: { label: 'Reserva', color: 'text-sky-400 bg-sky-500/10 border-sky-500/30', icon: Archive },
};

const regionalColors: Record<string, string> = {
  ribas: 'text-sky-400 bg-sky-500/10 border-sky-500/30',
  agua_clara: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/30',
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos,
  filtroRegional = 'todas',
  onColaboradorClick,
}) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const veiculosFiltrados = (veiculos || []).filter((v) => {
    if (!v) return false;
    if (filtroRegional === 'todas') return true;
    return v.regional === filtroRegional;
  });

  if (veiculosFiltrados.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-center">
        <Car className="w-12 h-12 text-muted-foreground/30 mb-4" />
        <p className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</p>
        <p className="text-xs text-muted-foreground mt-1">
          {filtroRegional !== 'todas'
            ? `Não há veículos cadastrados para ${regionalLabel[filtroRegional] ?? filtroRegional}`
            : 'Nenhum veículo cadastrado'}
        </p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-5">
      {veiculosFiltrados.map((veiculo) => {
        const isExpanded = expandedId === veiculo.id;
        const svConfig = statusVeiculoConfig[veiculo.statusOperacional] ?? statusVeiculoConfig.ativo;
        const SvIcon = svConfig.icon;
        const regColor = regionalColors[veiculo.regional] ?? '';

        const assentos = [
          veiculo.assentos?.motorista,
          veiculo.assentos?.frenteDir,
          veiculo.assentos?.trasEsq,
          veiculo.assentos?.trasDir,
        ].filter(Boolean);

        const presentes = assentos.filter((c) => c?.status === 'presente').length;
        const faltas = assentos.filter((c) => c?.status === 'falta').length;
        const substitutos = assentos.filter((c) => c?.status === 'substituto').length;

        return (
          <Card
            key={veiculo.id}
            className="border-border/60 hover:border-primary/30 transition-all hover:shadow-2xl group overflow-hidden"
          >
            {/* Header do Card */}
            <div className="px-4 pt-4 pb-3 border-b border-border/40 bg-gradient-to-r from-muted/30 to-transparent">
              <div className="flex items-start justify-between gap-2">
                <div className="flex items-center gap-2.5 min-w-0">
                  <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
                    <Car className="w-4 h-4 text-primary" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-extrabold text-foreground truncate">{veiculo.prefixo}</p>
                    <p className="text-[10px] text-muted-foreground">{veiculo.placa} · {veiculo.modelo}</p>
                  </div>
                </div>
                <div className="flex flex-col items-end gap-1 shrink-0">
                  <span className={cn('inline-flex items-center gap-1 px-2 py-0.5 rounded-full border text-[10px] font-semibold', svConfig.color)}>
                    <SvIcon className="w-3 h-3" />
                    {svConfig.label}
                  </span>
                  <span className={cn('inline-flex items-center gap-1 px-2 py-0.5 rounded-full border text-[10px] font-semibold', regColor)}>
                    <MapPin className="w-2.5 h-2.5" />
                    {regionalLabel[veiculo.regional] ?? veiculo.regional}
                  </span>
                </div>
              </div>

              {/* Mini stats de presença */}
              <div className="flex items-center gap-2 mt-3">
                <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-500/10 border border-emerald-500/20">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                  <span className="text-[10px] font-semibold text-emerald-400">{presentes} pres.</span>
                </div>
                {faltas > 0 && (
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-rose-500/10 border border-rose-500/20">
                    <span className="w-1.5 h-1.5 rounded-full bg-rose-400" />
                    <span className="text-[10px] font-semibold text-rose-400">{faltas} falta{faltas > 1 ? 's' : ''}</span>
                  </div>
                )}
                {substitutos > 0 && (
                  <div className="flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/10 border border-amber-500/20">
                    <span className="w-1.5 h-1.5 rounded-full bg-amber-400" />
                    <span className="text-[10px] font-semibold text-amber-400">{substitutos} sub.</span>
                  </div>
                )}
              </div>
            </div>

            {/* Vista Top do Veículo */}
            <CardContent className="p-3">
              <VehicleTopView
                motorista={veiculo.assentos.motorista}
                frenteDir={veiculo.assentos.frenteDir}
                trasEsq={veiculo.assentos.trasEsq}
                trasDir={veiculo.assentos.trasDir}
                onSeatClick={(colab) => onColaboradorClick?.(colab, veiculo.id)}
                prefixo={veiculo.prefixo}
              />
            </CardContent>

            {/* Footer expansível: equipes */}
            <div className="border-t border-border/40">
              <button
                onClick={() => setExpandedId(isExpanded ? null : veiculo.id)}
                className="w-full flex items-center justify-between px-4 py-2.5 text-xs font-semibold text-muted-foreground hover:text-foreground hover:bg-muted/30 transition-all"
              >
                <span className="flex items-center gap-1.5">
                  <span className="font-bold text-foreground">{veiculo.equipe1Codigo}</span>
                  <span className="text-muted-foreground/50">·</span>
                  <span className="font-bold text-foreground">{veiculo.equipe2Codigo}</span>
                </span>
                {isExpanded ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
              </button>

              {isExpanded && (
                <div className="px-4 pb-4 pt-1 space-y-2 border-t border-border/30">
                  {[
                    { codigo: veiculo.equipe1Codigo, membros: [veiculo.assentos?.motorista, veiculo.assentos?.frenteDir].filter(Boolean), num: 1 },
                    { codigo: veiculo.equipe2Codigo, membros: [veiculo.assentos?.trasEsq, veiculo.assentos?.trasDir].filter(Boolean), num: 2 },
                  ].map((eq) => (
                    <div key={eq.codigo} className="rounded-xl border border-border/40 bg-muted/20 p-3">
                      <div className="flex items-center gap-2 mb-2">
                        <span className="text-[10px] font-bold text-primary bg-primary/10 border border-primary/20 px-2 py-0.5 rounded-full">
                          Equipe {eq.num}
                        </span>
                        <span className="text-xs font-semibold text-foreground">{eq.codigo}</span>
                      </div>
                      <div className="space-y-1.5">
                        {eq.membros.map((m) => m && (
                          <div key={m.id} className="flex items-center gap-2">
                            <div className="w-6 h-6 rounded-full overflow-hidden border border-border/60 shrink-0 bg-muted">
                              {m.foto ? (
                                <img src={m.foto} alt={m.nome} className="w-full h-full object-cover" />
                              ) : (
                                <div className="w-full h-full flex items-center justify-center text-[9px] font-bold text-muted-foreground">
                                  {m.nome?.charAt(0)}
                                </div>
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-[11px] font-semibold text-foreground truncate">{m.nome}</p>
                              <p className="text-[9px] text-muted-foreground truncate">{m.cargo}</p>
                            </div>
                            <span className={cn(
                              'text-[9px] font-bold px-1.5 py-0.5 rounded-full border',
                              m.status === 'presente' ? 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' :
                              m.status === 'falta' ? 'text-rose-400 bg-rose-500/10 border-rose-500/20' :
                              'text-amber-400 bg-amber-500/10 border-amber-500/20'
                            )}>
                              {m.status === 'presente' ? 'Pres.' : m.status === 'falta' ? 'Falta' : 'Sub.'}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </Card>
        );
      })}
    </div>
  );
};

