import React, { useState, useMemo } from 'react';
import { Users, Search, Plus, Filter, AlertCircle, CheckCircle2, ShieldAlert, Sparkles, UserPlus } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Veiculo, Colaborador } from '../types';

interface TeamsManagementProps {
  veiculos: Veiculo[];
  onSelectColaborador: (colaborador: Colaborador, veiculoId: string) => void;
  onNovaEquipeClick?: () => void;
}

interface EquipeCardData {
  id: string;
  codigo: string;
  numero: 1 | 2;
  veiculoId: string;
  veiculoPrefixo: string;
  veiculoPlaca: string;
  veiculoModelo: string;
  regional: 'ribas' | 'agua_clara';
  lider: Colaborador;
  ajudante: Colaborador;
  status: 'completa' | 'incompleta' | 'critica';
}

const statusConfig = {
  completa: {
    label: 'Equipe Completa',
    badgeClass: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    icon: CheckCircle2,
    iconColor: 'text-emerald-400',
    borderClass: 'border-emerald-500/20 hover:border-emerald-500/40',
  },
  incompleta: {
    label: 'Com Desfalque / Substituto',
    badgeClass: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    icon: AlertCircle,
    iconColor: 'text-amber-400',
    borderClass: 'border-amber-500/20 hover:border-amber-500/40',
  },
  critica: {
    label: 'Operação Comprometida (Falta)',
    badgeClass: 'bg-rose-500/20 text-rose-400 border-rose-500/30',
    icon: ShieldAlert,
    iconColor: 'text-rose-400',
    borderClass: 'border-rose-500/30 hover:border-rose-500/50',
  },
};

export const TeamsManagement: React.FC<TeamsManagementProps> = ({
  veiculos,
  onSelectColaborador,
  onNovaEquipeClick,
}) => {
  const [search, setSearch] = useState('');
  const [filterRegional, setFilterRegional] = useState<'todas' | 'ribas' | 'agua_clara'>('todas');
  const [filterStatus, setFilterStatus] = useState<'todas' | 'completa' | 'incompleta' | 'critica'>('todas');

  const equipes: EquipeCardData[] = useMemo(() => {
    const lista: EquipeCardData[] = [];
    (veiculos || []).forEach((v) => {
      // Equipe 1: motorista e frenteDir
      const liderEq1 = v.assentos.motorista;
      const ajudanteEq1 = v.assentos.frenteDir;

      let statusEq1: EquipeCardData['status'] = 'completa';
      const hasFaltaEq1 = liderEq1?.status === 'falta' || ajudanteEq1?.status === 'falta';
      const hasSubEq1 = liderEq1?.status === 'substituto' || ajudanteEq1?.status === 'substituto';
      if (hasFaltaEq1) statusEq1 = 'critica';
      else if (hasSubEq1) statusEq1 = 'incompleta';

      lista.push({
        id: `${v.id}-eq1`,
        codigo: v.equipe1Codigo || `${v.prefixo}-EQ1`,
        numero: 1,
        veiculoId: v.id,
        veiculoPrefixo: v.prefixo,
        veiculoPlaca: v.placa,
        veiculoModelo: v.modelo,
        regional: v.regional,
        lider: liderEq1,
        ajudante: ajudanteEq1,
        status: statusEq1,
      });

      // Equipe 2: trasEsq e trasDir
      const liderEq2 = v.assentos.trasEsq;
      const ajudanteEq2 = v.assentos.trasDir;

      let statusEq2: EquipeCardData['status'] = 'completa';
      const hasFaltaEq2 = liderEq2?.status === 'falta' || ajudanteEq2?.status === 'falta';
      const hasSubEq2 = liderEq2?.status === 'substituto' || ajudanteEq2?.status === 'substituto';
      if (hasFaltaEq2) statusEq2 = 'critica';
      else if (hasSubEq2) statusEq2 = 'incompleta';

      lista.push({
        id: `${v.id}-eq2`,
        codigo: v.equipe2Codigo || `${v.prefixo}-EQ2`,
        numero: 2,
        veiculoId: v.id,
        veiculoPrefixo: v.prefixo,
        veiculoPlaca: v.placa,
        veiculoModelo: v.modelo,
        regional: v.regional,
        lider: liderEq2,
        ajudante: ajudanteEq2,
        status: statusEq2,
      });
    });
    return lista;
  }, [veiculos]);

  const equipesFiltradas = useMemo(() => {
    return equipes.filter((eq) => {
      const matchRegional = filterRegional === 'todas' || eq.regional === filterRegional;
      const matchStatus = filterStatus === 'todas' || eq.status === filterStatus;
      const matchSearch =
        !search ||
        eq.codigo.toLowerCase().includes(search.toLowerCase()) ||
        eq.veiculoPrefixo.toLowerCase().includes(search.toLowerCase()) ||
        eq.lider?.nome?.toLowerCase().includes(search.toLowerCase()) ||
        eq.ajudante?.nome?.toLowerCase().includes(search.toLowerCase());
      return matchRegional && matchStatus && matchSearch;
    });
  }, [equipes, filterRegional, filterStatus, search]);

  const stats = useMemo(() => {
    const total = equipes.length;
    const completas = equipes.filter((e) => e.status === 'completa').length;
    const incompletas = equipes.filter((e) => e.status === 'incompleta').length;
    const criticas = equipes.filter((e) => e.status === 'critica').length;
    return { total, completas, incompletas, criticas };
  }, [equipes]);

  return (
    <div className="space-y-6">
      {/* Botão Nova Equipe Destacado no Topo da aba */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4 p-4 rounded-2xl bg-gradient-to-r from-primary/15 via-primary/5 to-transparent border border-primary/25 shadow-lg backdrop-blur-md">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-primary/20 border border-primary/30 flex items-center justify-center shrink-0">
            <Users className="w-5 h-5 text-primary" />
          </div>
          <div>
            <h2 className="text-base font-bold text-foreground">Gestão de Equipes Operacionais</h2>
            <p className="text-xs text-muted-foreground">Monitore a composição e adicione novas equipes ao plantão</p>
          </div>
        </div>

        <Button
          onClick={onNovaEquipeClick}
          size="lg"
          className="gap-2 bg-primary text-primary-foreground font-bold shadow-lg shadow-primary/25 hover:brightness-110 active:scale-95 transition-all shrink-0"
        >
          <UserPlus className="w-4 h-4" />
          + Nova Equipe
        </Button>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card className="border-border/60 bg-card/60">
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground font-medium">Total de Equipes</p>
            <p className="text-2xl font-extrabold text-foreground mt-1">{stats.total}</p>
          </CardContent>
        </Card>
        <Card className="border-emerald-500/20 bg-emerald-500/5">
          <CardContent className="p-4">
            <p className="text-xs text-emerald-400 font-medium">Completas</p>
            <p className="text-2xl font-extrabold text-emerald-400 mt-1">{stats.completas}</p>
          </CardContent>
        </Card>
        <Card className="border-amber-500/20 bg-amber-500/5">
          <CardContent className="p-4">
            <p className="text-xs text-amber-400 font-medium">Com Substituto</p>
            <p className="text-2xl font-extrabold text-amber-400 mt-1">{stats.incompletas}</p>
          </CardContent>
        </Card>
        <Card className="border-rose-500/20 bg-rose-500/5">
          <CardContent className="p-4">
            <p className="text-xs text-rose-400 font-medium">Com Falta</p>
            <p className="text-2xl font-extrabold text-rose-400 mt-1">{stats.criticas}</p>
          </CardContent>
        </Card>
      </div>

      {/* Barra de Filtros */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por código, veículo ou colaborador..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>

        <div className="flex gap-2 flex-wrap">
          {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
            <button
              key={reg}
              onClick={() => setFilterRegional(reg)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all',
                filterRegional === reg
                  ? 'bg-primary text-primary-foreground border-primary'
                  : 'border-border text-muted-foreground hover:text-foreground hover:bg-muted'
              )}
            >
              {reg === 'todas' ? 'Todas' : reg === 'ribas' ? 'Ribas' : 'Água Clara'}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Cards de Equipes */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {equipesFiltradas.map((eq) => {
          const cfg = statusConfig[eq.status];
          const StatusIcon = cfg.icon;

          return (
            <Card
              key={eq.id}
              className={cn(
                'border transition-all hover:shadow-lg',
                cfg.borderClass
              )}
            >
              <CardHeader className="p-4 pb-3 border-b border-border/40">
                <div className="flex items-center justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-base font-extrabold text-foreground">{eq.codigo}</span>
                      <Badge variant="outline" className="text-[10px] px-1.5 py-0.5">
                        Equipe {eq.numero}
                      </Badge>
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {eq.veiculoPrefixo} &bull; {eq.veiculoModelo} ({eq.veiculoPlaca})
                    </p>
                  </div>
                  <Badge className={cn('text-[10px] font-bold px-2 py-0.5', cfg.badgeClass)}>
                    <StatusIcon className="w-3 h-3 mr-1 inline" />
                    {cfg.label}
                  </Badge>
                </div>
              </CardHeader>

              <CardContent className="p-4 space-y-3">
                {/* Líder / Membro 1 */}
                <div
                  onClick={() => eq.lider && onSelectColaborador(eq.lider, eq.veiculoId)}
                  className="flex items-center gap-3 p-2.5 rounded-xl bg-muted/40 hover:bg-muted/70 cursor-pointer transition-colors border border-border/40"
                >
                  <div className="w-9 h-9 rounded-full overflow-hidden border-2 border-border/80 bg-muted shrink-0 flex items-center justify-center">
                    {eq.lider?.foto ? (
                      <img src={eq.lider.foto} alt={eq.lider.nome} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-xs font-bold text-muted-foreground">
                        {eq.lider?.nome?.charAt(0) ?? '?'}
                      </span>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold text-foreground truncate">{eq.lider?.nome || 'Não atribuído'}</p>
                    <p className="text-[11px] text-muted-foreground truncate">{eq.lider?.cargo || 'Líder / Motorista'}</p>
                  </div>
                  <span
                    className={cn(
                      'text-[10px] font-bold px-2 py-0.5 rounded-full shrink-0',
                      eq.lider?.status === 'presente' && 'bg-emerald-500/20 text-emerald-400',
                      eq.lider?.status === 'falta' && 'bg-rose-500/20 text-rose-400',
                      eq.lider?.status === 'substituto' && 'bg-amber-500/20 text-amber-400'
                    )}
                  >
                    {eq.lider?.status || 'presente'}
                  </span>
                </div>

                {/* Ajudante / Membro 2 */}
                <div
                  onClick={() => eq.ajudante && onSelectColaborador(eq.ajudante, eq.veiculoId)}
                  className="flex items-center gap-3 p-2.5 rounded-xl bg-muted/40 hover:bg-muted/70 cursor-pointer transition-colors border border-border/40"
                >
                  <div className="w-9 h-9 rounded-full overflow-hidden border-2 border-border/80 bg-muted shrink-0 flex items-center justify-center">
                    {eq.ajudante?.foto ? (
                      <img src={eq.ajudante.foto} alt={eq.ajudante.nome} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-xs font-bold text-muted-foreground">
                        {eq.ajudante?.nome?.charAt(0) ?? '?'}
                      </span>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-bold text-foreground truncate">{eq.ajudante?.nome || 'Não atribuído'}</p>
                    <p className="text-[11px] text-muted-foreground truncate">{eq.ajudante?.cargo || 'Ajudante / Operador'}</p>
                  </div>
                  <span
                    className={cn(
                      'text-[10px] font-bold px-2 py-0.5 rounded-full shrink-0',
                      eq.ajudante?.status === 'presente' && 'bg-emerald-500/20 text-emerald-400',
                      eq.ajudante?.status === 'falta' && 'bg-rose-500/20 text-rose-400',
                      eq.ajudante?.status === 'substituto' && 'bg-amber-500/20 text-amber-400'
                    )}
                  >
                    {eq.ajudante?.status || 'presente'}
                  </span>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
};

files.newContent:
import React, { useState, useMemo } from 'react';
import { Users, Search, Plus, Filter, AlertCircle, CheckCircle2, ShieldAlert, Sparkles, UserPlus } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Veiculo, Colaborador, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface TeamsManagementProps {
  veiculos: Veiculo[];
  selectedRegional?: Regional | string;
  onOpenAttendanceModal: (colaborador: Colaborador, veiculoId: string) => void;
  onNovaEquipe?: () => void;
}

export const TeamsManagement: React.FC<TeamsManagementProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  onOpenAttendanceModal,
  onNovaEquipe,
}) => {
  const [termoBusca, setTermoBusca] = useState('');

  const veiculosFiltrados = useMemo(() => {
    if (!veiculos || !Array.isArray(veiculos)) return [];
    if (selectedRegional === 'todas') return veiculos;
    return veiculos.filter((v) => v?.regional === selectedRegional);
  }, [veiculos, selectedRegional]);

  const equipesFormatadas = useMemo(() => {
    const lista: Array<{
      id: string;
      codigo: string;
      regional: 'ribas' | 'agua_clara';
      veiculoPrefixo: string;
      veiculoPlaca: string;
      veiculoId: string;
      equipeNumero: 1 | 2;
      membros: Colaborador[];
    }> = [];

    veiculosFiltrados.forEach((v) => {
      const eq1Colabs = [v.assentos?.motorista, v.assentos?.frenteDir].filter(Boolean) as Colaborador[];
      const eq2Colabs = [v.assentos?.trasEsq, v.assentos?.trasDir].filter(Boolean) as Colaborador[];

      lista.push({
        id: `${v.id}-eq1`,
        codigo: v.equipe1Codigo || `EQ-${v.prefixo}-1`,
        regional: v.regional,
        veiculoPrefixo: v.prefixo,
        veiculoPlaca: v.placa,
        veiculoId: v.id,
        equipeNumero: 1,
        membros: eq1Colabs,
      });

      lista.push({
        id: `${v.id}-eq2`,
        codigo: v.equipe2Codigo || `EQ-${v.prefixo}-2`,
        regional: v.regional,
        veiculoPrefixo: v.prefixo,
        veiculoPlaca: v.placa,
        veiculoId: v.id,
        equipeNumero: 2,
        membros: eq2Colabs,
      });
    });

    return lista.filter((eq) => {
      if (!termoBusca) return true;
      const matchCodigo = eq.codigo.toLowerCase().includes(termoBusca.toLowerCase());
      const matchVeiculo = eq.veiculoPrefixo.toLowerCase().includes(termoBusca.toLowerCase());
      const matchMembro = eq.membros.some((m) => m?.nome?.toLowerCase().includes(termoBusca.toLowerCase()));
      return matchCodigo || matchVeiculo || matchMembro;
    });
  }, [veiculosFiltrados, termoBusca]);

  return (
    <div className="space-y-6">
      {/* Barra de Busca e Botão de Nova Equipe */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3 bg-card/60 backdrop-blur-md p-4 rounded-2xl border border-border">
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar equipe, membro ou veículo..."
            value={termoBusca}
            onChange={(e) => setTermoBusca(e.target.value)}
            className="pl-9 text-xs"
          />
        </div>

        {onNovaEquipe && (
          <Button onClick={onNovaEquipe} size="sm" className="w-full sm:w-auto text-xs gap-1.5 shadow-md">
            <Plus className="w-4 h-4" />
            Nova Equipe
          </Button>
        )}
      </div>

      {/* Grid de Equipes */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {equipesFormatadas.map((eq) => {
          const presentes = eq.membros.filter((m) => m.status === 'presente' || m.status === 'substituto').length;
          const temFalta = eq.membros.some((m) => m.status === 'falta');

          return (
            <Card key={eq.id} className="border-border/70 hover:border-primary/40 transition-all">
              <CardHeader className="p-4 pb-2 border-b border-border/40">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-7 h-7 rounded-lg bg-primary/10 border border-primary/20 flex items-center justify-center text-primary font-bold text-xs">
                      {eq.equipeNumero}
                    </div>
                    <div>
                      <CardTitle className="text-sm font-bold text-foreground leading-tight">
                        {eq.codigo}
                      </CardTitle>
                      <p className="text-[10px] text-muted-foreground">
                        Veículo {eq.veiculoPrefixo} ({eq.regional === 'ribas' ? 'Ribas' : 'Água Clara'})
                      </p>
                    </div>
                  </div>

                  <Badge variant={temFalta ? 'destructive' : 'success'} className="text-[10px]">
                    {presentes}/{eq.membros.length} ativos
                  </Badge>
                </div>
              </CardHeader>

              <CardContent className="p-4 space-y-2.5">
                {eq.membros.map((m) => (
                  <div
                    key={m.id}
                    onClick={() => onOpenAttendanceModal(m, eq.veiculoId)}
                    className="flex items-center justify-between p-2 rounded-xl bg-muted/40 hover:bg-muted/70 transition-colors cursor-pointer border border-border/40"
                  >
                    <div className="flex items-center gap-2.5 overflow-hidden">
                      <div className="w-7 h-7 rounded-full bg-card border border-border flex items-center justify-center text-[10px] font-bold text-foreground shrink-0 overflow-hidden">
                        {m.foto ? (
                          <img src={m.foto} alt={m.nome} className="w-full h-full object-cover" />
                        ) : (
                          m.nome.charAt(0)
                        )}
                      </div>
                      <div className="overflow-hidden">
                        <p className="text-xs font-semibold text-foreground truncate">{m.nome}</p>
                        <p className="text-[10px] text-muted-foreground truncate">{m.cargo}</p>
                      </div>
                    </div>

                    <Badge
                      variant={m.status === 'presente' ? 'success' : m.status === 'falta' ? 'destructive' : 'secondary'}
                      className="text-[10px] shrink-0 capitalize"
                    >
                      {m.status}
                    </Badge>
                  </div>
                ))}
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
};

