import React, { useState } from 'react';
import { X, Users, Car, Check, AlertCircle } from 'lucide-react';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Veiculo, Regional } from '../types';

export interface NewTeamModalProps {
  isOpen?: boolean;
  onClose: () => void;
  onSave: (dados: {
    codigo: string;
    regional: 'ribas' | 'agua_clara';
    veiculoId: string;
    equipeNumero: 1 | 2;
    liderNome: string;
  }) => void;
  veiculosDisponiveis?: Veiculo[];
}

export const NewTeamModal: React.FC<NewTeamModalProps> = ({
  isOpen = true,
  onClose,
  onSave,
  veiculosDisponiveis = [],
}) => {
  const [codigo, setCodigo] = useState('');
  const [regional, setRegional] = useState<'ribas' | 'agua_clara'>('ribas');
  const [veiculoId, setVeiculoId] = useState(veiculosDisponiveis[0]?.id || '');
  const [equipeNumero, setEquipeNumero] = useState<1 | 2>(1);
  const [liderNome, setLiderNome] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!codigo.trim() || !veiculoId) return;

    onSave({
      codigo,
      regional,
      veiculoId,
      equipeNumero,
      liderNome,
    });
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="bg-card border border-border rounded-2xl shadow-2xl w-full max-w-md overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b border-border">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-primary/15 border border-primary/20 flex items-center justify-center text-primary">
              <Users className="w-4 h-4" />
            </div>
            <h2 className="text-sm font-bold text-foreground">Cadastrar Nova Equipe</h2>
          </div>
          <button
            onClick={onClose}
            aria-label="Fechar"
            className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
              Código da Equipe
            </label>
            <Input
              placeholder="Ex: EQ-MS-01"
              value={codigo}
              onChange={(e) => setCodigo(e.target.value)}
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                Regional
              </label>
              <select
                value={regional}
                onChange={(e) => setRegional(e.target.value as 'ribas' | 'agua_clara')}
                className="w-full h-10 px-3 text-xs bg-muted/40 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
              >
                <option value="ribas">Ribas do Rio Pardo</option>
                <option value="agua_clara">Água Clara</option>
              </select>
            </div>

            <div>
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
                Turno / Turno da Equipe
              </label>
              <select
                value={equipeNumero}
                onChange={(e) => setEquipeNumero(Number(e.target.value) as 1 | 2)}
                className="w-full h-10 px-3 text-xs bg-muted/40 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
              >
                <option value={1}>Equipe 1 (Dianteira)</option>
                <option value={2}>Equipe 2 (Traseira)</option>
              </select>
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
              Veículo Associado
            </label>
            <select
              value={veiculoId}
              onChange={(e) => setVeiculoId(e.target.value)}
              className="w-full h-10 px-3 text-xs bg-muted/40 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
            >
              {veiculosDisponiveis.map((v) => (
                <option key={v.id} value={v.id}>
                  Prefixo {v.prefixo} ({v.modelo} - {v.placa})
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">
              Líder da Equipe (Opcional)
            </label>
            <Input
              placeholder="Nome do líder responsável..."
              value={liderNome}
              onChange={(e) => setLiderNome(e.target.value)}
            />
          </div>

          <div className="flex items-center justify-end gap-2 pt-2 border-t border-border">
            <Button type="button" variant="outline" size="sm" onClick={onClose}>
              Cancelar
            </Button>
            <Button type="submit" size="sm" className="gap-1.5">
              <Check className="w-4 h-4" />
              Salvar Equipe
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

