import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { AttendanceModal } from './components/AttendanceModal';
import { TeamsManagement } from './components/TeamsManagement';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'relatorios' | 'colaboradores'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  // Modal de Presença
  const [modalAttendance, setModalAttendance] = useState<{
    open: boolean;
    colaborador?: Colaborador;
    veiculoId?: string;
  }>({ open: false });

  // Modal de Nova Equipe
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Manipulação de Presença / Falta / Substituto
  const handleSaveAttendance = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentosAtualizados = { ...v.assentos };
        (Object.keys(assentosAtualizados) as Array<keyof typeof assentosAtualizados>).forEach((key) => {
          const colab = assentosAtualizados[key];
          if (colab && colab.id === colaboradorId) {
            assentosAtualizados[key] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos: assentosAtualizados };
      })
    );

    // Se um substituto foi selecionado da reserva, podemos ajustar se necessário
    setModalAttendance({ open: false });
  };

  const handleOpenAttendanceModal = (colaborador: Colaborador, veiculoId: string) => {
    setModalAttendance({
      open: true,
      colaborador,
      veiculoId,
    });
  };

  const handleCreateTeam = (data: any) => {
    // Criação de nova equipe (adiciona veículo se necessário ou aloca)
    console.log('Nova equipe criada:', data);
    setIsNewTeamModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-primary/20">
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        selectedRegional={selectedRegional}
        setSelectedRegional={setSelectedRegional}
        selectedDate={selectedDate}
        setSelectedDate={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Métricas e Composição de Equipes — oculto na aba de relatórios */}
        {activeTab !== 'relatorios' && (
          <MetricsHeader
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
            onNovaEquipe={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {/* Conteúdo dinâmico de acordo com a aba ativa */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onOpenAttendanceModal={handleOpenAttendanceModal}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onOpenAttendanceModal={handleOpenAttendanceModal}
            onNovaEquipe={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            selectedRegional={selectedRegional}
          />
        )}
      </main>

      {/* Modal de Presença */}
      {modalAttendance.open && modalAttendance.colaborador && modalAttendance.veiculoId && (
        <AttendanceModal
          colaborador={modalAttendance.colaborador}
          veiculoId={modalAttendance.veiculoId}
          onClose={() => setModalAttendance({ open: false })}
          onSave={handleSaveAttendance}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}

      {/* Modal de Nova Equipe */}
      {isNewTeamModalOpen && (
        <NewTeamModal
          isOpen={isNewTeamModalOpen}
          onClose={() => setIsNewTeamModalOpen(false)}
          onSave={handleCreateTeam}
          veiculosDisponiveis={veiculos}
        />
      )}
    </div>
  );
}

