    ringColor: 'ring-amber-500/30',
    badgeBg: 'bg-amber-500/20 text-amber-400 border-amber-500/40',
    badgeText: 'Substituto',
    icon: RefreshCw,
  },
};

interface SeatProps {
  colaborador?: Colaborador;
  labelPosicao: string;
  equipeTag: string;
  equipeColor: string;
  isMotorista?: boolean;
  onClick?: () => void;
}

const Seat: React.FC<SeatProps> = ({
  colaborador,
  labelPosicao,
  equipeTag,
  equipeColor,
  isMotorista = false,
  onClick,
