import React, { useState, useMemo } from 'react';
import {
  Car,
  Search,
  Filter,
  Users,
  MapPin,
  CheckCircle2,
  AlertTriangle,
  RefreshCw,
  Sparkles,
  ShieldCheck,
  ChevronDown
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { VehicleTopView } from './VehicleTopView';
import { Veiculo, Colaborador, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  selectedRegional: Regional;
  onSelectColaborador: (colaborador: Colaborador, veiculoId: string) => void;
  onNovaEquipeClick?: () => void;
}

const regionalConfig = {
  todas: { label: 'Todas as Regionais', badge: 'bg-primary/20 text-primary border-primary/30' },
  ribas: { label: 'Ribas do Rio Pardo', badge: 'bg-sky-500/20 text-sky-400 border-sky-500/30' },
  agua_clara: { label: 'Água Clara', badge: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  onSelectColaborador,
  onNovaEquipeClick,
}) => {
  const [busca, setBusca] = useState('');
  const [filtroStatus, setFiltroStatus] = useState<'todos' | 'completo' | 'falta' | 'substituto'>('todos');
  const [filtroRegional, setFiltroRegional] = useState<Regional>(selectedRegional);

  // Sincronizar regional inicial caso prop mude
  React.useEffect(() => {
    setFiltroRegional(selectedRegional);
  }, [selectedRegional]);

  // Filtragem e busca defensiva
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;

      // Filtro Regional
      if (filtroRegional !== 'todas' && v.regional !== filtroRegional) {
        return false;
      }

      // Busca por texto (Placa, Prefixo, Modelo, Nome de Colaboradores)
      if (busca.trim()) {
        const termo = busca.toLowerCase();
        const colabs = [
          v.assentos?.motorista?.nome,
          v.assentos?.frenteDir?.nome,
          v.assentos?.trasEsq?.nome,
          v.assentos?.trasDir?.nome,
        ].filter(Boolean).map(n => String(n).toLowerCase());

        const matchVeiculo =
          v.prefixo?.toLowerCase().includes(termo) ||
          v.placa?.toLowerCase().includes(termo) ||
          v.modelo?.toLowerCase().includes(termo) ||
          v.equipe1Codigo?.toLowerCase().includes(termo) ||
          v.equipe2Codigo?.toLowerCase().includes(termo);

        const matchColab = colabs.some(nome => nome.includes(termo));

        if (!matchVeiculo && !matchColab) return false;
      }

      // Filtro de Status das Equipes
      if (filtroStatus !== 'todos') {
        const statusAssentos = [
          v.assentos?.motorista?.status,
          v.assentos?.frenteDir?.status,
          v.assentos?.trasEsq?.status,
          v.assentos?.trasDir?.status,
        ];

        if (filtroStatus === 'falta') {
          return statusAssentos.includes('falta');
        }
        if (filtroStatus === 'substituto') {
          return statusAssentos.includes('substituto');
        }
        if (filtroStatus === 'completo') {
          return statusAssentos.every(st => st === 'presente');
        }
      }

      return true;
    });
  }, [veiculos, filtroRegional, busca, filtroStatus]);

  // Contadores rápidos para filtros
  const contagens = useMemo(() => {
    let totalFaltas = 0;
    let totalSubstitutos = 0;
    let totalCompletos = 0;

    (veiculos || []).forEach((v) => {
      const assentos = [
        v.assentos?.motorista?.status,
        v.assentos?.frenteDir?.status,
        v.assentos?.trasEsq?.status,
        v.assentos?.trasDir?.status,
      ];
      if (assentos.includes('falta')) totalFaltas++;
      if (assentos.includes('substituto')) totalSubstitutos++;
      if (assentos.every(s => s === 'presente')) totalCompletos++;
    });

    return { totalFaltas, totalSubstitutos, totalCompletos, total: (veiculos || []).length };
  }, [veiculos]);

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="bg-card/70 backdrop-blur-md rounded-2xl border border-border/60 p-4 shadow-sm space-y-4">
        <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between">
          {/* Campo de Busca */}
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Buscar veículo (placa, prefixo) ou colaborador por nome..."
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
              className="pl-9 bg-muted/40 border-border/60 text-sm"
            />
          </div>

          {/* Seletor de Regional */}
          <div className="flex items-center gap-2">
            {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
              <button
                key={reg}
                onClick={() => setFiltroRegional(reg)}
                className={cn(
                  'px-3 py-2 rounded-xl text-xs font-semibold border transition-all',
                  filtroRegional === reg
                    ? reg === 'ribas'
                      ? 'bg-sky-500 text-white border-sky-400 shadow'
                      : reg === 'agua_clara'
                      ? 'bg-emerald-500 text-white border-emerald-400 shadow'
                      : 'bg-primary text-primary-foreground border-primary shadow'
                    : 'border-border/60 text-muted-foreground hover:bg-muted hover:text-foreground'
                )}
              >
                {reg === 'todas' ? 'Todas' : reg === 'ribas' ? 'Ribas' : 'Água Clara'}
              </button>
            ))}
          </div>
        </div>

        {/* Filtros por Status */}
        <div className="flex items-center gap-2 flex-wrap pt-2 border-t border-border/40">
          <span className="text-xs text-muted-foreground font-medium flex items-center gap-1 mr-1">
            <Filter className="w-3.5 h-3.5" /> Filtrar:
          </span>

          <button
            onClick={() => setFiltroStatus('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all flex items-center gap-1.5',
              filtroStatus === 'todos'
                ? 'bg-muted text-foreground border-border shadow-sm'
                : 'border-border/40 text-muted-foreground hover:bg-muted/40'
            )}
          >
            <span>Todos os Veículos</span>
            <span className="px-1.5 py-0.2 rounded-full text-[10px] bg-foreground/10">
              {contagens.total}
            </span>
          </button>

          <button
            onClick={() => setFiltroStatus('falta')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all flex items-center gap-1.5',
              filtroStatus === 'falta'
                ? 'bg-rose-500/20 text-rose-300 border-rose-500/50 shadow-sm'
                : 'border-border/40 text-muted-foreground hover:bg-rose-500/10 hover:text-rose-400'
            )}
          >
            <AlertTriangle className="w-3.5 h-3.5 text-rose-400" />
            <span>Com Faltas</span>
            <span className="px-1.5 py-0.2 rounded-full text-[10px] bg-rose-500/20 text-rose-300">
              {contagens.totalFaltas}
            </span>
          </button>

          <button
            onClick={() => setFiltroStatus('substituto')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all flex items-center gap-1.5',
              filtroStatus === 'substituto'
                ? 'bg-amber-500/20 text-amber-300 border-amber-500/50 shadow-sm'
                : 'border-border/40 text-muted-foreground hover:bg-amber-500/10 hover:text-amber-400'
            )}
          >
            <RefreshCw className="w-3.5 h-3.5 text-amber-400" />
            <span>Com Substitutos</span>
            <span className="px-1.5 py-0.2 rounded-full text-[10px] bg-amber-500/20 text-amber-300">
              {contagens.totalSubstitutos}
            </span>
          </button>

          <button
            onClick={() => setFiltroStatus('completo')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all flex items-center gap-1.5',
              filtroStatus === 'completo'
                ? 'bg-emerald-500/20 text-emerald-300 border-emerald-500/50 shadow-sm'
                : 'border-border/40 text-muted-foreground hover:bg-emerald-500/10 hover:text-emerald-400'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
            <span>100% Presentes</span>
            <span className="px-1.5 py-0.2 rounded-full text-[10px] bg-emerald-500/20 text-emerald-300">
              {contagens.totalCompletos}
            </span>
          </button>
        </div>
      </div>

      {/* Listagem em Grid dos Carros */}
      {veiculosFiltrados.length === 0 ? (
        <div className="bg-card/40 border border-dashed border-border/60 rounded-3xl p-12 text-center flex flex-col items-center justify-center">
          <Car className="w-12 h-12 text-muted-foreground/40 mb-3" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm">
            Tente ajustar os filtros de busca ou selecionar outra regional.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const hasFalta = [
              veiculo.assentos?.motorista?.status,
              veiculo.assentos?.frenteDir?.status,
              veiculo.assentos?.trasEsq?.status,
              veiculo.assentos?.trasDir?.status,
            ].includes('falta');

            const hasSub = [
              veiculo.assentos?.motorista?.status,
              veiculo.assentos?.frenteDir?.status,
              veiculo.assentos?.trasEsq?.status,
              veiculo.assentos?.trasDir?.status,
            ].includes('substituto');

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'overflow-hidden border-2 transition-all hover:shadow-xl group',
                  hasFalta
                    ? 'border-rose-500/40 hover:border-rose-500/70'
                    : hasSub
                    ? 'border-amber-500/40 hover:border-amber-500/70'
                    : 'border-border/70 hover:border-primary/50'
                )}
              >
                {/* Header do Card de Veículo */}
                <CardHeader className="p-4 bg-muted/40 border-b border-border/50">
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex items-center gap-2.5">
                      <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/25 flex items-center justify-center text-primary font-extrabold text-sm">
                        <Car className="w-5 h-5" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <CardTitle className="text-base font-extrabold text-foreground">
                            {veiculo.prefixo}
                          </CardTitle>
                          <span className="px-2 py-0.5 rounded-md bg-secondary text-[11px] font-mono font-bold tracking-wider text-muted-foreground border border-border/60">
                            {veiculo.placa}
                          </span>
                        </div>
                        <p className="text-[11px] text-muted-foreground">
                          {veiculo.modelo} ({veiculo.ano})
                        </p>
                      </div>
                    </div>

                    {/* Badge Regional */}
                    <div className="flex flex-col items-end gap-1">
                      <span
                        className={cn(
                          'px-2 py-0.5 rounded-full text-[10px] font-bold border',
                          veiculo.regional === 'ribas'
                            ? 'bg-sky-500/20 text-sky-400 border-sky-500/30'
                            : 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30'
                        )}
                      >
                        {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                      </span>
                      {hasFalta && (
                        <span className="px-1.5 py-0.2 rounded text-[9px] font-bold bg-rose-500/20 text-rose-400 border border-rose-500/30 flex items-center gap-1">
                          <AlertTriangle className="w-2.5 h-2.5" /> Falta detectada
                        </span>
                      )}
                    </div>
                  </div>
                </CardHeader>

                {/* Conteúdo com a Visualização dos Assentos e Fotos */}
                <CardContent className="p-4 space-y-4">
                  {/* Visão Superior do Veículo com fotos nos 4 assentos */}
                  <VehicleTopView
                    veiculo={veiculo}
                    onSelectColaborador={onSelectColaborador}
                  />

                  {/* Resumo das Equipes atribuídas */}
                  <div className="grid grid-cols-2 gap-2 pt-1 border-t border-border/40 text-xs">
                    <div className="p-2 rounded-xl bg-sky-500/5 border border-sky-500/20">
                      <span className="text-[10px] font-bold uppercase text-sky-400 block mb-0.5">
                        Equipe 1 (Dianteira)
                      </span>
                      <p className="font-semibold text-foreground truncate">
                        {veiculo.equipe1Codigo}
                      </p>
                      <p className="text-[10px] text-muted-foreground truncate">
                        Líder: {veiculo.assentos?.motorista?.nome || 'N/D'}
                      </p>
                    </div>

                    <div className="p-2 rounded-xl bg-emerald-500/5 border border-emerald-500/20">
                      <span className="text-[10px] font-bold uppercase text-emerald-400 block mb-0.5">
                        Equipe 2 (Traseira)
                      </span>
                      <p className="font-semibold text-foreground truncate">
                        {veiculo.equipe2Codigo}
                      </p>
                      <p className="text-[10px] text-muted-foreground truncate">
                        Líder: {veiculo.assentos?.trasEsq?.nome || 'N/D'}
                      </p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};

