import React, { useState, useMemo } from 'react';
import { Search, Filter, Car, AlertCircle, CheckCircle2, RefreshCw } from 'lucide-react';
import { VehicleTopView } from './VehicleTopView';
import { Card, CardContent, CardHeader } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  selectedRegional: string;
  onSeatClick: (colaborador: Colaborador, veiculoId: string) => void;
  onSwapSeats?: (veiculoId: string, seatKey1: string, seatKey2: string) => void;
  onUpdateAttendance?: (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => void;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  onSeatClick,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completo' | 'incompleto'>('todos');

  // Filtragem por regional, texto e status de preenchimento
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((veiculo) => {
      if (!veiculo) return false;

      // Filtro de regional
      if (selectedRegional !== 'todas' && veiculo.regional !== selectedRegional) {
        return false;
      }

      // Filtro de texto (prefixo, placa, modelo, nomes)
      if (searchTerm.trim() !== '') {
        const termo = searchTerm.toLowerCase();
        const assentos = [
          veiculo.assentos?.motorista?.nome,
          veiculo.assentos?.frenteDir?.nome,
          veiculo.assentos?.trasEsq?.nome,
          veiculo.assentos?.trasDir?.nome,
        ]
          .filter(Boolean)
          .map((n) => n?.toLowerCase() || '');

        const matchPrefixo = veiculo.prefixo?.toLowerCase().includes(termo);
        const matchPlaca = veiculo.placa?.toLowerCase().includes(termo);
        const matchModelo = veiculo.modelo?.toLowerCase().includes(termo);
        const matchColab = assentos.some((nome) => nome.includes(termo));

        if (!matchPrefixo && !matchPlaca && !matchModelo && !matchColab) {
          return false;
        }
      }

      // Filtro por presença completa ou incompleta
      if (statusFilter !== 'todos') {
        const assentosArray = [
          veiculo.assentos?.motorista,
          veiculo.assentos?.frenteDir,
          veiculo.assentos?.trasEsq,
          veiculo.assentos?.trasDir,
        ].filter(Boolean);

        const todosPresentes = assentosArray.every(
          (c) => c && (c.status === 'presente' || c.status === 'substituto')
        );

        if (statusFilter === 'completo' && !todosPresentes) return false;
        if (statusFilter === 'incompleto' && todosPresentes) return false;
      }

      return true;
    });
  }, [veiculos, selectedRegional, searchTerm, statusFilter]);

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-card/60 backdrop-blur-md border border-border/60 p-4 rounded-2xl shadow-sm">
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            type="text"
            placeholder="Buscar por prefixo, placa, modelo ou colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10 h-10 bg-background/50 text-sm"
          />
        </div>

        <div className="flex items-center gap-2">
          <div className="inline-flex rounded-xl bg-muted/40 p-1 border border-border/50">
            <button
              onClick={() => setStatusFilter('todos')}
              className={cn(
                'px-3 py-1.5 text-xs font-semibold rounded-lg transition-all',
                statusFilter === 'todos'
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Todos ({veiculos.length})
            </button>
            <button
              onClick={() => setStatusFilter('completo')}
              className={cn(
                'px-3 py-1.5 text-xs font-semibold rounded-lg transition-all',
                statusFilter === 'completo'
                  ? 'bg-emerald-600 text-white shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Completos
            </button>
            <button
              onClick={() => setStatusFilter('incompleto')}
              className={cn(
                'px-3 py-1.5 text-xs font-semibold rounded-lg transition-all',
                statusFilter === 'incompleto'
                  ? 'bg-rose-600 text-white shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              Com Faltas
            </button>
          </div>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 px-4 text-center bg-card/40 border border-border/40 rounded-2xl">
          <Car className="w-12 h-12 text-muted-foreground/40 mb-3" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm">
            Tente redefinir os filtros ou mudar o termo de busca para visualizar as viaturas operacionais.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const colabs = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean);

            const faltasCount = colabs.filter((c) => c?.status === 'falta').length;
            const subsCount = colabs.filter((c) => c?.status === 'substituto').length;
            const presentesCount = colabs.filter((c) => c?.status === 'presente').length;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden border-border/70 hover:border-primary/40 transition-all duration-300 shadow-lg hover:shadow-primary/5 flex flex-col justify-between"
              >
                <div>
                  {/* Cabeçalho do Card */}
                  <CardHeader className="p-4 pb-3 border-b border-border/40 bg-muted/20">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2.5">
                        <div className="w-9 h-9 rounded-xl bg-primary/15 border border-primary/25 flex items-center justify-center text-primary font-black text-sm shadow-sm">
                          {veiculo.prefixo}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <h3 className="text-sm font-bold text-foreground">{veiculo.placa}</h3>
                            <Badge
                              variant="outline"
                              className={cn(
                                'text-[10px] font-bold px-1.5 py-0 uppercase',
                                veiculo.regional === 'ribas'
                                  ? 'border-sky-500/30 text-sky-400 bg-sky-500/10'
                                  : 'border-emerald-500/30 text-emerald-400 bg-emerald-500/10'
                              )}
                            >
                              {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                            </Badge>
                          </div>
                          <p className="text-xs text-muted-foreground font-medium">
                            {veiculo.modelo}
                          </p>
                        </div>
                      </div>

                      {/* Status resumo do veículo */}
                      <div className="flex items-center gap-1.5">
                        {faltasCount > 0 ? (
                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold bg-rose-500/15 text-rose-400 border border-rose-500/30">
                            <AlertCircle className="w-3 h-3" />
                            {faltasCount} {faltasCount === 1 ? 'falta' : 'faltas'}
                          </span>
                        ) : subsCount > 0 ? (
                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold bg-amber-500/15 text-amber-400 border border-amber-500/30">
                            <RefreshCw className="w-3 h-3" />
                            {subsCount} {subsCount === 1 ? 'subst.' : 'subst.'}
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                            <CheckCircle2 className="w-3 h-3" />
                            100% Presente
                          </span>
                        )}
                      </div>
                    </div>
                  </CardHeader>

                  {/* Visualização Superior Interativa com Fotos nos Assentos */}
                  <CardContent className="p-4 flex flex-col items-center justify-center">
                    <VehicleTopView
                      veiculo={veiculo}
                      onSeatClick={(colab) => onSeatClick(colab, veiculo.id)}
                    />
                  </CardContent>
                </div>

                {/* Rodapé informativo leve */}
                <div className="px-4 py-2.5 bg-muted/15 border-t border-border/30 flex items-center justify-between text-[11px] text-muted-foreground font-medium">
                  <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1 text-emerald-400">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                      {presentesCount} presentes
                    </span>
                    {subsCount > 0 && (
                      <span className="flex items-center gap-1 text-amber-400">
                        <span className="w-1.5 h-1.5 rounded-full bg-amber-400" />
                        {subsCount} substitutos
                      </span>
                    )}
                    {faltasCount > 0 && (
                      <span className="flex items-center gap-1 text-rose-400">
                        <span className="w-1.5 h-1.5 rounded-full bg-rose-400" />
                        {faltasCount} faltas
                      </span>
                    )}
                  </div>
                  <span className="text-[10px] text-muted-foreground/70">
                    Toque no assento para alterar
                  </span>
                </div>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};

