import React from 'react';
import { UserCheck, UserX, RefreshCw, User, ShieldCheck } from 'lucide-react';
import { Colaborador, StatusPresenca, Veiculo } from '../types';
import { cn } from '@/lib/utils';

export type VehicleZone = 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';

interface VehicleTopViewProps {
  veiculo: Veiculo;
  onSelectColaborador?: (colaborador: Colaborador, veiculoId: string) => void;
}

const statusConfig: Record<StatusPresenca, {
  label: string;
  borderColor: string;
  ringColor: string;
  badgeBg: string;
  badgeText: string;
  icon: React.ElementType;
}> = {
  presente: {
    label: 'Presente',
    borderColor: 'border-emerald-500',
    ringColor: 'ring-emerald-500/30',
    badgeBg: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/40',
    badgeText: 'Presente',
    icon: UserCheck,
  },
  falta: {
    label: 'Falta',
    borderColor: 'border-rose-500',
    ringColor: 'ring-rose-500/30',
    badgeBg: 'bg-rose-500/20 text-rose-400 border-rose-500/40',
    badgeText: 'Falta',
    icon: UserX,
  },
  substituto: {
    label: 'Substituto',
    borderColor: 'border-amber-500',
    ringColor: 'ring-amber-500/30',
    badgeBg: 'bg-amber-500/20 text-amber-400 border-amber-500/40',
    badgeText: 'Substituto',
    icon: RefreshCw,
  },
};

interface SeatProps {
  colaborador?: Colaborador;
  labelPosicao: string;
  equipeTag: string;
  equipeColor: string;
  isMotorista?: boolean;
  onClick?: () => void;
}

const Seat: React.FC<SeatProps> = ({
  colaborador,
  labelPosicao,
  equipeTag,
  equipeColor,
  isMotorista = false,
  onClick,
}) => {
  if (!colaborador) {
    return (
      <div className="flex flex-col items-center justify-center p-2.5 rounded-xl border border-dashed border-border/60 bg-muted/20 min-h-[90px] text-center">
        <User className="w-5 h-5 text-muted-foreground/40 mb-1" />
        <span className="text-[10px] text-muted-foreground">Vago</span>
      </div>
    );
  }

  const st = statusConfig[colaborador.status] || statusConfig.presente;
  const StatusIcon = st.icon;

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'group relative w-full flex flex-col items-center p-2 rounded-xl border-2 transition-all text-left cursor-pointer active:scale-95 hover:shadow-lg',
        st.borderColor,
        'bg-card/90 hover:bg-card hover:border-opacity-100',
        colaborador.status === 'falta' && 'bg-rose-500/5',
        colaborador.status === 'substituto' && 'bg-amber-500/5'
      )}
    >
      {/* Badge Equipe & Posição */}
      <div className="w-full flex items-center justify-between gap-1 mb-1.5">
        <span className={cn('px-1.5 py-0.5 rounded text-[9px] font-bold uppercase border', equipeColor)}>
          {equipeTag}
        </span>
        {isMotorista && (
          <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-sky-500/20 text-sky-400 border border-sky-500/30 flex items-center gap-0.5">
            <ShieldCheck className="w-2.5 h-2.5" /> Mot.
          </span>
        )}
      </div>

      {/* Foto do Colaborador com status ring */}
      <div className="relative mb-1.5">
        <div
          className={cn(
            'w-12 h-12 rounded-full overflow-hidden border-2 shadow-md bg-muted flex items-center justify-center ring-2',
            st.borderColor,
            st.ringColor
          )}
        >
          {colaborador.foto ? (
            <img
              src={colaborador.foto}
              alt={colaborador.nome}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform"
              onError={(e) => {
                (e.target as HTMLImageElement).src =
                  'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80';
              }}
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center font-bold text-xs text-foreground bg-primary/20">
              {(colaborador.nome || '?').substring(0, 2).toUpperCase()}
            </div>
          )}
        </div>

        {/* Ícone flutuante do Status */}
        <div
          className={cn(
            'absolute -bottom-1 -right-1 w-4 h-4 rounded-full flex items-center justify-center shadow border',
            colaborador.status === 'presente' && 'bg-emerald-500 text-white border-emerald-600',
            colaborador.status === 'falta' && 'bg-rose-500 text-white border-rose-600 animate-pulse',
            colaborador.status === 'substituto' && 'bg-amber-500 text-white border-amber-600'
          )}
        >
          <StatusIcon className="w-2.5 h-2.5" />
        </div>
      </div>

      {/* Nome e Cargo */}
      <div className="w-full text-center">
        <p className="text-xs font-bold text-foreground truncate w-full group-hover:text-primary transition-colors">
          {colaborador.nome || 'Colaborador'}
        </p>
        <p className="text-[10px] text-muted-foreground truncate w-full">
          {labelPosicao}
        </p>
      </div>

      {/* Indicador de Status textual */}
      <div className="mt-1.5 w-full flex items-center justify-center">
        <span className={cn('px-2 py-0.5 rounded-full text-[9px] font-semibold border text-center block w-full truncate', st.badgeBg)}>
          {colaborador.status === 'substituto' && colaborador.substitutoNome
            ? `Sub: ${colaborador.substitutoNome.split(' ')[0]}`
            : st.badgeText}
        </span>
      </div>
    </button>
  );
};

export const VehicleTopView: React.FC<VehicleTopViewProps> = ({
  veiculo,
  onSelectColaborador,
}) => {
  if (!veiculo || !veiculo.assentos) return null;

  const { motorista, frenteDir, trasEsq, trasDir } = veiculo.assentos;

  return (
    <div className="relative w-full rounded-2xl bg-gradient-to-b from-card/80 to-muted/30 border border-border/70 p-3.5 shadow-inner">
      {/* Indicador da Frente do Veículo / Parabrisa */}
      <div className="w-full flex items-center justify-center mb-3">
        <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-muted/60 border border-border/60 text-[10px] font-semibold text-muted-foreground tracking-wider uppercase">
          <div className="w-1.5 h-1.5 rounded-full bg-primary animate-ping" />
          <span>Frente do Carro (Cabine)</span>
        </div>
      </div>

      {/* Grid 2x2 com os 4 Assentos e Fotos */}
      <div className="grid grid-cols-2 gap-3 relative">
        {/* Linha Divisória interna imitando habitáculo */}
        <div className="absolute inset-y-0 left-1/2 -translate-x-1/2 w-px bg-border/40 pointer-events-none hidden sm:block" />

        {/* 1. Assento Dianteiro Esquerdo (Motorista - Equipe 1) */}
        <div className="flex flex-col">
          <Seat
            colaborador={motorista}
            labelPosicao="Motorista"
            equipeTag={`Eq. 1 (${veiculo.equipe1Codigo || 'E1'})`}
            equipeColor="bg-sky-500/15 text-sky-300 border-sky-500/30"
            isMotorista
            onClick={() => motorista && onSelectColaborador?.(motorista, veiculo.id)}
          />
        </div>

        {/* 2. Assento Dianteiro Direito (Equipe 1) */}
        <div className="flex flex-col">
          <Seat
            colaborador={frenteDir}
            labelPosicao="Carona Diant."
            equipeTag={`Eq. 1 (${veiculo.equipe1Codigo || 'E1'})`}
            equipeColor="bg-sky-500/15 text-sky-300 border-sky-500/30"
            onClick={() => frenteDir && onSelectColaborador?.(frenteDir, veiculo.id)}
          />
        </div>

        {/* 3. Assento Traseiro Esquerdo (Equipe 2) */}
        <div className="flex flex-col">
          <Seat
            colaborador={trasEsq}
            labelPosicao="Traseiro Esq."
            equipeTag={`Eq. 2 (${veiculo.equipe2Codigo || 'E2'})`}
            equipeColor="bg-emerald-500/15 text-emerald-300 border-emerald-500/30"
            onClick={() => trasEsq && onSelectColaborador?.(trasEsq, veiculo.id)}
          />
        </div>

        {/* 4. Assento Traseiro Direito (Equipe 2) */}
        <div className="flex flex-col">
          <Seat
            colaborador={trasDir}
            labelPosicao="Traseiro Dir."
            equipeTag={`Eq. 2 (${veiculo.equipe2Codigo || 'E2'})`}
            equipeColor="bg-emerald-500/15 text-emerald-300 border-emerald-500/30"
            onClick={() => trasDir && onSelectColaborador?.(trasDir, veiculo.id)}
          />
        </div>
      </div>

      {/* Rodapé do Carro / Traseira */}
      <div className="w-full flex items-center justify-center mt-3 pt-2 border-t border-border/40">
        <span className="text-[10px] text-muted-foreground/80">
          Toque na foto para alterar presença, registrar falta ou substituto
        </span>
      </div>
    </div>
  );
};

