                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold bg-amber-500/15 text-amber-400 border border-amber-500/30">
                            <RefreshCw className="w-3 h-3" />
                            {subsCount} {subsCount === 1 ? 'subst.' : 'subst.'}
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[11px] font-semibold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                            <CheckCircle2 className="w-3 h-3" />
                            100% Presente
                          </span>
                        )}
                      </div>
                    </div>
                  </CardHeader>

                  {/* Visualização Superior Interativa com Fotos nos Assentos */}
                  <CardContent className="p-4 flex flex-col items-center justify-center">
                    <VehicleTopView
                      veiculo={veiculo}
                      onSeatClick={(colab) => onSeatClick(colab, veiculo.id)}
                    />
                  </CardContent>
                </div>

                {/* Rodapé informativo leve */}
                <div className="px-4 py-2.5 bg-muted/15 border-t border-border/30 flex items-center justify-between text-[11px] text-muted-foreground font-medium">
                  <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1 text-emerald-400">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-400" />
                      {presentesCount} presentes
                    </span>
                    {subsCount > 0 && (
