import React, { useState, useMemo } from 'react';
import { Search, Filter, AlertCircle, CheckCircle2, RefreshCw } from 'lucide-react';
import { VehicleTopView } from './VehicleTopView';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  selectedRegional: string;
  onOpenAttendanceModal: (colaborador: Colaborador, veiculoId: string) => void;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  onOpenAttendanceModal,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completos' | 'incompletos'>('todos');

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional = selectedRegional === 'todas' || v.regional === selectedRegional;
      const matchSearch =
        !searchTerm ||
        v.prefixo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.placa?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        v.modelo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        Object.values(v.assentos || {}).some((c) =>
          c?.nome?.toLowerCase().includes(searchTerm.toLowerCase())
        );

      if (!matchRegional || !matchSearch) return false;

      if (statusFilter === 'todos') return true;

      const assentosArray = Object.values(v.assentos || {});
      const totalAtivos = assentosArray.filter(
        (c) => c && (c.status === 'presente' || c.status === 'substituto')
      ).length;

      if (statusFilter === 'completos') return totalAtivos === 4;
      if (statusFilter === 'incompletos') return totalAtivos < 4;

      return true;
    });
  }, [veiculos, selectedRegional, searchTerm, statusFilter]);

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-center justify-between">
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por placa, prefixo, colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 bg-card/60 border-border/70"
          />
        </div>

        <div className="flex items-center gap-1.5 w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0">
          <button
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all whitespace-nowrap',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/60 text-muted-foreground hover:border-border hover:bg-muted/40'
            )}
          >
            Todos ({veiculosFiltrados.length})
          </button>
          <button
            onClick={() => setStatusFilter('completos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all whitespace-nowrap flex items-center gap-1',
              statusFilter === 'completos'
                ? 'bg-emerald-500 text-white border-emerald-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:border-border hover:bg-muted/40'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5" />
            Completos
          </button>
          <button
            onClick={() => setStatusFilter('incompletos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all whitespace-nowrap flex items-center gap-1',
              statusFilter === 'incompletos'
                ? 'bg-rose-500 text-white border-rose-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:border-border hover:bg-muted/40'
            )}
          >
            <AlertCircle className="w-3.5 h-3.5" />
            Incompletos
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 text-center bg-card/40 rounded-2xl border border-dashed border-border p-8">
          <AlertCircle className="w-10 h-10 text-muted-foreground/40 mb-3" />
          <p className="text-sm font-semibold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1">Ajuste os filtros de busca para encontrar os veículos</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentosArray = Object.values(veiculo.assentos || {});
            const totalPresentes = assentosArray.filter((c) => c?.status === 'presente').length;
            const totalSubstitutos = assentosArray.filter((c) => c?.status === 'substituto').length;
            const totalFaltas = assentosArray.filter((c) => c?.status === 'falta').length;
            const totalAtivos = totalPresentes + totalSubstitutos;

            const isCompleto = totalAtivos === 4;

            return (
              <Card
                key={veiculo.id}
                className="overflow-hidden border-border/70 hover:border-primary/40 transition-all shadow-md bg-card/80 flex flex-col"
              >
                {/* Header do Card com apenas a Placa */}
                <div className="p-4 border-b border-border/40 bg-muted/20 flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="px-2.5 py-1 rounded-lg bg-primary/10 border border-primary/20 text-primary font-bold text-sm tracking-wider">
                      {veiculo.placa}
                    </span>
                    <span className="text-xs font-medium text-muted-foreground">
                      {veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'}
                    </span>
                  </div>

                  <Badge
                    variant={isCompleto ? 'outline' : 'destructive'}
                    className={cn(
                      'text-[11px] font-semibold',
                      isCompleto
                        ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30'
                        : 'bg-rose-500/10 text-rose-400 border-rose-500/30'
                    )}
                  >
                    {totalAtivos}/4 Ocupados
                  </Badge>
                </div>

                {/* Conteúdo: Visão dos Assentos do Veículo */}
                <CardContent className="p-4 flex-1 flex flex-col justify-center">
                  <VehicleTopView
                    veiculo={veiculo}
                    onSeatClick={(colaborador) => onOpenAttendanceModal(colaborador, veiculo.id)}
                  />
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};

