import React from 'react';
import { UserCheck, UserX, RefreshCw, User, ShieldCheck } from 'lucide-react';
import { Colaborador, StatusPresenca, Veiculo } from '../types';
import { cn } from '@/lib/utils';

export type VehicleZone = 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';

interface VehicleTopViewProps {
  veiculo: Veiculo;
  onSeatClick?: (seat: VehicleZone, colaborador: Colaborador) => void;
}

const statusConfig: Record<
  StatusPresenca,
  {
    icon: React.ElementType;
    bgBadge: string;
    textBadge: string;
    borderSeat: string;
    bgSeat: string;
    dotColor: string;
    label: string;
  }
> = {
  presente: {
    icon: UserCheck,
    bgBadge: 'bg-emerald-500/20 border-emerald-500/40 text-emerald-400',
    borderSeat: 'border-emerald-500/50 hover:border-emerald-400',
    bgSeat: 'bg-emerald-950/20 hover:bg-emerald-950/35',
    dotColor: 'bg-emerald-400 shadow-emerald-500/50',
    label: 'Presente',
  },
  falta: {
    icon: UserX,
    bgBadge: 'bg-rose-500/20 border-rose-500/40 text-rose-400',
    borderSeat: 'border-rose-500/60 hover:border-rose-400',
    bgSeat: 'bg-rose-950/30 hover:bg-rose-950/45',
    dotColor: 'bg-rose-400 shadow-rose-500/50',
    label: 'Falta',
  },
  substituto: {
    icon: RefreshCw,
    bgBadge: 'bg-amber-500/20 border-amber-500/40 text-amber-400',
    borderSeat: 'border-amber-500/60 hover:border-amber-400',
    bgSeat: 'bg-amber-950/30 hover:bg-amber-950/45',
    dotColor: 'bg-amber-400 shadow-amber-500/50',
    label: 'Substituto',
  },
};

export const VehicleTopView: React.FC<VehicleTopViewProps> = ({
  veiculo,
  onSeatClick,
}) => {
  if (!veiculo || !veiculo.assentos) return null;

  const { motorista, frenteDir, trasEsq, trasDir } = veiculo.assentos;

  const renderSeatCard = (seatKey: VehicleZone, colab: Colaborador) => {
    if (!colab) return null;

    const config = statusConfig[colab.status] || statusConfig.presente;
    const isSub = colab.status === 'substituto';
    const isFalta = colab.status === 'falta';

    return (
      <button
        key={seatKey}
        type="button"
        onClick={() => onSeatClick?.(seatKey, colab)}
        className={cn(
          'group relative w-full flex flex-col items-center justify-between p-3 rounded-xl border text-center transition-all duration-200 cursor-pointer shadow-sm',
          config.borderSeat,
          config.bgSeat
        )}
      >
        {/* Status indicator dot no topo superior direito */}
        <div className="absolute top-2 right-2 flex items-center gap-1">
          <span
            className={cn(
              'w-2 h-2 rounded-full ring-2 ring-background/60 shadow-sm animate-pulse',
              config.dotColor
            )}
          />
        </div>

        {/* Foto do colaborador */}
        <div className="relative mt-1 mb-2">
          <div
            className={cn(
              'w-14 h-14 rounded-full overflow-hidden border-2 shadow-md bg-muted flex items-center justify-center transition-transform duration-200 group-hover:scale-105',
              isFalta
                ? 'border-rose-500/70 opacity-60 grayscale'
                : isSub
                ? 'border-amber-500/70'
                : 'border-emerald-500/70'
            )}
          >
            {colab.foto ? (
              <img
                src={colab.foto}
                alt={colab.nome}
                className="w-full h-full object-cover"
                loading="lazy"
              />
            ) : (
              <User className="w-7 h-7 text-muted-foreground" />
            )}
          </div>

          {/* Badge de ícone de status sobre a foto */}
          <div
            className={cn(
              'absolute -bottom-1 -right-1 w-5 h-5 rounded-full flex items-center justify-center border text-[10px] shadow-sm',
              config.bgBadge
            )}
          >
            <config.icon className="w-3 h-3" />
          </div>
        </div>

        {/* Informações do colaborador */}
        <div className="w-full min-w-0">
          <p className="text-xs font-bold text-foreground truncate px-1" title={colab.nome}>
            {colab.nome}
          </p>
          <p className="text-[10px] text-muted-foreground truncate px-1 mt-0.5">
            {colab.cargo || 'Colaborador'}
          </p>

          {isSub && colab.substitutoNome && (
            <p className="text-[9px] font-semibold text-amber-400/90 truncate mt-1 bg-amber-500/10 rounded px-1.5 py-0.5">
              Sub: {colab.substitutoNome}
            </p>
          )}

          {isFalta && colab.motivoFalta && (
            <p className="text-[9px] font-semibold text-rose-400/90 truncate mt-1 bg-rose-500/10 rounded px-1.5 py-0.5">
              {colab.motivoFalta}
            </p>
          )}
        </div>
      </button>
    );
  };

  return (
    <div className="w-full max-w-md mx-auto p-4 rounded-2xl bg-card/40 border border-border/60 shadow-inner">
      {/* Representação visual da cabine do veículo */}
      <div className="relative rounded-2xl border-2 border-border/80 bg-background/50 p-4 pt-6 pb-6 overflow-hidden">
        {/* Marcador do para-brisa dianteiro */}
        <div className="absolute top-0 inset-x-8 h-2 rounded-b-lg bg-primary/20 border-b border-primary/30 flex items-center justify-center">
          <span className="text-[8px] font-bold uppercase tracking-widest text-primary/60">FRENTE</span>
        </div>

        {/* Grade de 4 assentos (2 na frente, 2 atrás) */}
        <div className="grid grid-cols-2 gap-3 mt-1">
          {/* Assentos dianteiros */}
          {renderSeatCard('motorista', motorista)}
          {renderSeatCard('frenteDir', frenteDir)}

          {/* Divisor do habitáculo do carro */}
          <div className="col-span-2 flex items-center justify-center my-0.5">
            <div className="h-px w-full bg-border/40" />
          </div>

          {/* Assentos traseiros */}
          {renderSeatCard('trasEsq', trasEsq)}
          {renderSeatCard('trasDir', trasDir)}
        </div>

        {/* Marcador traseiro do veículo */}
        <div className="absolute bottom-0 inset-x-12 h-1.5 rounded-t-lg bg-muted-foreground/20" />
      </div>
    </div>
  );
};

