import React from 'react';
import { UserCheck, UserX, RefreshCw, User } from 'lucide-react';
import { Colaborador, StatusPresenca, Veiculo } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleZone {
  key: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir';
  colaborador: Colaborador;
}

interface VehicleTopViewProps {
  veiculo: Veiculo;
  onSeatClick?: (colaborador: Colaborador) => void;
}

const statusBadgeConfig: Record<StatusPresenca, { label: string; icon: React.ElementType; bg: string; text: string; border: string }> = {
  presente: {
    label: 'Presente',
    icon: UserCheck,
    bg: 'bg-emerald-500/15',
    text: 'text-emerald-400',
    border: 'border-emerald-500/30',
  },
  falta: {
    label: 'Falta',
    icon: UserX,
    bg: 'bg-rose-500/15',
    text: 'text-rose-400',
    border: 'border-rose-500/30',
  },
  substituto: {
    label: 'Substituto',
    icon: RefreshCw,
    bg: 'bg-amber-500/15',
    text: 'text-amber-400',
    border: 'border-amber-500/30',
  },
};

export const VehicleTopView: React.FC<VehicleTopViewProps> = ({ veiculo, onSeatClick }) => {
  const assentos: VehicleZone[] = [
    { key: 'motorista', colaborador: veiculo.assentos?.motorista },
    { key: 'frenteDir', colaborador: veiculo.assentos?.frenteDir },
    { key: 'trasEsq', colaborador: veiculo.assentos?.trasEsq },
    { key: 'trasDir', colaborador: veiculo.assentos?.trasDir },
  ];

  return (
    <div className="w-full relative py-1">
      {/* Moldura do Veículo */}
      <div className="relative rounded-2xl border border-border/80 bg-background/50 backdrop-blur-sm p-3.5 shadow-inner">
        {/* Placa no topo do carro */}
        <div className="flex justify-center mb-3">
          <div className="px-3 py-1 rounded-md bg-slate-950 border border-slate-700/80 text-[11px] font-mono font-bold tracking-widest text-slate-200 shadow-sm flex items-center gap-1.5">
            <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
            <span>{veiculo.placa}</span>
          </div>
        </div>

        {/* 4 Assentos em Grid 2x2 */}
        <div className="grid grid-cols-2 gap-2.5">
          {assentos.map(({ key, colaborador }) => {
            if (!colaborador) {
              return (
                <div
                  key={key}
                  className="rounded-xl border border-dashed border-border/60 bg-muted/20 p-3 flex flex-col items-center justify-center min-h-[110px]"
                >
                  <User className="w-6 h-6 text-muted-foreground/30 mb-1" />
                  <span className="text-[11px] text-muted-foreground font-medium">Vago</span>
                </div>
              );
            }

            const statusInfo = statusBadgeConfig[colaborador.status] || statusBadgeConfig.presente;
            const StatusIcon = statusInfo.icon;

            return (
              <button
                key={key}
                type="button"
                onClick={() => onSeatClick?.(colaborador)}
                className={cn(
                  'group relative rounded-xl border p-2.5 text-left transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]',
                  'flex flex-col items-center justify-center text-center min-h-[115px]',
                  colaborador.status === 'presente' && 'bg-card/90 border-border/80 hover:border-emerald-500/50 shadow-sm',
                  colaborador.status === 'falta' && 'bg-rose-950/20 border-rose-500/30 hover:border-rose-500/60 shadow-sm',
                  colaborador.status === 'substituto' && 'bg-amber-950/20 border-amber-500/30 hover:border-amber-500/60 shadow-sm'
                )}
              >
                {/* Foto / Avatar */}
                <div className="relative mb-2">
                  <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-border/80 group-hover:border-primary/60 transition-all bg-muted shrink-0 shadow-sm">
                    {colaborador.foto ? (
                      <img
                        src={colaborador.foto}
                        alt={colaborador.nome}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          (e.target as HTMLImageElement).style.display = 'none';
                        }}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center bg-primary/10 text-primary font-bold text-sm">
                        {colaborador.nome?.charAt(0) ?? 'U'}
                      </div>
                    )}
                  </div>
                  {/* Ícone de status sobreposto */}
                  <div
                    className={cn(
                      'absolute -bottom-1 -right-1 w-5 h-5 rounded-full border border-background flex items-center justify-center text-white shadow-md',
                      colaborador.status === 'presente' && 'bg-emerald-500',
                      colaborador.status === 'falta' && 'bg-rose-500',
                      colaborador.status === 'substituto' && 'bg-amber-500'
                    )}
                  >
                    <StatusIcon className="w-3 h-3" />
                  </div>
                </div>

                {/* Nome do Colaborador */}
                <span className="text-xs font-bold text-foreground truncate max-w-full leading-tight">
                  {colaborador.nome}
                </span>

                {/* Badge de Status */}
                <div
                  className={cn(
                    'mt-1.5 px-2 py-0.5 rounded-full border text-[10px] font-semibold flex items-center gap-1',
                    statusInfo.bg,
                    statusInfo.text,
                    statusInfo.border
                  )}
                >
                  <StatusIcon className="w-2.5 h-2.5" />
                  <span>{statusInfo.label}</span>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

