import React, { useState, useMemo } from 'react';
import { Search, Filter, AlertCircle, CheckCircle2, RefreshCw, MapPin } from 'lucide-react';
import { VehicleTopView } from './VehicleTopView';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  onOpenAttendanceModal: (colaborador: Colaborador, veiculoId: string) => void;
  selectedRegional: string;
}

const regionalConfig: Record<string, { label: string; badgeClass: string; iconClass: string; borderClass: string; bgGlow: string }> = {
  ribas: {
    label: 'Ribas do Rio Pardo',
    badgeClass: 'bg-sky-500/15 text-sky-300 border-sky-400/40 shadow-sm shadow-sky-500/10 font-bold',
    iconClass: 'text-sky-400',
    borderClass: 'border-sky-500/30',
    bgGlow: 'from-sky-500/5 to-transparent',
  },
  agua_clara: {
    label: 'Água Clara',
    badgeClass: 'bg-emerald-500/15 text-emerald-300 border-emerald-400/40 shadow-sm shadow-emerald-500/10 font-bold',
    iconClass: 'text-emerald-400',
    borderClass: 'border-emerald-500/30',
    bgGlow: 'from-emerald-500/5 to-transparent',
  },
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  onOpenAttendanceModal,
  selectedRegional = 'todas',
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'todos' | 'completo' | 'incompleto' | 'com_falta'>('todos');

  // Filtrar veículos por busca e status
  const filteredVeiculos = useMemo(() => {
    return (veiculos || []).filter((veiculo) => {
      if (!veiculo) return false;

      // Filtro de texto por placa, modelo ou nomes dos colaboradores
      const matchSearch =
        !searchTerm ||
        veiculo.placa?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        veiculo.modelo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        veiculo.prefixo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        Object.values(veiculo.assentos || {}).some(
          (c) => c && c.nome?.toLowerCase().includes(searchTerm.toLowerCase())
        );

      if (!matchSearch) return false;

      // Status dos assentos
      const assentos = Object.values(veiculo.assentos || {}).filter(Boolean);
      const temFalta = assentos.some((c) => c?.status === 'falta');
      const todosPresentes = assentos.every((c) => c?.status === 'presente' || c?.status === 'substituto');

      if (statusFilter === 'completo') return todosPresentes && !temFalta;
      if (statusFilter === 'com_falta') return temFalta;
      if (statusFilter === 'incompleto') return temFalta || assentos.length < 4;

      return true;
    });
  }, [veiculos, searchTerm, statusFilter]);

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-center justify-between">
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por placa ou colaborador..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-9 bg-card/60 border-border/70 text-sm h-10 rounded-xl"
          />
        </div>

        {/* Filtros rápidos de status */}
        <div className="flex items-center gap-1.5 w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0">
          <button
            onClick={() => setStatusFilter('todos')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border shrink-0',
              statusFilter === 'todos'
                ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted hover:text-foreground'
            )}
          >
            Todos ({veiculos.length})
          </button>
          <button
            onClick={() => setStatusFilter('completo')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border shrink-0 flex items-center gap-1.5',
              statusFilter === 'completo'
                ? 'bg-emerald-500 text-white border-emerald-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted hover:text-foreground'
            )}
          >
            <CheckCircle2 className="w-3.5 h-3.5" />
            100% Presentes
          </button>
          <button
            onClick={() => setStatusFilter('com_falta')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border shrink-0 flex items-center gap-1.5',
              statusFilter === 'com_falta'
                ? 'bg-rose-500 text-white border-rose-500 shadow-sm'
                : 'border-border/60 text-muted-foreground hover:bg-muted hover:text-foreground'
            )}
          >
            <AlertCircle className="w-3.5 h-3.5" />
            Com Faltas
          </button>
        </div>
      </div>

      {/* Grid de Veículos */}
      {filteredVeiculos.length === 0 ? (
        <div className="py-16 text-center rounded-2xl border border-dashed border-border/70 bg-card/30">
          <AlertCircle className="w-10 h-10 text-muted-foreground/40 mx-auto mb-3" />
          <p className="text-base font-semibold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1">
            Tente mudar o termo de busca ou o filtro de status selecionado.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
          {filteredVeiculos.map((veiculo) => {
            const regConfig = regionalConfig[veiculo.regional] || {
              label: veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
              badgeClass: 'bg-primary/15 text-primary border-primary/30',
              iconClass: 'text-primary',
              borderClass: 'border-border/60',
              bgGlow: '',
            };

            const assentos = Object.values(veiculo.assentos || {}).filter(Boolean);
            const totalFaltas = assentos.filter((c) => c?.status === 'falta').length;
            const totalSubstitutos = assentos.filter((c) => c?.status === 'substituto').length;
            const totalPresentes = assentos.filter((c) => c?.status === 'presente').length;

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'relative border overflow-hidden transition-all duration-300 hover:shadow-xl hover:border-border group',
                  regConfig.borderClass
                )}
              >
                {/* Cabeçalho do Card: Placa e Nome da Unidade em Destaque Visível */}
                <div className="px-4 py-3.5 border-b border-border/50 bg-gradient-to-r from-card to-muted/30 flex items-center justify-between gap-3">
                  {/* Placa do Carro Estilizada */}
                  <div className="flex items-center gap-2.5">
                    <div className="px-2.5 py-1 rounded-lg bg-background/80 border border-border/70 shadow-inner flex items-center gap-1.5">
                      <span className="text-[11px] font-mono font-black tracking-wider text-foreground uppercase">
                        {veiculo.placa}
                      </span>
                    </div>
                  </div>

                  {/* Nome da Unidade / Regional com Alta Visibilidade */}
                  <div
                    className={cn(
                      'flex items-center gap-1.5 px-3 py-1 rounded-full border text-xs tracking-wide transition-all shadow-sm',
                      regConfig.badgeClass
                    )}
                  >
                    <MapPin className={cn('w-3.5 h-3.5 shrink-0', regConfig.iconClass)} />
                    <span className="font-extrabold uppercase text-[11px] tracking-wider">
                      {regConfig.label}
                    </span>
                  </div>
                </div>

                {/* Conteúdo: Veículo Top View com Fotos dos Colaboradores */}
                <CardContent className="p-4 pt-4">
                  <VehicleTopView
                    veiculo={veiculo}
                    onSeatClick={(colab) => onOpenAttendanceModal(colab, veiculo.id)}
                  />

                  {/* Resumo do Status do Carro */}
                  <div className="mt-3 pt-3 border-t border-border/40 flex items-center justify-between text-[11px]">
                    <div className="flex items-center gap-2">
                      <span className="flex items-center gap-1 text-emerald-400 font-semibold">
                        <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block" />
                        {totalPresentes} presentes
                      </span>
                      {totalSubstitutos > 0 && (
                        <span className="flex items-center gap-1 text-amber-400 font-semibold">
                          <span className="w-1.5 h-1.5 rounded-full bg-amber-400 inline-block" />
                          {totalSubstitutos} subst.
                        </span>
                      )}
                      {totalFaltas > 0 && (
                        <span className="flex items-center gap-1 text-rose-400 font-semibold">
                          <span className="w-1.5 h-1.5 rounded-full bg-rose-400 inline-block" />
                          {totalFaltas} falta(s)
                        </span>
                      )}
                    </div>
                    <span className="text-muted-foreground font-medium text-[10px]">
                      {veiculo.modelo}
                    </span>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
};

