          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Visualize as faltas do dia, a composição detalhada de cada carro e baixe o relatório oficial em PDF.
          </p>
        </div>

        <div className="flex items-center gap-2.5 w-full sm:w-auto">
          <Button
            onClick={handleGerarPDF}
            className="w-full sm:w-auto gap-2 bg-primary hover:bg-primary/90 text-primary-foreground font-semibold shadow-md"
          >
            <Printer className="w-4 h-4" />
            Salvar / Imprimir em PDF
          </Button>
        </div>
      </div>

      {/* Cards de Métricas do Dia */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card className="border-border/60 bg-muted/20">
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground font-medium">Veículos em Operação</p>
            <p className="text-2xl font-extrabold text-foreground mt-1">{stats.totalVeiculos}</p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Carros escalados</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-emerald-500/10">
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground font-medium">Colaboradores Presentes</p>
            <p className="text-2xl font-extrabold text-emerald-400 mt-1">{stats.totalPresentes}</p>
            <p className="text-[11px] text-emerald-400/80 mt-0.5">{stats.taxaPresenca}% de presença</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-rose-500/10">
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground font-medium">Faltas no Dia</p>
            <p className="text-2xl font-extrabold text-rose-400 mt-1">{stats.totalFaltas}</p>
            <p className="text-[11px] text-rose-400/80 mt-0.5">Afastamentos / Atestados</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-amber-500/10">
          <CardContent className="p-4">
            <p className="text-xs text-muted-foreground font-medium">Substitutos em Campo</p>
            <p className="text-2xl font-extrabold text-amber-400 mt-1">{stats.totalSubst}</p>
            <p className="text-[11px] text-amber-400/80 mt-0.5">Equipes recompostas</p>
          </CardContent>
        </Card>
      </div>

      {/* Seção 1: Faltas do Dia */}
      <Card className="border-border/70 overflow-hidden shadow-md">
        <CardHeader className="pb-3 border-b border-border/40 bg-muted/20">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2">
              <UserX className="w-4 h-4 text-rose-400" />
              Faltas Registradas no Dia ({dataFormatada})
            </CardTitle>
            <Badge variant={faltasDoDia.length > 0 ? 'destructive' : 'success'}>
              {faltasDoDia.length} {faltasDoDia.length === 1 ? 'falta' : 'faltas'}
            </Badge>
          </div>
          <CardDescription className="text-xs">
            Lista nominal dos colaboradores ausentes na data e motivos declarados.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0">
          {faltasDoDia.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-center">
              <CheckCircle2 className="w-10 h-10 text-emerald-400/80 mb-2" />
              <p className="text-sm font-semibold text-foreground">Nenhuma falta no dia de hoje</p>
              <p className="text-xs text-muted-foreground mt-0.5">Todos os colaboradores escalados estão presentes ou operando.</p>
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {faltasDoDia.map(({ colab, veiculo }) => (
                <div key={colab.id} className="p-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 hover:bg-muted/30 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-rose-500/30 bg-muted shrink-0 flex items-center justify-center">
                      {colab.foto ? (
                        <img src={colab.foto} alt={colab.nome} className="w-full h-full object-cover" />
                      ) : (
                        <span className="text-sm font-bold text-rose-400">{colab.nome.charAt(0)}</span>
                      )}
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-bold text-foreground">{colab.nome}</p>
                        <span className="px-2 py-0.5 rounded text-[10px] font-semibold bg-rose-500/20 text-rose-400 border border-rose-500/30">
