export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos conforme a regional selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return selectedRegional === 'todas' || v.regional === selectedRegional;
    });
  }, [veiculos, selectedRegional]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    veiculosFiltrados.forEach((v) => {
      if (!v?.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter(Boolean);

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return todosColaboradores.filter((item) => item.colab.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return todosColaboradores.filter((item) => item.colab.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = todosColaboradores.filter((i) => i.colab.status === 'presente').length;
    const totalFaltas = faltasDoDia.length;
    const totalSubst = substitutosDoDia.length;
    const totalGeral = todosColaboradores.length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    let totalDuplas = 0;
    let totalTrios = 0;

    veiculosFiltrados.forEach((v) => {
      const eq1 = [v.assentos?.motorista, v.assentos?.frenteDir].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;
      const eq2 = [v.assentos?.trasEsq, v.assentos?.trasDir].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;

      if (eq1 === 1) totalDuplas++;
      else if (eq1 >= 2) totalTrios++;

      if (eq2 === 1) totalDuplas++;
      else if (eq2 >= 2) totalTrios++;
    });

    return {
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
      totalVeiculos: veiculosFiltrados.length,
      totalDuplas,
      totalTrios,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Ranking de faltas do mês selecionado
  const rankingMesSelecionado = useMemo(() => {
    const dadoMes = HISTORICO_MENSAL_FALTAS.find((m) => m.mesIndex === selectedMonth);
    return dadoMes ? dadoMes.faltas : [];
  }, [selectedMonth]);

  const maxFaltasNoMes = useMemo(() => {
    if (rankingMesSelecionado.length === 0) return 1;
    return Math.max(...rankingMesSelecionado.map((r) => r.totalFaltas));
  }, [rankingMesSelecionado]);

  // Função para Gerar / Imprimir o Relatório Completo em PDF
  const handleGerarPDF = () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      alert('Por favor, permita pop-ups no navegador para gerar a impressão do relatório em PDF.');
      return;
    }

    const htmlCarros = veiculosFiltrados.map((v, idx) => {
      const assentos = [
        { nome: 'Motorista', c: v.assentos?.motorista, eq: 'Equipe 1' },
        { nome: 'Dianteiro Dir.', c: v.assentos?.frenteDir, eq: 'Equipe 1' },
        { nome: 'Traseiro Esq.', c: v.assentos?.trasEsq, eq: 'Equipe 2' },
        { nome: 'Traseiro Dir.', c: v.assentos?.trasDir, eq: 'Equipe 2' },
      ];

      const eq1Ativos = [v.assentos?.motorista, v.assentos?.frenteDir].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;
      const eq2Ativos = [v.assentos?.trasEsq, v.assentos?.trasDir].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;
      const totalOcupantes = eq1Ativos + eq2Ativos;

      return `
        <div style="border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; margin-bottom: 14px; page-break-inside: avoid; background: #fafafa;">
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 8px; margin-bottom: 8px;">
            <div>
              <span style="font-size: 14px; font-weight: bold; background: #0f172a; color: #ffffff; padding: 4px 8px; border-radius: 4px; letter-spacing: 1px;">
                ${v.placa}
              </span>
              <span style="margin-left: 8px; font-size: 13px; font-weight: 600; color: #334155;">
                ${v.modelo} (Prefixo ${v.prefixo})
              </span>
              <span style="margin-left: 8px; font-size: 11px; padding: 2px 6px; border-radius: 4px; background: ${v.regional === 'ribas' ? '#e0f2fe; color: #0369a1;' : '#dcfce7; color: #15803d;'}">
                ${v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
              </span>
            </div>
            <div style="text-align: right; font-size: 12px; font-weight: bold; color: #1e293b;">
              Ocupação Total: <span style="color: #2563eb;">${totalOcupantes}/4</span> | Eq. 1: ${eq1Ativos} pess. | Eq. 2: ${eq2Ativos} pess.
            </div>
          </div>

          <table style="width: 100%; border-collapse: collapse; font-size: 11px;">
            <thead>
              <tr style="background: #f1f5f9; text-align: left; color: #475569;">
                <th style="padding: 6px 8px;">Posição</th>
                <th style="padding: 6px 8px;">Equipe</th>
                <th style="padding: 6px 8px;">Colaborador</th>
                <th style="padding: 6px 8px;">Cargo</th>
                <th style="padding: 6px 8px;">Status</th>
                <th style="padding: 6px 8px;">Detalhe / Observação</th>
              </tr>
            </thead>
            <tbody>
              ${assentos.map((pos) => {
                const c = pos.c;
                if (!c) {
                  return `
                    <tr style="border-bottom: 1px solid #e2e8f0;">
                      <td style="padding: 6px 8px; color: #64748b;">${pos.nome}</td>
                      <td style="padding: 6px 8px; color: #64748b;">${pos.eq}</td>
                      <td colspan="4" style="padding: 6px 8px; color: #94a3b8; font-style: italic;">Vago / Não alocado</td>
                    </tr>
                  `;
                }

                let statusColor = '#16a34a';
                let statusBg = '#dcfce7';
                let statusLabel = 'PRESENTE';

                if (c.status === 'falta') {
                  statusColor = '#dc2626';
                  statusBg = '#fee2e2';
                  statusLabel = 'FALTA';
                } else if (c.status === 'substituto') {
                  statusColor = '#d97706';
                  statusBg = '#fef3c7';
                  statusLabel = 'SUBSTITUTO';
                }

                return `
                  <tr style="border-bottom: 1px solid #e2e8f0;">
                    <td style="padding: 6px 8px; font-weight: 600; color: #334155;">${pos.nome}</td>
                    <td style="padding: 6px 8px; color: #475569;">${pos.eq}</td>
                    <td style="padding: 6px 8px; font-weight: bold; color: #0f172a;">${c.nome}</td>
                    <td style="padding: 6px 8px; color: #64748b;">${c.cargo || '-'}</td>
                    <td style="padding: 6px 8px;">
                      <span style="background: ${statusBg}; color: ${statusColor}; padding: 2px 6px; border-radius: 4px; font-weight: bold; font-size: 10px;">
                        ${statusLabel}
                      </span>
                    </td>
                    <td style="padding: 6px 8px; color: #475569;">
                      ${c.status === 'falta' ? (c.motivoFalta ? `Motivo: <strong>${c.motivoFalta}</strong>` : 'Falta Registrada') : ''}
                      ${c.status === 'substituto' ? (c.substitutoNome ? `Substituindo: <strong>${c.substitutoNome}</strong>` : 'Operando como substituto') : ''}
                      ${c.status === 'presente' ? 'Em operação normal' : ''}
                    </td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>
      `;
    }).join('');

    const htmlFaltasTabela = faltasDoDia.length > 0 ? `
      <table style="width: 100%; border-collapse: collapse; font-size: 11px; margin-bottom: 20px;">
        <thead>
          <tr style="background: #fee2e2; color: #991b1b; text-align: left;">
            <th style="padding: 8px;">Colaborador</th>
            <th style="padding: 8px;">Cargo</th>
            <th style="padding: 8px;">Placa / Carro</th>
            <th style="padding: 8px;">Regional</th>
            <th style="padding: 8px;">Motivo da Falta</th>
          </tr>
        </thead>
        <tbody>
          ${faltasDoDia.map(({ colab, veiculo }) => `
            <tr style="border-bottom: 1px solid #fecaca;">
              <td style="padding: 8px; font-weight: bold; color: #7f1d1d;">${colab.nome}</td>
              <td style="padding: 8px; color: #475569;">${colab.cargo}</td>
              <td style="padding: 8px; font-weight: 600; color: #0f172a;">${veiculo.placa}</td>
              <td style="padding: 8px; color: #475569;">${veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</td>
              <td style="padding: 8px; font-weight: 600; color: #b91c1c;">${colab.motivoFalta || 'Falta Não Justificada'}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    ` : `
      <div style="background: #f0fdf4; border: 1px solid #bbf7d0; color: #166534; padding: 12px; border-radius: 8px; font-size: 12px; font-weight: 600; margin-bottom: 20px;">
        ✅ Nenhuma falta registrada no dia ${dataFormatada}! 100% de assiduidade na frota.
      </div>
    `;

    printWindow.document.write(`
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="utf-8" />
        <title>Relatório Operacional de Faltas e Composição de Veículos - ${dataFormatada}</title>
        <style>
          @page { size: A4 portrait; margin: 12mm; }
          body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            color: #0f172a;
            background: #ffffff;
            margin: 0;
            padding: 10px;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
          }
          h1, h2, h3, p { margin: 0; }
          .header {
