            justify-content: space-between;
            align-items: center;
            border-bottom: 2px solid #0f172a;
            padding-bottom: 12px;
            margin-bottom: 16px;
          }
          .stats-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 10px;
            margin-bottom: 20px;
          }
          .stat-box {
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 8px 12px;
            background: #f8fafc;
            text-align: center;
          }
          .stat-val { font-size: 18px; font-weight: 800; color: #0f172a; }
          .stat-lbl { font-size: 10px; color: #64748b; text-transform: uppercase; font-weight: 600; }
          .section-title {
            font-size: 14px;
            font-weight: 800;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: #1e293b;
            border-left: 4px solid #2563eb;
            padding-left: 8px;
            margin-top: 18px;
            margin-bottom: 10px;
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div>
            <h1 style="font-size: 18px; font-weight: 800; color: #0f172a;">RELATÓRIO DIÁRIO DE CONTROLE DE FROTAS</h1>
            <p style="font-size: 12px; color: #64748b; margin-top: 2px;">
              Unidade: <strong>${regionalLabel[selectedRegional]}</strong> | Data: <strong>${dataFormatada}</strong>
            </p>
          </div>
          <div style="text-align: right;">
            <p style="font-size: 11px; color: #64748b;">Emissão do Relatório:</p>
            <p style="font-size: 11px; font-weight: bold; color: #0f172a;">${new Date().toLocaleDateString('pt-BR')} às ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</p>
          </div>
        </div>

        <!-- Estatísticas Gerais -->
        <div class="stats-grid">
          <div class="stat-box">
            <div class="stat-lbl">Total de Veículos</div>
            <div class="stat-val">${stats.totalVeiculos}</div>
          </div>
          <div class="stat-box">
            <div class="stat-lbl">Colaboradores Presentes</div>
            <div class="stat-val" style="color: #16a34a;">${stats.totalPresentes}</div>
