        ${htmlFaltasTabela}

        <!-- Seção 2: Composição de Veículos e Equipes -->
        <div class="section-title">2. Composição e Quantidade de Equipes por Veículo (${stats.totalVeiculos} Carros)</div>
        <div style="font-size: 11px; color: #64748b; margin-bottom: 12px;">
