          </div>
          <CardDescription className="text-xs">
            Lista nominal dos colaboradores ausentes na data e motivos declarados.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0">
          {faltasDoDia.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-center">
              <CheckCircle2 className="w-10 h-10 text-emerald-400/80 mb-2" />
              <p className="text-sm font-semibold text-foreground">Nenhuma falta no dia de hoje</p>
              <p className="text-xs text-muted-foreground mt-0.5">Todos os colaboradores escalados estão presentes ou operando.</p>
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {faltasDoDia.map(({ colab, veiculo }) => (
                <div key={colab.id} className="p-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 hover:bg-muted/30 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-rose-500/30 bg-muted shrink-0 flex items-center justify-center">
                      {colab.foto ? (
                        <img src={colab.foto} alt={colab.nome} className="w-full h-full object-cover" />
                      ) : (
                        <span className="text-sm font-bold text-rose-400">{colab.nome.charAt(0)}</span>
                      )}
