              <Calendar className="w-4 h-4 text-muted-foreground shrink-0" />
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="h-9 px-3 text-xs font-semibold bg-muted/60 border border-border rounded-xl text-foreground focus:outline-none focus:ring-2 focus:ring-primary"
              >
                {MESES.map((nomeMes, idx) => (
                  <option key={nomeMes} value={idx}>
                    Mês de {nomeMes}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-5">
          <div className="space-y-4">
            {rankingMesSelecionado.map((item, idx) => {
              const porcentagem = Math.round((item.totalFaltas / maxFaltasNoMes) * 100);
              return (
                <div key={item.nome} className="space-y-1.5">
                  <div className="flex items-center justify-between text-xs">
                    <div className="flex items-center gap-2">
                      <span className={cn(
                        'w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold',
                        idx === 0 ? 'bg-rose-500 text-white' : idx === 1 ? 'bg-amber-500 text-white' : 'bg-muted text-muted-foreground'
                      )}>
                        {idx + 1}
                      </span>
                      <span className="font-bold text-foreground">{item.nome}</span>
                      <span className="text-muted-foreground hidden sm:inline">• {item.cargo}</span>
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground">{item.regional}</span>
                    </div>
                    <span className="font-bold text-rose-400">{item.totalFaltas} {item.totalFaltas === 1 ? 'falta' : 'faltas'}</span>
                  </div>
                  <div className="w-full h-2.5 rounded-full bg-muted/60 overflow-hidden">
                    <div
                      className={cn(
                        'h-full rounded-full transition-all duration-500',
                        idx === 0 ? 'bg-rose-500' : idx === 1 ? 'bg-amber-500' : 'bg-primary'
                      )}
                      style={{ width: `${porcentagem}%` }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Seção 3: Como Ficou Cada Carro e Quantidade de Equipes */}
      <Card className="border-border/70 overflow-hidden shadow-md">
        <CardHeader className="pb-3 border-b border-border/40 bg-muted/20">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2">
              <Car className="w-4 h-4 text-primary" />
              Composição Atual por Veículo & Equipes Formadas
            </CardTitle>
            <Badge variant="outline">{veiculosFiltrados.length} veículos</Badge>
          </div>
          <CardDescription className="text-xs">
            Status dos assentos e número de integrantes alocados em cada carro.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-4 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {veiculosFiltrados.map((v) => {
              const eq1Presentes = [v.assentos?.motorista, v.assentos?.frenteDir].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;
              const eq2Presentes = [v.assentos?.trasEsq, v.assentos?.trasDir].filter((c) => c && (c.status === 'presente' || c.status === 'substituto')).length;
              const totalOcupantes = eq1Presentes + eq2Presentes;

              return (
                <div key={v.id} className="p-4 rounded-xl border border-border/70 bg-card/40 space-y-3">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-sm font-black px-2.5 py-1 rounded-lg bg-muted border border-border">
                        {v.placa}
                      </span>
                      <div>
                        <p className="text-xs font-bold text-foreground">{v.modelo}</p>
                        <p className="text-[10px] text-muted-foreground">Prefixo {v.prefixo}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-primary/10 text-primary border border-primary/20">
                        {totalOcupantes}/4 Ocupantes
                      </span>
                      <p className="text-[10px] text-muted-foreground mt-0.5">
                        Eq 1: {eq1Presentes}p | Eq 2: {eq2Presentes}p
                      </p>
                    </div>
                  </div>

                  {/* Grid de assentos */}
                  <div className="grid grid-cols-2 gap-2 text-xs pt-1 border-t border-border/40">
                    <div className="p-2 rounded-lg bg-muted/30">
                      <p className="text-[10px] font-bold text-muted-foreground uppercase">Equipe 1 (Dianteira)</p>
                      <p className="font-semibold text-foreground truncate mt-0.5">
                        {v.assentos?.motorista?.nome || '—'}
                      </p>
                      <p className="font-semibold text-foreground truncate">
                        {v.assentos?.frenteDir?.nome || '—'}
                      </p>
                    </div>
                    <div className="p-2 rounded-lg bg-muted/30">
                      <p className="text-[10px] font-bold text-muted-foreground uppercase">Equipe 2 (Traseira)</p>
                      <p className="font-semibold text-foreground truncate mt-0.5">
                        {v.assentos?.trasEsq?.nome || '—'}
                      </p>
                      <p className="font-semibold text-foreground truncate">
                        {v.assentos?.trasDir?.nome || '—'}
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

