import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { ExportReports } from './components/ExportReports';
import { AttendanceModal } from './components/AttendanceModal';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta, MetricasGerais } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'colaboradores' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  // Modal de Presença
  const [attendanceModalData, setAttendanceModalData] = useState<{
    isOpen: boolean;
    colaborador?: Colaborador;
    veiculoId?: string;
  }>({ isOpen: false });

  // Modal de Nova Equipe
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Manipular clique no assento
  const handleAssentoClick = (veiculoId: string, _zone: string, colaborador: Colaborador) => {
    setAttendanceModalData({
      isOpen: true,
      colaborador,
      veiculoId,
    });
  };

  // Salvar alterações de presença
  const handleSaveAttendance = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const novosAssentos = { ...v.assentos };
        (Object.keys(novosAssentos) as Array<keyof typeof novosAssentos>).forEach((key) => {
          if (novosAssentos[key]?.id === colaboradorId) {
            novosAssentos[key] = {
              ...novosAssentos[key],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos: novosAssentos };
      })
    );

    setAttendanceModalData({ isOpen: false });
  };

  // Criar nova equipe
  const handleCreateTeam = (novaEquipe: {
    nome: string;
    regional: 'ribas' | 'agua_clara';
    numero: 1 | 2;
    lider: string;
    veiculoId: string;
  }) => {
    setIsNewTeamModalOpen(false);
  };

  // Veículos filtrados por regional
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return selectedRegional === 'todas' || v.regional === selectedRegional;
    });
  }, [veiculos, selectedRegional]);

  // Cálculo de Métricas Gerais
  const metricas: MetricasGerais = useMemo(() => {
    let totalColabs = 0;
    let presentes = 0;
    let faltas = 0;
    let substitutos = 0;
    let totalEquipes = 0;
    let equipesCompletas = 0;
    let equipesIncompletas = 0;

    veiculosFiltrados.forEach((v) => {
      const assentosArray = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      assentosArray.forEach((c) => {
        if (!c) return;
        totalColabs++;
        if (c.status === 'presente') presentes++;
        else if (c.status === 'falta') faltas++;
        else if (c.status === 'substituto') substitutos++;
      });

      // Equipe 1
      const eq1 = [v.assentos?.motorista, v.assentos?.frenteDir].filter(Boolean);
      if (eq1.length > 0) {
        totalEquipes++;
        const eq1Ok = eq1.every((c) => c?.status === 'presente' || c?.status === 'substituto');
        if (eq1Ok) equipesCompletas++;
        else equipesIncompletas++;
      }

      // Equipe 2
      const eq2 = [v.assentos?.trasEsq, v.assentos?.trasDir].filter(Boolean);
      if (eq2.length > 0) {
        totalEquipes++;
        const eq2Ok = eq2.every((c) => c?.status === 'presente' || c?.status === 'substituto');
        if (eq2Ok) equipesCompletas++;
        else equipesIncompletas++;
      }
    });

    const taxaPresenca = totalColabs > 0 ? Math.round(((presentes + substitutos) / totalColabs) * 100) : 100;

    return {
      totalVeiculos: veiculosFiltrados.length,
      veiculosAtivos: veiculosFiltrados.filter((v) => v.statusOperacional === 'ativo').length,
      totalEquipes,
      equipesCompletas,
      equipesIncompletas,
      totalColaboradores: totalColabs,
      colaboradoresPresentes: presentes,
      colaboradoresFaltas: faltas,
      colaboradoresSubstitutos: substitutos,
      taxaPresenca,
    };
  }, [veiculosFiltrados]);

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col selection:bg-primary/20">
      {/* Barra de Navegação Superior */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas Resumo */}
        <MetricsHeader metricas={metricas} />

        {/* Visualização por Abas */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculosFiltrados}
            onAssentoClick={handleAssentoClick}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculosFiltrados}
            onNovaEquipe={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculosFiltrados}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculosFiltrados}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal de Controle de Faltas/Substituições */}
      {attendanceModalData.isOpen && attendanceModalData.colaborador && attendanceModalData.veiculoId && (
        <AttendanceModal
          colaborador={attendanceModalData.colaborador}
          veiculoId={attendanceModalData.veiculoId}
          onClose={() => setAttendanceModalData({ isOpen: false })}
          onSave={handleSaveAttendance}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}

      {/* Modal de Cadastro de Equipe */}
      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onSave={handleCreateTeam}
        veiculosDisponiveis={veiculos}
      />
    </div>
  );
}

