export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos conforme a regional selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return selectedRegional === 'todas' || v.regional === selectedRegional;
    });
  }, [veiculos, selectedRegional]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    veiculosFiltrados.forEach((v) => {
      if (!v?.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter(Boolean);

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return todosColaboradores.filter((item) => item.colab.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return todosColaboradores.filter((item) => item.colab.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = todosColaboradores.filter((i) => i.colab.status === 'presente').length;
    const totalFaltas = faltasDoDia.length;
    const totalSubst = substitutosDoDia.length;
    const totalGeral = todosColaboradores.length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: veiculosFiltrados.length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const dadosMes = useMemo(() => {
    return HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMonth) || HISTORICO_MENSAL_FALTAS[0];
  }, [selectedMonth]);

  const handlePrint = () => {
    window.print();
  };

  const handleExportCSV = () => {
    const headers = 'Placa,Regional,Modelo,Motorista,Status Motorista,Frente Dir,Status Frente Dir,Traseiro Esq,Status Tras Esq,Traseiro Dir,Status Tras Dir\n';
    const rows = veiculosFiltrados.map((v) => {
      const m = v.assentos?.motorista?.nome ?? 'Vago';
      const mSt = v.assentos?.motorista?.status ?? '-';
      const fd = v.assentos?.frenteDir?.nome ?? 'Vago';
      const fdSt = v.assentos?.frenteDir?.status ?? '-';
      const te = v.assentos?.trasEsq?.nome ?? 'Vago';
      const teSt = v.assentos?.trasEsq?.status ?? '-';
      const td = v.assentos?.trasDir?.nome ?? 'Vago';
      const tdSt = v.assentos?.trasDir?.status ?? '-';
      const reg = v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
      return `"${v.placa}","${reg}","${v.modelo}","${m}","${mSt}","${fd}","${fdSt}","${te}","${teSt}","${td}","${tdSt}"`;
    }).join('\n');

    const blob = new Blob([headers + rows], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `relatorio-operacao-${dataFormatada.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Ações do Relatório */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-5 rounded-2xl bg-card border border-border">
        <div>
          <h2 className="text-xl font-bold text-foreground flex items-center gap-2">
            <FileSpreadsheet className="w-5 h-5 text-primary" />
            Relatório Operacional e Presença
          </h2>
          <p className="text-xs text-muted-foreground mt-1">
            Data: <span className="text-foreground font-semibold">{dataFormatada}</span> • Regional: <span className="text-foreground font-semibold">{regionalLabel[selectedRegional] || 'Todas'}</span>
          </p>
        </div>

        <div className="flex items-center gap-2.5 flex-wrap">
          <Button onClick={handlePrint} variant="default" className="gap-2 shadow-md">
            <Printer className="w-4 h-4" />
            Imprimir / Salvar em PDF
          </Button>
          <Button onClick={handleExportCSV} variant="outline" className="gap-2">
            <Download className="w-4 h-4" />
            Exportar CSV
          </Button>
        </div>
      </div>

      {/* Cards de Métricas do Dia */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <Card className="border-border">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Veículos em Operação</p>
              <p className="text-2xl font-bold text-foreground mt-1">{stats.totalVeiculos}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
              <Car className="w-5 h-5" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-border">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Colaboradores Presentes</p>
              <p className="text-2xl font-bold text-emerald-400 mt-1">{stats.totalPresentes}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-400">
              <UserCheck className="w-5 h-5" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-border">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Faltas no Dia</p>
              <p className="text-2xl font-bold text-rose-400 mt-1">{stats.totalFaltas}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-rose-500/10 flex items-center justify-center text-rose-400">
              <UserX className="w-5 h-5" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-border">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Substitutos Atuando</p>
              <p className="text-2xl font-bold text-amber-400 mt-1">{stats.totalSubst}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-amber-500/10 flex items-center justify-center text-amber-400">
              <RefreshCw className="w-5 h-5" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Seção 1: Faltas Registradas no Dia */}
      <Card className="border-border">
        <CardHeader className="pb-3 border-b border-border/60">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2 text-foreground">
              <UserX className="w-4 h-4 text-rose-400" />
              Faltas Registradas no Dia ({faltasDoDia.length})
            </CardTitle>
            <Badge variant="outline" className="text-xs border-rose-500/30 text-rose-400 bg-rose-500/10">
              {dataFormatada}
            </Badge>
          </div>
          <CardDescription>
            Colaboradores ausentes que necessitam de acompanhamento ou substituição
          </CardDescription>
        </CardHeader>
        <CardContent className="p-4">
          {faltasDoDia.length === 0 ? (
            <div className="flex items-center justify-center gap-2 py-8 text-sm text-emerald-400 font-medium">
              <CheckCircle2 className="w-5 h-5" />
              Nenhuma falta registrada no dia! 100% de presença operacional.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs border-collapse">
                <thead>
                  <tr className="border-b border-border text-muted-foreground font-semibold">
                    <th className="py-2.5 px-3">Colaborador</th>
                    <th className="py-2.5 px-3">Cargo</th>
                    <th className="py-2.5 px-3">Placa do Veículo</th>
                    <th className="py-2.5 px-3">Unidade</th>
                    <th className="py-2.5 px-3">Motivo da Falta</th>
                    <th className="py-2.5 px-3">Substituto Designado</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40">
                  {faltasDoDia.map(({ colab, veiculo }) => (
                    <tr key={colab.id} className="hover:bg-muted/30">
                      <td className="py-2.5 px-3 font-semibold text-foreground">{colab.nome}</td>
                      <td className="py-2.5 px-3 text-muted-foreground">{colab.cargo}</td>
                      <td className="py-2.5 px-3 font-mono font-bold text-foreground">{veiculo.placa}</td>
                      <td className="py-2.5 px-3 text-muted-foreground">
                        {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </td>
                      <td className="py-2.5 px-3">
                        <span className="inline-flex items-center gap-1 text-rose-400 font-medium bg-rose-500/10 px-2 py-0.5 rounded-md border border-rose-500/20">
                          {colab.motivoFalta || 'Falta Injustificada'}
                        </span>
                      </td>
                      <td className="py-2.5 px-3">
                        {colab.substitutoNome ? (
                          <span className="text-amber-400 font-medium flex items-center gap-1">
                            <RefreshCw className="w-3 h-3" />
                            {colab.substitutoNome}
                          </span>
                        ) : (
                          <span className="text-muted-foreground italic">Sem substituto</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Seção 2: Estrutura dos Carros e Equipes */}
      <Card className="border-border">
        <CardHeader className="pb-3 border-b border-border/60">
          <CardTitle className="text-base flex items-center gap-2 text-foreground">
            <Car className="w-4 h-4 text-primary" />
            Ocupação dos Carros e Distribuição das Equipes ({veiculosFiltrados.length} Veículos)
          </CardTitle>
          <CardDescription>
            Detalhamento de cada carro com os ocupantes presentes, faltas e equipe de trabalho
          </CardDescription>
        </CardHeader>
        <CardContent className="p-4 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {veiculosFiltrados.map((v) => {
              const assentos = [
                { pos: 'Motorista', colab: v.assentos?.motorista },
                { pos: 'Dianteiro Dir.', colab: v.assentos?.frenteDir },
                { pos: 'Traseiro Esq.', colab: v.assentos?.trasEsq },
                { pos: 'Traseiro Dir.', colab: v.assentos?.trasDir },
              ];

              const totalAtivos = assentos.filter(
                (a) => a.colab && (a.colab.status === 'presente' || a.colab.status === 'substituto')
              ).length;

              return (
                <div key={v.id} className="p-4 rounded-xl border border-border bg-card/40 space-y-3">
                  <div className="flex items-center justify-between pb-2 border-b border-border/60">
                    <div className="flex items-center gap-2">
                      <span className="font-mono text-sm font-black text-foreground bg-muted px-2.5 py-1 rounded-lg border border-border">
                        {v.placa}
                      </span>
                      <span className="text-xs text-muted-foreground">{v.modelo}</span>
                    </div>
                    <Badge variant="outline" className={cn(
                      'text-[11px]',
                      totalAtivos === 4 ? 'text-emerald-400 border-emerald-500/30 bg-emerald-500/10' : 'text-amber-400 border-amber-500/30 bg-amber-500/10'
                    )}>
                      {totalAtivos}/4 Ocupantes
                    </Badge>
                  </div>

                  <div className="grid grid-cols-2 gap-2 text-xs">
                    {assentos.map((a, idx) => {
                      const c = a.colab;
                      if (!c) {
                        return (
                          <div key={idx} className="p-2 rounded-lg bg-muted/20 border border-dashed border-border/60 text-muted-foreground">
                            <span className="text-[10px] text-muted-foreground/70 block">{a.pos}</span>
                            <span className="font-medium italic">Vazio</span>
                          </div>
                        );
                      }

                      const isFalta = c.status === 'falta';
                      const isSubst = c.status === 'substituto';
                      const nome = isSubst && c.substitutoNome ? c.substitutoNome : c.nome;

                      return (
                        <div
                          key={idx}
                          className={cn(
                            'p-2 rounded-lg border flex flex-col justify-between',
                            isFalta
                              ? 'bg-rose-500/10 border-rose-500/30 text-rose-300'
                              : isSubst
                              ? 'bg-amber-500/10 border-amber-500/30 text-amber-300'
                              : 'bg-muted/30 border-border/60 text-foreground'
                          )}
                        >
                          <div>
                            <span className="text-[10px] text-muted-foreground block">{a.pos}</span>
                            <span className="font-semibold truncate block">{nome}</span>
                          </div>
                          <span className="text-[9px] font-medium mt-1 uppercase">
                            {isFalta ? 'Falta' : isSubst ? 'Substituto' : 'Presente'}
                          </span>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Seção 3: Histórico de Faltas por Mês */}
      <Card className="border-border">
        <CardHeader className="pb-3 border-b border-border/60">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-base flex items-center gap-2 text-foreground">
                <Calendar className="w-4 h-4 text-primary" />
                Histórico Acumulado de Faltas por Mês
              </CardTitle>
              <CardDescription>
                Selecione o mês desejado para ver os colaboradores com faltas no período
              </CardDescription>
            </div>

            <div className="flex items-center gap-2 overflow-x-auto pb-1 max-w-full">
              {MESES.map((mes, idx) => (
                <button
                  key={mes}
                  onClick={() => setSelectedMonth(idx)}
                  className={cn(
                    'px-3 py-1.5 rounded-lg text-xs font-semibold whitespace-nowrap transition-all border',
                    selectedMonth === idx
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                      : 'border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/40'
                  )}
                >
                  {mes}
                </button>
              ))}
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-4">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs border-collapse">
              <thead>
                <tr className="border-b border-border text-muted-foreground font-semibold">
                  <th className="py-2.5 px-3">Colaborador</th>
                  <th className="py-2.5 px-3">Função</th>
                  <th className="py-2.5 px-3">Regional</th>
                  <th className="py-2.5 px-3 text-center">Faltas em {dadosMes.mes}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/40">
                {dadosMes.faltas.map((f, i) => (
                  <tr key={i} className="hover:bg-muted/30">
                    <td className="py-2.5 px-3 font-semibold text-foreground">{f.nome}</td>
                    <td className="py-2.5 px-3 text-muted-foreground">{f.cargo}</td>
                    <td className="py-2.5 px-3 text-muted-foreground">{f.regional}</td>
                    <td className="py-2.5 px-3 text-center">
                      <Badge variant="outline" className="border-rose-500/30 text-rose-400 bg-rose-500/10 font-bold">
                        {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'}
                      </Badge>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

