import React, { useState, useMemo } from 'react';
import { Users, Search, Filter, Phone, Badge as BadgeIcon, MapPin, ChevronDown, ChevronUp, UserCheck, UserX, RefreshCw } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

interface CollaboratorsManagementProps {
  veiculos: Veiculo[];
  colaboradoresReserva: Colaborador[];
}

const posicaoLabel: Record<string, string> = {
  motorista: 'Motorista / Líder',
  frente_dir: 'Dianteiro Direito',
  tras_esq: 'Traseiro Esquerdo',
  tras_dir: 'Traseiro Direito',
};

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos,
  colaboradoresReserva,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const colaboradores: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      const assentos: Array<{ colab: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome,
          cargo: colab.cargo,
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status,
          motivoFalta: colab.motivoFalta,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId,
          equipeNumero: colab.equipeNumero,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo,
          veiculoPlaca: v.placa,
          regional: v.regional,
        });
      });
    });
    return lista;
  }, [veiculos]);

  const colaboradoresFiltrados = useMemo(() => {
    return colaboradores.filter((c) => {
      const matchSearch =
        !search ||
        c.nome.toLowerCase().includes(search.toLowerCase()) ||
        c.cargo.toLowerCase().includes(search.toLowerCase()) ||
        c.matricula.toLowerCase().includes(search.toLowerCase()) ||
        c.veiculoPrefixo.toLowerCase().includes(search.toLowerCase());
      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      return matchSearch && matchStatus;
    });
  }, [colaboradores, search, filterStatus]);

  const stats = useMemo(() => {
    const presentes = colaboradores.filter((c) => c.status === 'presente').length;
    const faltas = colaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = colaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: colaboradores.length };
  }, [colaboradores]);

  const reservaFiltrada = useMemo(() => {
    if (!search) return colaboradoresReserva || [];
    return (colaboradoresReserva || []).filter(
      (c) =>
        c.nome.toLowerCase().includes(search.toLowerCase()) ||
        c.cargo.toLowerCase().includes(search.toLowerCase())
    );
  }, [colaboradoresReserva, search]);

  return (
    <div className="space-y-6">
      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: 'Total', value: stats.total, color: 'text-foreground', bg: 'bg-muted/40' },
          { label: 'Presentes', value: stats.presentes, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
          { label: 'Faltas', value: stats.faltas, color: 'text-rose-400', bg: 'bg-rose-500/10' },
          { label: 'Substitutos', value: stats.substitutos, color: 'text-amber-400', bg: 'bg-amber-500/10' },
        ].map((s) => (
          <Card key={s.label} className={cn('border-border/60', s.bg)}>
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
              <p className={cn('text-2xl font-extrabold mt-1', s.color)}>{s.value}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Filtros */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por nome, cargo, matrícula ou veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
        <div className="flex gap-2 flex-wrap">
          {(['todos', 'presente', 'falta', 'substituto'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setFilterStatus(s)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all',
                filterStatus === s
                  ? 'bg-primary text-primary-foreground border-primary'
                  : 'border-border text-muted-foreground hover:text-foreground hover:bg-muted'
              )}
            >
              {s === 'todos' ? 'Todos' : s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Lista de Colaboradores */}
      <Card className="border-border/60">
        <CardHeader className="pb-3 border-b border-border/40">
          <CardTitle className="text-base flex items-center gap-2">
            <Users className="w-4 h-4 text-primary" />
            Colaboradores em Campo
            <span className="ml-auto text-xs font-normal text-muted-foreground">
              {colaboradoresFiltrados.length} de {colaboradores.length}
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {colaboradoresFiltrados.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <UserX className="w-10 h-10 text-muted-foreground/40 mb-3" />
              <p className="text-sm font-semibold text-foreground">Nenhum colaborador encontrado</p>
              <p className="text-xs text-muted-foreground mt-1">Tente ajustar os filtros de busca</p>
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {colaboradoresFiltrados.map((c) => {
                const isExpanded = expandedId === c.id;
                const sc = statusConfig[c.status] ?? statusConfig.presente;
                return (
                  <div key={c.id} className="hover:bg-muted/30 transition-colors">
                    <div
                      className="flex items-center gap-3 p-4 cursor-pointer"
                      onClick={() => setExpandedId(isExpanded ? null : c.id)}
                    >
                      {/* Avatar */}
                      <div className="w-10 h-10 rounded-full overflow-hidden bg-muted shrink-0 border border-border/60">
                        {c.foto ? (
                          <img src={c.foto} alt={c.nome} className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-sm font-bold text-muted-foreground">
                            {c.nome.charAt(0)}
                          </div>
                        )}
                      </div>

                      {/* Info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="text-sm font-bold text-foreground truncate">{c.nome}</span>
                          <span className={cn(
                            'inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold border',
                            sc.className
                          )}>
                            {sc.label}
                          </span>
                        </div>
                        <p className="text-xs text-muted-foreground mt-0.5 truncate">
                          {c.cargo} · {posicaoLabel[c.posicaoVeiculo] ?? c.posicaoVeiculo}
                        </p>
                        <div className="flex items-center gap-2 mt-0.5">
                          <span className="text-[11px] font-mono text-muted-foreground">{c.veiculoPrefixo}</span>
                          <span className="text-muted-foreground text-[10px]">·</span>
                          <span className="text-[11px] text-muted-foreground">{regionalLabel[c.regional] ?? c.regional}</span>
                        </div>
                      </div>

                      {/* Expand toggle */}
                      <button className="p-1 text-muted-foreground hover:text-foreground transition-colors shrink-0">
                        {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                      </button>
                    </div>

                    {/* Expanded Details */}
                    {isExpanded && (
                      <div className="px-4 pb-4 pt-0 grid grid-cols-2 sm:grid-cols-3 gap-3 bg-muted/20 border-t border-border/30">
                        <div>
                          <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">Matrícula</p>
                          <p className="text-xs font-mono font-bold text-foreground">{c.matricula || '—'}</p>
                        </div>
                        <div>
                          <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">Telefone</p>
                          <p className="text-xs font-mono text-foreground">{c.telefone || '—'}</p>
                        </div>
                        <div>
                          <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">Equipe</p>
                          <p className="text-xs font-semibold text-foreground">{c.equipeId} (Nº {c.equipeNumero})</p>
                        </div>
                        <div>
                          <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">Placa</p>
                          <p className="text-xs font-mono text-foreground">{c.veiculoPlaca}</p>
                        </div>
                        {c.motivoFalta && (
                          <div className="col-span-2">
                            <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">Motivo da Falta</p>
                            <p className="text-xs text-rose-400 font-semibold">{c.motivoFalta}</p>
                          </div>
                        )}
                        {c.substitutoNome && (
                          <div className="col-span-2">
                            <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold mb-0.5">Substituto</p>
                            <p className="text-xs text-amber-400 font-semibold">{c.substitutoNome}</p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Reserva */}
      {reservaFiltrada.length > 0 && (
        <Card className="border-border/60">
          <CardHeader className="pb-3 border-b border-border/40">
            <CardTitle className="text-base flex items-center gap-2">
              <RefreshCw className="w-4 h-4 text-amber-400" />
              Colaboradores em Reserva
              <span className="ml-auto text-xs font-normal text-muted-foreground">
                {reservaFiltrada.length} disponíveis
              </span>
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y divide-border/40">
              {reservaFiltrada.map((c) => (
                <div key={c.id} className="flex items-center gap-3 p-4 hover:bg-muted/30 transition-colors">
                  <div className="w-9 h-9 rounded-full overflow-hidden bg-muted shrink-0 border border-border/60">
                    {c.foto ? (
                      <img src={c.foto} alt={c.nome} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-xs font-bold text-muted-foreground">
                        {c.nome.charAt(0)}
                      </div>
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-bold text-foreground truncate">{c.nome}</p>
                    <p className="text-xs text-muted-foreground truncate">{c.cargo}</p>
                  </div>
                  <Badge variant="outline" className="text-[10px] border-amber-500/30 bg-amber-500/10 text-amber-400 shrink-0">
                    Reserva
                  </Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

