    const presentes = (colaboradores || []).filter((c) => c.status === 'presente').length;
    const faltas = (colaboradores || []).filter((c) => c.status === 'falta').length;
    const substitutos = (colaboradores || []).filter((c) => c.status === 'substituto').length;
