                          ) : (
                            <span className="font-bold text-muted-foreground text-sm">{c.nome.charAt(0)}</span>
                          )}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <p className="text-sm font-bold text-foreground">{c.nome}</p>
                            <Badge variant="outline" className="text-[10px] py-0 px-1.5 border-border/60">
                              {c.matricula}
