import React, { useState, useMemo } from 'react';
import { Search, Filter, AlertCircle, CheckCircle2, RefreshCw, MapPin } from 'lucide-react';
import { VehicleTopView, VehicleZone } from './VehicleTopView';
import { AttendanceModal } from './AttendanceModal';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  selectedRegional: string;
  onUpdateStatus: (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => void;
  colaboradoresReserva?: Colaborador[];
}

const regionalNomeCompleto: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
  todas: 'Todas as Unidades',
};

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos,
  selectedRegional,
  onUpdateStatus,
  colaboradoresReserva,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<string>('todos');
  const [activeModal, setActiveModal] = useState<{
    veiculoId: string;
    colaborador: Colaborador;
  } | null>(null);

  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      const matchRegional =
        selectedRegional === 'todas' || v.regional === selectedRegional;

      const matchSearch =
        !search ||
        v.placa?.toLowerCase().includes(search.toLowerCase()) ||
        v.modelo?.toLowerCase().includes(search.toLowerCase()) ||
        v.assentos?.motorista?.nome?.toLowerCase().includes(search.toLowerCase()) ||
        v.assentos?.frenteDir?.nome?.toLowerCase().includes(search.toLowerCase()) ||
        v.assentos?.trasEsq?.nome?.toLowerCase().includes(search.toLowerCase()) ||
        v.assentos?.trasDir?.nome?.toLowerCase().includes(search.toLowerCase());

      const assentosList = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      let matchStatus = true;
      if (filterStatus === 'completo') {
        matchStatus = assentosList.every(
          (c) => c && (c.status === 'presente' || c.status === 'substituto')
        );
      } else if (filterStatus === 'com_falta') {
        matchStatus = assentosList.some((c) => c && c.status === 'falta');
      } else if (filterStatus === 'com_substituto') {
        matchStatus = assentosList.some((c) => c && c.status === 'substituto');
      }

      return matchRegional && matchSearch && matchStatus;
    });
  }, [veiculos, selectedRegional, search, filterStatus]);

  const handleAssentoClick = (
    veiculoId: string,
    _posicao: VehicleZone,
    colaborador: Colaborador
  ) => {
    setActiveModal({ veiculoId, colaborador });
  };

  const handleSaveModal = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    onUpdateStatus(veiculoId, colaboradorId, novoStatus, motivoFalta, substituto);
    setActiveModal(null);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3 items-stretch sm:items-center justify-between">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por placa ou colaborador..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>

        <div className="flex gap-2 flex-wrap">
          {[
            { id: 'todos', label: 'Todos' },
            { id: 'completo', label: 'Completos' },
            { id: 'com_falta', label: 'Com Falta' },
            { id: 'com_substituto', label: 'Substitutos' },
          ].map((f) => (
            <button
              key={f.id}
              onClick={() => setFilterStatus(f.id)}
              className={cn(
                'px-3.5 py-1.5 rounded-xl text-xs font-semibold border transition-all',
                filterStatus === f.id
                  ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                  : 'border-border text-muted-foreground hover:text-foreground hover:bg-muted'
              )}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <Card className="border-dashed border-2">
          <CardContent className="flex flex-col items-center justify-center py-16 text-center">
            <AlertCircle className="w-12 h-12 text-muted-foreground/40 mb-3" />
            <p className="text-base font-semibold text-foreground">Nenhum veículo encontrado</p>
            <p className="text-xs text-muted-foreground mt-1 max-w-sm">
              Não encontramos nenhum veículo com os critérios de busca selecionados.
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {veiculosFiltrados.map((veiculo) => {
            const assentosList = [
              veiculo.assentos?.motorista,
              veiculo.assentos?.frenteDir,
              veiculo.assentos?.trasEsq,
              veiculo.assentos?.trasDir,
            ].filter(Boolean);

            const faltasCount = assentosList.filter((c) => c?.status === 'falta').length;
            const substCount = assentosList.filter((c) => c?.status === 'substituto').length;
            const presentesCount = assentosList.filter((c) => c?.status === 'presente').length;

            const isRibas = veiculo.regional === 'ribas';
            const nomeUnidade = regionalNomeCompleto[veiculo.regional] || 'Unidade';

            return (
              <Card
                key={veiculo.id}
                className={cn(
                  'overflow-hidden border-2 transition-all hover:shadow-xl group flex flex-col',
                  faltasCount > 0
                    ? 'border-rose-500/40 bg-gradient-to-b from-rose-500/[0.02] to-card'
                    : substCount > 0
                    ? 'border-amber-500/40 bg-gradient-to-b from-amber-500/[0.02] to-card'
                    : 'border-border/70 hover:border-primary/50'
                )}
              >
                {/* Header do Card com Placa e Unidade em Alto Destaque */}
                <div className="px-5 py-4 border-b border-border/60 bg-muted/20">
                  <div className="flex items-center justify-between gap-3">
                    {/* Placa do Carro Estilizada */}
                    <div className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-background border-2 border-border shadow-inner">
                      <span className="font-mono text-base font-extrabold text-foreground tracking-wider uppercase">
                        {veiculo.placa}
                      </span>
                    </div>

                    {/* Unidade em Alto Destaque e Visibilidade */}
                    <div
                      className={cn(
                        'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold border shadow-sm tracking-wide',
                        isRibas
                          ? 'bg-sky-500/15 text-sky-400 border-sky-500/40'
                          : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/40'
                      )}
                    >
                      <MapPin className="w-3.5 h-3.5 shrink-0" />
                      <span>{nomeUnidade}</span>
                    </div>
                  </div>

                  {/* Badges de Status Geral do Carro */}
                  <div className="flex items-center gap-2 mt-3 pt-2.5 border-t border-border/30">
                    <span className="text-[11px] font-semibold text-muted-foreground">
                      Status da Tripulação:
                    </span>
                    <div className="flex items-center gap-1.5 ml-auto">
                      {faltasCount === 0 && substCount === 0 ? (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                          <CheckCircle2 className="w-3 h-3" />
                          100% Presente
                        </span>
                      ) : (
                        <>
                          {presentesCount > 0 && (
                            <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                              {presentesCount} pres.
                            </span>
                          )}
                          {substCount > 0 && (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-500/15 text-amber-400 border border-amber-500/30">
                              <RefreshCw className="w-2.5 h-2.5" />
                              {substCount} subst.
                            </span>
                          )}
                          {faltasCount > 0 && (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-rose-500/15 text-rose-400 border border-rose-500/30">
                              <AlertCircle className="w-2.5 h-2.5" />
                              {faltasCount} falta{faltasCount > 1 ? 's' : ''}
                            </span>
                          )}
                        </>
                      )}
                    </div>
                  </div>
                </div>

                {/* Vista dos Assentos / Colaboradores */}
                <CardContent className="p-4 flex-1 flex flex-col justify-center">
                  <VehicleTopView
                    veiculo={veiculo}
                    onAssentoClick={(pos, colab) => handleAssentoClick(veiculo.id, pos, colab)}
                  />
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Modal de Presença */}
      {activeModal && (
        <AttendanceModal
          colaborador={activeModal.colaborador}
          veiculoId={activeModal.veiculoId}
          onClose={() => setActiveModal(null)}
          onSave={handleSaveModal}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}
    </div>
  );
};

