import React, { useState } from 'react';
import { X, Users, Car, Check, MapPin } from 'lucide-react';
import { Button } from './ui/button';
import { Colaborador, Veiculo, Regional } from '../types';

export interface NewTeamModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit?: (dados: any) => void;
  onSalvar?: (novaEquipe: any) => void;
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
}

export const NewTeamModal: React.FC<NewTeamModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  onSalvar,
  veiculos = [],
  colaboradoresReserva = [],
}) => {
  const [nomeEquipe, setNomeEquipe] = useState('');
  const [regional, setRegional] = useState<Regional>('ribas');
  const [veiculoId, setVeiculoId] = useState('');
  const [lider, setLider] = useState('');

  if (!isOpen) return null;

  const handleSalvar = (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
      id: `eq-${Date.now()}`,
      nome: nomeEquipe,
      regional,
      veiculoId,
      lider,
    };

    if (onSubmit) onSubmit(payload);
    if (onSalvar) onSalvar(payload);
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="bg-card border border-border/80 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-150"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-6 py-5 border-b border-border/60 bg-gradient-to-r from-primary/10 via-card to-card">
          <div className="flex items-center gap-3">
