              <h2 className="text-base font-bold text-foreground">Nova Equipe</h2>
              <p className="text-xs text-muted-foreground">Cadastrar e alocar nova equipe de campo</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <form onSubmit={handleSalvar} className="p-6 space-y-4">
          <div>
            <label className="text-xs font-semibold text-foreground uppercase tracking-wider mb-1.5 block">
              Nome ou Código da Equipe
            </label>
            <input
              type="text"
              required
              placeholder="Ex: Equipe Florestal 105"
              value={nomeEquipe}
              onChange={(e) => setNomeEquipe(e.target.value)}
              className="w-full h-10 px-3 text-sm bg-muted/40 border border-border/80 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground placeholder:text-muted-foreground"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-foreground uppercase tracking-wider mb-1.5 block">
                Regional
              </label>
              <select
                value={regional}
                onChange={(e) => setRegional(e.target.value as Regional)}
                className="w-full h-10 px-3 text-sm bg-muted/40 border border-border/80 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
              >
                <option value="ribas">Ribas do Rio Pardo</option>
                <option value="agua_clara">Água Clara</option>
              </select>
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground uppercase tracking-wider mb-1.5 block">
                Veículo
              </label>
              <select
                value={veiculoId}
                onChange={(e) => setVeiculoId(e.target.value)}
                className="w-full h-10 px-3 text-sm bg-muted/40 border border-border/80 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
              >
                <option value="">Selecione um veículo...</option>
                {veiculos.map((v) => (
                  <option key={v.id} value={v.id}>
                    {v.placa} - {v.modelo}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-foreground uppercase tracking-wider mb-1.5 block">
              Líder / Responsável
            </label>
            <input
              type="text"
              placeholder="Nome do líder da equipe"
              value={lider}
              onChange={(e) => setLider(e.target.value)}
              className="w-full h-10 px-3 text-sm bg-muted/40 border border-border/80 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground placeholder:text-muted-foreground"
            />
          </div>

          <div className="flex justify-end gap-2.5 pt-4 border-t border-border/60">
            <Button type="button" variant="outline" onClick={onClose} size="sm">
              Cancelar
            </Button>
            <Button type="submit" size="sm" className="gap-1.5">
              <Check className="w-4 h-4" />
              Salvar Equipe
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

