import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { AttendanceModal } from './components/AttendanceModal';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta, MetricasGerais } from './types';
import { VehicleZone } from './components/VehicleTopView';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'relatorios' | 'colaboradores'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [searchTerm, setSearchTerm] = useState('');
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  // Estados de Modais
  const [isAttendanceModalOpen, setIsAttendanceModalOpen] = useState(false);
  const [selectedColaboradorModal, setSelectedColaboradorModal] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
  } | null>(null);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Cálculo das Métricas Gerais
  const metricas: MetricasGerais = useMemo(() => {
    const veiculosFiltrados = (veiculos || []).filter(
      (v) => selectedRegional === 'todas' || v?.regional === selectedRegional
    );

    let totalColabs = 0;
    let presentes = 0;
    let faltas = 0;
    let substitutos = 0;

    veiculosFiltrados.forEach((v) => {
      if (!v?.assentos) return;
      const assentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ].filter(Boolean);

      assentos.forEach((c) => {
        if (!c) return;
        totalColabs++;
        if (c.status === 'presente') presentes++;
        else if (c.status === 'falta') faltas++;
        else if (c.status === 'substituto') substitutos++;
      });
    });

    const taxaPresenca = totalColabs > 0 ? Math.round(((presentes + substitutos) / totalColabs) * 100) : 100;

    return {
      totalVeiculos: veiculosFiltrados.length,
      veiculosAtivos: veiculosFiltrados.filter((v) => v?.statusOperacional === 'ativo').length,
      totalEquipes: veiculosFiltrados.length * 2,
      equipesCompletas: veiculosFiltrados.length * 2,
      equipesIncompletas: 0,
      totalColaboradores: totalColabs,
      colaboradoresPresentes: presentes,
      colaboradoresFaltas: faltas,
      colaboradoresSubstitutos: substitutos,
      taxaPresenca,
    };
  }, [veiculos, selectedRegional]);

  // Abertura do Modal de Presença
  const handleOpenAttendance = (veiculoId: string, _zone: VehicleZone | string, colaborador: Colaborador) => {
    if (!colaborador) return;
    setSelectedColaboradorModal({ colaborador, veiculoId });
    setIsAttendanceModalOpen(true);
  };

  // Salvar Presença / Falta / Substituto
  const handleSaveAttendance = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId || !v.assentos) return v;

        const atualizarAssento = (colab?: Colaborador): Colaborador | undefined => {
          if (!colab || colab.id !== colaboradorId) return colab;
          return {
            ...colab,
            status: novoStatus,
            motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
            substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
            substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
          };
        };

        return {
          ...v,
          assentos: {
            motorista: atualizarAssento(v.assentos.motorista)!,
            frenteDir: atualizarAssento(v.assentos.frenteDir)!,
            trasEsq: atualizarAssento(v.assentos.trasEsq)!,
            trasDir: atualizarAssento(v.assentos.trasDir)!,
          },
        };
      })
    );

    setIsAttendanceModalOpen(false);
    setSelectedColaboradorModal(null);
  };

  // Criação de Nova Equipe
  const handleCreateTeam = (dados: any) => {
    setIsNewTeamModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      {/* Navbar Superior */}
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        selectedRegional={selectedRegional}
        setSelectedRegional={setSelectedRegional}
        selectedDate={selectedDate}
        setSelectedDate={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Cabeçalho de Métricas */}
        <MetricsHeader
          metricas={metricas}
          selectedRegional={selectedRegional}
        />

        {/* Abas */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            onAssentoClick={handleOpenAttendance}
            selectedRegional={selectedRegional}
            searchTerm={searchTerm}
            setSearchTerm={setSearchTerm}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            onNovaEquipe={() => setIsNewTeamModalOpen(true)}
            onOpenAttendanceModal={(colab, vtrId) => handleOpenAttendance(vtrId, 'motorista', colab)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}
      </main>

      {/* Modal de Registro de Presença / Falta */}
      {isAttendanceModalOpen && selectedColaboradorModal && (
        <AttendanceModal
          colaborador={selectedColaboradorModal.colaborador}
          veiculoId={selectedColaboradorModal.veiculoId}
          onClose={() => {
            setIsAttendanceModalOpen(false);
            setSelectedColaboradorModal(null);
          }}
          onSave={handleSaveAttendance}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}

      {/* Modal de Criação de Nova Equipe */}
      {isNewTeamModalOpen && (
        <NewTeamModal
          isOpen={isNewTeamModalOpen}
          onClose={() => setIsNewTeamModalOpen(false)}
          onSubmit={handleCreateTeam}
          veiculos={veiculos}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}
    </div>
  );
}

