export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos com proteção a nulos
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return selectedRegional === 'todas' || v.regional === selectedRegional;
    });
  }, [veiculos, selectedRegional]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const dadosMes = useMemo(() => {
    return HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMonth) || HISTORICO_MENSAL_FALTAS[0];
  }, [selectedMonth]);

  const handleImprimir = () => {
    window.print();
  };

  const handleExportCSV = () => {
    const cabecalho = 'Data;Placa;Regional;Colaborador;Cargo;Status;MotivoFalta;Substituto\n';
    const linhas = (todosColaboradores || []).map(({ colab, veiculo }) => {
      const reg = veiculo?.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
      const motivo = colab?.motivoFalta || '-';
      const subst = colab?.substitutoNome || '-';
      return `${dataFormatada};${veiculo?.placa || '-'};${reg};"${colab?.nome || ''}";"${colab?.cargo || ''}";${colab?.status || ''};"${motivo}";"${subst}"`;
    }).join('\n');

    const blob = new Blob(['\uFEFF' + cabecalho + linhas], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `relatorio_presenca_${dataFormatada.replace(/\//g, '-')}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Ações do Relatório */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 rounded-2xl bg-card border border-border">
        <div>
          <div className="flex items-center gap-2">
            <Calendar className="w-5 h-5 text-primary" />
            <h2 className="text-base font-bold text-foreground">Relatório Diário Operacional</h2>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            Data: <span className="text-foreground font-semibold">{dataFormatada}</span> • Unidade: <span className="text-foreground font-semibold">{regionalLabel[selectedRegional] || 'Todas'}</span>
          </p>
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportCSV}
            className="flex-1 sm:flex-initial gap-2 text-xs"
          >
            <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
            Exportar CSV
          </Button>

          <Button
            size="sm"
            onClick={handleImprimir}
            className="flex-1 sm:flex-initial gap-2 text-xs bg-primary text-primary-foreground shadow-lg hover:bg-primary/90"
          >
            <Printer className="w-4 h-4" />
            Salvar em PDF / Imprimir
          </Button>
        </div>
      </div>

      {/* Cards de Métricas Rápidas */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card className="border-border/60 bg-muted/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-muted-foreground">Veículos Operando</span>
              <Car className="w-4 h-4 text-primary" />
            </div>
            <p className="text-2xl font-black text-foreground mt-1">{stats.totalVeiculos}</p>
            <p className="text-[11px] text-muted-foreground mt-0.5">2 equipes por veículo</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-emerald-500/5 border-emerald-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-emerald-400">Presentes</span>
              <UserCheck className="w-4 h-4 text-emerald-400" />
            </div>
            <p className="text-2xl font-black text-emerald-400 mt-1">{stats.totalPresentes}</p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Efetivo confirmado</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-rose-500/5 border-rose-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-rose-400">Faltas do Dia</span>
              <UserX className="w-4 h-4 text-rose-400" />
            </div>
            <p className="text-2xl font-black text-rose-400 mt-1">{stats.totalFaltas}</p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Necessitam atenção</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-amber-500/5 border-amber-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-amber-400">Substitutos</span>
              <RefreshCw className="w-4 h-4 text-amber-400" />
            </div>
            <p className="text-2xl font-black text-amber-400 mt-1">{stats.totalSubst}</p>
            <p className="text-[11px] text-muted-foreground mt-0.5">Cobriram ausências</p>
          </CardContent>
        </Card>
      </div>

      {/* SEÇÃO 1: Faltas Registradas no Dia */}
      <Card className="border-rose-500/30 bg-rose-500/[0.02]">
        <CardHeader className="pb-3 border-b border-border/40">
          <CardTitle className="text-base flex items-center justify-between">
            <div className="flex items-center gap-2 text-rose-400">
              <UserX className="w-4 h-4" />
              <span>Faltas Registradas no Dia ({stats.totalFaltas})</span>
            </div>
            <Badge variant="destructive" className="text-[10px]">Atenção Operacional</Badge>
          </CardTitle>
          <CardDescription className="text-xs">
            Colaboradores ausentes hoje com justificativa e impacto por veículo
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0">
          {faltasDoDia.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center px-4">
              <CheckCircle2 className="w-8 h-8 text-emerald-400 mb-2" />
              <p className="text-sm font-semibold text-foreground">Nenhuma falta registrada hoje!</p>
              <p className="text-xs text-muted-foreground">Todos os colaboradores estão presentes ou foram substituídos com sucesso.</p>
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {faltasDoDia.map(({ colab, veiculo }) => (
                <div key={colab.id} className="p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-rose-500/5 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full border-2 border-rose-500/40 bg-rose-500/10 flex items-center justify-center font-bold text-rose-400 shrink-0">
                      {colab.foto ? (
                        <img src={colab.foto} alt={colab.nome} className="w-full h-full object-cover rounded-full" />
                      ) : (
                        colab.nome.charAt(0)
                      )}
