            {veiculosFiltrados.map((v) => {
              const ocupantes = [
                v.assentos?.motorista,
                v.assentos?.frenteDir,
                v.assentos?.trasEsq,
                v.assentos?.trasDir,
              ].filter((c): c is Colaborador => Boolean(c));

              const presentesCount = ocupantes.filter((c) => c.status === 'presente').length;
              const faltasCount = ocupantes.filter((c) => c.status === 'falta').length;
              const substCount = ocupantes.filter((c) => c.status === 'substituto').length;

              return (
                <div
                  key={v.id}
                  className="rounded-xl border border-border/80 bg-card/70 p-4 space-y-3 hover:border-primary/50 transition-all shadow-sm"
                >
                  {/* Cabeçalho do Carro */}
                  <div className="flex items-center justify-between pb-2 border-b border-border/40">
                    <div className="flex items-center gap-2">
                      <div className="px-2.5 py-1 rounded-lg bg-primary/10 border border-primary/20 text-primary font-black text-sm tracking-wide">
                        {v.placa}
                      </div>
                      <span className="text-xs text-muted-foreground font-medium">
                        {v.modelo}
                      </span>
                    </div>

                    <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full bg-muted text-muted-foreground">
                      {v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                    </span>
                  </div>

                  {/* Resumo das 2 Equipes do Carro */}
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div className="p-2.5 rounded-lg bg-muted/30 border border-border/40">
                      <div className="flex items-center justify-between mb-1.5">
                        <span className="font-bold text-foreground">Equipe 01 (Frente)</span>
                        <Badge variant="outline" className="text-[9px] py-0 px-1.5">2 vagas</Badge>
                      </div>
                      <div className="space-y-1">
                        <div className="flex items-center justify-between text-[11px]">
                          <span className="text-muted-foreground truncate max-w-[110px]">
                            {v.assentos?.motorista?.nome || 'Motorista Vago'}
                          </span>
                          <span className={cn(
                            'text-[9px] font-bold px-1.5 rounded',
                            v.assentos?.motorista?.status === 'falta' ? 'bg-rose-500/20 text-rose-400' :
                            v.assentos?.motorista?.status === 'substituto' ? 'bg-amber-500/20 text-amber-400' : 'bg-emerald-500/20 text-emerald-400'
                          )}>
                            {v.assentos?.motorista?.status || 'vago'}
                          </span>
                        </div>
                        <div className="flex items-center justify-between text-[11px]">
                          <span className="text-muted-foreground truncate max-w-[110px]">
                            {v.assentos?.frenteDir?.nome || 'Passageiro Vago'}
                          </span>
                          <span className={cn(
                            'text-[9px] font-bold px-1.5 rounded',
                            v.assentos?.frenteDir?.status === 'falta' ? 'bg-rose-500/20 text-rose-400' :
                            v.assentos?.frenteDir?.status === 'substituto' ? 'bg-amber-500/20 text-amber-400' : 'bg-emerald-500/20 text-emerald-400'
                          )}>
                            {v.assentos?.frenteDir?.status || 'vago'}
                          </span>
                        </div>
                      </div>
                    </div>

                    <div className="p-2.5 rounded-lg bg-muted/30 border border-border/40">
                      <div className="flex items-center justify-between mb-1.5">
                        <span className="font-bold text-foreground">Equipe 02 (Traseira)</span>
                        <Badge variant="outline" className="text-[9px] py-0 px-1.5">2 vagas</Badge>
                      </div>
                      <div className="space-y-1">
                        <div className="flex items-center justify-between text-[11px]">
                          <span className="text-muted-foreground truncate max-w-[110px]">
                            {v.assentos?.trasEsq?.nome || 'Traseiro Esq Vago'}
                          </span>
                          <span className={cn(
                            'text-[9px] font-bold px-1.5 rounded',
                            v.assentos?.trasEsq?.status === 'falta' ? 'bg-rose-500/20 text-rose-400' :
                            v.assentos?.trasEsq?.status === 'substituto' ? 'bg-amber-500/20 text-amber-400' : 'bg-emerald-500/20 text-emerald-400'
                          )}>
                            {v.assentos?.trasEsq?.status || 'vago'}
                          </span>
                        </div>
                        <div className="flex items-center justify-between text-[11px]">
                          <span className="text-muted-foreground truncate max-w-[110px]">
                            {v.assentos?.trasDir?.nome || 'Traseiro Dir Vago'}
                          </span>
                          <span className={cn(
                            'text-[9px] font-bold px-1.5 rounded',
                            v.assentos?.trasDir?.status === 'falta' ? 'bg-rose-500/20 text-rose-400' :
                            v.assentos?.trasDir?.status === 'substituto' ? 'bg-amber-500/20 text-amber-400' : 'bg-emerald-500/20 text-emerald-400'
                          )}>
                            {v.assentos?.trasDir?.status || 'vago'}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Status rodapé do veículo */}
                  <div className="flex items-center justify-between pt-1 text-[11px] text-muted-foreground border-t border-border/30">
                    <span>Ocupação: <strong className="text-foreground">{ocupantes.length}/4 integrantes</strong> (2 equipes)</span>
                    <div className="flex items-center gap-2">
                      <span className="text-emerald-400 font-semibold">{presentesCount} pres.</span>
                      {faltasCount > 0 && <span className="text-rose-400 font-semibold">{faltasCount} falta</span>}
                      {substCount > 0 && <span className="text-amber-400 font-semibold">{substCount} subst.</span>}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* SEÇÃO 3: Análise Mensal de Faltas */}
      <Card className="border-border/60">
        <CardHeader className="pb-3 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-primary" />
                Histórico e Reincidência de Faltas por Mês
              </CardTitle>
              <CardDescription className="text-xs">
                Selecione o mês para visualizar os colaboradores com maiores índices de faltas
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2">
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="h-9 px-3 text-xs bg-muted border border-border rounded-xl text-foreground font-semibold focus:outline-none focus:ring-2 focus:ring-primary"
              >
                {MESES.map((m, idx) => (
                  <option key={m} value={idx}>{m} / 2026</option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-4">
          <div className="space-y-3">
            <p className="text-xs font-semibold text-muted-foreground">
              Colaboradores com faltas acumuladas em <span className="text-foreground font-bold">{MESES[selectedMonth]}</span>:
            </p>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {(dadosMes?.faltas || []).map((f, idx) => (
                <div
                  key={idx}
                  className="flex items-center justify-between p-3 rounded-xl border border-border/60 bg-muted/20 hover:border-border transition-colors"
                >
                  <div>
                    <p className="text-xs font-bold text-foreground">{f.nome}</p>
                    <p className="text-[11px] text-muted-foreground">{f.cargo}</p>
                    <p className="text-[10px] text-muted-foreground mt-0.5">{f.regional}</p>
                  </div>
                  <div className="text-right">
                    <span className="inline-block px-2.5 py-1 rounded-full text-xs font-black bg-rose-500/15 text-rose-400 border border-rose-500/30">
                      {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

