export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional: initialRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(initialRegional || 'todas');

  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos por unidade selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return unidadeFiltro === 'todas' || v.regional === unidadeFiltro;
    });
  }, [veiculos, unidadeFiltro]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const dadosMes = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMonth) || HISTORICO_MENSAL_FALTAS[0];
    const listaFaltas = (mesObj?.faltas || []).filter((f) => {
      if (unidadeFiltro === 'todas') return true;
      if (unidadeFiltro === 'ribas') return f.regional.includes('Ribas');
      if (unidadeFiltro === 'agua_clara') return f.regional.includes('Água Clara');
      return true;
    });
    const maxFaltas = listaFaltas.length > 0 ? Math.max(...listaFaltas.map((f) => f.totalFaltas)) : 1;
    return {
      mes: mesObj.mes,
      faltas: listaFaltas,
      maxFaltas,
    };
  }, [selectedMonth, unidadeFiltro]);

  // Gerador de PDF Completo (Janela de impressão nativa)
  const handleGerarPDF = () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const faltasHtml = faltasDoDia.length > 0
      ? faltasDoDia.map(f => `
        <tr style="border-bottom: 1px solid #e2e8f0;">
          <td style="padding: 8px 12px; font-weight: bold; color: #1e293b;">${f.colab.nome}</td>
          <td style="padding: 8px 12px; color: #64748b;">${f.colab.cargo || 'Operador'}</td>
          <td style="padding: 8px 12px; color: #475569;">${f.veiculo.placa}</td>
          <td style="padding: 8px 12px; color: #475569;">${regionalLabel[f.veiculo.regional]}</td>
          <td style="padding: 8px 12px; color: #e11d48; font-weight: 600;">${f.colab.motivoFalta || 'Não Informado'}</td>
        </tr>
      `).join('')
      : `<tr><td colspan="5" style="padding: 16px; text-align: center; color: #16a34a; font-weight: bold;">Nenhuma falta registrada nesta unidade na data de hoje! 🎉</td></tr>`;

    const veiculosHtml = (veiculosFiltrados || []).map(v => {
      const colabs = [v.assentos?.motorista, v.assentos?.frenteDir, v.assentos?.trasEsq, v.assentos?.trasDir].filter(Boolean) as Colaborador[];
      const ativos = colabs.filter(c => c.status === 'presente' || c.status === 'substituto');
      const faltas = colabs.filter(c => c.status === 'falta');

      const tipoEquipe = ativos.length >= 3 ? 'Trio' : ativos.length === 2 ? 'Dupla' : `${ativos.length} pessoa(s)`;
      const statusBadge = faltas.length === 0 
        ? '<span style="background: #dcfce7; color: #166534; padding: 3px 8px; border-radius: 9999px; font-size: 11px; font-weight: bold;">Completo</span>'
        : `<span style="background: #fee2e2; color: #991b1b; padding: 3px 8px; border-radius: 9999px; font-size: 11px; font-weight: bold;">${faltas.length} Falta(s)</span>`;

      return `
        <div style="border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; margin-bottom: 12px; background: #f8fafc; page-break-inside: avoid;">
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 8px; margin-bottom: 8px;">
            <div>
              <span style="font-size: 14px; font-weight: bold; color: #0f172a; background: #e2e8f0; padding: 2px 8px; border-radius: 4px;">${v.placa}</span>
              <span style="font-size: 12px; color: #64748b; margin-left: 8px;">${v.modelo}</span>
              <span style="font-size: 11px; font-weight: 600; color: #0284c7; margin-left: 8px; background: #e0f2fe; padding: 2px 6px; border-radius: 4px;">${regionalLabel[v.regional]}</span>
            </div>
            <div>
              <span style="font-size: 12px; font-weight: 600; color: #334155; margin-right: 8px;">${tipoEquipe} (${ativos.length}/4)</span>
              ${statusBadge}
            </div>
          </div>
          <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px;">
            ${colabs.map(c => {
              const statusCor = c.status === 'falta' ? '#e11d48' : c.status === 'substituto' ? '#d97706' : '#16a34a';
              const statusTexto = c.status === 'falta' ? `FALTA (${c.motivoFalta || 'Injustificada'})` : c.status === 'substituto' ? `SUBSTITUTO (${c.substitutoNome || ''})` : 'PRESENTE';
              return `
                <div style="background: #ffffff; border: 1px solid #e2e8f0; padding: 6px 10px; border-radius: 6px; font-size: 11px;">
                  <div style="font-weight: bold; color: #1e293b;">${c.status === 'substituto' ? (c.substitutoNome || c.nome) : c.nome}</div>
                  <div style="color: #64748b; font-size: 10px;">${c.cargo || 'Operador'}</div>
                  <div style="color: ${statusCor}; font-weight: bold; font-size: 10px; margin-top: 2px;">• ${statusTexto}</div>
                </div>
              `;
            }).join('')}
          </div>
        </div>
      `;
    }).join('');

    const htmlContent = `
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="UTF-8">
        <title>Diário Operacional - ${dataFormatada}</title>
        <style>
          @page { size: A4; margin: 15mm; }
          body { font-family: system-ui, -apple-system, sans-serif; color: #1e293b; margin: 0; padding: 0; }
          h1, h2, h3 { margin: 0; }
          table { width: 100%; border-collapse: collapse; text-align: left; }
        </style>
      </head>
      <body>
        <div style="border-bottom: 2px solid #0284c7; padding-bottom: 12px; margin-bottom: 20px; display: flex; justify-content: space-between; align-items: flex-end;">
          <div>
            <h1 style="font-size: 20px; color: #0f172a;">RELATÓRIO DIÁRIO OPERACIONAL</h1>
            <p style="font-size: 12px; color: #64748b; margin-top: 4px;">Controle de Faltas, Lotação e Composição de Equipes nos Veículos</p>
          </div>
          <div style="text-align: right; font-size: 12px;">
            <div><strong>Data:</strong> ${dataFormatada}</div>
            <div><strong>Unidade:</strong> ${regionalLabel[unidadeFiltro]}</div>
          </div>
        </div>

        <!-- Métricas Rápidas -->
        <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 20px;">
          <div style="background: #f1f5f9; padding: 10px; border-radius: 6px; text-align: center;">
            <div style="font-size: 10px; color: #64748b; text-transform: uppercase;">Veículos</div>
            <div style="font-size: 18px; font-weight: bold; color: #0f172a;">${stats.totalVeiculos}</div>
          </div>
