                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </CardContent>
        </Card>
      </div>

      {/* Seção Gráfica: Ranking de Faltas por Mês */}
      <Card className="border-border/60">
        <CardHeader className="pb-4 border-b border-border/40">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-primary" />
                Ranking de Faltas por Mês
              </CardTitle>
              <CardDescription className="text-xs text-muted-foreground">
                Colaboradores com maior índice de ausências no mês de {dadosMes.mes} ({regionalLabel[unidadeFiltro]})
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-xs font-bold text-muted-foreground">Mês:</span>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="h-9 px-3 text-xs bg-muted/40 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground font-semibold cursor-pointer"
              >
                {MESES.map((m, idx) => (
                  <option key={m} value={idx}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-6">
          {dadosMes.faltas.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground text-sm">
              Nenhuma falta registrada para a unidade selecionada em {dadosMes.mes}.
            </div>
          ) : (
            <div className="space-y-4">
              {dadosMes.faltas.map((item, idx) => {
                const percent = Math.round((item.totalFaltas / dadosMes.maxFaltas) * 100);
                return (
                  <div key={item.nome} className="space-y-1.5">
                    <div className="flex items-center justify-between text-xs font-semibold">
                      <div className="flex items-center gap-2">
                        <span className={cn(
                          'w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold',
                          idx === 0 ? 'bg-rose-500 text-white' : 'bg-muted text-muted-foreground'
                        )}>
                          {idx + 1}
                        </span>
                        <span className="text-foreground">{item.nome}</span>
                        <span className="text-muted-foreground font-normal">({item.cargo})</span>
                        <Badge variant="outline" className="text-[10px] py-0 px-1.5 border-border/60">
                          {item.regional}
                        </Badge>
                      </div>
                      <span className="text-rose-400 font-black">{item.totalFaltas} falta(s)</span>
                    </div>
                    {/* Barra de Progresso */}
                    <div className="h-2.5 w-full bg-muted/50 rounded-full overflow-hidden p-0.5 border border-border/30">
                      <div
                        className={cn(
                          'h-full rounded-full transition-all duration-500',
                          idx === 0
                            ? 'bg-gradient-to-r from-rose-500 to-red-500 shadow-sm'
                            : idx === 1
                            ? 'bg-gradient-to-r from-amber-500 to-rose-400'
                            : 'bg-primary/70'
                        )}
                        style={{ width: `${percent}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

