export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional: initialRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(initialRegional || 'todas');

  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos por unidade selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return unidadeFiltro === 'todas' || v.regional === unidadeFiltro;
    });
  }, [veiculos, unidadeFiltro]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const dadosMes = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMonth) || HISTORICO_MENSAL_FALTAS[0];
    const listaFaltas = (mesObj?.faltas || []).filter((f) => {
      if (unidadeFiltro === 'todas') return true;
      if (unidadeFiltro === 'ribas') return f.regional.includes('Ribas');
      if (unidadeFiltro === 'agua_clara') return f.regional.includes('Água Clara');
      return true;
    });
    const maxFaltas = listaFaltas.length > 0 ? Math.max(...listaFaltas.map((f) => f.totalFaltas)) : 1;
    return {
      mes: mesObj.mes,
      faltas: listaFaltas,
      maxFaltas,
    };
  }, [selectedMonth, unidadeFiltro]);

  // Gerador de PDF Completo (Janela de impressão nativa)
  const handleGerarPDF = () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const faltasHtml = faltasDoDia.length > 0
      ? faltasDoDia.map(f => `
        <tr style="border-bottom: 1px solid #e2e8f0;">
          <td style="padding: 8px 12px; font-weight: bold; color: #1e293b;">${f.colab.nome}</td>
          <td style="padding: 8px 12px; color: #64748b;">${f.colab.cargo || 'Operador'}</td>
          <td style="padding: 8px 12px; color: #475569;">${f.veiculo.placa}</td>
          <td style="padding: 8px 12px; color: #475569;">${regionalLabel[f.veiculo.regional]}</td>
          <td style="padding: 8px 12px; color: #e11d48; font-weight: 600;">${f.colab.motivoFalta || 'Não Informado'}</td>
        </tr>
      `).join('')
      : `<tr><td colspan="5" style="padding: 16px; text-align: center; color: #16a34a; font-weight: bold;">Nenhuma falta registrada nesta unidade na data de hoje! 🎉</td></tr>`;

    const veiculosHtml = (veiculosFiltrados || []).map(v => {
      const colabs = [v.assentos?.motorista, v.assentos?.frenteDir, v.assentos?.trasEsq, v.assentos?.trasDir].filter(Boolean) as Colaborador[];
      const ativos = colabs.filter(c => c.status === 'presente' || c.status === 'substituto');
      const faltas = colabs.filter(c => c.status === 'falta');

      const tipoEquipe = ativos.length >= 3 ? 'Trio' : ativos.length === 2 ? 'Dupla' : `${ativos.length} pessoa(s)`;
      const statusBadge = faltas.length === 0 
        ? '<span style="background: #dcfce7; color: #166534; padding: 3px 8px; border-radius: 9999px; font-size: 11px; font-weight: bold;">Completo</span>'
        : `<span style="background: #fee2e2; color: #991b1b; padding: 3px 8px; border-radius: 9999px; font-size: 11px; font-weight: bold;">${faltas.length} Falta(s)</span>`;

      return `
        <div style="border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px; margin-bottom: 12px; background: #f8fafc; page-break-inside: avoid;">
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 8px; margin-bottom: 8px;">
            <div>
              <span style="font-size: 14px; font-weight: bold; color: #0f172a; background: #e2e8f0; padding: 2px 8px; border-radius: 4px;">${v.placa}</span>
              <span style="font-size: 12px; color: #64748b; margin-left: 8px;">${v.modelo}</span>
              <span style="font-size: 11px; font-weight: 600; color: #0284c7; margin-left: 8px; background: #e0f2fe; padding: 2px 6px; border-radius: 4px;">${regionalLabel[v.regional]}</span>
            </div>
            <div>
              <span style="font-size: 12px; font-weight: 600; color: #334155; margin-right: 8px;">${tipoEquipe} (${ativos.length}/4)</span>
              ${statusBadge}
            </div>
          </div>
          <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px;">
            ${colabs.map(c => {
              const statusCor = c.status === 'falta' ? '#e11d48' : c.status === 'substituto' ? '#d97706' : '#16a34a';
              const statusTexto = c.status === 'falta' ? `FALTA (${c.motivoFalta || 'Injustificada'})` : c.status === 'substituto' ? `SUBSTITUTO (${c.substitutoNome || ''})` : 'PRESENTE';
              return `
                <div style="background: #ffffff; border: 1px solid #e2e8f0; padding: 6px 10px; border-radius: 6px; font-size: 11px;">
                  <div style="font-weight: bold; color: #1e293b;">${c.status === 'substituto' ? (c.substitutoNome || c.nome) : c.nome}</div>
                  <div style="color: #64748b; font-size: 10px;">${c.cargo || 'Operador'}</div>
                  <div style="color: ${statusCor}; font-weight: bold; font-size: 10px; margin-top: 2px;">• ${statusTexto}</div>
                </div>
              `;
            }).join('')}
          </div>
        </div>
      `;
    }).join('');

    const htmlContent = `
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="UTF-8">
        <title>Diário Operacional - ${dataFormatada}</title>
        <style>
          @page { size: A4; margin: 15mm; }
          body { font-family: system-ui, -apple-system, sans-serif; color: #1e293b; margin: 0; padding: 0; }
          h1, h2, h3 { margin: 0; }
          table { width: 100%; border-collapse: collapse; text-align: left; }
        </style>
      </head>
      <body>
        <div style="border-bottom: 2px solid #0284c7; padding-bottom: 12px; margin-bottom: 20px; display: flex; justify-content: space-between; align-items: flex-end;">
          <div>
            <h1 style="font-size: 20px; color: #0f172a;">RELATÓRIO DIÁRIO OPERACIONAL</h1>
            <p style="font-size: 12px; color: #64748b; margin-top: 4px;">Controle de Faltas, Lotação e Composição de Equipes nos Veículos</p>
          </div>
          <div style="text-align: right; font-size: 12px;">
            <div><strong>Data:</strong> ${dataFormatada}</div>
            <div><strong>Unidade:</strong> ${regionalLabel[unidadeFiltro]}</div>
          </div>
        </div>

        <!-- Métricas Rápidas -->
        <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 20px;">
          <div style="background: #f1f5f9; padding: 10px; border-radius: 6px; text-align: center;">
            <div style="font-size: 10px; color: #64748b; text-transform: uppercase;">Veículos</div>
            <div style="font-size: 18px; font-weight: bold; color: #0f172a;">${stats.totalVeiculos}</div>
          </div>
          <div style="background: #dcfce7; padding: 10px; border-radius: 6px; text-align: center;">
            <div style="font-size: 10px; color: #166534; text-transform: uppercase;">Presentes</div>
            <div style="font-size: 18px; font-weight: bold; color: #16a34a;">${stats.totalPresentes}</div>
          </div>
          <div style="background: #fee2e2; padding: 10px; border-radius: 6px; text-align: center;">
            <div style="font-size: 10px; color: #991b1b; text-transform: uppercase;">Faltas do Dia</div>
            <div style="font-size: 18px; font-weight: bold; color: #e11d48;">${stats.totalFaltas}</div>
          </div>
          <div style="background: #fef3c7; padding: 10px; border-radius: 6px; text-align: center;">
            <div style="font-size: 10px; color: #92400e; text-transform: uppercase;">Substitutos</div>
            <div style="font-size: 18px; font-weight: bold; color: #d97706;">${stats.totalSubst}</div>
          </div>
        </div>

        <!-- Seção de Faltas do Dia -->
        <div style="margin-bottom: 24px;">
          <h2 style="font-size: 14px; color: #0f172a; border-bottom: 1px solid #cbd5e1; padding-bottom: 6px; margin-bottom: 10px;">
            1. Relação de Faltas Registradas no Dia
          </h2>
          <table style="font-size: 11px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 6px; overflow: hidden;">
            <thead>
              <tr style="background: #f8fafc; border-bottom: 1px solid #cbd5e1; color: #475569;">
                <th style="padding: 8px 12px;">Colaborador</th>
                <th style="padding: 8px 12px;">Cargo</th>
                <th style="padding: 8px 12px;">Veículo (Placa)</th>
                <th style="padding: 8px 12px;">Unidade</th>
                <th style="padding: 8px 12px;">Motivo da Falta</th>
              </tr>
            </thead>
            <tbody>
              ${faltasHtml}
            </tbody>
          </table>
        </div>

        <!-- Seção de Veículos e Equipes -->
        <div>
          <h2 style="font-size: 14px; color: #0f172a; border-bottom: 1px solid #cbd5e1; padding-bottom: 6px; margin-bottom: 12px;">
            2. Composição de Cada Veículo e Quantidade de Equipes
          </h2>
          ${veiculosHtml}
        </div>

        <script>
          window.onload = function() {
            window.print();
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  return (
    <div className="space-y-6">
      {/* Top Banner Diário Operacional */}
      <Card className="border-border/60 bg-gradient-to-r from-card/80 via-primary/5 to-card/80 backdrop-blur-md overflow-hidden">
        <CardHeader className="pb-4">
          <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
            <div className="space-y-1">
              <div className="flex items-center gap-2 flex-wrap">
                <Badge variant="outline" className="border-primary/40 text-primary bg-primary/10 gap-1.5 py-1">
                  <Calendar className="w-3.5 h-3.5" />
                  Diário Operacional · {dataFormatada}
                </Badge>
                <Badge variant="outline" className="border-emerald-500/40 text-emerald-400 bg-emerald-500/10">
                  {stats.taxaPresenca}% Efetividade
                </Badge>
              </div>
              <CardTitle className="text-xl sm:text-2xl font-black tracking-tight text-foreground flex items-center gap-2">
                Relatórios e Diário de Campo
              </CardTitle>
              <CardDescription className="text-sm text-muted-foreground max-w-2xl">
                Consolidação detalhada das faltas do dia, composição de cada carro e ranking mensal por unidade.
              </CardDescription>
            </div>

            {/* Ações de Impressão e PDF */}
            <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto">
              <Button
                onClick={handleGerarPDF}
                size="lg"
                className="bg-primary hover:bg-primary/90 text-primary-foreground font-bold shadow-lg shadow-primary/25 gap-2 w-full sm:w-auto cursor-pointer"
              >
                <Printer className="w-4 h-4" />
                Salvar em PDF / Imprimir Diário
              </Button>
            </div>
          </div>

          {/* SELETOR DE UNIDADE NO DIÁRIO OPERACIONAL */}
          <div className="pt-4 mt-4 border-t border-border/50 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 bg-muted/20 p-3 rounded-xl">
            <div className="flex items-center gap-2 text-xs font-bold text-foreground">
              <div className="w-6 h-6 rounded-lg bg-primary/15 border border-primary/30 flex items-center justify-center text-primary">
                <MapPin className="w-3.5 h-3.5" />
              </div>
              <span>Selecione a Unidade:</span>
            </div>

            <div className="flex items-center gap-1.5 flex-wrap w-full sm:w-auto">
              {[
                { key: 'todas' as const, label: 'Todas as Unidades' },
                { key: 'ribas' as const, label: 'Ribas do Rio Pardo' },
                { key: 'agua_clara' as const, label: 'Água Clara' },
              ].map((btn) => (
                <button
                  key={btn.key}
                  type="button"
                  onClick={() => setUnidadeFiltro(btn.key)}
                  className={cn(
                    'flex-1 sm:flex-none px-3.5 py-1.5 rounded-lg text-xs font-bold transition-all border cursor-pointer flex items-center justify-center gap-1.5',
                    unidadeFiltro === btn.key
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm scale-102'
                      : 'border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/60'
                  )}
                >
                  <span className={cn(
                    'w-2 h-2 rounded-full',
                    btn.key === 'todas' ? 'bg-sky-400' : btn.key === 'ribas' ? 'bg-indigo-400' : 'bg-emerald-400'
                  )} />
                  {btn.label}
                </button>
              ))}
            </div>
          </div>
        </CardHeader>

        {/* Resumo de Indicadores */}
        <CardContent className="pt-0">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-3">
            <div className="p-3.5 rounded-xl border border-border/60 bg-muted/20">
              <p className="text-xs text-muted-foreground font-medium">Veículos ({regionalLabel[unidadeFiltro]})</p>
              <p className="text-2xl font-black text-foreground mt-1">{stats.totalVeiculos}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-emerald-500/30 bg-emerald-500/10">
              <p className="text-xs text-emerald-400 font-medium">Presentes em Campo</p>
              <p className="text-2xl font-black text-emerald-400 mt-1">{stats.totalPresentes}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-rose-500/30 bg-rose-500/10">
              <p className="text-xs text-rose-400 font-medium">Faltas Registradas</p>
              <p className="text-2xl font-black text-rose-400 mt-1">{stats.totalFaltas}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-amber-500/30 bg-amber-500/10">
              <p className="text-xs text-amber-400 font-medium">Substitutos Atuando</p>
              <p className="text-2xl font-black text-amber-400 mt-1">{stats.totalSubst}</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Grid Principal: Faltas do Dia & Distribuição por Carro */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Card 1: Faltas do Dia */}
        <Card className="border-border/60">
          <CardHeader className="pb-3 border-b border-border/40">
            <div className="flex items-center justify-between">
              <CardTitle className="text-base flex items-center gap-2">
                <ShieldAlert className="w-4 h-4 text-rose-400" />
                Faltas de Hoje ({regionalLabel[unidadeFiltro]})
              </CardTitle>
              <Badge variant="destructive" className="font-bold">
                {faltasDoDia.length} ausência(s)
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="p-4">
            {faltasDoDia.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-10 text-center">
                <CheckCircle2 className="w-10 h-10 text-emerald-400 mb-2" />
                <p className="text-sm font-bold text-foreground">Nenhuma falta nesta unidade hoje!</p>
                <p className="text-xs text-muted-foreground mt-0.5">Todos os colaboradores escalados estão presentes ou com substitutos.</p>
              </div>
            ) : (
              <div className="space-y-3">
                {faltasDoDia.map(({ colab, veiculo }) => (
                  <div
                    key={colab.id}
                    className="p-3 rounded-xl border border-rose-500/30 bg-rose-500/5 flex items-center justify-between gap-3"
                  >
                    <div className="min-w-0">
                      <p className="text-sm font-bold text-foreground truncate">{colab.nome}</p>
                      <p className="text-xs text-muted-foreground">{colab.cargo || 'Operador Florestal'}</p>
                      <div className="flex items-center gap-2 mt-1.5 flex-wrap">
                        <span className="text-[11px] font-bold text-foreground bg-muted/60 px-2 py-0.5 rounded border border-border/50">
                          {veiculo.placa}
                        </span>
                        <span className="text-[11px] font-semibold text-rose-400 bg-rose-500/10 px-2 py-0.5 rounded border border-rose-500/20">
                          {colab.motivoFalta || 'Falta Injustificada'}
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Card 2: Como Ficou Cada Carro */}
        <Card className="border-border/60">
          <CardHeader className="pb-3 border-b border-border/40">
            <div className="flex items-center justify-between">
              <CardTitle className="text-base flex items-center gap-2">
                <Car className="w-4 h-4 text-primary" />
                Lotação e Equipes por Carro ({regionalLabel[unidadeFiltro]})
              </CardTitle>
              <Badge variant="outline" className="border-primary/40 text-primary">
                {veiculosFiltrados.length} veículos
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="p-4 space-y-3 max-h-[420px] overflow-y-auto pr-1">
            {veiculosFiltrados.map((v) => {
              const colabs = [v.assentos?.motorista, v.assentos?.frenteDir, v.assentos?.trasEsq, v.assentos?.trasDir].filter(Boolean) as Colaborador[];
              const ativos = colabs.filter((c) => c.status === 'presente' || c.status === 'substituto');
              const faltas = colabs.filter((c) => c.status === 'falta');

              return (
                <div
                  key={v.id}
                  className="p-3.5 rounded-xl border border-border/60 bg-muted/15 hover:bg-muted/30 transition-colors"
                >
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-black text-foreground bg-background/80 px-2 py-0.5 rounded-md border border-border">
                        {v.placa}
                      </span>
                      <span className="text-xs text-muted-foreground font-medium">{v.modelo}</span>
                    </div>
                    <Badge
                      variant={faltas.length === 0 ? 'success' : 'destructive'}
                      className="text-[11px] font-bold"
                    >
                      {ativos.length >= 3 ? 'Trio' : 'Dupla'} ({ativos.length}/4)
                    </Badge>
                  </div>

                  <div className="grid grid-cols-2 gap-2 text-xs">
                    {colabs.map((c) => (
                      <div
                        key={c.id}
                        className={cn(
                          'p-1.5 rounded-lg border flex items-center justify-between',
                          c.status === 'falta'
                            ? 'bg-rose-500/10 border-rose-500/30 text-rose-300'
                            : c.status === 'substituto'
                            ? 'bg-amber-500/10 border-amber-500/30 text-amber-300'
                            : 'bg-background/40 border-border/40 text-foreground'
                        )}
                      >
                        <span className="truncate font-semibold text-[11px]">
                          {c.status === 'substituto' ? (c.substitutoNome || c.nome) : c.nome}
                        </span>
                        <span className="text-[10px] uppercase font-bold shrink-0 ml-1">
                          {c.status === 'falta' ? 'Falta' : c.status === 'substituto' ? 'Subst' : 'Pres'}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </CardContent>
        </Card>
      </div>

      {/* Seção Gráfica: Ranking de Faltas por Mês */}
      <Card className="border-border/60">
        <CardHeader className="pb-4 border-b border-border/40">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-primary" />
                Ranking de Faltas por Mês
              </CardTitle>
              <CardDescription className="text-xs text-muted-foreground">
                Colaboradores com maior índice de ausências no mês de {dadosMes.mes} ({regionalLabel[unidadeFiltro]})
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-xs font-bold text-muted-foreground">Mês:</span>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="h-9 px-3 text-xs bg-muted/40 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground font-semibold cursor-pointer"
              >
                {MESES.map((m, idx) => (
                  <option key={m} value={idx}>
                    {m}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-6">
          {dadosMes.faltas.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground text-sm">
              Nenhuma falta registrada para a unidade selecionada em {dadosMes.mes}.
            </div>
          ) : (
            <div className="space-y-4">
              {dadosMes.faltas.map((item, idx) => {
                const percent = Math.round((item.totalFaltas / dadosMes.maxFaltas) * 100);
                return (
                  <div key={item.nome} className="space-y-1.5">
                    <div className="flex items-center justify-between text-xs font-semibold">
                      <div className="flex items-center gap-2">
                        <span className={cn(
                          'w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold',
                          idx === 0 ? 'bg-rose-500 text-white' : 'bg-muted text-muted-foreground'
                        )}>
                          {idx + 1}
                        </span>
                        <span className="text-foreground">{item.nome}</span>
                        <span className="text-muted-foreground font-normal">({item.cargo})</span>
                        <Badge variant="outline" className="text-[10px] py-0 px-1.5 border-border/60">
                          {item.regional}
                        </Badge>
                      </div>
                      <span className="text-rose-400 font-black">{item.totalFaltas} falta(s)</span>
                    </div>
                    {/* Barra de Progresso */}
                    <div className="h-2.5 w-full bg-muted/50 rounded-full overflow-hidden p-0.5 border border-border/30">
                      <div
                        className={cn(
                          'h-full rounded-full transition-all duration-500',
                          idx === 0
                            ? 'bg-gradient-to-r from-rose-500 to-red-500 shadow-sm'
                            : idx === 1
                            ? 'bg-gradient-to-r from-amber-500 to-rose-400'
                            : 'bg-primary/70'
                        )}
                        style={{ width: `${percent}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

