import React, { useState, useEffect } from 'react';
import { Calendar, Users, Car, FileSpreadsheet, ChevronLeft, ChevronRight, X } from 'lucide-react';
import { Button } from './ui/button';
import { Regional } from '../types';

interface NavbarProps {
  activeTab: 'veiculos' | 'equipes' | 'relatorios' | 'colaboradores';
  setActiveTab: (tab: 'veiculos' | 'equipes' | 'relatorios' | 'colaboradores') => void;
  selectedRegional: Regional;
  setSelectedRegional: (regional: Regional) => void;
  selectedDate: Date;
  setSelectedDate?: (date: Date) => void;
  onNovaEquipeClick?: () => void;
}

const DIAS_SEMANA_FULL = [
  'Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira',
  'Quinta-feira', 'Sexta-feira', 'Sábado',
];

const MESES = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro',
];

const DIAS_SEMANA = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];

export const Navbar: React.FC<NavbarProps> = ({
  activeTab,
  setActiveTab,
  selectedDate,
  setSelectedDate,
  onNovaEquipeClick,
}) => {
  const [calendarOpen, setCalendarOpen] = useState(false);
  const [viewDate, setViewDate] = useState(new Date(selectedDate instanceof Date && !isNaN(selectedDate.getTime()) ? selectedDate : new Date()));

  const dataValida = selectedDate instanceof Date && !isNaN(selectedDate.getTime())
    ? selectedDate
    : new Date();

  const dia = String(dataValida.getDate()).padStart(2, '0');
  const mes = String(dataValida.getMonth() + 1).padStart(2, '0');
  const ano = dataValida.getFullYear();
  const dataNumerica = `${dia}/${mes}/${ano}`;
  const diaSemana = DIAS_SEMANA_FULL[dataValida.getDay()];

  useEffect(() => {
    if (calendarOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [calendarOpen]);

  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const handlePrevMonth = () => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() - 1, 1));
  const handleNextMonth = () => setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + 1, 1));

  const handleSelectDay = (day: number) => {
    const newDate = new Date(viewDate.getFullYear(), viewDate.getMonth(), day);
    setSelectedDate?.(newDate);
    setCalendarOpen(false);
  };

  const handleToday = () => {
    const today = new Date();
    setViewDate(today);
    setSelectedDate?.(today);
    setCalendarOpen(false);
  };

  const isToday = (day: number) => {
    const today = new Date();
    return (
      day === today.getDate() &&
      viewDate.getMonth() === today.getMonth() &&
      viewDate.getFullYear() === today.getFullYear()
    );
  };

  const isSelected = (day: number) =>
    day === dataValida.getDate() &&
    viewDate.getMonth() === dataValida.getMonth() &&
    viewDate.getFullYear() === dataValida.getFullYear();

  const daysInMonth = getDaysInMonth(viewDate.getFullYear(), viewDate.getMonth());
  const firstDay = getFirstDayOfMonth(viewDate.getFullYear(), viewDate.getMonth());
  const blanks = Array(firstDay).fill(null);
  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

  const tabs = [
    { id: 'veiculos' as const, label: 'Veículos', icon: Car },
    { id: 'equipes' as const, label: 'Equipes', icon: Users },
    { id: 'relatorios' as const, label: 'Relatórios', icon: FileSpreadsheet },
    { id: 'colaboradores' as const, label: 'Colaboradores', icon: Users },
  ];

  return (
    <>
      <header className="sticky top-0 z-40 w-full bg-card/95 backdrop-blur-md border-b border-border/60 shadow-sm transition-all">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

          {/* Linha 1: Logo + Título + Data */}
          <div className="flex items-center justify-between h-16 sm:h-20 gap-4">
            <div className="flex items-center gap-3 shrink-0">
              <img
                src="/logo_inventar_expandWEB_novo2.jpg"
                alt="Logo Inventar"
                className="h-10 md:h-12 w-auto object-contain rounded-lg"
                onError={(e) => {
                  (e.target as HTMLImageElement).style.display = 'none';
                }}
              />
              <div className="flex flex-col">
                <div className="flex items-center gap-1.5">
                  <h1 className="text-base sm:text-lg font-bold tracking-tight text-foreground leading-tight">
                    Controle de Frotas
                  </h1>
                  <span className="hidden sm:inline-flex items-center px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-primary/10 text-primary border border-primary/20">
                    PRO
                  </span>
                </div>
                <button
                  onClick={() => setCalendarOpen(true)}
                  className="flex items-center gap-1.5 mt-0.5 group hover:opacity-80 transition-opacity text-left"
                >
                  <Calendar className="h-3 w-3 text-primary shrink-0" />
                  <span className="text-xs font-semibold text-foreground tracking-tight">
                    {dataNumerica}
                  </span>
                  <span className="text-[11px] font-medium text-muted-foreground hidden sm:inline">
                    • {diaSemana}
                  </span>
                </button>
              </div>
            </div>

            {/* Botão Nova Equipe — canto direito linha 1 */}
            <Button
              onClick={onNovaEquipeClick}
              size="sm"
              className="shrink-0 text-xs gap-1.5 hidden md:flex"
            >
              <Users className="w-3.5 h-3.5" />
              Nova Equipe
            </Button>
          </div>

          {/* Linha 2: Tabs de Navegação */}
          <div className="flex items-center gap-1 pb-2 overflow-x-auto scrollbar-hide">
            {tabs.map(({ id, label, icon: Icon }) => (
              <button
                key={id}
                onClick={() => setActiveTab(id)}
                className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-xs font-semibold transition-all border whitespace-nowrap ${
                  activeTab === id
                    ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                    : 'text-muted-foreground border-transparent hover:text-foreground hover:bg-secondary'
                }`}
              >
                <Icon className="w-3.5 h-3.5" />
                <span>{label}</span>
              </button>
            ))}
          </div>
        </div>
      </header>

      {/* Modal Calendário — Fullscreen Overlay */}
      {calendarOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-background/70 backdrop-blur-md"
          onClick={() => setCalendarOpen(false)}
        >
          <div
            className="relative w-full max-w-sm mx-4 bg-card border border-border/80 rounded-3xl shadow-2xl overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header do Calendário */}
            <div className="flex items-center justify-between px-6 py-5 bg-primary text-primary-foreground">
              <div>
                <p className="text-xs font-medium opacity-80 uppercase tracking-widest">Selecionar Data</p>
                <p className="text-2xl font-extrabold mt-0.5">
                  {MESES[viewDate.getMonth()]} {viewDate.getFullYear()}
                </p>
              </div>
              <button
                onClick={() => setCalendarOpen(false)}
                className="p-2 rounded-xl bg-white/20 hover:bg-white/30 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Data Selecionada */}
            <div className="px-6 py-3 bg-primary/10 border-b border-border/40 flex items-center gap-2">
              <Calendar className="w-4 h-4 text-primary" />
              <span className="text-sm font-bold text-foreground">
                {diaSemana}, {dia}/{mes}/{ano}
              </span>
            </div>

            {/* Navegação Mês */}
            <div className="flex items-center justify-between px-6 py-3 border-b border-border/40">
              <button
                onClick={handlePrevMonth}
                className="p-1.5 rounded-lg hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
              <span className="text-sm font-bold text-foreground">
                {MESES[viewDate.getMonth()]} {viewDate.getFullYear()}
              </span>
              <button
                onClick={handleNextMonth}
                className="p-1.5 rounded-lg hover:bg-muted transition-colors text-muted-foreground hover:text-foreground"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>

            {/* Grid Dias Semana */}
            <div className="px-4 pt-3 pb-1 grid grid-cols-7 gap-1">
              {DIAS_SEMANA.map((d) => (
                <div key={d} className="text-center text-[10px] font-bold text-muted-foreground uppercase py-1">
                  {d}
                </div>
              ))}
            </div>

            {/* Grid Dias */}
            <div className="px-4 pb-4 grid grid-cols-7 gap-1">
              {blanks.map((_, i) => (
                <div key={`blank-${i}`} />
              ))}
              {days.map((day) => (
                <button
                  key={`day-${day}`}
                  onClick={() => handleSelectDay(day)}
                  className={`
                    w-full aspect-square flex items-center justify-center rounded-xl text-sm font-semibold transition-all
                    ${isSelected(day)
                      ? 'bg-primary text-primary-foreground shadow-md scale-105'
                      : isToday(day)
                      ? 'bg-primary/20 text-primary border border-primary/40 font-bold'
                      : 'text-foreground hover:bg-muted hover:scale-105'
                    }
                  `}
                >
                  {day}
                </button>
              ))}
            </div>

            {/* Footer */}
            <div className="px-4 pb-4 flex gap-2">
              <button
                onClick={handleToday}
                className="flex-1 py-2.5 rounded-xl bg-primary/10 text-primary text-sm font-semibold hover:bg-primary/20 transition-colors border border-primary/20"
              >
                Hoje
              </button>
              <button
                onClick={() => setCalendarOpen(false)}
                className="flex-1 py-2.5 rounded-xl bg-muted text-muted-foreground text-sm font-semibold hover:bg-muted/80 transition-colors"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

