import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Regional, Veiculo, Colaborador, StatusPresenca, MotivoFalta } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'relatorios' | 'colaboradores'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Handler para atualizar presença do colaborador
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentos = { ...v.assentos };
        (Object.keys(assentos) as Array<keyof typeof assentos>).forEach((chave) => {
          const colab = assentos[chave];
          if (colab && colab.id === colaboradorId) {
            assentos[chave] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos };
      })
    );
  };

  const handleCreateTeam = (newTeamData: any) => {
    // Adiciona nova equipe / veículo
    if (newTeamData) {
      setVeiculos((prev) => [
        ...prev,
        {
          id: `vtr-${Date.now()}`,
          prefixo: newTeamData.prefixo || `CARRO ${prev.length + 101}`,
          placa: newTeamData.placa || 'NEW-0000',
          modelo: newTeamData.modelo || 'Veículo Operacional',
          ano: 2024,
          regional: newTeamData.regional || 'ribas',
          statusOperacional: 'ativo',
          equipe1Codigo: newTeamData.equipe1Codigo || `EQ-${prev.length + 101}A`,
          equipe2Codigo: newTeamData.equipe2Codigo || `EQ-${prev.length + 101}B`,
          assentos: newTeamData.assentos || {
            motorista: {
              id: `col-${Date.now()}-1`,
              nome: newTeamData.motoristaNome || 'Motorista Titular',
              cargo: 'Motorista / Operador',
              matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
              foto: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80',
              telefone: '(67) 99999-0001',
              status: 'presente',
              equipeId: `EQ-${prev.length + 101}A`,
              equipeNumero: 1,
              posicaoVeiculo: 'motorista',
            },
            frenteDir: {
              id: `col-${Date.now()}-2`,
              nome: newTeamData.ajudante1Nome || 'Ajudante 1',
              cargo: 'Operador de Campo',
              matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
              foto: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80',
              telefone: '(67) 99999-0002',
              status: 'presente',
              equipeId: `EQ-${prev.length + 101}A`,
              equipeNumero: 1,
              posicaoVeiculo: 'frente_dir',
            },
            trasEsq: {
              id: `col-${Date.now()}-3`,
              nome: newTeamData.ajudante2Nome || 'Ajudante 2',
              cargo: 'Técnico Operacional',
              matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
              foto: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&auto=format&fit=crop&q=80',
              telefone: '(67) 99999-0003',
              status: 'presente',
              equipeId: `EQ-${prev.length + 101}B`,
              equipeNumero: 2,
              posicaoVeiculo: 'tras_esq',
            },
            trasDir: {
              id: `col-${Date.now()}-4`,
              nome: newTeamData.ajudante3Nome || 'Ajudante 3',
              cargo: 'Auxiliar Operacional',
              matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
              foto: 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=150&auto=format&fit=crop&q=80',
              telefone: '(67) 99999-0004',
              status: 'presente',
              equipeId: `EQ-${prev.length + 101}B`,
              equipeNumero: 2,
              posicaoVeiculo: 'tras_dir',
            },
          },
        },
      ]);
    }
    setIsNewTeamModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        selectedRegional={selectedRegional}
        setSelectedRegional={setSelectedRegional}
        selectedDate={selectedDate}
        setSelectedDate={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas / Composição de Equipes */}
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
          onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
          onNovaEquipe={() => setIsNewTeamModalOpen(true)}
        />

        {/* Conteúdo da Tab Ativa */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onUpdateStatus={handleUpdateStatus}
            filtroRegional={selectedRegional}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            filtroRegional={selectedRegional}
            onNovaEquipe={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedDate={selectedDate}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}
      </main>

      {/* Modal Nova Equipe */}
      {isNewTeamModalOpen && (
        <NewTeamModal
          isOpen={isNewTeamModalOpen}
          onClose={() => setIsNewTeamModalOpen(false)}
          onSave={handleCreateTeam}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}
    </div>
  );
}

