import React, { useState, useMemo } from 'react';
import { Search, Filter, AlertCircle, CheckCircle2, RefreshCw } from 'lucide-react';
import { VehicleTopView, VehicleZone } from './VehicleTopView';
import { AttendanceModal } from './AttendanceModal';
import { Colaborador, StatusPresenca, MotivoFalta, Veiculo, Regional } from '../types';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  selectedRegional?: Regional | string;
  searchTerm?: string;
  setSearchTerm?: (term: string) => void;
  onUpdateAssento?: (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => void;
  onAssentoClick?: (veiculoId: string, zone: string, colaborador: Colaborador) => void;
  colaboradoresReserva?: Colaborador[];
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  searchTerm: propSearchTerm,
  setSearchTerm: propSetSearchTerm,
  onUpdateAssento,
  onAssentoClick,
  colaboradoresReserva = [],
}) => {
  const [localSearch, setLocalSearch] = useState('');
  const [modalData, setModalData] = useState<{
    veiculoId: string;
    colaborador: Colaborador;
  } | null>(null);

  const searchTerm = propSearchTerm !== undefined ? propSearchTerm : localSearch;
  const handleSearchChange = (val: string) => {
    if (propSetSearchTerm) {
      propSetSearchTerm(val);
    } else {
      setLocalSearch(val);
    }
  };

  const listaSegura = veiculos || [];

  const veiculosFiltrados = useMemo(() => {
    return listaSegura.filter((veiculo) => {
      if (!veiculo) return false;
      const matchesRegional =
        !selectedRegional || selectedRegional === 'todas' || veiculo.regional === selectedRegional;

      const q = (searchTerm || '').toLowerCase();
      const matchesSearch =
        !q ||
        veiculo.placa?.toLowerCase().includes(q) ||
        veiculo.prefixo?.toLowerCase().includes(q) ||
        veiculo.modelo?.toLowerCase().includes(q) ||
        Object.values(veiculo.assentos || {}).some((colab) =>
          colab?.nome?.toLowerCase().includes(q) ||
          colab?.cargo?.toLowerCase().includes(q) ||
          colab?.substitutoNome?.toLowerCase().includes(q)
        );

      return matchesRegional && matchesSearch;
    });
  }, [listaSegura, selectedRegional, searchTerm]);

  const handleAssentoClick = (veiculoId: string, zone: VehicleZone, colaborador: Colaborador) => {
    if (onAssentoClick) {
      onAssentoClick(veiculoId, zone, colaborador);
    }
    setModalData({ veiculoId, colaborador });
  };

  const handleModalSave = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    if (onUpdateAssento) {
      onUpdateAssento(veiculoId, colaboradorId, novoStatus, motivoFalta, substituto);
    }
    setModalData(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row gap-3 items-center justify-between">
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
          <input
            type="text"
            placeholder="Buscar por placa, modelo ou colaborador..."
            value={searchTerm}
            onChange={(e) => handleSearchChange(e.target.value)}
            className="w-full h-10 pl-10 pr-4 text-sm bg-card/60 backdrop-blur-md border border-border/80 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground placeholder:text-muted-foreground shadow-sm"
          />
        </div>
        <div className="text-xs text-muted-foreground self-end sm:self-center font-medium">
          Exibindo <span className="font-bold text-foreground">{veiculosFiltrados.length}</span> de {listaSegura.length} veículos
        </div>
      </div>

      {veiculosFiltrados.length === 0 ? (
        <div className="p-12 text-center border-2 border-dashed border-border/60 rounded-3xl bg-card/40">
          <Filter className="w-10 h-10 text-muted-foreground mx-auto mb-3 opacity-50" />
          <h3 className="text-base font-bold text-foreground">Nenhum veículo encontrado</h3>
          <p className="text-xs text-muted-foreground mt-1">Tente ajustar o termo de pesquisa ou trocar a regional.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {veiculosFiltrados.map((veiculo) => {
            const assentos = Object.values(veiculo.assentos || {}).filter(Boolean) as Colaborador[];
            const presentes = assentos.filter((c) => c.status === 'presente').length;
            const faltas = assentos.filter((c) => c.status === 'falta').length;
            const substitutos = assentos.filter((c) => c.status === 'substituto').length;

            return (
              <div
                key={veiculo.id}
                className="bg-card/75 border border-border/80 rounded-3xl p-5 shadow-lg flex flex-col justify-between hover:border-primary/50 transition-all"
              >
                <div>
                  <div className="flex items-center justify-between pb-3.5 border-b border-border/50 mb-4">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-base tracking-tight text-foreground font-mono bg-muted/60 px-2.5 py-0.5 rounded-lg border border-border/60">
                          {veiculo.placa}
                        </span>
                        <span
                          className={`text-[10px] font-bold px-2 py-0.5 rounded-md uppercase tracking-wider ${
                            veiculo.regional === 'ribas'
                              ? 'bg-sky-500/15 text-sky-400 border border-sky-500/30'
                              : 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/30'
                          }`}
                        >
                          {veiculo.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1 font-medium">{veiculo.modelo}</p>
                    </div>

                    <div className="flex items-center gap-1.5">
                      {presentes > 0 && (
                        <span className="flex items-center gap-1 text-[11px] font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                          <CheckCircle2 className="w-3 h-3" /> {presentes}
                        </span>
                      )}
                      {faltas > 0 && (
                        <span className="flex items-center gap-1 text-[11px] font-bold text-rose-400 bg-rose-500/10 px-2 py-0.5 rounded-full border border-rose-500/20">
                          <AlertCircle className="w-3 h-3" /> {faltas}
                        </span>
                      )}
                      {substitutos > 0 && (
                        <span className="flex items-center gap-1 text-[11px] font-bold text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded-full border border-amber-500/20">
                          <RefreshCw className="w-3 h-3" /> {substitutos}
                        </span>
                      )}
                    </div>
                  </div>

                  <VehicleTopView
                    veiculo={veiculo}
                    onAssentoClick={(zone, colab) => handleAssentoClick(veiculo.id, zone, colab)}
                  />
                </div>
              </div>
            );
          })}
        </div>
      )}

      {modalData && (
        <AttendanceModal
          colaborador={modalData.colaborador}
          veiculoId={modalData.veiculoId}
          onClose={() => setModalData(null)}
          onSave={handleModalSave}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}
    </div>
  );
};

