export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional: initialRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(initialRegional || 'todas');

  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos por unidade selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return unidadeFiltro === 'todas' || v.regional === unidadeFiltro;
    });
  }, [veiculos, unidadeFiltro]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const faltasMesSelecionado = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((m) => m.mesIndex === selectedMonth);
    if (!mesObj) return [];
    if (unidadeFiltro === 'todas') return mesObj.faltas;
    const regionalNome = regionalLabel[unidadeFiltro];
    return (mesObj.faltas || []).filter((f) => f.regional === regionalNome);
  }, [selectedMonth, unidadeFiltro]);

  // Exportar / Imprimir em PDF
  const handlePrintPDF = () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      window.print();
      return;
    }

    const htmlContent = `
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="UTF-8" />
        <title>Relatório Operacional Diário - ${dataFormatada}</title>
        <style>
          body {
            font-family: Arial, sans-serif;
            margin: 20px;
            color: #1a1a1a;
            font-size: 12px;
          }
          h1 { font-size: 18px; margin-bottom: 4px; color: #0f172a; }
          h2 { font-size: 14px; margin-top: 18px; margin-bottom: 8px; border-bottom: 2px solid #e2e8f0; padding-bottom: 4px; color: #1e293b; }
          .header { display: flex; justify-content: space-between; border-bottom: 2px solid #0f172a; padding-bottom: 10px; margin-bottom: 16px; }
          .meta { font-size: 11px; color: #64748b; }
          .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 16px; }
          .stat-box { border: 1px solid #cbd5e1; border-radius: 6px; padding: 10px; text-align: center; }
          .stat-val { font-size: 18px; font-weight: bold; color: #0f172a; }
          .stat-lbl { font-size: 10px; text-transform: uppercase; color: #64748b; margin-top: 2px; }
          table { width: 100%; border-collapse: collapse; margin-bottom: 16px; font-size: 11px; }
          th, td { border: 1px solid #cbd5e1; padding: 6px 8px; text-align: left; }
          th { background-color: #f1f5f9; font-weight: bold; color: #334155; }
          .badge-falta { color: #dc2626; font-weight: bold; }
          .badge-subst { color: #d97706; font-weight: bold; }
          .badge-pres { color: #16a34a; font-weight: bold; }
          .veiculo-card { border: 1px solid #cbd5e1; border-radius: 6px; padding: 10px; margin-bottom: 12px; }
          .veiculo-header { font-weight: bold; margin-bottom: 6px; display: flex; justify-content: space-between; }
          @media print {
            body { margin: 0; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div>
            <h1>Relatório Diário de Operação & Faltas</h1>
            <div class="meta">Unidade: <strong>${regionalLabel[unidadeFiltro] || 'Todas'}</strong> | Data: <strong>${dataFormatada}</strong></div>
          </div>
          <div style="text-align: right;">
            <div class="meta">Gerado automaticamente pelo Sistema</div>
            <div class="meta">Total de Veículos: ${stats.totalVeiculos}</div>
          </div>
        </div>

        <div class="stats-grid">
          <div class="stat-box">
            <div class="stat-val">${stats.totalGeral}</div>
            <div class="stat-lbl">Total Colaboradores</div>
          </div>
          <div class="stat-box">
            <div class="stat-val" style="color: #16a34a;">${stats.totalPresentes}</div>
            <div class="stat-lbl">Presentes</div>
          </div>
          <div class="stat-box">
            <div class="stat-val" style="color: #dc2626;">${stats.totalFaltas}</div>
            <div class="stat-lbl">Faltas no Dia</div>
          </div>
          <div class="stat-box">
            <div class="stat-val" style="color: #d97706;">${stats.totalSubst}</div>
            <div class="stat-lbl">Substitutos Ativos</div>
          </div>
        </div>

        <h2>1. Quadro de Faltas do Dia (${faltasDoDia.length})</h2>
        ${faltasDoDia.length === 0 ? '<p style="color: #16a34a; font-weight: bold;">Nenhuma falta registrada nesta data.</p>' : `
          <table>
            <thead>
              <tr>
                <th>Colaborador</th>
                <th>Cargo</th>
                <th>Matrícula</th>
                <th>Veículo</th>
                <th>Motivo da Falta</th>
                <th>Substituto</th>
              </tr>
            </thead>
            <tbody>
              ${faltasDoDia.map(f => `
                <tr>
                  <td><strong>${f.colab.nome}</strong></td>
                  <td>${f.colab.cargo || '-'}</td>
                  <td>${f.colab.matricula || '-'}</td>
                  <td>${f.veiculo.placa} (${f.veiculo.regional === 'ribas' ? 'Ribas' : 'Água Clara'})</td>
                  <td class="badge-falta">${f.colab.motivoFalta || 'Falta Não Informada'}</td>
                  <td>${f.colab.substitutoNome ? `<span class="badge-subst">${f.colab.substitutoNome}</span>` : 'Sem substituto'}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        `}

        <h2>2. Composição de Veículos e Equipes</h2>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
          ${veiculosFiltrados.map(v => {
            const assentos = [v.assentos.motorista, v.assentos.frenteDir, v.assentos.trasEsq, v.assentos.trasDir].filter(Boolean);
            const ativos = assentos.filter(c => c && (c.status === 'presente' || c.status === 'substituto')).length;
            return `
              <div class="veiculo-card">
                <div class="veiculo-header">
                  <span>${v.placa} - ${v.modelo}</span>
                  <span>${ativos}/4 Colaboradores</span>
                </div>
                <div style="font-size: 10px; color: #475569; margin-bottom: 6px;">
                  Unidade: ${v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'} | Equipes: ${v.equipe1Codigo} / ${v.equipe2Codigo}
                </div>
                <table style="margin: 0; font-size: 10px;">
                  <tbody>
                    <tr>
                      <td width="30%"><strong>Motorista:</strong></td>
                      <td>${v.assentos.motorista?.nome || 'Vago'} <span class="${v.assentos.motorista?.status === 'falta' ? 'badge-falta' : v.assentos.motorista?.status === 'substituto' ? 'badge-subst' : 'badge-pres'}">(${v.assentos.motorista?.status || 'vazio'})</span></td>
                    </tr>
                    <tr>
                      <td><strong>Passageiro Diant.:</strong></td>
                      <td>${v.assentos.frenteDir?.nome || 'Vago'} <span class="${v.assentos.frenteDir?.status === 'falta' ? 'badge-falta' : v.assentos.frenteDir?.status === 'substituto' ? 'badge-subst' : 'badge-pres'}">(${v.assentos.frenteDir?.status || 'vazio'})</span></td>
                    </tr>
                    <tr>
                      <td><strong>Traseiro Esq.:</strong></td>
                      <td>${v.assentos.trasEsq?.nome || 'Vago'} <span class="${v.assentos.trasEsq?.status === 'falta' ? 'badge-falta' : v.assentos.trasEsq?.status === 'substituto' ? 'badge-subst' : 'badge-pres'}">(${v.assentos.trasEsq?.status || 'vazio'})</span></td>
                    </tr>
                    <tr>
                      <td><strong>Traseiro Dir.:</strong></td>
                      <td>${v.assentos.trasDir?.nome || 'Vago'} <span class="${v.assentos.trasDir?.status === 'falta' ? 'badge-falta' : v.assentos.trasDir?.status === 'substituto' ? 'badge-subst' : 'badge-pres'}">(${v.assentos.trasDir?.status || 'vazio'})</span></td>
                    </tr>
                  </tbody>
                </table>
              </div>
            `;
          }).join('')}
        </div>
      </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(htmlContent);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => {
      printWindow.print();
    }, 250);
  };

  // Exportar para CSV
  const handleExportCSV = () => {
    const rows = [
      ['Data', 'Unidade', 'Placa Veículo', 'Modelo', 'Equipe', 'Posição', 'Colaborador', 'Matrícula', 'Cargo', 'Status Presença', 'Motivo Falta', 'Substituto'],
    ];

    (veiculosFiltrados || []).forEach((v) => {
      const posicoes: Array<{ label: string; colab?: Colaborador; eq: string }> = [
        { label: 'Motorista', colab: v.assentos?.motorista, eq: v.equipe1Codigo },
        { label: 'Frente Dir', colab: v.assentos?.frenteDir, eq: v.equipe1Codigo },
        { label: 'Trás Esq', colab: v.assentos?.trasEsq, eq: v.equipe2Codigo },
        { label: 'Trás Dir', colab: v.assentos?.trasDir, eq: v.equipe2Codigo },
      ];

      posicoes.forEach(({ label, colab, eq }) => {
        if (colab) {
          rows.push([
            dataFormatada,
            v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
            v.placa,
            v.modelo,
            eq,
            label,
            colab.nome,
            colab.matricula || '',
            colab.cargo || '',
            colab.status,
            colab.motivoFalta || '',
            colab.substitutoNome || '',
          ]);
        }
      });
    });

    const csvContent = 'data:text/csv;charset=utf-8,\uFEFF' + rows.map((e) => e.map((c) => `"${c}"`).join(',')).join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `relatorio-operacional-${dataFormatada.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Filtro de Unidade Superior */}
      <Card className="border-border/60 bg-card/80 shadow-lg">
        <CardContent className="p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
              <Filter className="w-5 h-5 text-primary" />
            </div>
            <div>
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Filtrar por Unidade</p>
              <p className="text-sm font-bold text-foreground">Relatório e Exportação Consolidada</p>
            </div>
          </div>

          <div className="flex items-center gap-1.5 p-1 bg-muted/40 border border-border/50 rounded-xl flex-wrap">
            {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
              <button
                key={reg}
                onClick={() => setUnidadeFiltro(reg)}
                className={cn(
                  'px-3.5 py-1.5 rounded-lg text-xs font-bold transition-all cursor-pointer flex items-center gap-1.5',
                  unidadeFiltro === reg
                    ? 'bg-primary text-primary-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/60'
                )}
              >
                <MapPin className="w-3.5 h-3.5" />
                {regionalLabel[reg]}
              </button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Visão Resumo Operacional */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 sm:gap-4">
        <Card className="border-border/60 bg-gradient-to-br from-card to-card/60">
          <CardContent className="p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
              <Users className="w-5 h-5 text-primary" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground font-medium">Total Escalado</p>
              <p className="text-2xl font-black text-foreground leading-none mt-1">{stats.totalGeral}</p>
            </div>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-gradient-to-br from-emerald-500/5 to-card/60">
          <CardContent className="p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center shrink-0">
              <UserCheck className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground font-medium">Presentes</p>
              <p className="text-2xl font-black text-emerald-400 leading-none mt-1">{stats.totalPresentes}</p>
            </div>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-gradient-to-br from-rose-500/5 to-card/60">
          <CardContent className="p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-rose-500/10 border border-rose-500/20 flex items-center justify-center shrink-0">
              <UserX className="w-5 h-5 text-rose-400" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground font-medium">Faltas do Dia</p>
              <p className="text-2xl font-black text-rose-400 leading-none mt-1">{stats.totalFaltas}</p>
            </div>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-gradient-to-br from-amber-500/5 to-card/60">
          <CardContent className="p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-500/10 border border-amber-500/20 flex items-center justify-center shrink-0">
              <RefreshCw className="w-5 h-5 text-amber-400" />
            </div>
            <div>
              <p className="text-xs text-muted-foreground font-medium">Substitutos</p>
              <p className="text-2xl font-black text-amber-400 leading-none mt-1">{stats.totalSubst}</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Painel de Ações de Exportação */}
      <Card className="border-border/60">
        <CardHeader className="pb-4">
          <CardTitle className="text-base flex items-center gap-2">
            <FileSpreadsheet className="w-5 h-5 text-primary" />
            Relatório do Diário Operacional ({dataFormatada})
          </CardTitle>
          <CardDescription>
            Gere o documento impresso em PDF contendo as faltas registradas no dia e a distribuição de cada veículo por equipe.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-wrap gap-3">
            <Button
              onClick={handlePrintPDF}
              className="gap-2 bg-primary hover:bg-primary/90 text-primary-foreground font-bold shadow-md shadow-primary/20"
            >
              <Printer className="w-4 h-4" />
              Salvar em PDF / Imprimir Diário
            </Button>
            <Button
              variant="outline"
              onClick={handleExportCSV}
              className="gap-2 border-border/80 hover:bg-muted font-semibold"
            >
              <Download className="w-4 h-4" />
              Exportar Dados em Planilha (CSV)
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Tabela de Faltas do Dia */}
      <Card className="border-border/60">
        <CardHeader className="pb-3 border-b border-border/40">
          <CardTitle className="text-base flex items-center gap-2">
            <UserX className="w-5 h-5 text-rose-400" />
            Faltas Registradas Hoje ({faltasDoDia.length})
          </CardTitle>
          <CardDescription>
            Listagem detalhada das ausências apontadas no dia e seus respectivos motivos e substitutos.
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0">
          {faltasDoDia.length === 0 ? (
            <div className="p-8 text-center flex flex-col items-center justify-center">
              <CheckCircle2 className="w-10 h-10 text-emerald-400 mb-2" />
              <p className="font-bold text-foreground">Nenhuma falta registrada para os veículos filtrados.</p>
              <p className="text-xs text-muted-foreground mt-1">Todos os colaboradores escalados estão presentes ou com substituição.</p>
            </div>
          ) : (
            <div className="divide-y divide-border/40 overflow-x-auto">
              {faltasDoDia.map(({ colab, veiculo }) => (
                <div key={colab.id} className="p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-muted/20 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-rose-500/40 bg-muted shrink-0">
                      {colab.foto ? (
                        <img src={colab.foto} alt={colab.nome} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center font-bold text-xs">{colab.nome.charAt(0)}</div>
                      )}
                    </div>
                    <div>
                      <p className="text-sm font-bold text-foreground">{colab.nome}</p>
                      <p className="text-xs text-muted-foreground">{colab.cargo} · Matrícula: {colab.matricula || 'N/A'}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 flex-wrap">
                    <div className="text-xs font-semibold px-2.5 py-1 rounded-lg bg-muted border border-border/60">
                      Placa: <span className="font-mono text-foreground font-bold">{veiculo.placa}</span>
                    </div>

                    <Badge variant="destructive" className="gap-1">
                      <ShieldAlert className="w-3 h-3" />
                      {colab.motivoFalta || 'Falta Registrada'}
                    </Badge>

                    {colab.substitutoNome && (
                      <Badge variant="secondary" className="gap-1 bg-amber-500/15 text-amber-400 border-amber-500/30">
                        <RefreshCw className="w-3 h-3" />
                        Subst: {colab.substitutoNome}
                      </Badge>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Histórico Mensal de Faltas */}
      <Card className="border-border/60">
        <CardHeader className="pb-3 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <Calendar className="w-5 h-5 text-primary" />
                Histórico Acumulado Mensal
              </CardTitle>
              <CardDescription>
                Selecione o mês para analisar o ranking e recorrência de faltas.
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2">
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="h-9 px-3 text-xs font-semibold bg-muted/60 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground"
              >
                {MESES.map((mes, idx) => (
                  <option key={mes} value={idx}>
                    {mes}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {faltasMesSelecionado.length === 0 ? (
            <div className="p-8 text-center text-muted-foreground text-xs">
              Nenhum dado registrado para {MESES[selectedMonth]}.
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {faltasMesSelecionado.map((item, index) => (
                <div key={index} className="p-4 flex items-center justify-between gap-4 hover:bg-muted/20">
                  <div className="flex items-center gap-3">
                    <span className="w-6 h-6 rounded-full bg-primary/10 text-primary font-bold text-xs flex items-center justify-center shrink-0">
                      {index + 1}
                    </span>
                    <div>
                      <p className="text-sm font-bold text-foreground">{item.nome}</p>
                      <p className="text-xs text-muted-foreground">{item.cargo} · {item.regional}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-black text-rose-400">{item.totalFaltas}</span>
                    <span className="text-xs text-muted-foreground">faltas no mês</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

