                          {v.assentos?.trasDir?.status === 'falta' ? 'Falta' : 'OK'}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Card: Histórico Mensal de Faltas */}
      <Card className="border-border/60">
        <CardHeader className="pb-3 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <Calendar className="w-4 h-4 text-primary" />
                Histórico e Top Faltas por Mês
              </CardTitle>
              <CardDescription>
                Selecione o mês para consultar o ranking de colaboradores com mais ausências
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2 overflow-x-auto pb-1 max-w-full">
              {MESES.map((m, idx) => (
                <button
                  key={m}
                  type="button"
                  onClick={() => setSelectedMonth(idx)}
                  className={cn(
                    'px-2.5 py-1 rounded-lg text-xs font-semibold whitespace-nowrap transition-all cursor-pointer border',
                    selectedMonth === idx
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                      : 'border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/40'
                  )}
                >
                  {m.slice(0, 3)}
                </button>
              ))}
            </div>
          </div>
        </CardHeader>

        <CardContent className="pt-4">
          <div className="flex items-center justify-between mb-3 text-xs text-muted-foreground">
            <span>Mês selecionado: <strong className="text-foreground">{MESES[selectedMonth]}</strong></span>
            <span>Unidade: <strong className="text-foreground">{regionalLabel[unidadeFiltro]}</strong></span>
          </div>

          {faltasDoMes.length === 0 ? (
            <div className="py-8 text-center text-xs text-muted-foreground">
              Nenhuma falta registrada neste mês para a unidade selecionada.
            </div>
          ) : (
            <div className="space-y-2">
              {faltasDoMes.map((f, i) => (
                <div
                  key={i}
                  className="flex items-center justify-between p-3 rounded-xl border border-border/40 bg-muted/20 hover:bg-muted/40 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <span className="w-6 h-6 rounded-full bg-rose-500/10 text-rose-400 font-bold text-xs flex items-center justify-center border border-rose-500/20">
                      {i + 1}º
                    </span>
                    <div>
                      <p className="text-xs font-bold text-foreground">{f.nome}</p>
                      <p className="text-[11px] text-muted-foreground">{f.cargo} • {f.regional}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-xs font-bold text-rose-400 bg-rose-500/10 px-2.5 py-1 rounded-lg border border-rose-500/20">
                      {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

