                <tr>
                  <td><strong>${f.colab.nome}</strong></td>
                  <td>${f.colab.cargo} (${f.colab.matricula || 'S/M'})</td>
                  <td>${f.veiculo.prefixo} (${f.veiculo.placa}) - Eq. ${f.colab.equipeNumero}</td>
                  <td><span class="badge-falta">${f.colab.motivoFalta || 'Falta Registrada'}</span></td>
                  <td>${f.colab.substitutoNome ? `<span class="badge-subst">Substituído por: ${f.colab.substitutoNome}</span>` : '<em>Sem substituto alocado</em>'}</td>
                </tr>
              `
                )
                .join('')}
            </tbody>
          </table>
        `
        }

        <h2>2. DISPOSIÇÃO DOS VEÍCULOS E QUANTIDADE DE EQUIPES</h2>
        ${veiculosFiltrados
          .map(
            (v) => `
          <div class="veiculo-card">
            <div class="veiculo-header">
              <span>${v.prefixo} - ${v.modelo} (Placa: ${v.placa})</span>
              <span>Regional: ${regionalLabel[v.regional] || v.regional} | Status: Ativo (2 Equipes)</span>
            </div>
            <div class="veiculo-body">
              <div class="eq-col">
                <div class="eq-title">EQUIPE 1 (${v.equipe1Codigo || 'EQ-1'})</div>
                <div style="margin-bottom: 4px;"><strong>Motorista:</strong> ${v.assentos?.motorista?.nome || 'Vago'} ${v.assentos?.motorista?.status === 'falta' ? '<span class="badge-falta">FALTA</span>' : v.assentos?.motorista?.status === 'substituto' ? '<span class="badge-subst">SUBST</span>' : '<span class="badge-pres">OK</span>'}</div>
                <div><strong>Dianteiro Dir:</strong> ${v.assentos?.frenteDir?.nome || 'Vago'} ${v.assentos?.frenteDir?.status === 'falta' ? '<span class="badge-falta">FALTA</span>' : v.assentos?.frenteDir?.status === 'substituto' ? '<span class="badge-subst">SUBST</span>' : '<span class="badge-pres">OK</span>'}</div>
              </div>
              <div class="eq-col">
                <div class="eq-title">EQUIPE 2 (${v.equipe2Codigo || 'EQ-2'})</div>
                <div style="margin-bottom: 4px;"><strong>Traseiro Esq:</strong> ${v.assentos?.trasEsq?.nome || 'Vago'} ${v.assentos?.trasEsq?.status === 'falta' ? '<span class="badge-falta">FALTA</span>' : v.assentos?.trasEsq?.status === 'substituto' ? '<span class="badge-subst">SUBST</span>' : '<span class="badge-pres">OK</span>'}</div>
                <div><strong>Traseiro Dir:</strong> ${v.assentos?.trasDir?.nome || 'Vago'} ${v.assentos?.trasDir?.status === 'falta' ? '<span class="badge-falta">FALTA</span>' : v.assentos?.trasDir?.status === 'substituto' ? '<span class="badge-subst">SUBST</span>' : '<span class="badge-pres">OK</span>'}</div>
              </div>
            </div>
          </div>
        `
          )
          .join('')}

        <div class="footer">
          <span>Sistema de Gestão e Controle Operacional de Faltas</span>
          <span>Página 1 de 1</span>
        </div>

        <script>
          window.onload = function() {
            setTimeout(function() {
              window.print();
            }, 300);
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  // Exportar em CSV
  const handleExportCSV = () => {
    let csv = 'Veiculo;Placa;Regional;Equipe;Posicao;Colaborador;Matricula;Cargo;Status;MotivoFalta;Substituto\n';

    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentosMap = [
        { c: v.assentos.motorista, pos: 'Motorista', eq: v.equipe1Codigo || 'EQ-1' },
        { c: v.assentos.frenteDir, pos: 'Dianteiro Direito', eq: v.equipe1Codigo || 'EQ-1' },
        { c: v.assentos.trasEsq, pos: 'Traseiro Esquerdo', eq: v.equipe2Codigo || 'EQ-2' },
        { c: v.assentos.trasDir, pos: 'Traseiro Direito', eq: v.equipe2Codigo || 'EQ-2' },
      ];

      assentosMap.forEach(({ c, pos, eq }) => {
        if (!c) return;
        csv += `"${v.prefixo || ''}";"${v.placa || ''}";"${v.regional || ''}";"${eq}";"${pos}";"${c.nome || ''}";"${c.matricula || ''}";"${c.cargo || ''}";"${c.status || ''}";"${c.motivoFalta || ''}";"${c.substitutoNome || ''}"\n`;
      });
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `relatorio-operacional-${dataFormatada.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Seletor de Unidade / Regional no Topo dos Relatórios */}
      <Card className="border-border/60 bg-card/70 backdrop-blur-md">
        <CardContent className="p-4 sm:p-5">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2.5 rounded-xl bg-primary/10 text-primary border border-primary/20 shrink-0">
                <MapPin className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-sm font-bold text-foreground">Filtrar por Unidade Operacional</h3>
                <p className="text-xs text-muted-foreground">
                  Selecione a base para atualizar todos os relatórios, faltas do dia e listagem de carros
                </p>
              </div>
            </div>

            {/* Botoes de Unidade */}
            <div className="flex items-center gap-2 flex-wrap">
              {[
                { id: 'todas', label: 'Todas as Unidades' },
                { id: 'ribas', label: 'Ribas do Rio Pardo' },
                { id: 'agua_clara', label: 'Água Clara' },
              ].map((reg) => (
                <button
                  key={reg.id}
                  type="button"
                  onClick={() => setUnidadeFiltro(reg.id as Regional)}
                  className={cn(
                    'px-3.5 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer flex items-center gap-1.5',
                    unidadeFiltro === reg.id
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm shadow-primary/20 scale-105'
                      : 'border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/40'
                  )}
                >
                  <MapPin className="w-3.5 h-3.5" />
                  {reg.label}
                </button>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Card Principal: Diário Operacional */}
      <Card className="border-border/60 bg-gradient-to-br from-card/90 via-card/70 to-card/50">
        <CardHeader className="pb-4 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <Badge variant="outline" className="text-primary border-primary/30">
                  <Calendar className="w-3 h-3 mr-1" />
                  {dataFormatada}
                </Badge>
                <Badge variant="secondary" className="text-xs">
                  {regionalLabel[unidadeFiltro]}
                </Badge>
              </div>
              <CardTitle className="text-xl">Diário Operacional e Faltas do Dia</CardTitle>
              <CardDescription>
                Resumo instantâneo das faltas, substituições e disposição dos veículos e equipes
              </CardDescription>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <Button
                variant="outline"
                size="sm"
                onClick={handleExportCSV}
                className="gap-1.5"
              >
                <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
                Exportar CSV
              </Button>
              <Button
                size="sm"
                onClick={handlePrintRelatorioDiario}
                className="gap-1.5 bg-primary text-primary-foreground shadow-md shadow-primary/20 hover:bg-primary/90"
              >
                <Printer className="w-4 h-4" />
                Salvar em PDF / Imprimir
              </Button>
            </div>
          </div>
        </CardHeader>

        <CardContent className="pt-6 space-y-6">
          {/* Indicadores resumidos */}
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
            <div className="p-3.5 rounded-xl border border-border/60 bg-card/40">
              <p className="text-[11px] font-medium text-muted-foreground">Veículos</p>
              <p className="text-xl font-bold text-foreground mt-0.5">{stats.totalVeiculos}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-border/60 bg-card/40">
              <p className="text-[11px] font-medium text-muted-foreground">Total Pessoas</p>
              <p className="text-xl font-bold text-foreground mt-0.5">{stats.totalGeral}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-emerald-500/20 bg-emerald-500/5">
              <p className="text-[11px] font-medium text-emerald-400">Presentes</p>
              <p className="text-xl font-bold text-emerald-400 mt-0.5">{stats.totalPresentes}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-rose-500/20 bg-rose-500/5">
              <p className="text-[11px] font-medium text-rose-400">Faltas</p>
              <p className="text-xl font-bold text-rose-400 mt-0.5">{stats.totalFaltas}</p>
            </div>
            <div className="p-3.5 rounded-xl border border-amber-500/20 bg-amber-500/5 col-span-2 sm:col-span-1">
              <p className="text-[11px] font-medium text-amber-400">Substitutos</p>
              <p className="text-xl font-bold text-amber-400 mt-0.5">{stats.totalSubst}</p>
            </div>
          </div>

          {/* Seção 1: Faltas do Dia */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h4 className="text-sm font-bold text-foreground flex items-center gap-2">
                <ShieldAlert className="w-4 h-4 text-rose-400" />
                Faltas Registradas Hoje
                <span className="text-xs px-2 py-0.5 rounded-full bg-rose-500/15 text-rose-400 font-semibold">
                  {faltasDoDia.length}
                </span>
              </h4>
            </div>

            {faltasDoDia.length === 0 ? (
              <div className="p-4 rounded-xl border border-emerald-500/20 bg-emerald-500/5 flex items-center gap-3 text-emerald-400 text-xs">
