                <span>Excelente! Nenhuma falta registrada até o momento nesta unidade.</span>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {faltasDoDia.map((item, idx) => (
                  <div
