                    className="p-3.5 rounded-xl border border-rose-500/30 bg-rose-500/[0.04] flex items-center justify-between gap-3"
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="w-10 h-10 rounded-full overflow-hidden border border-rose-500/40 bg-muted shrink-0 flex items-center justify-center">
                        {item.colab.foto ? (
                          <img
                            src={item.colab.foto}
                            alt={item.colab.nome}
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <span className="text-xs font-bold text-rose-400">{item.colab.nome?.charAt(0)}</span>
                        )}
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-foreground truncate">{item.colab.nome}</p>
                        <p className="text-xs text-muted-foreground truncate">
                          {item.colab.cargo} • {item.veiculo.prefixo} ({item.veiculo.placa})
                        </p>
                        <p className="text-[11px] font-semibold text-rose-400 mt-0.5">
                          Motivo: {item.colab.motivoFalta || 'Falta Registrada'}
                        </p>
                      </div>
                    </div>

                    <div className="text-right shrink-0">
                      {item.colab.substitutoNome ? (
                        <div className="text-[10px] bg-amber-500/10 border border-amber-500/30 text-amber-400 px-2 py-1 rounded-md">
                          Substituído por: <strong>{item.colab.substitutoNome}</strong>
                        </div>
                      ) : (
                        <div className="text-[10px] bg-rose-500/10 border border-rose-500/30 text-rose-400 px-2 py-1 rounded-md">
                          Sem substituto
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Seção 2: Estrutura de Carros e Quantidade de Equipes */}
          <div>
            <h4 className="text-sm font-bold text-foreground flex items-center gap-2 mb-3">
              <Car className="w-4 h-4 text-primary" />
              Disposição dos Veículos e Equipes Alocadas
            </h4>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
              {(veiculosFiltrados || []).map((v) => (
                <div
                  key={v.id}
                  className="p-3.5 rounded-xl border border-border/60 bg-card/40 hover:border-border transition-all flex flex-col justify-between"
                >
                  <div className="flex items-center justify-between pb-2 border-b border-border/40 mb-2.5">
                    <div>
                      <h5 className="text-xs font-bold text-foreground">{v.prefixo}</h5>
                      <p className="text-[11px] text-muted-foreground">{v.modelo} • <span className="font-mono">{v.placa}</span></p>
                    </div>
                    <Badge variant="outline" className="text-[10px]">
                      2 Equipes
                    </Badge>
                  </div>

                  <div className="space-y-2 text-xs">
                    {/* Equipe 1 */}
                    <div className="p-2 rounded-lg bg-muted/30 border border-border/30">
                      <div className="flex items-center justify-between text-[10px] font-semibold text-muted-foreground mb-1">
                        <span>Equipe 1 ({v.equipe1Codigo || 'EQ-1'})</span>
                        <span>Motorista + Diant. Dir</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="truncate max-w-[130px] font-medium text-foreground">
                          {v.assentos?.motorista?.nome || 'Vago'}
