        return `<span style="color: #d97706; font-weight: 600;">${c.substitutoNome || c.nome} (Substituto)</span>`;
      };

      return `
        <div style="margin-bottom: 12px; padding: 12px; border: 1px solid #cbd5e1; border-radius: 8px; background-color: #f8fafc; page-break-inside: avoid;">
