              ${v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
            </span>
          </div>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px;">
            <div><strong>1. Dianteiro Esq:</strong> ${formatStatus(motorista)}</div>
            <div><strong>2. Dianteiro Dir:</strong> ${formatStatus(frenteDir)}</div>
            <div><strong>3. Traseiro Esq:</strong> ${formatStatus(trasEsq)}</div>
            <div><strong>4. Traseiro Dir:</strong> ${formatStatus(trasDir)}</div>
          </div>
        </div>
      `;
    }).join('');

    const htmlContent = `
