        </style>
      </head>
      <body>
        <div class="header">
          <div>
            <h1>DIÁRIO OPERACIONAL E CONTROLE DE PRESENÇA</h1>
            <p style="margin: 0; font-size: 12px; color: #64748b;">Unidade: <strong>${regionalLabel[unidadeFiltro]}</strong> | Data: <strong>${dataFormatada}</strong></p>
