      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => {
        printWindow.print();
      }, 350);
    }
  };

  // Exportar CSV
  const handleExportCSV = () => {
    const rows = [
      ['Data', 'Unidade', 'Placa', 'Colaborador', 'Matricula', 'Cargo', 'Status', 'Motivo Falta', 'Substituto'],
