                  <option key={m} value={idx} className="bg-card text-foreground">
                    {m}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {dadosMesSelecionado.length === 0 ? (
            <div className="p-8 text-center text-xs text-muted-foreground">
              Nenhuma falta registrada para o mês de {MESES[selectedMonth]} na unidade selecionada.
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {dadosMesSelecionado.map((f, idx) => (
                <div key={idx} className="flex items-center justify-between p-3.5 hover:bg-muted/20 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-7 h-7 rounded-full bg-muted/60 border border-border flex items-center justify-center font-bold text-xs text-muted-foreground">
                      {idx + 1}
                    </div>
                    <div>
                      <p className="font-bold text-xs sm:text-sm text-foreground">{f.nome}</p>
                      <p className="text-[11px] text-muted-foreground">{f.cargo} • {f.regional}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="inline-flex items-center px-2.5 py-1 rounded-lg text-xs font-bold bg-rose-500/15 text-rose-400 border border-rose-500/30">
                      {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

