export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional: initialRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(initialRegional || 'todas');

  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos por unidade selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return unidadeFiltro === 'todas' || v.regional === unidadeFiltro;
    });
  }, [veiculos, unidadeFiltro]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const dadosMesSelecionado = useMemo(() => {
    const item = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMonth);
    const lista = item?.faltas || [];
    if (unidadeFiltro === 'todas') return lista;
    const regNome = unidadeFiltro === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
    return lista.filter((f) => f.regional === regNome);
  }, [selectedMonth, unidadeFiltro]);

  // Exportar PDF do Diário Operacional
  const handleExportPDF = () => {
    const faltasHtml = faltasDoDia.length > 0
      ? faltasDoDia.map((item) => `
        <tr style="border-bottom: 1px solid #e2e8f0;">
          <td style="padding: 8px 10px; font-weight: bold; color: #1e293b;">${item.colab?.nome || 'Não informado'}</td>
          <td style="padding: 8px 10px; color: #475569;">${item.colab?.cargo || 'Operador'}</td>
          <td style="padding: 8px 10px; color: #64748b; font-family: monospace;">${item.colab?.matricula || '-'}</td>
          <td style="padding: 8px 10px; color: #dc2626; font-weight: 600;">${item.colab?.motivoFalta || 'Falta Não Justificada'}</td>
          <td style="padding: 8px 10px; color: #1e293b; font-weight: bold;">${item.veiculo?.placa || '-'}</td>
          <td style="padding: 8px 10px; color: #475569;">${item.veiculo?.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</td>
        </tr>
      `).join('')
      : `<tr><td colspan="6" style="padding: 16px; text-align: center; color: #16a34a; font-weight: bold;">✅ Nenhuma falta registrada nesta data e unidade.</td></tr>`;

    const veiculosHtml = veiculosFiltrados.map((v) => {
      const motorista = v?.assentos?.motorista;
      const frenteDir = v?.assentos?.frenteDir;
      const trasEsq = v?.assentos?.trasEsq;
      const trasDir = v?.assentos?.trasDir;

      const formatStatus = (c?: Colaborador) => {
        if (!c) return '<span style="color: #94a3b8;">Vago</span>';
        if (c.status === 'presente') return `<span style="color: #16a34a; font-weight: 600;">${c.nome} (Presente)</span>`;
        if (c.status === 'falta') return `<span style="color: #dc2626; font-weight: 600;">${c.nome} (FALTA - ${c.motivoFalta || 'Sem just.'})</span>`;
        return `<span style="color: #d97706; font-weight: 600;">${c.substitutoNome || c.nome} (Substituto)</span>`;
      };

      return `
        <div style="margin-bottom: 12px; padding: 12px; border: 1px solid #cbd5e1; border-radius: 8px; background-color: #f8fafc; page-break-inside: avoid;">
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 6px; margin-bottom: 8px;">
            <div>
              <strong style="font-size: 14px; color: #0f172a; font-family: monospace;">🚗 PLACA: ${v.placa}</strong>
              <span style="font-size: 11px; color: #64748b; margin-left: 8px;">(${v.modelo || ''})</span>
            </div>
            <span style="font-size: 11px; padding: 3px 8px; background: #e0f2fe; color: #0369a1; border-radius: 4px; font-weight: 600;">
              ${v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
            </span>
          </div>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 11px;">
            <div><strong>1. Dianteiro Esq:</strong> ${formatStatus(motorista)}</div>
            <div><strong>2. Dianteiro Dir:</strong> ${formatStatus(frenteDir)}</div>
            <div><strong>3. Traseiro Esq:</strong> ${formatStatus(trasEsq)}</div>
            <div><strong>4. Traseiro Dir:</strong> ${formatStatus(trasDir)}</div>
          </div>
        </div>
      `;
    }).join('');

    const htmlContent = `
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="UTF-8">
        <title>Relatório Operacional - ${dataFormatada}</title>
        <style>
          * { box-sizing: border-box; font-family: Arial, sans-serif; }
          body { padding: 24px; color: #0f172a; background: #ffffff; }
          h1 { font-size: 20px; margin: 0 0 4px; color: #0f172a; }
          .header { border-bottom: 2px solid #0f172a; padding-bottom: 12px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: flex-end; }
          .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 20px; }
          .stat-box { border: 1px solid #e2e8f0; border-radius: 6px; padding: 10px; background: #f8fafc; text-align: center; }
          .stat-val { font-size: 18px; font-weight: bold; margin-top: 4px; }
          .section-title { font-size: 14px; font-weight: bold; background: #0f172a; color: #ffffff; padding: 6px 12px; border-radius: 4px; margin: 18px 0 10px; }
          table { width: 100%; border-collapse: collapse; font-size: 11px; margin-bottom: 16px; }
          th { background: #f1f5f9; padding: 8px 10px; text-align: left; border-bottom: 2px solid #cbd5e1; color: #334155; }
          @media print {
            body { padding: 0; }
            @page { margin: 15mm; size: A4 portrait; }
          }
        </style>
      </head>
      <body>
        <div class="header">
          <div>
            <h1>DIÁRIO OPERACIONAL E CONTROLE DE PRESENÇA</h1>
            <p style="margin: 0; font-size: 12px; color: #64748b;">Unidade: <strong>${regionalLabel[unidadeFiltro]}</strong> | Data: <strong>${dataFormatada}</strong></p>
          </div>
          <div style="text-align: right; font-size: 11px; color: #64748b;">
            Emissão: ${new Date().toLocaleTimeString('pt-BR')}
          </div>
        </div>

        <div class="stats-grid">
          <div class="stat-box">
            <div style="font-size: 10px; color: #64748b;">TOTAL VEÍCULOS</div>
            <div class="stat-val" style="color: #0f172a;">${stats.totalVeiculos}</div>
          </div>
          <div class="stat-box">
            <div style="font-size: 10px; color: #64748b;">EFETIVO TOTAL</div>
            <div class="stat-val" style="color: #0f172a;">${stats.totalGeral}</div>
          </div>
          <div class="stat-box">
            <div style="font-size: 10px; color: #64748b;">FALTAS DO DIA</div>
            <div class="stat-val" style="color: #dc2626;">${stats.totalFaltas}</div>
          </div>
          <div class="stat-box">
            <div style="font-size: 10px; color: #64748b;">TAXA DE PRESENÇA</div>
            <div class="stat-val" style="color: #16a34a;">${stats.taxaPresenca}%</div>
          </div>
        </div>

        <div class="section-title">1. RELAÇÃO DE FALTAS REGISTRADAS NO DIA</div>
        <table>
          <thead>
            <tr>
              <th>Colaborador</th>
              <th>Função</th>
              <th>Matrícula</th>
              <th>Motivo da Falta</th>
              <th>Placa do Veículo</th>
              <th>Unidade</th>
            </tr>
          </thead>
          <tbody>
            ${faltasHtml}
          </tbody>
        </table>

        <div class="section-title">2. OCUPAÇÃO E STATUS DOS VEÍCULOS</div>
        <div>
          ${veiculosHtml}
        </div>
      </body>
      </html>
    `;

    const printWindow = window.open('', '_blank', 'width=900,height=800');
    if (printWindow) {
      printWindow.document.open();
      printWindow.document.write(htmlContent);
      printWindow.document.close();
      printWindow.focus();
      setTimeout(() => {
        printWindow.print();
      }, 350);
    }
  };

  // Exportar CSV
  const handleExportCSV = () => {
    const rows = [
      ['Data', 'Unidade', 'Placa', 'Colaborador', 'Matricula', 'Cargo', 'Status', 'Motivo Falta', 'Substituto'],
    ];

    veiculosFiltrados.forEach((v) => {
      const assentos = [
        v?.assentos?.motorista,
        v?.assentos?.frenteDir,
        v?.assentos?.trasEsq,
        v?.assentos?.trasDir,
      ];

      assentos.forEach((c) => {
        if (c) {
          rows.push([
            dataFormatada,
            v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara',
            v.placa || '',
            c.nome || '',
            c.matricula || '',
            c.cargo || '',
            c.status || 'presente',
            c.motivoFalta || '',
            c.substitutoNome || '',
          ]);
        }
      });
    });

    const csvContent = 'data:text/csv;charset=utf-8,\uFEFF' + rows.map((e) => e.map(x => `"${x}"`).join(';')).join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `relatorio_operacional_${unidadeFiltro}_${dataFormatada.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Top Banner de Seleção e Ações */}
      <Card className="border-border/60 bg-gradient-to-r from-card to-card/70 shadow-lg">
        <CardContent className="p-6">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-5">
            <div>
              <div className="flex items-center gap-2 mb-1.5">
                <FileSpreadsheet className="w-5 h-5 text-primary" />
                <h2 className="text-xl font-bold text-foreground">Relatório e Diário Operacional</h2>
              </div>
              <p className="text-xs sm:text-sm text-muted-foreground">
                Geração consolidada de presença, faltas justificadas e ocupação dos veículos por unidade.
              </p>
            </div>

            <div className="flex flex-wrap items-center gap-3">
              {/* Seletor de Unidade */}
              <div className="flex items-center gap-2 bg-muted/40 border border-border/80 rounded-xl px-3 py-1.5">
