                className="gap-1.5 font-semibold text-xs border-border/80"
              >
                <Download className="w-3.5 h-3.5 text-primary" />
                Exportar CSV
              </Button>

              <Button
                size="sm"
                onClick={handleExportPDF}
                className="gap-1.5 font-semibold text-xs shadow-md bg-primary hover:bg-primary/90 text-primary-foreground"
              >
                <Printer className="w-3.5 h-3.5" />
                Salvar em PDF
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Resumo Numérico */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3.5">
        <Card className="border-border/60 bg-muted/20">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Veículos em Campo</p>
              <p className="text-2xl font-extrabold text-foreground mt-0.5">{stats.totalVeiculos}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
              <Car className="w-5 h-5" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-emerald-500/5">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs text-muted-foreground font-medium">Colaboradores Presentes</p>
              <p className="text-2xl font-extrabold text-emerald-400 mt-0.5">{stats.totalPresentes}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-400">
              <UserCheck className="w-5 h-5" />
