          {faltasDoDia.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-center px-4">
              <CheckCircle2 className="w-10 h-10 text-emerald-400 mb-2" />
              <p className="text-sm font-bold text-foreground">Excelente! 100% de Presença</p>
              <p className="text-xs text-muted-foreground mt-0.5">Nenhuma falta computada para os veículos filtrados nesta data.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead className="bg-muted/40 text-muted-foreground font-semibold border-b border-border/40">
                  <tr>
                    <th className="p-3">Colaborador</th>
                    <th className="p-3">Função</th>
                    <th className="p-3">Matrícula</th>
                    <th className="p-3">Motivo da Ausência</th>
                    <th className="p-3">Placa do Carro</th>
                    <th className="p-3">Unidade</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40">
                  {faltasDoDia.map((item, idx) => (
                    <tr key={idx} className="hover:bg-rose-500/[0.04] transition-colors">
                      <td className="p-3 font-bold text-foreground flex items-center gap-2">
                        <div className="w-6 h-6 rounded-full bg-rose-500/20 text-rose-400 flex items-center justify-center text-[10px]">
                          {item.colab?.nome?.charAt(0) || 'C'}
                        </div>
                        {item.colab?.nome}
                      </td>
                      <td className="p-3 text-muted-foreground">{item.colab?.cargo || 'Operador'}</td>
                      <td className="p-3 font-mono text-muted-foreground">{item.colab?.matricula || '-'}</td>
                      <td className="p-3">
                        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-semibold bg-rose-500/15 text-rose-400 border border-rose-500/30">
                          {item.colab?.motivoFalta || 'Falta Injustificada'}
                        </span>
                      </td>
                      <td className="p-3 font-mono font-bold text-foreground">{item.veiculo?.placa || '-'}</td>
                      <td className="p-3 text-muted-foreground">
                        {item.veiculo?.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Relatório Histórico de Faltas por Mês */}
      <Card className="border-border/60">
        <CardHeader className="py-4 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <Calendar className="w-4 h-4 text-primary" />
                Histórico Mensal de Faltas
              </CardTitle>
              <CardDescription className="text-xs">
                Ranking consolidado de colaboradores com registros de ausência no período.
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2">
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                aria-label="Selecionar mês"
                className="bg-muted/50 border border-border rounded-xl px-3 py-1.5 text-xs font-bold text-foreground focus:outline-none cursor-pointer"
              >
                {MESES.map((m, idx) => (
                  <option key={m} value={idx} className="bg-card text-foreground">
                    {m}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {dadosMesSelecionado.length === 0 ? (
            <div className="p-8 text-center text-xs text-muted-foreground">
              Nenhuma falta registrada para o mês de {MESES[selectedMonth]} na unidade selecionada.
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {dadosMesSelecionado.map((f, idx) => (
                <div key={idx} className="flex items-center justify-between p-3.5 hover:bg-muted/20 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-7 h-7 rounded-full bg-muted/60 border border-border flex items-center justify-center font-bold text-xs text-muted-foreground">
                      {idx + 1}
                    </div>
                    <div>
                      <p className="font-bold text-xs sm:text-sm text-foreground">{f.nome}</p>
                      <p className="text-[11px] text-muted-foreground">{f.cargo} • {f.regional}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="inline-flex items-center px-2.5 py-1 rounded-lg text-xs font-bold bg-rose-500/15 text-rose-400 border border-rose-500/30">
                      {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

