export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional: initialRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(initialRegional || 'todas');

  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos por unidade selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return unidadeFiltro === 'todas' || v.regional === unidadeFiltro;
    });
  }, [veiculos, unidadeFiltro]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const dadosMesSelecionado = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((m) => m.mesIndex === selectedMonth) || HISTORICO_MENSAL_FALTAS[0];
    const listaFaltas = mesObj?.faltas || [];

    if (unidadeFiltro === 'todas') {
      return listaFaltas;
    }
    const nomeRegAlvo = unidadeFiltro === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
    return listaFaltas.filter((item) => item.regional === nomeRegAlvo);
  }, [selectedMonth, unidadeFiltro]);

  const handlePrintRelatorioGeral = () => {
    const nomeUnidade = regionalLabel[unidadeFiltro] || 'Geral';
    const printWindow = window.open('', '_blank', 'width=900,height=800');
    if (!printWindow) return;

    const faltasHtml = faltasDoDia.length === 0
      ? '<p style="color: #10b981; font-weight: bold;">Nenhuma falta registrada nesta data.</p>'
      : `
        <table style="width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 13px;">
          <thead>
            <tr style="background-color: #f1f5f9; text-align: left;">
              <th style="padding: 8px; border: 1px solid #cbd5e1;">Colaborador</th>
              <th style="padding: 8px; border: 1px solid #cbd5e1;">Cargo</th>
              <th style="padding: 8px; border: 1px solid #cbd5e1;">Placa / Veículo</th>
              <th style="padding: 8px; border: 1px solid #cbd5e1;">Motivo</th>
            </tr>
          </thead>
          <tbody>
            ${faltasDoDia.map(({ colab, veiculo }) => `
              <tr>
                <td style="padding: 8px; border: 1px solid #cbd5e1; font-weight: bold; color: #b91c1c;">${colab.nome}</td>
                <td style="padding: 8px; border: 1px solid #cbd5e1;">${colab.cargo || 'Operador'}</td>
                <td style="padding: 8px; border: 1px solid #cbd5e1; font-weight: 600;">${veiculo.placa || veiculo.prefixo}</td>
                <td style="padding: 8px; border: 1px solid #cbd5e1;">${colab.motivoFalta || 'Falta Registrada'}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      `;

    const htmlContent = `
      <!DOCTYPE html>
      <html>
        <head>
          <title>Relatório Operacional - ${dataFormatada}</title>
          <style>
            body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; padding: 25px; color: #1e293b; line-height: 1.5; }
            h1 { font-size: 22px; margin-bottom: 4px; color: #0f172a; }
            .subtitle { color: #64748b; font-size: 14px; margin-bottom: 20px; }
            .badge { display: inline-block; padding: 4px 10px; background: #e2e8f0; border-radius: 6px; font-size: 12px; font-weight: bold; }
            .card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; margin-bottom: 20px; background: #fafafa; }
            .grid { display: flex; gap: 15px; margin-bottom: 20px; }
            .grid-item { flex: 1; padding: 12px; background: white; border: 1px solid #e2e8f0; border-radius: 8px; text-align: center; }
            .grid-item .val { font-size: 20px; font-weight: bold; margin-top: 4px; }
            @media print {
              body { padding: 0; }
              button { display: none; }
            }
          </style>
        </head>
        <body>
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; margin-bottom: 15px;">
            <div>
              <h1>Diário Operacional e Controle de Presença</h1>
              <p class="subtitle">Unidade: <strong>${nomeUnidade}</strong> | Data: <strong>${dataFormatada}</strong></p>
            </div>
            <div>
              <span class="badge">Presença: ${stats.taxaPresenca}%</span>
            </div>
          </div>

          <div class="grid">
            <div class="grid-item">
              <div style="font-size: 12px; color: #64748b;">Veículos</div>
              <div class="val" style="color: #2563eb;">${stats.totalVeiculos}</div>
            </div>
            <div class="grid-item">
              <div style="font-size: 12px; color: #64748b;">Colaboradores</div>
              <div class="val">${stats.totalGeral}</div>
            </div>
            <div class="grid-item">
              <div style="font-size: 12px; color: #64748b;">Presentes</div>
              <div class="val" style="color: #16a34a;">${stats.totalPresentes}</div>
            </div>
            <div class="grid-item">
              <div style="font-size: 12px; color: #64748b;">Faltas</div>
              <div class="val" style="color: #dc2626;">${stats.totalFaltas}</div>
            </div>
            <div class="grid-item">
              <div style="font-size: 12px; color: #64748b;">Substitutos</div>
              <div class="val" style="color: #d97706;">${stats.totalSubst}</div>
            </div>
          </div>

          <div class="card">
            <h3 style="margin-top: 0; margin-bottom: 10px; font-size: 16px; color: #dc2626;">Faltas Registradas na Data</h3>
            ${faltasHtml}
          </div>

          <div style="margin-top: 30px; text-align: center;">
            <button onclick="window.print()" style="padding: 10px 20px; background: #0284c7; color: white; border: none; border-radius: 6px; font-weight: bold; cursor: pointer;">
              Imprimir / Salvar PDF
            </button>
          </div>
        </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  const handleExportCSV = () => {
    const header = 'Nome,Cargo,Matricula,Placa_Veiculo,Unidade,Status,Motivo_Falta,Substituto\n';
    const rows = (todosColaboradores || []).map(({ colab, veiculo }) => {
      const nome = `"${colab?.nome || ''}"`;
      const cargo = `"${colab?.cargo || ''}"`;
      const matricula = `"${colab?.matricula || ''}"`;
      const placa = `"${veiculo?.placa || ''}"`;
      const unidade = `"${regionalLabel[veiculo?.regional] || ''}"`;
      const status = `"${colab?.status || ''}"`;
      const motivo = `"${colab?.motivoFalta || ''}"`;
      const substituto = `"${colab?.substitutoNome || ''}"`;
      return [nome, cargo, matricula, placa, unidade, status, motivo, substituto].join(',');
    }).join('\n');

    const blob = new Blob(['\uFEFF' + header + rows], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', `relatorio_diario_${unidadeFiltro}_${dataFormatada.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Seletor de Unidade */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-4 rounded-2xl bg-card border border-border">
        <div className="flex items-center gap-2.5">
          <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
            <Filter className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-sm font-bold text-foreground">Unidade Operacional</h2>
            <p className="text-xs text-muted-foreground">Filtre os dados do relatório por base ou veja o consolidado geral</p>
          </div>
        </div>

        <div className="flex items-center gap-1.5 p-1 bg-muted/50 rounded-xl border border-border self-start sm:self-auto">
          {(['todas', 'ribas', 'agua_clara'] as const).map((r) => (
            <button
              key={r}
              type="button"
              onClick={() => setUnidadeFiltro(r)}
              className={cn(
                'px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all cursor-pointer',
                unidadeFiltro === r
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted'
              )}
            >
