                    <th className="p-3">Colaborador</th>
                    <th className="p-3">Cargo</th>
                    <th className="p-3">Unidade</th>
                    <th className="p-3 text-right">Total no Mês</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40">
