                <div className="flex items-start justify-between gap-2">
                  <div className={cn('w-9 h-9 rounded-lg border flex items-center justify-center shrink-0', card.iconBg)}>
                    {card.icon}
                  </div>
                  <div className="text-right">
                    <p className={cn('text-3xl font-extrabold leading-none', card.numColor)}>{card.total}</p>
                    <p className="text-[10px] text-muted-foreground mt-1">equipes</p>
                  </div>
                </div>
                <div className="mt-3">
                  <p className="text-xs font-bold text-foreground">{card.label}</p>
                  <p className="text-[10px] text-muted-foreground">{card.descricao}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Botão NOVA EQUIPE abaixo de Composição de Equipes */}
      {onNovaEquipe && (
        <div className="flex items-center justify-end">
          <Button
            type="button"
            onClick={onNovaEquipe}
            className="w-full sm:w-auto px-5 py-2.5 h-auto text-sm font-bold gap-2 shadow-lg hover:shadow-primary/20 transition-all rounded-xl cursor-pointer"
          >
            <PlusCircle className="w-4 h-4 shrink-0" />
            NOVA EQUIPE
          </Button>
        </div>
      )}
    </div>
  );
};

