                          Placa: {veiculo.placa || veiculo.prefixo}
                        </span>
                        <span className="text-xs px-2.5 py-1 rounded-md bg-rose-500/15 border border-rose-500/30 font-semibold text-rose-400">
                          {colab.motivoFalta || 'Falta Injustificada'}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Histórico Mensal de Faltas por Colaborador */}
      <Card className="border-border/60">
        <CardHeader className="pb-4 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <Calendar className="w-5 h-5 text-primary" />
                Histórico de Faltas por Mês
              </CardTitle>
              <CardDescription>
                Selecione o mês para acompanhar os registros acumulados por colaborador
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="pt-5 space-y-4">
          {/* Seletor de Meses */}
          <div className="flex gap-1.5 overflow-x-auto pb-2 scrollbar-none">
            {MESES.map((mes, idx) => (
              <button
                key={mes}
                type="button"
                onClick={() => setSelectedMonth(idx)}
                className={cn(
                  'px-3 py-1.5 rounded-xl text-xs font-semibold whitespace-nowrap transition-all border shrink-0 cursor-pointer',
                  selectedMonth === idx
                    ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                    : 'bg-card border-border text-muted-foreground hover:text-foreground hover:bg-muted'
                )}
              >
                {mes}
              </button>
            ))}
          </div>

          {/* Tabela do Mês */}
          {dadosMesSelecionado.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-10 text-center">
              <CheckCircle2 className="w-8 h-8 text-emerald-500/60 mb-2" />
              <p className="text-xs font-semibold text-foreground">Sem histórico de faltas para {MESES[selectedMonth]}</p>
              <p className="text-[11px] text-muted-foreground">Nenhuma ocorrência registrada nesta unidade no período selecionado.</p>
            </div>
          ) : (
            <div className="border border-border/60 rounded-xl overflow-hidden">
              <table className="w-full text-xs text-left">
                <thead className="bg-muted/50 border-b border-border text-muted-foreground font-semibold uppercase tracking-wider text-[10px]">
                  <tr>
                    <th className="p-3">Colaborador</th>
                    <th className="p-3">Cargo</th>
                    <th className="p-3">Unidade</th>
                    <th className="p-3 text-right">Total no Mês</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40">
                  {dadosMesSelecionado.map((f, i) => (
                    <tr key={i} className="hover:bg-muted/20 transition-colors">
                      <td className="p-3 font-semibold text-foreground">{f.nome}</td>
                      <td className="p-3 text-muted-foreground">{f.cargo}</td>
                      <td className="p-3 text-muted-foreground">{f.regional}</td>
                      <td className="p-3 text-right">
                        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-bold bg-rose-500/15 border border-rose-500/30 text-rose-400">
                          {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

