export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional: initialRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [unidadeFiltro, setUnidadeFiltro] = useState<Regional>(initialRegional || 'todas');

  const currentMonthIndex = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.getMonth()
    : new Date().getMonth();

  const [selectedMonth, setSelectedMonth] = useState<number>(currentMonthIndex);

  const dataFormatada = (selectedDate instanceof Date && !isNaN(selectedDate.getTime()))
    ? selectedDate.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })
    : new Date().toLocaleDateString('pt-BR');

  // Filtragem dos veículos por unidade selecionada
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return unidadeFiltro === 'todas' || v.regional === unidadeFiltro;
    });
  }, [veiculos, unidadeFiltro]);

  // Lista de todos os colaboradores do dia atual com status e faltas
  const todosColaboradores = useMemo(() => {
    const list: Array<{ colab: Colaborador; veiculo: Veiculo }> = [];
    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter((item): item is Colaborador => Boolean(item));

      assentos.forEach((c) => {
        if (c) list.push({ colab: c, veiculo: v });
      });
    });
    return list;
  }, [veiculosFiltrados]);

  // Faltas do dia
  const faltasDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'falta');
  }, [todosColaboradores]);

  // Substitutos do dia
  const substitutosDoDia = useMemo(() => {
    return (todosColaboradores || []).filter((item) => item?.colab?.status === 'substituto');
  }, [todosColaboradores]);

  // Estatísticas gerais
  const stats = useMemo(() => {
    const totalPresentes = (todosColaboradores || []).filter((i) => i?.colab?.status === 'presente').length;
    const totalFaltas = (faltasDoDia || []).length;
    const totalSubst = (substitutosDoDia || []).length;
    const totalGeral = (todosColaboradores || []).length;
    const taxaPresenca = totalGeral > 0 ? Math.round(((totalPresentes + totalSubst) / totalGeral) * 100) : 100;

    return {
      totalVeiculos: (veiculosFiltrados || []).length,
      totalGeral,
      totalPresentes,
      totalFaltas,
      totalSubst,
      taxaPresenca,
    };
  }, [todosColaboradores, faltasDoDia, substitutosDoDia, veiculosFiltrados]);

  // Faltas do mês selecionado
  const faltasMesSelecionado = useMemo(() => {
    const dadosMes = HISTORICO_MENSAL_FALTAS.find((h) => h.mesIndex === selectedMonth);
    if (!dadosMes) return [];
    if (unidadeFiltro === 'todas') return dadosMes.faltas;
    const nomeRegional = regionalLabel[unidadeFiltro] || '';
    return dadosMes.faltas.filter((f) => f.regional.toLowerCase().includes(nomeRegional.toLowerCase()));
  }, [selectedMonth, unidadeFiltro]);

  // Exportação para CSV (compatível com Excel)
  const exportarCSV = () => {
    const cabecalho = ['Veículo', 'Placa', 'Regional', 'Equipe', 'Colaborador', 'Matrícula', 'Cargo', 'Status', 'Motivo Falta', 'Substituto'];
    const linhas: string[][] = [];

    (veiculosFiltrados || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentosMap = [
        { c: v.assentos.motorista, eq: v.equipe1Codigo || 'EQ-1' },
        { c: v.assentos.frenteDir, eq: v.equipe1Codigo || 'EQ-1' },
        { c: v.assentos.trasEsq, eq: v.equipe2Codigo || 'EQ-2' },
        { c: v.assentos.trasDir, eq: v.equipe2Codigo || 'EQ-2' },
      ];

      assentosMap.forEach(({ c, eq }) => {
        if (!c) return;
        linhas.push([
          `"${v.prefixo || ''}"`,
          `"${v.placa || ''}"`,
          `"${regionalLabel[v.regional] || v.regional}"`,
          `"${eq}"`,
          `"${c.nome || ''}"`,
          `"${c.matricula || ''}"`,
          `"${c.cargo || ''}"`,
          `"${c.status || ''}"`,
          `"${c.motivoFalta || '-'}"`,
          `"${c.substitutoNome || '-'}"`,
        ]);
      });
    });

    const csvContent = '\uFEFF' + [cabecalho.join(';'), ...linhas.map((l) => l.join(';'))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `relatorio_operacional_${unidadeFiltro}_${dataFormatada.replace(/\//g, '-')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  // Impressão nativa sem iframes conflitantes
  const imprimirRelatorio = () => {
    const printWindow = window.open('', '_blank');
    if (!printWindow) {
      window.print();
      return;
    }

    const htmlContent = `
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="utf-8">
        <title>Diário Operacional - ${dataFormatada}</title>
        <style>
          body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; margin: 20px; color: #111; }
          h1 { font-size: 18px; margin-bottom: 4px; }
          h2 { font-size: 14px; margin-top: 18px; margin-bottom: 8px; border-bottom: 1px solid #ccc; padding-bottom: 4px; }
          .header-info { font-size: 12px; color: #555; margin-bottom: 15px; }
          .stats-bar { display: flex; gap: 15px; margin-bottom: 15px; background: #f4f4f5; padding: 10px; border-radius: 6px; font-size: 12px; }
          .stat-item { font-weight: bold; }
          table { width: 100%; border-collapse: collapse; margin-bottom: 15px; font-size: 11px; }
          th, td { border: 1px solid #ddd; padding: 6px 8px; text-align: left; }
          th { background-color: #f8fafc; font-weight: 600; }
          .badge-falta { color: #dc2626; font-weight: bold; }
          .badge-subst { color: #d97706; font-weight: bold; }
          .badge-presente { color: #16a34a; }
          @media print {
            body { margin: 0; }
            button { display: none; }
          }
        </style>
      </head>
      <body>
        <h1>DIÁRIO OPERACIONAL DE CAMPO - CONTROLE DE FALTAS</h1>
        <div class="header-info">
          <strong>Data:</strong> ${dataFormatada} | 
          <strong>Unidade:</strong> ${regionalLabel[unidadeFiltro] || 'Todas as Unidades'} | 
          <strong>Emissão:</strong> ${new Date().toLocaleTimeString('pt-BR')}
        </div>

        <div class="stats-bar">
          <div class="stat-item">Total Veículos: ${stats.totalVeiculos}</div>
          <div class="stat-item">Efetivo Total: ${stats.totalGeral}</div>
          <div class="stat-item">Presentes: ${stats.totalPresentes}</div>
          <div class="stat-item">Faltas: ${stats.totalFaltas}</div>
          <div class="stat-item">Substitutos: ${stats.totalSubst}</div>
          <div class="stat-item">Taxa de Presença: ${stats.taxaPresenca}%</div>
        </div>

        <h2>Ocorrências de Ausência e Substituições (${stats.totalFaltas + stats.totalSubst})</h2>
        ${(faltasDoDia.length === 0 && substitutosDoDia.length === 0) ? '<p style="font-size: 11px; color: #666;">Nenhuma falta ou substituição registrada hoje.</p>' : `
        <table>
          <thead>
            <tr>
              <th>Veículo / Placa</th>
              <th>Colaborador</th>
              <th>Cargo</th>
              <th>Status</th>
              <th>Motivo / Substituto</th>
            </tr>
          </thead>
          <tbody>
            ${[...faltasDoDia, ...substitutosDoDia].map(item => `
              <tr>
                <td>${item.veiculo?.prefixo || '-'} (${item.veiculo?.placa || '-'})</td>
                <td><strong>${item.colab?.nome || '-'}</strong></td>
                <td>${item.colab?.cargo || '-'}</td>
                <td class="${item.colab?.status === 'falta' ? 'badge-falta' : 'badge-subst'}">
                  ${item.colab?.status === 'falta' ? 'FALTA' : 'SUBSTITUTO'}
                </td>
                <td>
                  ${item.colab?.status === 'falta' ? (item.colab?.motivoFalta || 'Sem motivo') : `Substituto por: ${item.colab?.substitutoNome || 'Reserva'}`}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
        `}

        <h2>Composição dos Veículos em Operação</h2>
        <table>
          <thead>
            <tr>
              <th>Veículo</th>
              <th>Regional</th>
              <th>Motorista (Eq. 1)</th>
              <th>Frente Dir. (Eq. 1)</th>
              <th>Traseiro Esq. (Eq. 2)</th>
              <th>Traseiro Dir. (Eq. 2)</th>
            </tr>
          </thead>
          <tbody>
            ${(veiculosFiltrados || []).map(v => `
              <tr>
                <td><strong>${v.prefixo}</strong><br><small>${v.placa}</small></td>
                <td>${regionalLabel[v.regional]}</td>
                <td>${v.assentos?.motorista?.nome || '-'} (${v.assentos?.motorista?.status})</td>
                <td>${v.assentos?.frenteDir?.nome || '-'} (${v.assentos?.frenteDir?.status})</td>
                <td>${v.assentos?.trasEsq?.nome || '-'} (${v.assentos?.trasEsq?.status})</td>
                <td>${v.assentos?.trasDir?.nome || '-'} (${v.assentos?.trasDir?.status})</td>
              </tr>
            `).join('')}
          </tbody>
        </table>

        <script>
          window.onload = function() {
            window.print();
          };
        </script>
      </body>
      </html>
    `;

    printWindow.document.open();
    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  return (
    <div className="space-y-6">
      {/* Barra de Filtro de Unidade */}
      <Card className="border-border/60 bg-card/60 backdrop-blur-md">
        <CardContent className="p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-primary/10 border border-primary/20 text-primary">
              <MapPin className="w-5 h-5" />
            </div>
            <div>
              <p className="text-xs font-medium text-muted-foreground">Filtrar por Unidade Regional</p>
              <h3 className="text-base font-bold text-foreground">
                {regionalLabel[unidadeFiltro]}
              </h3>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap w-full sm:w-auto">
            {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
              <button
                key={reg}
                type="button"
                onClick={() => setUnidadeFiltro(reg)}
                className={cn(
                  'px-3.5 py-1.5 rounded-xl text-xs font-semibold border transition-all cursor-pointer flex-1 sm:flex-initial text-center',
                  unidadeFiltro === reg
                    ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                    : 'border-border/60 text-muted-foreground hover:text-foreground hover:bg-muted/50'
                )}
              >
                {regionalLabel[reg]}
              </button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Cartões de Indicadores Rápidos da Unidade */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 sm:gap-4">
        <Card className="border-border/60 bg-muted/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <p className="text-xs text-muted-foreground font-medium">Veículos Ativos</p>
              <Car className="w-4 h-4 text-primary" />
            </div>
            <p className="text-2xl font-black mt-1 text-foreground">{stats.totalVeiculos}</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-emerald-500/5 border-emerald-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <p className="text-xs text-emerald-400 font-medium">Presentes Hoje</p>
              <UserCheck className="w-4 h-4 text-emerald-400" />
            </div>
            <p className="text-2xl font-black mt-1 text-emerald-400">{stats.totalPresentes}</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-rose-500/5 border-rose-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <p className="text-xs text-rose-400 font-medium">Faltas Registradas</p>
              <UserX className="w-4 h-4 text-rose-400" />
            </div>
            <p className="text-2xl font-black mt-1 text-rose-400">{stats.totalFaltas}</p>
          </CardContent>
        </Card>

        <Card className="border-border/60 bg-amber-500/5 border-amber-500/20">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <p className="text-xs text-amber-400 font-medium">Substitutos em Campo</p>
              <RefreshCw className="w-4 h-4 text-amber-400" />
            </div>
            <p className="text-2xl font-black mt-1 text-amber-400">{stats.totalSubst}</p>
          </CardContent>
        </Card>
      </div>

      {/* Seção 1: Diário Operacional de Hoje */}
      <Card className="border-border/60">
        <CardHeader className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-border/40">
          <div>
            <CardTitle className="text-base flex items-center gap-2">
              <Calendar className="w-4 h-4 text-primary" />
              Diário Operacional do Dia — {dataFormatada}
            </CardTitle>
            <CardDescription className="mt-1">
              Visualização consolidada de presenças, faltas e substituições para {regionalLabel[unidadeFiltro]}
            </CardDescription>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            <Button
              variant="outline"
              size="sm"
              onClick={exportarCSV}
              className="gap-1.5 border-border/60 hover:bg-muted text-xs"
            >
              <FileSpreadsheet className="w-3.5 h-3.5 text-emerald-400" />
              Exportar CSV / Excel
            </Button>
            <Button
              size="sm"
              onClick={imprimirRelatorio}
              className="gap-1.5 bg-primary text-primary-foreground hover:bg-primary/90 text-xs"
            >
              <Printer className="w-3.5 h-3.5" />
              Imprimir / Salvar PDF
            </Button>
          </div>
        </CardHeader>

        <CardContent className="p-0">
          {faltasDoDia.length === 0 && substitutosDoDia.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center p-6">
              <div className="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center mb-3">
                <CheckCircle2 className="w-6 h-6 text-emerald-400" />
              </div>
              <h4 className="text-sm font-bold text-foreground">100% de Presença</h4>
              <p className="text-xs text-muted-foreground mt-1 max-w-sm">
                Nenhuma falta ou substituição foi registrada hoje para a unidade selecionada. Todas as equipes estão operando normalmente.
              </p>
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {[...faltasDoDia, ...substitutosDoDia].map(({ colab, veiculo }) => (
                <div key={`${veiculo.id}-${colab.id}`} className="p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-muted/20 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-border/60 bg-muted shrink-0">
                      {colab.foto ? (
                        <img src={colab.foto} alt={colab.nome} className="w-full h-full object-cover" />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-xs font-bold text-muted-foreground">
                          {colab.nome?.charAt(0) ?? 'C'}
                        </div>
                      )}
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-bold text-foreground">{colab.nome}</p>
                        <Badge
                          variant={colab.status === 'falta' ? 'destructive' : 'secondary'}
                          className="text-[10px] px-2 py-0.5"
                        >
                          {colab.status === 'falta' ? 'Falta' : 'Substituto'}
                        </Badge>
                      </div>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {colab.cargo} • Matrícula: {colab.matricula || '-'}
                      </p>
                    </div>
                  </div>

                  <div className="flex flex-col sm:items-end text-xs text-muted-foreground bg-muted/30 sm:bg-transparent p-2.5 sm:p-0 rounded-xl">
                    <span className="font-semibold text-foreground">
                      {veiculo.prefixo} ({veiculo.placa})
                    </span>
                    <span className="text-[11px] mt-0.5">
                      {colab.status === 'falta'
                        ? `Motivo: ${colab.motivoFalta || 'Não informado'}`
                        : `Substituto por: ${colab.substitutoNome || 'Reserva'}`}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Seção 2: Histórico Mensal de Faltas */}
      <Card className="border-border/60">
        <CardHeader className="pb-4 border-b border-border/40 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <CardTitle className="text-base flex items-center gap-2">
              <TrendingUp className="w-4 h-4 text-primary" />
              Histórico Mensal de Ausências
            </CardTitle>
            <CardDescription className="mt-1">
              Registro acumulado de ausências por mês e colaborador
            </CardDescription>
          </div>

          <div className="flex items-center gap-1.5 overflow-x-auto pb-1 max-w-full">
            {MESES.map((mes, idx) => (
              <button
                key={mes}
                type="button"
                onClick={() => setSelectedMonth(idx)}
                className={cn(
                  'px-2.5 py-1 text-xs rounded-lg font-medium transition-all whitespace-nowrap cursor-pointer shrink-0',
                  selectedMonth === idx
                    ? 'bg-primary text-primary-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                )}
              >
                {mes.slice(0, 3)}
              </button>
            ))}
          </div>
        </CardHeader>

        <CardContent className="p-0">
          {faltasMesSelecionado.length === 0 ? (
            <div className="p-8 text-center text-xs text-muted-foreground">
              Nenhuma falta registrada no mês de {MESES[selectedMonth]} para a unidade selecionada.
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {faltasMesSelecionado.map((f, idx) => (
                <div key={idx} className="p-4 flex items-center justify-between hover:bg-muted/20 transition-colors">
                  <div className="flex items-center gap-3">
                    <div className="w-7 h-7 rounded-full bg-rose-500/10 border border-rose-500/30 text-rose-400 font-bold text-xs flex items-center justify-center shrink-0">
                      {f.totalFaltas}
                    </div>
                    <div>
                      <p className="text-sm font-bold text-foreground">{f.nome}</p>
                      <p className="text-xs text-muted-foreground">{f.cargo} • {f.regional}</p>
                    </div>
                  </div>

                  <Badge variant="destructive" className="text-xs font-semibold px-2.5 py-1">
                    {f.totalFaltas} {f.totalFaltas === 1 ? 'falta' : 'faltas'} em {MESES[selectedMonth]}
                  </Badge>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

