        <CardContent className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {veiculosFiltrados.map((v) => {
              const assentosList = [
                { pos: 'Motorista', colab: v.assentos?.motorista },
                { pos: 'Passageiro Dianteiro', colab: v.assentos?.frenteDir },
                { pos: 'Passageiro Traseiro 1', colab: v.assentos?.trasEsq },
                { pos: 'Passageiro Traseiro 2', colab: v.assentos?.trasDir },
              ];

              const totalAssentosPresentes = assentosList.filter((a) => a.colab && a.colab.status !== 'falta').length;

              return (
                <div
                  key={v.id}
                  className="rounded-2xl border border-border/70 bg-card/40 p-4 space-y-3 hover:border-primary/40 transition-all shadow-sm"
