                                Falta
                              </Badge>
                            ) : isSubst ? (
                              <Badge variant="outline" className="text-[9px] px-1.5 py-0 border-amber-500/40 text-amber-400 bg-amber-500/10">
                                Substituto
                              </Badge>
                            ) : (
                              <Badge variant="outline" className="text-[9px] px-1.5 py-0 border-emerald-500/40 text-emerald-400 bg-emerald-500/10">
                                Presente
                              </Badge>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Seção 3: Histórico Mensal de Faltas */}
      <Card className="border-border/60">
        <CardHeader className="pb-3 border-b border-border/40">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <CardTitle className="text-sm font-bold flex items-center gap-2">
                <ShieldAlert className="w-4 h-4 text-amber-400" />
                Histórico e Ranking Mensal de Faltas
              </CardTitle>
              <CardDescription className="text-xs text-muted-foreground mt-0.5">
                Colaboradores com maior índice de faltas no mês selecionado.
              </CardDescription>
            </div>

            {/* Seletor de Mês */}
            <div className="flex items-center gap-2">
              <span className="text-xs text-muted-foreground font-medium">Mês:</span>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(Number(e.target.value))}
                className="h-9 px-3 text-xs bg-muted/60 border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground font-semibold cursor-pointer"
              >
                {MESES.map((mes, idx) => (
                  <option key={mes} value={idx}>
                    {mes}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </CardHeader>
        <CardContent className="p-4">
          {faltasMesSelecionado.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <CheckCircle2 className="w-8 h-8 text-emerald-400 mb-2 opacity-80" />
              <p className="text-xs font-bold text-foreground">Nenhuma falta computada para {MESES[selectedMonth]}</p>
              <p className="text-[11px] text-muted-foreground">Unidade sem registros de ausência neste período.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {faltasMesSelecionado.map((item, idx) => (
                <div
                  key={idx}
                  className="p-3.5 rounded-xl border border-border/70 bg-card/50 flex items-center justify-between gap-3 hover:border-amber-500/40 transition-all shadow-sm"
                >
                  <div className="min-w-0">
                    <p className="text-xs font-bold text-foreground truncate">{item.nome}</p>
                    <p className="text-[11px] text-muted-foreground truncate">{item.cargo}</p>
                    <p className="text-[10px] text-muted-foreground/80 mt-0.5 flex items-center gap-1">
                      <MapPin className="w-3 h-3 text-primary/70" />
                      {item.regional}
                    </p>
                  </div>
                  <div className="text-right shrink-0">
                    <span className="inline-flex items-center justify-center w-8 h-8 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 font-extrabold text-sm">
                      {item.totalFaltas}
                    </span>
                    <p className="text-[9px] text-muted-foreground mt-0.5">faltas</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

