                          : 'border-amber-500/40 text-amber-400 bg-amber-500/10'
                      )}
                    >
                      {totalAssentosPresentes}/4 Operando
                    </Badge>
                  </div>

                  <div className="divide-y divide-border/30 pt-1">
                    {assentosList.map(({ pos, colab }, idx) => {
                      if (!colab) return null;
                      const isFalta = colab.status === 'falta';
                      const isSubst = colab.status === 'substituto';
                      const nomeDisplay = isSubst && colab.substitutoNome ? colab.substitutoNome : colab.nome;

                      return (
                        <div key={idx} className="py-1.5 flex items-center justify-between text-xs">
                          <div className="min-w-0 pr-2">
                            <p className={cn('truncate font-medium', isFalta ? 'text-rose-400 line-through' : 'text-foreground')}>
