                            </p>
                            <p className="text-[10px] text-muted-foreground truncate">{pos}</p>
                          </div>
                          <div>
                            {isFalta ? (
                              <Badge variant="outline" className="text-[9px] px-1.5 py-0 border-rose-500/40 text-rose-400 bg-rose-500/10">
                                Falta
                              </Badge>
                            ) : isSubst ? (
