import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  RefreshCw,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  FileCheck
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
}

const posicaoLabel: Record<string, string> = {
  motorista: 'Motorista / Líder',
  frente_dir: 'Dianteiro Direito',
  tras_esq: 'Traseiro Esquerdo',
  tras_dir: 'Traseiro Direito',
};

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onImportarColaboradores,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>('todas');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Estados do Modal de Importação Excel / CSV
  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lista de colaboradores extraídos dos veículos e lista reserva
  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    // Adiciona colaboradores reserva se houver
    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresImportados, setColaboradoresImportados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresImportados];
  }, [colaboradoresBase, colaboradoresImportados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  // Função para processar arquivo Excel / CSV importado
  const processarArquivo = (file: File) => {
    setErroImportacao(null);
    setArquivoNome(file.name);

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target?.result as string;
        if (!text) {
          setErroImportacao('O arquivo selecionado está vazio.');
          return;
        }

        // Divide linhas considerando diferentes quebras de linha
        const linhas = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
        if (linhas.length < 2) {
          setErroImportacao('O arquivo precisa conter cabeçalho e pelo menos 1 linha de dados.');
          return;
        }

        // Identifica separador (, ou ;)
        const headerLinha = linhas[0];
        const separador = headerLinha.includes(';') ? ';' : ',';
        const headers = headerLinha.split(separador).map((h) => h.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''));

        // Índices das colunas
        const idxNome = headers.findIndex((h) => h.includes('nome') || h.includes('colaborador'));
        const idxCargo = headers.findIndex((h) => h.includes('cargo') || h.includes('funcao') || h.includes('ocupacao'));
        const idxUnidade = headers.findIndex((h) => h.includes('unidade') || h.includes('regional') || h.includes('polo') || h.includes('cidade'));
        const idxMatricula = headers.findIndex((h) => h.includes('matricula') || h.includes('registro') || h.includes('id'));
        const idxTelefone = headers.findIndex((h) => h.includes('telefone') || h.includes('celular') || h.includes('contato'));

        if (idxNome === -1) {
          setErroImportacao('Coluna de "Nome" não encontrada no cabeçalho do arquivo.');
          return;
        }

        const registros: RegistroImportado[] = [];

        for (let i = 1; i < linhas.length; i++) {
          const valores = linhas[i].split(separador).map((v) => v.trim().replace(/^["']|["']$/g, ''));
          const nome = valores[idxNome] || '';
          if (!nome) continue;

          const cargo = (idxCargo !== -1 && valores[idxCargo]) ? valores[idxCargo] : 'Operador';
          const unidadeTexto = (idxUnidade !== -1 && valores[idxUnidade]) ? valores[idxUnidade].toLowerCase() : '';

          let unidade: 'ribas' | 'agua_clara' = 'ribas';
          if (unidadeTexto.includes('agua') || unidadeTexto.includes('clara') || unidadeTexto.includes('agc')) {
            unidade = 'agua_clara';
          }

          const matricula = idxMatricula !== -1 ? valores[idxMatricula] : `MAT-${Math.floor(1000 + Math.random() * 9000)}`;
          const telefone = idxTelefone !== -1 ? valores[idxTelefone] : '(67) 99999-0000';

          registros.push({
            nome,
            cargo,
            unidade,
            matricula,
            telefone,
          });
        }

        if (registros.length === 0) {
          setErroImportacao('Nenhum registro válido foi encontrado para importação.');
          return;
        }

        setRegistrosPrevia(registros);
      } catch (err) {
        setErroImportacao('Erro ao processar o arquivo. Certifique-se de que é um formato válido (.csv ou .xlsx/.xls exportado como csv).');
      }
    };

    reader.onerror = () => {
      setErroImportacao('Falha na leitura do arquivo.');
    };

    reader.readAsText(file, 'UTF-8');
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processarArquivo(file);
    }
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const file = e.dataTransfer.files?.[0];
    if (file) {
      processarArquivo(file);
    }
  };

  const confirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novos: ColaboradorCompleto[] = registrosPrevia.map((reg, i) => ({
      id: `imp-${Date.now()}-${i}`,
      nome: reg.nome,
      cargo: reg.cargo,
      matricula: reg.matricula || `MAT-${1000 + i}`,
      foto: `https://images.unsplash.com/photo-${1535713875002 + i}?w=150&auto=format&fit=crop&q=80`,
      telefone: reg.telefone || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'importados',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Importado',
      veiculoPlaca: '-',
      regional: reg.unidade,
    }));

    setColaboradoresImportados((prev) => [...prev, ...novos]);
    if (onImportarColaboradores) {
      onImportarColaboradores(novos);
    }

    setSucessoMsg(`${novos.length} colaboradores importados com sucesso!`);
    setRegistrosPrevia([]);
    setArquivoNome('');
    setTimeout(() => {
      setModalImportAberto(false);
      setSucessoMsg(null);
    }, 1800);
  };

  const baixarModeloCSV = () => {
    const csvContent = "Nome;Funcao;Unidade;Matricula;Telefone\n" +
      "Carlos Alberto Souza;Operador I;Ribas do Rio Pardo;MAT-4021;(67) 99811-2233\n" +
      "Marcos Vinicius Lima;Motorista;Agua Clara;MAT-4022;(67) 99722-4455\n" +
      "Juliana Mendes Rocha;Tecnica Florestal;Ribas do Rio Pardo;MAT-4023;(67) 99633-6677";

    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Header com Título e Botão de Importação Excel */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-card/60 backdrop-blur-md p-5 rounded-2xl border border-border/70 shadow-sm">
        <div>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-primary/15 border border-primary/25 flex items-center justify-center">
              <Users className="w-4 h-4 text-primary" />
            </div>
            <h2 className="text-lg font-bold text-foreground">Gestão de Colaboradores</h2>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            Consulte a escala, presenças e importe dados de planilhas Excel / CSV
          </p>
        </div>

        <div className="flex items-center gap-2.5 flex-wrap">
          <Button
            type="button"
            onClick={baixarModeloCSV}
            variant="outline"
            size="sm"
            className="text-xs gap-1.5 border-border/80 hover:bg-muted font-medium cursor-pointer"
          >
            <Download className="w-3.5 h-3.5 text-muted-foreground" />
            <span>Baixar Modelo CSV</span>
          </Button>

          <Button
            type="button"
            onClick={() => {
              setErroImportacao(null);
              setRegistrosPrevia([]);
              setArquivoNome('');
              setModalImportAberto(true);
            }}
            className="text-xs gap-2 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold shadow-md shadow-emerald-600/20 cursor-pointer"
          >
            <UploadCloud className="w-4 h-4" />
            <span>Importar Planilha Excel</span>
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {[
          { label: 'Total Geral', value: stats.total, color: 'text-foreground', bg: 'bg-muted/40' },
          { label: 'Presentes', value: stats.presentes, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
          { label: 'Faltas Registradas', value: stats.faltas, color: 'text-rose-400', bg: 'bg-rose-500/10' },
          { label: 'Substitutos Ativos', value: stats.substitutos, color: 'text-amber-400', bg: 'bg-amber-500/10' },
        ].map((s) => (
          <Card key={s.label} className={cn('border-border/60 shadow-sm', s.bg)}>
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
              <p className={cn('text-2xl font-extrabold mt-1 tracking-tight', s.color)}>{s.value}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Buscar por nome, função/cargo, matrícula, veículo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9 text-xs sm:text-sm bg-card/60"
          />
        </div>

        {/* Filtro de Unidade/Regional */}
        <div className="flex gap-1.5 items-center bg-card/50 p-1 rounded-xl border border-border/60">
          {(['todas', 'ribas', 'agua_clara'] as const).map((reg) => (
            <button
              key={reg}
              type="button"
              onClick={() => setFilterRegional(reg)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all cursor-pointer',
                filterRegional === reg
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/60'
              )}
            >
              {reg === 'todas' ? 'Todas Unidades' : reg === 'ribas' ? 'Ribas' : 'Água Clara'}
            </button>
          ))}
        </div>

        {/* Filtro de Status */}
        <div className="flex gap-1.5 flex-wrap items-center bg-card/50 p-1 rounded-xl border border-border/60">
          {(['todos', 'presente', 'falta', 'substituto'] as const).map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => setFilterStatus(s)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-semibold transition-all cursor-pointer',
                filterStatus === s
                  ? 'bg-secondary text-secondary-foreground border border-border/80 shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/60'
              )}
            >
              {s === 'todos' ? 'Todos' : s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Lista de Colaboradores */}
      <Card className="border-border/60 shadow-lg overflow-hidden">
        <CardHeader className="pb-3 border-b border-border/40 bg-muted/20">
          <CardTitle className="text-sm font-bold flex items-center gap-2">
            <Users className="w-4 h-4 text-primary" />
            Colaboradores Cadastrados
            <span className="ml-auto text-xs font-normal text-muted-foreground">
              {colaboradoresFiltrados.length} de {todosColaboradores.length} encontrados
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {colaboradoresFiltrados.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <UserX className="w-10 h-10 text-muted-foreground/40 mb-3" />
              <p className="text-sm font-semibold text-foreground">Nenhum colaborador encontrado</p>
              <p className="text-xs text-muted-foreground mt-1">Tente ajustar os filtros ou importar uma nova planilha.</p>
            </div>
          ) : (
            <div className="divide-y divide-border/40">
              {colaboradoresFiltrados.map((c) => {
                const isExpanded = expandedId === c.id;
                const sc = statusConfig[c.status] ?? statusConfig.presente;
                return (
                  <div key={c.id} className="hover:bg-muted/30 transition-colors">
                    <div
                      className="flex items-center justify-between p-4 cursor-pointer"
                      onClick={() => setExpandedId(isExpanded ? null : c.id)}
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <img
                          src={c.foto || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80'}
                          alt={c.nome}
                          className="w-10 h-10 rounded-xl object-cover border border-border shrink-0 bg-muted"
                          onError={(e) => {
                            (e.target as HTMLImageElement).src =
                              'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80';
                          }}
                        />
                        <div className="min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-sm font-bold text-foreground truncate">{c.nome}</span>
                            <span className={cn('px-2 py-0.5 rounded-full text-[10px] font-bold border', sc.className)}>
                              {sc.label}
                            </span>
                            <span className={cn(
                              'px-2 py-0.5 rounded-full text-[10px] font-semibold border',
                              c.regional === 'ribas'
                                ? 'bg-sky-500/10 text-sky-400 border-sky-500/20'
                                : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                            )}>
                              {regionalLabel[c.regional] || 'Ribas do Rio Pardo'}
                            </span>
                          </div>
                          <p className="text-xs text-muted-foreground mt-0.5">
                            {c.cargo} • {c.matricula || 'Sem Matrícula'} • {c.veiculoPrefixo}
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 shrink-0">
                        {isExpanded ? (
                          <ChevronUp className="w-4 h-4 text-muted-foreground" />
                        ) : (
                          <ChevronDown className="w-4 h-4 text-muted-foreground" />
                        )}
                      </div>
                    </div>

                    {isExpanded && (
                      <div className="px-4 pb-4 pt-1 border-t border-border/30 bg-muted/10 grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
                        <div className="space-y-1">
                          <span className="text-muted-foreground block text-[11px]">Posição no Veículo</span>
                          <span className="font-semibold text-foreground">
                            {posicaoLabel[c.posicaoVeiculo] || c.posicaoVeiculo}
                          </span>
                        </div>
                        <div className="space-y-1">
                          <span className="text-muted-foreground block text-[11px]">Unidade / Regional</span>
                          <span className="font-semibold text-foreground">
                            {regionalLabel[c.regional] || 'Ribas do Rio Pardo'}
                          </span>
                        </div>
                        <div className="space-y-1">
                          <span className="text-muted-foreground block text-[11px]">Telefone</span>
                          <span className="font-semibold text-foreground flex items-center gap-1">
                            <Phone className="w-3 h-3 text-muted-foreground" />
                            {c.telefone || 'Não informado'}
                          </span>
                        </div>
                        {c.status === 'falta' && c.motivoFalta && (
                          <div className="col-span-full mt-1 p-2.5 rounded-lg bg-rose-500/10 border border-rose-500/25 text-rose-300">
                            <span className="font-bold block">Motivo da Falta:</span>
                            {c.motivoFalta}
                          </div>
                        )}
                        {c.status === 'substituto' && c.substitutoNome && (
                          <div className="col-span-full mt-1 p-2.5 rounded-lg bg-amber-500/10 border border-amber-500/25 text-amber-300">
                            <span className="font-bold block">Substituindo Colaborador:</span>
                            {c.substitutoNome}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Modal de Importação Excel / CSV */}
      {modalImportAberto && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-md animate-in fade-in duration-150"
          onClick={() => setModalImportAberto(false)}
        >
          <div
            className="relative w-full max-w-2xl bg-card border border-border rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
            onClick={(e) => e.stopPropagation()}
          >
            {/* Header Modal */}
            <div className="flex items-center justify-between px-6 py-5 border-b border-border bg-muted/20">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 flex items-center justify-center">
                  <FileSpreadsheet className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-base font-bold text-foreground">Importar Colaboradores via Excel / CSV</h3>
                  <p className="text-xs text-muted-foreground">Envie sua planilha com as colunas Nome, Função e Unidade</p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => setModalImportAberto(false)}
                className="p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-muted transition-colors cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Conteúdo do Modal */}
            <div className="p-6 overflow-y-auto space-y-4 flex-1">
              {/* Feedback de Sucesso */}
              {sucessoMsg && (
                <div className="flex items-center gap-2 p-3.5 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 text-sm font-semibold">
                  <CheckCircle2 className="w-5 h-5 shrink-0" />
                  <span>{sucessoMsg}</span>
                </div>
              )}

              {/* Feedback de Erro */}
              {erroImportacao && (
                <div className="flex items-center gap-2 p-3.5 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-400 text-xs sm:text-sm font-semibold">
                  <AlertCircle className="w-5 h-5 shrink-0" />
                  <span>{erroImportacao}</span>
                </div>
              )}

              {/* Área de Drag and Drop */}
              <div
                onDragOver={(e) => e.preventDefault()}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
                className={cn(
                  'border-2 border-dashed rounded-2xl p-6 text-center cursor-pointer transition-all flex flex-col items-center justify-center gap-3',
                  arquivoNome
                    ? 'border-emerald-500/50 bg-emerald-500/5'
                    : 'border-border/80 hover:border-primary/60 hover:bg-muted/30 bg-muted/10'
                )}
              >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv, .xlsx, .xls, text/csv"
                  className="hidden"
                  onChange={handleFileChange}
                />
                <div className="w-12 h-12 rounded-2xl bg-primary/10 border border-primary/20 text-primary flex items-center justify-center">
                  <UploadCloud className="w-6 h-6" />
                </div>
                <div>
                  <p className="text-sm font-bold text-foreground">
                    {arquivoNome ? arquivoNome : 'Arraste o arquivo ou clique para selecionar'}
                  </p>
                  <p className="text-xs text-muted-foreground mt-1">
                    Suporta arquivos <strong>.CSV</strong> ou planilhas <strong>Excel</strong> (.xlsx / .csv)
                  </p>
                </div>
                <Button type="button" variant="outline" size="sm" className="text-xs pointer-events-none mt-1">
                  Selecionar Arquivo
                </Button>
              </div>

              {/* Explicação das Colunas */}
              <div className="p-3.5 rounded-xl bg-muted/30 border border-border/50 text-xs text-muted-foreground space-y-1.5">
                <p className="font-semibold text-foreground flex items-center gap-1.5">
                  <FileCheck className="w-4 h-4 text-primary" /> Colunas Reconhecidas Automaticamente:
                </p>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 pt-1 text-[11px]">
                  <div className="p-2 rounded-lg bg-card/60 border border-border/40">
                    <span className="font-bold text-foreground block">1. Nome</span>
                    <span className="text-muted-foreground">Nome completo do colaborador</span>
                  </div>
                  <div className="p-2 rounded-lg bg-card/60 border border-border/40">
                    <span className="font-bold text-foreground block">2. Função / Cargo</span>
                    <span className="text-muted-foreground">Ex: Motorista, Operador I, Técnico</span>
                  </div>
                  <div className="p-2 rounded-lg bg-card/60 border border-border/40">
                    <span className="font-bold text-foreground block">3. Unidade / Regional</span>
                    <span className="text-muted-foreground">Ribas do Rio Pardo ou Água Clara</span>
                  </div>
                </div>
              </div>

              {/* Pré-visualização da Tabela de Registros Encontrados */}
              {registrosPrevia.length > 0 && (
                <div className="space-y-2 pt-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-foreground">
                      Registros Identificados ({registrosPrevia.length}):
                    </span>
                    <span className="text-[11px] text-muted-foreground">
                      Revise antes de confirmar
                    </span>
                  </div>

                  <div className="max-h-48 overflow-y-auto border border-border/60 rounded-xl divide-y divide-border/40 text-xs">
                    {registrosPrevia.map((reg, idx) => (
                      <div key={idx} className="p-2.5 flex items-center justify-between gap-2 hover:bg-muted/40">
                        <div className="min-w-0">
                          <p className="font-bold text-foreground truncate">{reg.nome}</p>
                          <p className="text-[11px] text-muted-foreground">{reg.cargo}</p>
                        </div>
                        <span className={cn(
                          'px-2 py-0.5 rounded-full text-[10px] font-bold shrink-0 border',
                          reg.unidade === 'ribas'
                            ? 'bg-sky-500/15 text-sky-400 border-sky-500/30'
                            : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30'
                        )}>
                          {reg.unidade === 'ribas' ? 'Ribas' : 'Água Clara'}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Rodapé do Modal */}
            <div className="flex items-center justify-between px-6 py-4 border-t border-border bg-muted/20">
              <Button
                type="button"
                variant="outline"
                onClick={baixarModeloCSV}
                className="text-xs gap-1.5"
              >
                <Download className="w-3.5 h-3.5" />
                Baixar Modelo
              </Button>

              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant="ghost"
                  onClick={() => setModalImportAberto(false)}
                  className="text-xs"
                >
                  Cancelar
                </Button>
                <Button
                  type="button"
                  onClick={confirmarImportacao}
                  disabled={registrosPrevia.length === 0}
                  className="text-xs gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold"
                >
                  <CheckCircle2 className="w-3.5 h-3.5" />
                  Confirmar Importação ({registrosPrevia.length})
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

