import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, StatusPresenca, MotivoFalta, Colaborador, Regional } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'relatorios' | 'colaboradores'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Manipulação de Presença nos Veículos
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentosAtualizados = { ...v.assentos };
        const chaves: Array<keyof typeof assentosAtualizados> = [
          'motorista',
          'frenteDir',
          'trasEsq',
          'trasDir',
        ];

        chaves.forEach((chave) => {
          const colab = assentosAtualizados[chave];
          if (colab && colab.id === colaboradorId) {
            assentosAtualizados[chave] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' && substituto ? substituto.id : undefined,
              substitutoNome: novoStatus === 'substituto' && substituto ? substituto.nome : undefined,
            };
          }
        });

        return {
          ...v,
          assentos: assentosAtualizados,
        };
      })
    );
  };

  // Salvar Novo Veículo / Nova Equipe
  const handleSaveNewTeam = (data: {
    prefixo: string;
    placa: string;
    modelo: string;
    regional: 'ribas' | 'agua_clara';
  }) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: data.prefixo,
      placa: data.placa,
      modelo: data.modelo,
      ano: 2024,
      regional: data.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: `EQ-${data.prefixo.replace(/\D/g, '') || '00'}A`,
      equipe2Codigo: `EQ-${data.prefixo.replace(/\D/g, '') || '00'}B`,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: 'Novo Motorista',
          cargo: 'Motorista / Operador',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99981-0000',
          status: 'presente',
          equipeId: `EQ-${data.prefixo}A`,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: 'Novo Operador Dianteiro',
          cargo: 'Operador de Campo',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99981-0001',
          status: 'presente',
          equipeId: `EQ-${data.prefixo}A`,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: 'Novo Operador Traseiro 1',
          cargo: 'Técnico de Campo',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99981-0002',
          status: 'presente',
          equipeId: `EQ-${data.prefixo}B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: 'Novo Operador Traseiro 2',
          cargo: 'Ajudante Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99981-0003',
          status: 'presente',
          equipeId: `EQ-${data.prefixo}B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  // Receber colaboradores importados do Excel
  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const novosReservas: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto,
      telefone: n.telefone,
      status: n.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...prev, ...novosReservas]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-primary/20">
      {/* Navbar Superior */}
      <Navbar
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        selectedRegional={selectedRegional}
        setSelectedRegional={setSelectedRegional}
        selectedDate={selectedDate}
        setSelectedDate={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Aba Veículos */}
        {activeTab === 'veiculos' && (
          <div className="space-y-6 animate-in fade-in duration-150">
            <MetricsHeader
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              onFiltroRegionalChange={(reg) => setSelectedRegional(reg)}
              onNovaEquipe={() => setIsNewTeamModalOpen(true)}
            />
            <VehicleCardGrid
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              onUpdateStatus={handleUpdateStatus}
              filtroRegional={selectedRegional}
              selectedRegional={selectedRegional}
            />
          </div>
        )}

        {/* Aba Equipes */}
        {activeTab === 'equipes' && (
          <div className="animate-in fade-in duration-150">
            <TeamsManagement veiculos={veiculos} selectedRegional={selectedRegional} />
          </div>
        )}

        {/* Aba Relatórios */}
        {activeTab === 'relatorios' && (
          <div className="animate-in fade-in duration-150">
            <ExportReports
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedDate={selectedDate}
            />
          </div>
        )}

        {/* Aba Colaboradores */}
        {activeTab === 'colaboradores' && (
          <div className="animate-in fade-in duration-150">
            <CollaboratorsManagement
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              onImportarColaboradores={handleImportarColaboradores}
            />
          </div>
        )}
      </main>

      {/* Modal de Nova Equipe */}
      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onSave={handleSaveNewTeam}
        colaboradoresReserva={colaboradoresReserva}
      />
    </div>
  );
}

