import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Regional, StatusPresenca, MotivoFalta, Colaborador, Veiculo, MetricasGerais } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Manipular atualização de presença de colaborador
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((v) => {
        if (v.id !== veiculoId) return v;

        const updatedAssentos = { ...v.assentos };
        const keys: Array<keyof typeof updatedAssentos> = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'];

        keys.forEach((k) => {
          if (updatedAssentos[k]?.id === colaboradorId) {
            updatedAssentos[k] = {
              ...updatedAssentos[k],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos: updatedAssentos };
      })
    );
  };

  // Manipular criação de nova equipe
  const handleCreateTeam = (teamData: {
    nome: string;
    numero: 1 | 2;
    regional: 'ribas' | 'agua_clara';
    veiculoPrefixo: string;
    veiculoPlaca: string;
    liderNome: string;
    membro2Nome: string;
    membro3Nome: string;
    membro4Nome: string;
  }) => {
    const novoVeiculoId = `vtr-${Date.now()}`;
    const prefixoFormatado = teamData.veiculoPrefixo.toUpperCase();
    const placaFormatada = teamData.veiculoPlaca.toUpperCase();

    const novoVeiculo: Veiculo = {
      id: novoVeiculoId,
      prefixo: prefixoFormatado,
      placa: placaFormatada,
      modelo: 'Nova Viatura Operacional',
      ano: new Date().getFullYear(),
      regional: teamData.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: `EQ-${prefixoFormatado.replace(/\s+/g, '')}-A`,
      equipe2Codigo: `EQ-${prefixoFormatado.replace(/\s+/g, '')}-B`,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: teamData.liderNome || 'Líder de Equipe',
          cargo: 'Motorista / Líder Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-1001',
          status: 'presente',
          equipeId: `EQ-${prefixoFormatado.replace(/\s+/g, '')}-A`,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: teamData.membro2Nome || 'Operador 2',
          cargo: 'Operador de Máquinas',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-1002',
          status: 'presente',
          equipeId: `EQ-${prefixoFormatado.replace(/\s+/g, '')}-A`,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: teamData.membro3Nome || 'Operador 3',
          cargo: 'Técnico Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-1003',
          status: 'presente',
          equipeId: `EQ-${prefixoFormatado.replace(/\s+/g, '')}-B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: teamData.membro4Nome || 'Operador 4',
          cargo: 'Ajudante Geral',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-1004',
          status: 'presente',
          equipeId: `EQ-${prefixoFormatado.replace(/\s+/g, '')}-B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  // Manipular adição manual de colaborador no banco de reserva
  const handleAdicionarColaborador = (novoColab: ColaboradorCompleto) => {
    const colabReserva: Colaborador = {
      id: novoColab.id,
      nome: novoColab.nome,
      cargo: novoColab.cargo,
      matricula: novoColab.matricula,
      foto: novoColab.foto || '',
      telefone: novoColab.telefone,
      status: novoColab.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };
    setColaboradoresReserva((prev) => [colabReserva, ...prev]);
  };

  // Manipular importação em lote
  const handleImportarColaboradores = (novosColaboradores: ColaboradorCompleto[]) => {
    const novosReserva: Colaborador[] = novosColaboradores.map((c) => ({
      id: c.id,
      nome: c.nome,
      cargo: c.cargo,
      matricula: c.matricula,
      foto: c.foto || '',
      telefone: c.telefone,
      status: c.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));
    setColaboradoresReserva((prev) => [...prev, ...novosReserva]);
  };

  // Cálculo de Métricas Gerais
  const metricas: MetricasGerais = useMemo(() => {
    const veiculosFiltrados = (veiculos || []).filter((v) => {
      if (!v) return false;
      return selectedRegional === 'todas' || v.regional === selectedRegional;
    });

    let totalColabs = 0;
    let presentes = 0;
    let faltas = 0;
    let substitutos = 0;
    let equipesCompletas = 0;
    let equipesIncompletas = 0;

    veiculosFiltrados.forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos = [
        v.assentos.motorista,
        v.assentos.frenteDir,
        v.assentos.trasEsq,
        v.assentos.trasDir,
      ].filter(Boolean);

      assentos.forEach((c) => {
        if (!c) return;
        totalColabs++;
        if (c.status === 'presente') presentes++;
        else if (c.status === 'falta') faltas++;
        else if (c.status === 'substituto') substitutos++;
      });

      // Equipe 1 (motorista + frenteDir)
      const eq1Presentes = [v.assentos.motorista, v.assentos.frenteDir].filter((c) => c && c.status !== 'falta').length;
      if (eq1Presentes === 2) equipesCompletas++;
      else equipesIncompletas++;

      // Equipe 2 (trasEsq + trasDir)
      const eq2Presentes = [v.assentos.trasEsq, v.assentos.trasDir].filter((c) => c && c.status !== 'falta').length;
      if (eq2Presentes === 2) equipesCompletas++;
      else equipesIncompletas++;
    });

    const taxaPresenca = totalColabs > 0 ? Math.round(((presentes + substitutos) / totalColabs) * 100) : 100;

    return {
      totalVeiculos: veiculosFiltrados.length,
      veiculosAtivos: veiculosFiltrados.filter((v) => v?.statusOperacional === 'ativo').length,
      totalEquipes: veiculosFiltrados.length * 2,
      equipesCompletas,
      equipesIncompletas,
      totalColaboradores: totalColabs,
      colaboradoresPresentes: presentes,
      colaboradoresFaltas: faltas,
      colaboradoresSubstitutos: substitutos,
      taxaPresenca,
    };
  }, [veiculos, selectedRegional]);

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-primary/20 selection:text-primary">
      {/* Navbar Global */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas Operacionais e Botão Nova Equipe */}
        <MetricsHeader
          metricas={metricas}
          selectedRegional={selectedRegional}
          onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
        />

        {/* Visualização por Abas */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onUpdateStatus={handleUpdateStatus}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal para Adicionar Nova Equipe */}
      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onCreateTeam={handleCreateTeam}
      />
    </div>
  );
}

