import React from 'react';
import {
  Car,
  Calendar,
  Layers,
  MapPin,
  Users,
  FileSpreadsheet,
  PlusCircle,
  Sparkles,
} from 'lucide-react';
import { Regional } from '../types';
import { Button } from './ui/button';
import { Badge } from './ui/badge';
import { cn } from '@/lib/utils';

export interface NavbarProps {
  currentTab: 'veiculos' | 'colaboradores' | 'relatorios' | 'showcase';
  setCurrentTab: (tab: 'veiculos' | 'colaboradores' | 'relatorios' | 'showcase') => void;
  selectedRegional: Regional;
  setSelectedRegional: (reg: Regional) => void;
  selectedDate: Date;
  setSelectedDate: (date: Date) => void;
  onOpenNewTeamModal?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  currentTab,
  setCurrentTab,
  selectedRegional,
  setSelectedRegional,
  selectedDate,
  setSelectedDate,
  onOpenNewTeamModal,
}) => {
  const tabs = [
    { id: 'veiculos' as const, label: 'Veículos & Assentos', icon: Car },
    { id: 'colaboradores' as const, label: 'Colaboradores', icon: Users },
    { id: 'relatorios' as const, label: 'Relatórios & Exportação', icon: FileSpreadsheet },
  ];

  const regionais: Array<{ id: Regional; label: string }> = [
    { id: 'todas', label: 'Todas as Unidades' },
    { id: 'ribas', label: 'Ribas do Rio Pardo' },
    { id: 'agua_clara', label: 'Água Clara' },
  ];

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.value) {
      const [year, month, day] = e.target.value.split('-').map(Number);
      setSelectedDate(new Date(year, month - 1, day));
    }
  };

  const formattedDateValue = selectedDate instanceof Date && !isNaN(selectedDate.getTime())
    ? selectedDate.toISOString().split('T')[0]
    : new Date().toISOString().split('T')[0];

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border/80 bg-card/85 backdrop-blur-xl shadow-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row items-center justify-between py-3 gap-3">

          {/* Logo & Título Principal */}
          <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-start">
            <div className="flex items-center gap-3 cursor-pointer" onClick={() => setCurrentTab('veiculos')}>
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-emerald-600 to-teal-400 flex items-center justify-center text-white shadow-lg shadow-emerald-500/20">
                <Layers className="w-5 h-5" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <h1 className="text-base sm:text-lg font-black tracking-tight text-foreground">
                    Controle de Presença
                  </h1>
                  <Badge variant="outline" className="text-[10px] bg-emerald-500/10 text-emerald-400 border-emerald-500/30">
                    Operacional
                  </Badge>
                </div>
                <p className="text-xs text-muted-foreground">Gestão de Equipes, Faltas & Veículos</p>
              </div>
            </div>

            {/* Botão Nova Equipe mobile */}
            {onOpenNewTeamModal && (
              <Button
                variant="default"
                size="sm"
                onClick={onOpenNewTeamModal}
                className="md:hidden flex items-center gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold shadow"
              >
                <PlusCircle className="w-4 h-4" />
                <span>Nova Equipe</span>
              </Button>
            )}
          </div>

          {/* Abas de Navegação Superiores (Totalmente Clicáveis e Destacadas) */}
          <nav className="flex items-center gap-1.5 p-1 bg-muted/60 border border-border/60 rounded-xl w-full md:w-auto overflow-x-auto justify-center">
            {tabs.map((tab) => {
              const Icon = tab.icon;
              const isActive = currentTab === tab.id;
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setCurrentTab(tab.id)}
                  className={cn(
                    'flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs sm:text-sm font-semibold transition-all cursor-pointer whitespace-nowrap',
                    isActive
                      ? 'bg-card text-foreground shadow-sm border border-border text-emerald-400 font-bold'
                      : 'text-muted-foreground hover:text-foreground hover:bg-card/40'
                  )}
                >
                  <Icon className={cn('w-4 h-4', isActive ? 'text-emerald-400' : 'text-muted-foreground')} />
                  <span>{tab.label}</span>
                </button>
              );
            })}
          </nav>

          {/* Controles do Topo: Filtro Regional, Data e Ação */}
          <div className="flex items-center gap-2 w-full md:w-auto justify-end flex-wrap">

            {/* Seletor de Regional */}
            <div className="flex items-center gap-1 bg-muted/40 border border-border rounded-xl p-1">
              <MapPin className="w-3.5 h-3.5 text-muted-foreground ml-1.5 hidden sm:inline-block" />
              {regionais.map((reg) => (
                <button
                  key={reg.id}
                  type="button"
                  onClick={() => setSelectedRegional(reg.id)}
                  className={cn(
                    'px-2.5 py-1 text-xs font-medium rounded-lg transition-all cursor-pointer whitespace-nowrap',
                    selectedRegional === reg.id
                      ? 'bg-primary text-primary-foreground font-semibold shadow-sm'
                      : 'text-muted-foreground hover:text-foreground hover:bg-card/60'
                  )}
                >
                  {reg.label.replace('Todas as Unidades', 'Todas').replace('Ribas do Rio Pardo', 'Ribas')}
                </button>
              ))}
            </div>

            {/* Seletor de Data do Plantão */}
            <div className="flex items-center gap-1.5 bg-muted/40 border border-border rounded-xl px-2.5 py-1 text-xs text-foreground">
              <Calendar className="w-3.5 h-3.5 text-muted-foreground" />
              <input
                type="date"
                value={formattedDateValue}
                onChange={handleDateChange}
                className="bg-transparent text-xs text-foreground focus:outline-none cursor-pointer"
              />
            </div>

            {/* Botão de Adicionar Nova Equipe (Desktop) */}
            {onOpenNewTeamModal && (
              <Button
                variant="default"
                size="sm"
                onClick={onOpenNewTeamModal}
                className="hidden md:flex items-center gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold text-xs shadow cursor-pointer"
              >
                <PlusCircle className="w-4 h-4" />
                <span>Nova Equipe</span>
              </Button>
            )}
          </div>

        </div>
      </div>
    </header>
  );
};

