  onTabChange: (tab: 'veiculos' | 'colaboradores' | 'relatorios' | 'equipes') => void;
  onNovaEquipeClick: () => void;
  onNovoColaboradorClick?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  selectedRegional,
