export default function App() {
  const [currentTab, setCurrentTab] = useState<'veiculos' | 'colaboradores' | 'relatorios' | 'showcase'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Handler para atualizar presença/falta/substituto de um colaborador em um assento
  const handleSaveAttendance = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentos = { ...v.assentos };

        (Object.keys(assentos) as Array<keyof typeof assentos>).forEach((key) => {
          if (assentos[key]?.id === colaboradorId) {
            assentos[key] = {
              ...assentos[key],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos };
      })
    );
  };

  // Handler para criar nova equipe / novo veículo
  const handleSaveNewTeam = (novaEquipeData: any) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: novaEquipeData.prefixo || `CARRO ${Math.floor(100 + Math.random() * 900)}`,
      placa: novaEquipeData.placa || 'BRA-2024',
      modelo: novaEquipeData.modelo || 'Toyota Hilux 4x4',
      ano: 2024,
      regional: novaEquipeData.regional || 'ribas',
      statusOperacional: 'ativo',
      equipe1Codigo: novaEquipeData.equipe1Codigo || 'EQ-NOVA-A',
      equipe2Codigo: novaEquipeData.equipe2Codigo || 'EQ-NOVA-B',
      assentos: {
        motorista: novaEquipeData.assentos?.motorista || {
          id: `col-${Date.now()}-1`,
          nome: novaEquipeData.motoristaNome || 'Motorista Titular',
          cargo: 'Motorista / Líder',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-0001',
          status: 'presente',
          equipeId: novaEquipeData.equipe1Codigo || 'EQ-NOVA-A',
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: novaEquipeData.assentos?.frenteDir || {
          id: `col-${Date.now()}-2`,
          nome: novaEquipeData.ajudante1Nome || 'Operador Frente',
          cargo: 'Operador de Máquinas',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-0002',
          status: 'presente',
          equipeId: novaEquipeData.equipe1Codigo || 'EQ-NOVA-A',
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: novaEquipeData.assentos?.trasEsq || {
          id: `col-${Date.now()}-3`,
          nome: novaEquipeData.ajudante2Nome || 'Operador Trás Esq',
          cargo: 'Técnico Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-0003',
          status: 'presente',
          equipeId: novaEquipeData.equipe2Codigo || 'EQ-NOVA-B',
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: novaEquipeData.assentos?.trasDir || {
          id: `col-${Date.now()}-4`,
          nome: novaEquipeData.ajudante3Nome || 'Ajudante Trás Dir',
          cargo: 'Ajudante Geral',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: '',
          telefone: '(67) 99999-0004',
          status: 'presente',
          equipeId: novaEquipeData.equipe2Codigo || 'EQ-NOVA-B',
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
    setIsNewTeamModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col selection:bg-emerald-500 selection:text-white">
      {/* Barra de Navegação Superior com todas as abas e botões clicáveis */}
      <Navbar
        currentTab={currentTab}
        setCurrentTab={setCurrentTab}
        selectedRegional={selectedRegional}
        setSelectedRegional={setSelectedRegional}
        selectedDate={selectedDate}
        setSelectedDate={setSelectedDate}
        onOpenNewTeamModal={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Visualização de Veículos & Assentos */}
        {currentTab === 'veiculos' && (
          <div className="space-y-6 animate-in fade-in duration-200">
            <MetricsHeader
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
            />
            <VehicleCardGrid
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              onSaveAttendance={handleSaveAttendance}
              colaboradoresReserva={colaboradoresReserva}
            />
          </div>
        )}

        {/* Visualização de Gestão de Colaboradores */}
        {currentTab === 'colaboradores' && (
          <div className="animate-in fade-in duration-200">
            <CollaboratorsManagement
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
            />
          </div>
        )}

        {/* Visualização de Relatórios & Diário Operacional */}
        {currentTab === 'relatorios' && (
          <div className="animate-in fade-in duration-200">
            <ExportReports
              veiculos={veiculos}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              selectedDate={selectedDate}
            />
          </div>
        )}
      </main>

      {/* Modal de Criação de Nova Equipe / Veículo */}
      {isNewTeamModalOpen && (
        <NewTeamModal
          isOpen={isNewTeamModalOpen}
          onClose={() => setIsNewTeamModalOpen(false)}
          onSave={handleSaveNewTeam}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}
    </div>
  );
}

