import React from 'react';
import {
  Car,
  Calendar,
  Layers,
  MapPin,
  Users,
  FileSpreadsheet,
  PlusCircle,
  Sparkles,
} from 'lucide-react';
import { Regional } from '../types';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';

export interface NavbarProps {
  selectedRegional: Regional;
  onRegionalChange: (regional: Regional) => void;
  selectedDate: Date;
  onDateChange: (date: Date) => void;
  activeTab: 'veiculos' | 'colaboradores' | 'relatorios' | 'equipes';
  onTabChange: (tab: 'veiculos' | 'colaboradores' | 'relatorios' | 'equipes') => void;
  onNovaEquipeClick: () => void;
  onNovoColaboradorClick?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({
  selectedRegional,
  onRegionalChange,
  selectedDate,
  onDateChange,
  activeTab,
  onTabChange,
  onNovaEquipeClick,
  onNovoColaboradorClick,
}) => {
  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (value) {
      const [year, month, day] = value.split('-').map(Number);
      const newDate = new Date(year, month - 1, day);
      onDateChange(newDate);
    }
  };

  const formattedDateValue = (() => {
    try {
      const d = selectedDate instanceof Date && !isNaN(selectedDate.getTime()) ? selectedDate : new Date();
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    } catch {
      return new Date().toISOString().split('T')[0];
    }
  })();

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border/60 bg-background/80 backdrop-blur-xl transition-all">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 py-3.5">
          {/* Logo e Título */}
          <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-start">
            <div className="flex items-center gap-2.5">
              <div className="h-10 w-10 rounded-xl bg-gradient-to-tr from-emerald-600 to-teal-500 flex items-center justify-center shadow-md shadow-emerald-600/20 ring-1 ring-white/20">
                <Car className="h-5 w-5 text-white" />
              </div>
              <div>
                <div className="flex items-center gap-1.5">
                  <h1 className="text-base sm:text-lg font-bold tracking-tight text-foreground">
                    Controle de Faltas
                  </h1>
                  <span className="hidden sm:inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-500/15 text-emerald-400 border border-emerald-500/30">
                    <Sparkles className="w-2.5 h-2.5" /> Pro
                  </span>
                </div>
                <p className="text-[11px] text-muted-foreground">
                  Gestão Operacional & Presença de Frotas
                </p>
              </div>
            </div>

            {/* Ação rápida Mobile */}
            <div className="flex md:hidden items-center gap-2">
              <Button
                size="sm"
                onClick={onNovaEquipeClick}
                className="bg-emerald-600 hover:bg-emerald-500 text-white text-xs h-8 px-2.5 gap-1 shadow-sm"
              >
                <PlusCircle className="w-3.5 h-3.5" />
                <span>Equipe</span>
              </Button>
            </div>
          </div>

          {/* Abas de Navegação */}
          <nav className="flex items-center p-1 bg-muted/60 border border-border/60 rounded-xl shadow-inner max-w-full overflow-x-auto">
            <button
              type="button"
              onClick={() => onTabChange('veiculos')}
              className={cn(
                'flex items-center gap-2 px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap cursor-pointer',
                activeTab === 'veiculos'
                  ? 'bg-card text-foreground shadow-sm ring-1 ring-border/50'
                  : 'text-muted-foreground hover:text-foreground hover:bg-card/40'
              )}
            >
              <Car className="w-3.5 h-3.5 text-emerald-500" />
              <span>Veículos</span>
            </button>

            <button
              type="button"
              onClick={() => onTabChange('colaboradores')}
              className={cn(
                'flex items-center gap-2 px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap cursor-pointer',
                activeTab === 'colaboradores'
                  ? 'bg-card text-foreground shadow-sm ring-1 ring-border/50'
                  : 'text-muted-foreground hover:text-foreground hover:bg-card/40'
              )}
            >
              <Users className="w-3.5 h-3.5 text-blue-500" />
              <span>Colaboradores</span>
            </button>

            <button
              type="button"
              onClick={() => onTabChange('equipes')}
              className={cn(
                'flex items-center gap-2 px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap cursor-pointer',
                activeTab === 'equipes'
                  ? 'bg-card text-foreground shadow-sm ring-1 ring-border/50'
                  : 'text-muted-foreground hover:text-foreground hover:bg-card/40'
              )}
            >
              <Layers className="w-3.5 h-3.5 text-purple-500" />
              <span>Equipes</span>
            </button>

            <button
              type="button"
              onClick={() => onTabChange('relatorios')}
              className={cn(
                'flex items-center gap-2 px-3.5 py-1.5 rounded-lg text-xs font-semibold transition-all whitespace-nowrap cursor-pointer',
                activeTab === 'relatorios'
                  ? 'bg-card text-foreground shadow-sm ring-1 ring-border/50'
                  : 'text-muted-foreground hover:text-foreground hover:bg-card/40'
              )}
            >
              <FileSpreadsheet className="w-3.5 h-3.5 text-amber-500" />
              <span>Relatórios</span>
            </button>
          </nav>

          {/* Filtros e Ações */}
          <div className="flex flex-wrap items-center justify-end gap-2 w-full md:w-auto">
            {/* Seletor de Unidade */}
            <div className="flex items-center bg-muted/50 border border-border/60 rounded-xl p-0.5 text-xs font-medium">
              <span className="flex items-center gap-1 pl-2.5 pr-1 text-muted-foreground text-[11px]">
                <MapPin className="w-3.5 h-3.5 text-emerald-400" />
              </span>
              <button
                type="button"
                onClick={() => onRegionalChange('todas')}
                className={cn(
                  'px-2.5 py-1 rounded-lg text-[11px] font-semibold transition-all cursor-pointer',
                  selectedRegional === 'todas'
                    ? 'bg-card text-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground'
                )}
              >
                Todas
              </button>
              <button
                type="button"
                onClick={() => onRegionalChange('ribas')}
                className={cn(
                  'px-2.5 py-1 rounded-lg text-[11px] font-semibold transition-all cursor-pointer',
                  selectedRegional === 'ribas'
                    ? 'bg-card text-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground'
                )}
              >
                Ribas
              </button>
              <button
                type="button"
                onClick={() => onRegionalChange('agua_clara')}
                className={cn(
                  'px-2.5 py-1 rounded-lg text-[11px] font-semibold transition-all cursor-pointer',
                  selectedRegional === 'agua_clara'
                    ? 'bg-card text-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground'
                )}
              >
                Água Clara
              </button>
            </div>

            {/* Input de Data */}
            <div className="relative flex items-center bg-card/60 border border-border/60 rounded-xl px-2.5 py-1 shadow-sm">
