import React from 'react';
import {
  Car,
  Calendar,
  Layers,
  MapPin,
  Users,
  FileSpreadsheet,
  PlusCircle,
  Sparkles,
} from 'lucide-react';
import { Regional } from '../types';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';

export interface NavbarProps {
  activeTab: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios' | 'showcase';
  onTabChange: (tab: 'veiculos' | 'equipes' | 'colaboradores' | 'relatorios' | 'showcase') => void;
  selectedRegional: Regional;
  onRegionalChange: (regional: Regional) => void;
  selectedDate: Date;
  onDateChange: (date: Date) => void;
  onOpenNovaEquipe?: () => void;
  totalVeiculos?: number;
  totalEquipes?: number;
  totalColaboradores?: number;
}

export const Navbar: React.FC<NavbarProps> = ({
  activeTab,
  onTabChange,
  selectedRegional,
  onRegionalChange,
  selectedDate,
  onDateChange,
  onOpenNovaEquipe,
  totalVeiculos = 6,
  totalEquipes = 12,
  totalColaboradores = 28,
}) => {
  const dataFormatadaInput = selectedDate.toISOString().split('T')[0];

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.value) return;
    const [ano, mes, dia] = e.target.value.split('-').map(Number);
    const novaData = new Date(ano, mes - 1, dia, 12, 0, 0);
    onDateChange(novaData);
  };

  const navItems = [
    {
      id: 'veiculos' as const,
      label: 'Veículos & Assentos',
      icon: Car,
      count: totalVeiculos,
    },
    {
      id: 'equipes' as const,
      label: 'Equipes',
      icon: Layers,
      count: totalEquipes,
    },
    {
      id: 'colaboradores' as const,
      label: 'Colaboradores',
      icon: Users,
      count: totalColaboradores,
    },
    {
      id: 'relatorios' as const,
      label: 'Relatórios & Diário',
