      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row items-center justify-between py-3.5 gap-3 sm:gap-4 border-b border-border/40">
          {/* Logotipo e Identificação */}
          <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-start">
            <div className="flex items-center gap-2.5">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-emerald-600 via-teal-500 to-cyan-400 p-0.5 shadow-lg shadow-emerald-500/20 flex items-center justify-center">
                <div className="w-full h-full bg-background rounded-[10px] flex items-center justify-center">
                  <Car className="w-5 h-5 text-emerald-400 animate-pulse" />
                </div>
              </div>
              <div>
                <h1 className="font-bold text-base sm:text-lg tracking-tight text-foreground flex items-center gap-1.5">
                  Controle de Faltas
                  <span className="hidden sm:inline-block px-1.5 py-0.5 text-[10px] font-bold tracking-wide uppercase bg-emerald-500/10 text-emerald-400 border border-emerald-500/30 rounded-md">
                    Operacional
                  </span>
                </h1>
                <p className="text-[11px] text-muted-foreground font-medium">
                  Gestão Diária de Presenças, Assentos e Equipes
                </p>
              </div>
            </div>

            {/* Botão Ação Rápida Mobile */}
            {onOpenNovaEquipe && (
              <Button
                variant="default"
                size="sm"
                onClick={onOpenNovaEquipe}
                className="md:hidden flex items-center gap-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold shadow-md"
              >
                <PlusCircle className="w-3.5 h-3.5" />
                Nova Equipe
              </Button>
            )}
          </div>

          {/* Filtros: Unidade Regional e Data */}
          <div className="flex items-center gap-2.5 w-full md:w-auto justify-between md:justify-end flex-wrap sm:flex-nowrap">
            {/* Seletor de Regional */}
            <div className="flex items-center gap-1 bg-muted/60 p-1 rounded-xl border border-border/60">
              <MapPin className="w-3.5 h-3.5 ml-1.5 text-muted-foreground shrink-0" />
              <button
                type="button"
                onClick={() => onRegionalChange('todas')}
                className={cn(
                  'px-2.5 py-1 text-xs font-semibold rounded-lg transition-all',
                  selectedRegional === 'todas'
                    ? 'bg-primary text-primary-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/80'
                )}
              >
                Todas
              </button>
              <button
                type="button"
                onClick={() => onRegionalChange('ribas')}
                className={cn(
                  'px-2.5 py-1 text-xs font-semibold rounded-lg transition-all',
                  selectedRegional === 'ribas'
                    ? 'bg-primary text-primary-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/80'
                )}
              >
                Ribas
              </button>
              <button
                type="button"
                onClick={() => onRegionalChange('agua_clara')}
                className={cn(
                  'px-2.5 py-1 text-xs font-semibold rounded-lg transition-all',
                  selectedRegional === 'agua_clara'
                    ? 'bg-primary text-primary-foreground shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/80'
                )}
              >
                Água Clara
              </button>
            </div>

            {/* Seletor de Data */}
            <div className="flex items-center gap-1.5 bg-muted/60 px-3 py-1.5 rounded-xl border border-border/60">
              <Calendar className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
