              />
            </div>

            {/* Botão Nova Equipe Desktop */}
            {onOpenNovaEquipe && (
              <Button
                variant="default"
                size="sm"
                onClick={onOpenNovaEquipe}
                className="hidden md:flex items-center gap-1.5 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white text-xs font-semibold shadow-md shadow-emerald-900/20"
              >
                <PlusCircle className="w-4 h-4" />
                Nova Equipe
              </Button>
            )}
          </div>
        </div>

        {/* Abas de Navegação Principal */}
        <nav className="flex items-center gap-2 overflow-x-auto py-2.5 no-scrollbar">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => onTabChange(item.id)}
                className={cn(
                  'flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-semibold transition-all whitespace-nowrap cursor-pointer',
                  isActive
                    ? 'bg-primary text-primary-foreground shadow-md shadow-primary/20 scale-[1.01]'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/60 border border-transparent hover:border-border/40'
                )}
              >
                <Icon className={cn('w-4 h-4 shrink-0', isActive ? 'text-primary-foreground' : 'text-muted-foreground')} />
                <span>{item.label}</span>
                {item.count !== undefined && (
                  <span
                    className={cn(
                      'px-2 py-0.2 rounded-full text-[10px] font-bold',
                      isActive
                        ? 'bg-primary-foreground/20 text-primary-foreground'
                        : 'bg-muted text-muted-foreground'
                    )}
                  >
                    {item.count}
                  </span>
                )}
              </button>
            );
          })}

          <button
            type="button"
            onClick={() => onTabChange('showcase')}
            className={cn(
              'ml-auto flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold transition-all whitespace-nowrap border',
              activeTab === 'showcase'
                ? 'bg-accent text-accent-foreground border-accent'
                : 'text-muted-foreground hover:text-foreground border-border/40 hover:bg-muted/50'
            )}
          >
            <Sparkles className="w-3.5 h-3.5 text-amber-400 shrink-0" />
            <span className="hidden sm:inline">Componentes</span>
          </button>
        </nav>
      </div>
    </header>
  );
};

