import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Regional, Veiculo, Colaborador, StatusPresenca, MotivoFalta } from './types';

export default function App() {
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'relatorios' | 'equipes'>('veiculos');
  const [modalNovaEquipeAberto, setModalNovaEquipeAberto] = useState(false);

  // Atualização de Presença de um Colaborador no Veículo
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentosAtualizados = { ...v.assentos };
        (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
          const colab = assentosAtualizados[pos];
          if (colab && colab.id === colaboradorId) {
            assentosAtualizados[pos] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' && substituto ? substituto.id : undefined,
              substitutoNome: novoStatus === 'substituto' && substituto ? substituto.nome : undefined,
            };
          }
        });

        return {
          ...v,
          assentos: assentosAtualizados,
        };
      })
    );
  };

  // Criação de Nova Equipe
  const handleCriarEquipe = (novaEquipe: {
    prefixo: string;
    placa: string;
    modelo: string;
    regional: 'ribas' | 'agua_clara';
    equipe1Codigo: string;
    equipe2Codigo: string;
    motoristaNome: string;
    frenteDirNome: string;
    trasEsqNome: string;
    trasDirNome: string;
  }) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: novaEquipe.prefixo,
      placa: novaEquipe.placa,
      modelo: novaEquipe.modelo,
      ano: new Date().getFullYear(),
      regional: novaEquipe.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: novaEquipe.equipe1Codigo,
      equipe2Codigo: novaEquipe.equipe2Codigo,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: novaEquipe.motoristaNome,
          cargo: 'Motorista / Operador',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0001',
          status: 'presente',
          equipeId: novaEquipe.equipe1Codigo,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: novaEquipe.frenteDirNome,
          cargo: 'Operador de Campo',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0002',
          status: 'presente',
          equipeId: novaEquipe.equipe1Codigo,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: novaEquipe.trasEsqNome,
          cargo: 'Técnico Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0003',
          status: 'presente',
          equipeId: novaEquipe.equipe2Codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: novaEquipe.trasDirNome,
          cargo: 'Ajudante Geral',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0004',
          status: 'presente',
          equipeId: novaEquipe.equipe2Codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  // Importar novos colaboradores para a reserva
  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const formatados: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80',
      telefone: n.telefone,
      status: n.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...formatados, ...prev]);
  };

  // Adicionar colaborador manual
  const handleAdicionarColaborador = (novo: ColaboradorCompleto) => {
    const colab: Colaborador = {
      id: novo.id,
      nome: novo.nome,
      cargo: novo.cargo,
      matricula: novo.matricula,
      foto: novo.foto || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80',
      telefone: novo.telefone,
      status: novo.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };
    setColaboradoresReserva((prev) => [colab, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col antialiased">
      {/* Barra de Navegação Superior */}
      <Navbar
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas Gerais e Resumo Operacional */}
        {activeTab === 'veiculos' && (
          <MetricsHeader
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
          />
        )}

        {/* Visualização por Abas */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
            onUpdateStatus={handleUpdateStatus}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal de Criação de Nova Equipe */}
      <NewTeamModal
        isOpen={modalNovaEquipeAberto}
        onClose={() => setModalNovaEquipeAberto(false)}
        onSave={handleCriarEquipe}
      />
    </div>
  );
}

