import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { TeamsManagement } from './components/TeamsManagement';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { ExportReports } from './components/ExportReports';
import { ComponentShowcase } from './components/ComponentShowcase';
import { AttendanceModal } from './components/AttendanceModal';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta, MetricasGerais } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'colaboradores' | 'relatorios' | 'showcase'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  // Estados dos Modais
  const [attendanceModalData, setAttendanceModalData] = useState<{
    isOpen: boolean;
    veiculoId: string;
    colaborador: Colaborador | null;
  }>({
    isOpen: false,
    veiculoId: '',
    colaborador: null,
  });

  const [isNovaEquipeModalOpen, setIsNovaEquipeModalOpen] = useState(false);

  // Veículos filtrados por regional
  const veiculosFiltrados = useMemo(() => {
    return (veiculos || []).filter((v) => {
      if (!v) return false;
      return selectedRegional === 'todas' || v.regional === selectedRegional;
    });
  }, [veiculos, selectedRegional]);

  // Lista agregada de todos os colaboradores
  const todosColaboradores = useMemo(() => {
    const list: Colaborador[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      if (v.assentos.motorista) list.push(v.assentos.motorista);
      if (v.assentos.frenteDir) list.push(v.assentos.frenteDir);
      if (v.assentos.trasEsq) list.push(v.assentos.trasEsq);
      if (v.assentos.trasDir) list.push(v.assentos.trasDir);
    });
    return list;
  }, [veiculos]);

  // Métricas gerais calculadas dinamicamente
  const metricas: MetricasGerais = useMemo(() => {
    const totalVeiculos = veiculosFiltrados.length;
    const veiculosAtivos = veiculosFiltrados.filter((v) => v.statusOperacional === 'ativo').length;
    const totalEquipes = totalVeiculos * 2;

    let totalColaboradores = 0;
    let colaboradoresPresentes = 0;
    let colaboradoresFaltas = 0;
    let colaboradoresSubstitutos = 0;
    let equipesCompletas = 0;
    let equipesIncompletas = 0;

    veiculosFiltrados.forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos1 = [v.assentos.motorista, v.assentos.frenteDir];
      const assentos2 = [v.assentos.trasEsq, v.assentos.trasDir];

      const eq1Completa = assentos1.every((c) => c && c.status !== 'falta');
      const eq2Completa = assentos2.every((c) => c && c.status !== 'falta');

      if (eq1Completa) equipesCompletas += 1;
      else equipesIncompletas += 1;

      if (eq2Completa) equipesCompletas += 1;
      else equipesIncompletas += 1;

      const todosAssentos = [...assentos1, ...assentos2];
      todosAssentos.forEach((c) => {
        if (!c) return;
        totalColaboradores += 1;
        if (c.status === 'presente') colaboradoresPresentes += 1;
        else if (c.status === 'falta') colaboradoresFaltas += 1;
        else if (c.status === 'substituto') colaboradoresSubstitutos += 1;
      });
    });

    const taxaPresenca =
      totalColaboradores > 0
        ? Math.round(((colaboradoresPresentes + colaboradoresSubstitutos) / totalColaboradores) * 100)
        : 100;

    return {
      totalVeiculos,
      veiculosAtivos,
      totalEquipes,
      equipesCompletas,
      equipesIncompletas,
      totalColaboradores,
      colaboradoresPresentes,
      colaboradoresFaltas,
      colaboradoresSubstitutos,
      taxaPresenca,
    };
  }, [veiculosFiltrados]);

  // Handler de abertura do modal de presença
  const handleOpenAttendance = (veiculoId: string, colaborador: Colaborador) => {
    setAttendanceModalData({
      isOpen: true,
      veiculoId,
      colaborador,
    });
  };

  // Handler de salvamento de presença
  const handleSaveAttendance = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const updateAssento = (c: Colaborador): Colaborador => {
          if (c.id !== colaboradorId) return c;
          return {
            ...c,
            status: novoStatus,
            motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
            substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
            substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
          };
        };

        return {
          ...v,
          assentos: {
            motorista: updateAssento(v.assentos.motorista),
            frenteDir: updateAssento(v.assentos.frenteDir),
            trasEsq: updateAssento(v.assentos.trasEsq),
            trasDir: updateAssento(v.assentos.trasDir),
          },
        };
      })
    );

    setAttendanceModalData({ isOpen: false, veiculoId: '', colaborador: null });
  };

  // Handler para criação de nova equipe
  const handleCreateNovaEquipe = (novoVeiculo: Veiculo) => {
    setVeiculos((prev) => [novoVeiculo, ...prev]);
    setIsNovaEquipeModalOpen(false);
  };

  // Handler de importação de colaboradores
  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const novosReserva: Colaborador[] = novos.map((n) => ({
      id: n.id,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto || '',
      telefone: n.telefone,
      status: n.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...novosReserva, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col antialiased">
      {/* Top Navbar */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onOpenNovaEquipe={() => setIsNovaEquipeModalOpen(true)}
        totalVeiculos={veiculosFiltrados.length}
        totalEquipes={veiculosFiltrados.length * 2}
        totalColaboradores={todosColaboradores.length}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Métricas Globais do Topo */}
        <MetricsHeader
          metricas={metricas}
          selectedRegional={selectedRegional}
          onOpenNovaEquipe={() => setIsNovaEquipeModalOpen(true)}
        />

        {/* Visualizações por Aba */}
        {activeTab === 'veiculos' && (
          <div className="space-y-6 animate-in fade-in duration-200">
            <VehicleCardGrid
              veiculos={veiculosFiltrados}
              onAssentoClick={handleOpenAttendance}
              colaboradoresReserva={colaboradoresReserva}
            />
          </div>
        )}

        {activeTab === 'equipes' && (
          <div className="animate-in fade-in duration-200">
            <TeamsManagement
              veiculos={veiculosFiltrados}
              selectedRegional={selectedRegional}
              onOpenNovaEquipe={() => setIsNovaEquipeModalOpen(true)}
            />
          </div>
        )}

        {activeTab === 'colaboradores' && (
          <div className="animate-in fade-in duration-200">
            <CollaboratorsManagement
              veiculos={veiculosFiltrados}
              colaboradoresReserva={colaboradoresReserva}
              onImportarColaboradores={handleImportarColaboradores}
            />
          </div>
        )}

        {activeTab === 'relatorios' && (
          <div className="animate-in fade-in duration-200">
            <ExportReports
              veiculos={veiculosFiltrados}
              colaboradoresReserva={colaboradoresReserva}
              selectedRegional={selectedRegional}
              selectedDate={selectedDate}
            />
          </div>
        )}

        {activeTab === 'showcase' && (
          <div className="animate-in fade-in duration-200">
            <ComponentShowcase />
          </div>
        )}
      </main>

      {/* Modal de Presença / Falta / Substituto */}
      {attendanceModalData.isOpen && attendanceModalData.colaborador && (
        <AttendanceModal
          colaborador={attendanceModalData.colaborador}
          veiculoId={attendanceModalData.veiculoId}
          onClose={() => setAttendanceModalData({ isOpen: false, veiculoId: '', colaborador: null })}
          onSave={handleSaveAttendance}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}

      {/* Modal de Cadastro de Nova Equipe */}
      {isNovaEquipeModalOpen && (
        <NewTeamModal
          isOpen={isNovaEquipeModalOpen}
          onClose={() => setIsNovaEquipeModalOpen(false)}
          onSave={handleCreateNovaEquipe}
          colaboradoresDisponiveis={colaboradoresReserva}
        />
      )}
    </div>
  );
}

