import React, { useState, useMemo } from 'react';
import { Search, Filter, AlertCircle, CheckCircle2, RefreshCw, MapPin, Users } from 'lucide-react';
import { VehicleTopView, VehicleZone } from './VehicleTopView';
import { AttendanceModal } from './AttendanceModal';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from '../types';
import { cn } from '@/lib/utils';

export interface VehicleCardGridProps {
  veiculos: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  onUpdateStatus?: (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => void;
  filtroRegional?: Regional;
  selectedRegional?: Regional;
}

export const VehicleCardGrid: React.FC<VehicleCardGridProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onUpdateStatus,
  filtroRegional = 'todas',
  selectedRegional,
}) => {
  const [selectedColaborador, setSelectedColaborador] = useState<{
    colaborador: Colaborador;
    veiculoId: string;
    posicao: VehicleZone;
  } | null>(null);

  const [busca, setBusca] = useState('');
  const regionalEfetiva = selectedRegional || filtroRegional || 'todas';

  const veiculosFiltrados = useMemo(() => {
    const lista = veiculos || [];
    return lista.filter((v) => {
      if (!v) return false;
      const matchRegional = regionalEfetiva === 'todas' || v.regional === regionalEfetiva;
      const termo = busca.trim().toLowerCase();
      if (!termo) return matchRegional;

      const matchPlaca = (v.placa || '').toLowerCase().includes(termo);
      const matchPrefixo = (v.prefixo || '').toLowerCase().includes(termo);
      const matchModelo = (v.modelo || '').toLowerCase().includes(termo);

      const assentos = [
        v.assentos?.motorista,
        v.assentos?.frenteDir,
        v.assentos?.trasEsq,
        v.assentos?.trasDir,
      ];
      const matchColaborador = assentos.some(
        (c) =>
          c &&
          ((c.nome || '').toLowerCase().includes(termo) ||
            (c.substitutoNome || '').toLowerCase().includes(termo) ||
            (c.cargo || '').toLowerCase().includes(termo))
      );

      return matchRegional && (matchPlaca || matchPrefixo || matchModelo || matchColaborador);
    });
  }, [veiculos, regionalEfetiva, busca]);

  const handleSalvarPresenca = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    onUpdateStatus?.(veiculoId, colaboradorId, novoStatus, motivoFalta, substituto);
    setSelectedColaborador(null);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Busca e Filtros Rápidos */}
      <div className="flex flex-col sm:flex-row gap-3 items-center justify-between">
        <div className="relative w-full sm:max-w-md">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
          <input
            type="text"
            placeholder="Buscar por placa, prefixo ou colaborador..."
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            className="w-full h-10 pl-10 pr-4 text-xs sm:text-sm bg-card/60 backdrop-blur-md border border-border rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-foreground placeholder:text-muted-foreground shadow-sm"
          />
        </div>

        <div className="flex items-center gap-2 text-xs text-muted-foreground self-end sm:self-center">
          <span className="font-semibold text-foreground">{veiculosFiltrados.length}</span>{' '}
          {veiculosFiltrados.length === 1 ? 'veículo listado' : 'veículos listados'}
        </div>
      </div>

      {/* Grid de Veículos */}
      {veiculosFiltrados.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 bg-card/40 border border-border/60 rounded-2xl text-center">
          <AlertCircle className="w-10 h-10 text-muted-foreground/50 mb-3" />
          <p className="text-base font-bold text-foreground">Nenhum veículo encontrado</p>
          <p className="text-xs text-muted-foreground mt-1 max-w-sm">
            Tente mudar o filtro regional ou o termo pesquisado na barra de busca.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
          {veiculosFiltrados.map((v) => {
            if (!v) return null;
            const regLabel = v.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
            const regBadgeColor =
              v.regional === 'ribas'
                ? 'bg-sky-500/15 text-sky-400 border-sky-500/30'
                : 'bg-emerald-500/15 text-emerald-400 border-emerald-500/30';

            return (
              <div
                key={v.id}
                className="bg-card/70 backdrop-blur-md border border-border/80 rounded-2xl p-5 shadow-lg flex flex-col justify-between hover:border-border transition-all"
              >
                {/* Header do Card */}
                <div>
                  <div className="flex items-center justify-between gap-2 mb-3 pb-3 border-b border-border/50">
                    <div>
                      <h3 className="text-base font-extrabold text-foreground tracking-tight">
                        {v.prefixo || 'Sem Prefixo'}
                      </h3>
                      <p className="text-xs text-muted-foreground font-medium">
                        {v.modelo} • <span className="font-semibold text-foreground/80">{v.placa}</span>
                      </p>
                    </div>

                    <div className={cn('px-2.5 py-1 rounded-lg border text-[11px] font-bold flex items-center gap-1.5', regBadgeColor)}>
                      <MapPin className="w-3 h-3" />
                      <span>{regLabel}</span>
                    </div>
                  </div>

                  {/* Assentos e Colaboradores */}
                  <VehicleTopView
                    veiculo={v}
                    onAssentoClick={(posicao, colab) => {
                      setSelectedColaborador({
                        colaborador: colab,
                        veiculoId: v.id,
                        posicao,
                      });
                    }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modal de Presença */}
      {selectedColaborador && (
        <AttendanceModal
          colaborador={selectedColaborador.colaborador}
          veiculoId={selectedColaborador.veiculoId}
          onClose={() => setSelectedColaborador(null)}
          onSave={handleSalvarPresenca}
          colaboradoresReserva={colaboradoresReserva}
        />
      )}
    </div>
  );
};

