import React, { useState, useMemo } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, StatusPresenca, MotivoFalta, Regional } from './types';

export default function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'equipes' | 'colaboradores' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);

  // Atualização de Status de Colaborador (Presença, Falta ou Substituto)
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prevVeiculos) =>
      prevVeiculos.map((veiculo) => {
        if (veiculo.id !== veiculoId) return veiculo;

        const assentos = { ...veiculo.assentos };
        const keys: Array<keyof typeof assentos> = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'];

        keys.forEach((k) => {
          const colab = assentos[k];
          if (colab && colab.id === colaboradorId) {
            assentos[k] = {
              ...colab,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...veiculo, assentos };
      })
    );
  };

  // Importar novos colaboradores em lote
  const handleImportarColaboradores = (novos: ColaboradorCompleto[]) => {
    const novosConvertidos: Colaborador[] = novos.map((n, idx) => ({
      id: n.id || `imp-${Date.now()}-${idx}`,
      nome: n.nome,
      cargo: n.cargo,
      matricula: n.matricula,
      foto: n.foto || '',
      telefone: n.telefone || '',
      status: n.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...prev, ...novosConvertidos]);
  };

  // Adicionar colaborador individual
  const handleAdicionarColaborador = (novo: ColaboradorCompleto) => {
    const novoConvertido: Colaborador = {
      id: novo.id || `col-${Date.now()}`,
      nome: novo.nome,
      cargo: novo.cargo,
      matricula: novo.matricula,
      foto: novo.foto || '',
      telefone: novo.telefone || '',
      status: novo.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };

    setColaboradoresReserva((prev) => [novoConvertido, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col selection:bg-primary/20 selection:text-primary">
      {/* Barra de Navegação Superior */}
      <Navbar
        activeTab={activeTab}
        onSelectTab={setActiveTab}
        selectedRegional={selectedRegional}
        onSelectRegional={setSelectedRegional}
        selectedDate={selectedDate}
        onSelectDate={setSelectedDate}
      />

      {/* Conteúdo Principal com enquadramento harmônico em container responsivo */}
      <main className="flex-1 w-full max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Painel de Métricas e Indicadores Globais */}
        <MetricsHeader
          veiculos={veiculos}
          colaboradoresReserva={colaboradoresReserva}
          selectedRegional={selectedRegional}
        />

        {/* Telas Dinâmicas por Aba */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onUpdateStatus={handleUpdateStatus}
            selectedRegional={selectedRegional}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
          />
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Rodapé Simples e Discreto */}
      <footer className="border-t border-border/50 py-4 mt-auto bg-card/30">
        <div className="max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row items-center justify-between gap-2 text-xs text-muted-foreground">
          <span>© {new Date().getFullYear()} Controle de Faltas — Gestão Operacional de Equipes</span>
          <span className="font-medium">Ribas do Rio Pardo & Água Clara • MS</span>
        </div>
      </footer>
    </div>
  );
}

