                  className="text-xs font-semibold text-primary hover:text-primary/80 gap-1.5 h-8"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo CSV
                </Button>
              </div>

              {/* Erro */}
              {erroImportacao && (
                <div className="p-3.5 rounded-xl bg-rose-500/15 border border-rose-500/30 text-rose-300 text-xs flex items-center gap-2.5">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <p>{erroImportacao}</p>
                </div>
              )}

              {/* Prévia dos Dados */}
              {registrosPrevia.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <p className="text-xs font-bold text-foreground uppercase tracking-wider">
                      Prévia dos Registros ({registrosPrevia.length} encontrados)
                    </p>
                    <Badge variant="outline" className="border-emerald-500/30 text-emerald-400 bg-emerald-500/10 text-[11px]">
                      Pronto para importação
                    </Badge>
                  </div>

                  <div className="border border-border rounded-xl overflow-hidden max-h-48 overflow-y-auto">
                    <table className="w-full text-left text-xs border-collapse">
                      <thead className="bg-muted/60 text-muted-foreground font-semibold sticky top-0">
                        <tr>
                          <th className="p-2.5">Nome</th>
                          <th className="p-2.5">Função</th>
                          <th className="p-2.5">Unidade</th>
                          <th className="p-2.5">Matrícula</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/40">
                        {registrosPrevia.map((reg, idx) => (
                          <tr key={idx} className="hover:bg-muted/20">
                            <td className="p-2.5 font-medium text-foreground">{reg.nome}</td>
                            <td className="p-2.5 text-muted-foreground">{reg.cargo}</td>
                            <td className="p-2.5">
                              <span className="capitalize">{reg.unidade === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara'}</span>
                            </td>
                            <td className="p-2.5 text-muted-foreground">{reg.matricula || '-'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>

            {/* Modal Footer */}
            <div className="px-6 py-4 border-t border-border bg-muted/10 flex items-center justify-end gap-2.5">
              <Button
                type="button"
                variant="outline"
                onClick={() => setModalImportAberto(false)}
              >
                Cancelar
              </Button>
              <Button
                type="button"
                disabled={registrosPrevia.length === 0}
                onClick={handleConfirmarImportacao}
                className="gap-2 bg-emerald-600 hover:bg-emerald-500 text-white font-semibold disabled:opacity-50"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar e Importar {registrosPrevia.length > 0 ? `(${registrosPrevia.length})` : ''}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

