import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  RefreshCw,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  FileCheck,
  UserPlus,
  Plus,
  Camera,
  Image as ImageIcon,
  Trash2
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const posicaoLabel: Record<string, string> = {
  motorista: 'Motorista / Líder',
  frente_dir: 'Dianteiro Direito',
  tras_esq: 'Traseiro Esquerdo',
  tras_dir: 'Traseiro Direito',
};

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>('todas');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Estados do Modal de Cadastro Manual de Colaborador
  const [modalNovoColaboradorAberto, setModalNovoColaboradorAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novoStatus, setNovoStatus] = useState<StatusPresenca>('presente');
  const [formErro, setFormErro] = useState<string | null>(null);
  const fotoInputRef = useRef<HTMLInputElement>(null);

  // Estados do Modal de Importação Excel / CSV
  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lista de colaboradores extraídos dos veículos e lista reserva
  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    // Adiciona colaboradores reserva se houver
    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  // Handler para Upload de Foto de Colaborador
  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Verificar formato
    if (!file.type.startsWith('image/')) {
      setFormErro('Por favor, selecione um arquivo de imagem válido (PNG, JPG, JPEG, WEBP).');
      return;
    }

    // Verificar tamanho (máximo 5MB)
    if (file.size > 5 * 1024 * 1024) {
      setFormErro('A imagem selecionada deve ter no máximo 5MB.');
      return;
    }

    setFormErro(null);
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === 'string') {
        setNovaFoto(reader.result);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleRemoverFoto = () => {
    setNovaFoto('');
    if (fotoInputRef.current) {
      fotoInputRef.current.value = '';
    }
  };

  // Handler para Adicionar Colaborador Manualmente
  const handleCadastrarNovoColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) {
      setFormErro('Por favor, informe o nome do colaborador.');
      return;
    }
    if (!novoCargo.trim()) {
      setFormErro('Por favor, informe a função/cargo do colaborador.');
      return;
    }

    const novoColab: ColaboradorCompleto = {
      id: `col-novo-${Date.now()}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim(),
      matricula: novaMatricula.trim() || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      foto: novaFoto.trim() || `https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80`,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      status: novoStatus,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: novaUnidade,
    };

    setColaboradoresAdicionados((prev) => [novoColab, ...prev]);
    onAdicionarColaborador?.(novoColab);

    // Limpar formulário e fechar modal
    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaFoto('');
    setNovaUnidade('ribas');
    setNovoStatus('presente');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
    setSucessoMsg(`Colaborador "${novoColab.nome}" cadastrado com sucesso!`);
    setTimeout(() => setSucessoMsg(null), 4000);
  };

  // Processamento do arquivo Excel/CSV
  const processarArquivo = (file: File) => {
    setErroImportacao(null);
    setArquivoNome(file.name);

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const conteudo = e.target?.result as string;
        if (!conteudo) {
          setErroImportacao('O arquivo selecionado está vazio.');
          return;
        }

        const linhas = conteudo.split(/\r\n|\n/).filter((l) => l.trim().length > 0);
        if (linhas.length < 2) {
          setErroImportacao('O arquivo precisa conter cabeçalho e ao menos uma linha de dados.');
          return;
        }

        const delimitador = linhas[0].includes(';') ? ';' : linhas[0].includes('\t') ? '\t' : ',';
        const cabecalho = linhas[0].toLowerCase().split(delimitador).map((c) => c.trim().replace(/"/g, ''));

        const idxNome = cabecalho.findIndex((c) => c.includes('nome') || c.includes('colaborador') || c.includes('funcionario'));
        const idxCargo = cabecalho.findIndex((c) => c.includes('função') || c.includes('funcao') || c.includes('cargo') || c.includes('posto'));
        const idxUnidade = cabecalho.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('base') || c.includes('filial'));
        const idxMatricula = cabecalho.findIndex((c) => c.includes('matr') || c.includes('codigo') || c.includes('id'));
        const idxTel = cabecalho.findIndex((c) => c.includes('tel') || c.includes('fone') || c.includes('cel'));

        if (idxNome === -1) {
          setErroImportacao('Não foi encontrada a coluna "Nome" ou "Colaborador" no cabeçalho.');
          return;
        }

        const registros: RegistroImportado[] = [];

        for (let i = 1; i < linhas.length; i++) {
          const colunas = linhas[i].split(delimitador).map((col) => col.trim().replace(/^"|"$/g, ''));
          if (colunas.length <= idxNome) continue;

          const nome = colunas[idxNome];
          if (!nome) continue;

          const cargo = (idxCargo !== -1 && colunas[idxCargo]) ? colunas[idxCargo] : 'Operador Florestal';
          const unidadeRaw = (idxUnidade !== -1 && colunas[idxUnidade]) ? colunas[idxUnidade].toLowerCase() : '';

          let unidade: 'ribas' | 'agua_clara' = 'ribas';
          if (unidadeRaw.includes('agua') || unidadeRaw.includes('água') || unidadeRaw.includes('clara')) {
            unidade = 'agua_clara';
          }

          const matricula = idxMatricula !== -1 && colunas[idxMatricula] ? colunas[idxMatricula] : undefined;
          const telefone = idxTel !== -1 && colunas[idxTel] ? colunas[idxTel] : undefined;

          registros.push({
            nome,
            cargo,
            unidade,
            matricula,
            telefone,
          });
        }

        if (registros.length === 0) {
          setErroImportacao('Nenhum registro válido foi encontrado no arquivo.');
          return;
        }

        setRegistrosPrevia(registros);
      } catch (err) {
        setErroImportacao('Erro ao ler e processar o arquivo. Verifique se o formato é CSV/Excel válido.');
      }
    };

    reader.onerror = () => {
      setErroImportacao('Falha na leitura do arquivo local.');
    };

    reader.readAsText(file, 'UTF-8');
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processarArquivo(file);
    }
  };

  const handleConfirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novosColabs: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => ({
      id: `imp-${Date.now()}-${idx}`,
      nome: reg.nome,
      cargo: reg.cargo || 'Operador Florestal',
      matricula: reg.matricula || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      foto: `https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80`,
      telefone: reg.telefone || '(67) 99999-0000',
      status: 'presente',
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco de Reserva',
      veiculoPlaca: '-',
      regional: reg.unidade,
    }));

    setColaboradoresAdicionados((prev) => [...novosColabs, ...prev]);
    onImportarColaboradores?.(novosColabs);

    setSucessoMsg(`Sucesso! ${novosColabs.length} colaboradores importados para o banco do sistema.`);
    setRegistrosPrevia([]);
    setArquivoNome('');
    setModalImportAberto(false);

    setTimeout(() => {
      setSucessoMsg(null);
    }, 5000);
  };

  const downloadModeloCSV = () => {
    const csvContent = 'data:text/csv;charset=utf-8,' + encodeURIComponent(
      'Nome;Funcao;Unidade;Matricula;Telefone\n' +
      'Carlos Eduardo Silva;Operador de Máquinas;Ribas do Rio Pardo;MAT-4011;(67) 99812-4455\n' +
      'Mariana Alves Costa;Técnica de Segurança;Água Clara;MAT-4012;(67) 99876-1234\n' +
      'Lucas Santos Ramos;Motorista Especializado;Ribas do Rio Pardo;MAT-4013;(67) 99123-8899\n' +
      'Juliana Ferreira;Ajudante Geral;Água Clara;MAT-4014;(67) 99765-4321'
    );
    const link = document.createElement('a');
    link.setAttribute('href', csvContent);
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Alerta de Sucesso */}
      {sucessoMsg && (
        <div className="flex items-center gap-3 p-4 rounded-2xl bg-emerald-500/15 border border-emerald-500/40 text-emerald-300 shadow-lg animate-in slide-in-from-top-2 duration-200">
          <CheckCircle2 className="w-5 h-5 shrink-0 text-emerald-400" />
          <p className="text-sm font-semibold">{sucessoMsg}</p>
        </div>
      )}

      {/* Cards de Métricas Rápidas */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <Card className="border-border/60 bg-card/70 hover:border-border transition-all">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Total Geral</p>
              <p className="text-2xl sm:text-3xl font-black text-foreground mt-0.5">{stats.total}</p>
              <p className="text-[11px] text-muted-foreground mt-0.5">Colaboradores no sistema</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
              <Users className="w-6 h-6" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-emerald-500/30 bg-emerald-500/5 hover:border-emerald-500/50 transition-all">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-emerald-400 uppercase tracking-wider">Presentes</p>
              <p className="text-2xl sm:text-3xl font-black text-emerald-300 mt-0.5">{stats.presentes}</p>
              <p className="text-[11px] text-emerald-400/70 mt-0.5">Em operação regular</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
              <UserCheck className="w-6 h-6" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-rose-500/30 bg-rose-500/5 hover:border-rose-500/50 transition-all">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-rose-400 uppercase tracking-wider">Faltas</p>
              <p className="text-2xl sm:text-3xl font-black text-rose-300 mt-0.5">{stats.faltas}</p>
              <p className="text-[11px] text-rose-400/70 mt-0.5">Ausências registradas</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-rose-500/15 border border-rose-500/30 flex items-center justify-center text-rose-400">
              <UserX className="w-6 h-6" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-amber-500/30 bg-amber-500/5 hover:border-amber-500/50 transition-all">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-amber-400 uppercase tracking-wider">Substitutos</p>
              <p className="text-2xl sm:text-3xl font-black text-amber-300 mt-0.5">{stats.substitutos}</p>
              <p className="text-[11px] text-amber-400/70 mt-0.5">Coberturas em andamento</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-amber-500/15 border border-amber-500/30 flex items-center justify-center text-amber-400">
              <RefreshCw className="w-6 h-6" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Barra de Ações: Busca, Filtros, Botão Adicionar e Importar Excel */}
      <Card className="border-border/60 bg-card/60">
        <CardContent className="p-4 sm:p-5">
          <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between">
            {/* Input de Busca */}
            <div className="relative flex-1 min-w-[240px]">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                type="text"
                placeholder="Buscar por nome, função, matrícula, placa ou prefixo..."
