                  <p className="text-xs text-muted-foreground mt-1">
                    Formato aceito: .csv ou exportação de Excel com as colunas <b>Nome</b>, <b>Função</b> e <b>Unidade</b>
                  </p>
                </div>
              </div>

              {/* Botão Baixar Modelo */}
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-background/60 border border-border">
                <div className="flex items-center gap-2.5">
                  <FileCheck className="w-4 h-4 text-primary shrink-0" />
                  <span className="text-xs text-muted-foreground">
                    Precisa de uma referência? Baixe nossa planilha modelo pré-formatada.
                  </span>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={downloadModeloCSV}
                  className="rounded-xl text-xs gap-1.5 border-border hover:bg-muted shrink-0"
                >
                  <Download className="w-3.5 h-3.5" />
                  Baixar Modelo CSV
                </Button>
              </div>

              {/* Erro de importação se houver */}
              {erroImportacao && (
                <div className="flex items-center gap-2 p-3 rounded-xl bg-rose-500/15 border border-rose-500/40 text-rose-300 text-xs">
                  <AlertCircle className="w-4 h-4 shrink-0 text-rose-400" />
                  <span>{erroImportacao}</span>
                </div>
              )}

              {/* Prévia dos Dados Identificados */}
              {registrosPrevia.length > 0 && (
                <div className="space-y-2.5">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-bold text-foreground uppercase tracking-wider">
                      Prévia dos Colaboradores Identificados ({registrosPrevia.length})
                    </span>
                    <Badge variant="success" className="text-[11px]">
                      {registrosPrevia.length} prontos para importar
                    </Badge>
                  </div>

                  <div className="max-h-52 overflow-y-auto rounded-xl border border-border/70 bg-card divide-y divide-border/40 text-xs">
                    {registrosPrevia.map((reg, idx) => (
                      <div key={idx} className="p-2.5 flex items-center justify-between gap-3">
                        <div className="min-w-0">
                          <p className="font-bold text-foreground truncate">{reg.nome}</p>
                          <p className="text-[11px] text-muted-foreground truncate">{reg.cargo}</p>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                          <span className="text-[11px] px-2 py-0.5 rounded-md bg-muted text-muted-foreground border border-border/50">
                            {regionalLabel[reg.unidade]}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Footer do Modal */}
            <div className="px-6 py-4 border-t border-border bg-muted/20 flex items-center justify-end gap-2 shrink-0">
              <Button
                type="button"
                variant="outline"
                onClick={() => setModalImportAberto(false)}
                className="h-10 px-4 rounded-xl"
              >
                Cancelar
              </Button>
              <Button
                type="button"
                disabled={registrosPrevia.length === 0}
                onClick={handleConfirmarImportacao}
                className="h-10 px-5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-semibold gap-2 disabled:opacity-50"
              >
                <CheckCircle2 className="w-4 h-4" />
                Confirmar Importação ({registrosPrevia.length})
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

