              <p className="text-[11px] text-rose-400/70 mt-0.5">Ausências registradas</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-rose-500/15 border border-rose-500/30 flex items-center justify-center text-rose-400">
              <UserX className="w-6 h-6" />
            </div>
          </CardContent>
        </Card>

        <Card className="border-amber-500/30 bg-amber-500/5 hover:border-amber-500/50 transition-all">
          <CardContent className="p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-amber-400 uppercase tracking-wider">Substitutos</p>
              <p className="text-2xl sm:text-3xl font-black text-amber-300 mt-0.5">{stats.substitutos}</p>
              <p className="text-[11px] text-amber-400/70 mt-0.5">Coberturas em andamento</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-amber-500/15 border border-amber-500/30 flex items-center justify-center text-amber-400">
              <RefreshCw className="w-6 h-6" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Barra de Ações: Busca, Filtros, Botão Adicionar e Importar Excel */}
      <Card className="border-border/60 bg-card/60">
        <CardContent className="p-4 sm:p-5">
          <div className="flex flex-col md:flex-row gap-3 items-stretch md:items-center justify-between">
            {/* Input de Busca */}
            <div className="relative flex-1 min-w-[240px]">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                type="text"
                placeholder="Buscar por nome, função, matrícula, placa ou prefixo..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-10 h-11 bg-background/60 border-border/80 rounded-xl"
              />
            </div>

            {/* Filtros e Botões */}
            <div className="flex flex-wrap items-center gap-2">
              {/* Filtro Unidade */}
              <select
                aria-label="Filtrar por Unidade"
                value={filterRegional}
                onChange={(e) => setFilterRegional(e.target.value as Regional | 'todas')}
                className="h-11 px-3 text-xs sm:text-sm rounded-xl bg-background/80 border border-border text-foreground focus:outline-none focus:ring-2 focus:ring-primary cursor-pointer"
              >
                <option value="todas">Todas as Unidades</option>
                <option value="ribas">Ribas do Rio Pardo</option>
                <option value="agua_clara">Água Clara</option>
              </select>

              {/* Filtro Status */}
              <select
                aria-label="Filtrar por Status"
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as StatusPresenca | 'todos')}
                className="h-11 px-3 text-xs sm:text-sm rounded-xl bg-background/80 border border-border text-foreground focus:outline-none focus:ring-2 focus:ring-primary cursor-pointer"
              >
                <option value="todos">Todos os Status</option>
                <option value="presente">Presentes</option>
                <option value="falta">Faltas</option>
                <option value="substituto">Substitutos</option>
              </select>

              {/* Botão Adicionar Colaborador */}
              <Button
                type="button"
                onClick={() => {
                  setFormErro(null);
                  setNovaFoto('');
                  setModalNovoColaboradorAberto(true);
                }}
                className="h-11 px-4 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground font-semibold shadow-md gap-2"
              >
                <UserPlus className="w-4 h-4 shrink-0" />
                <span>Adicionar Colaborador</span>
              </Button>

              {/* Botão Importar Excel */}
              <Button
                type="button"
                onClick={() => {
                  setErroImportacao(null);
                  setRegistrosPrevia([]);
                  setArquivoNome('');
                  setModalImportAberto(true);
                }}
                variant="outline"
                className="h-11 px-4 rounded-xl border-emerald-500/40 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 font-semibold gap-2 transition-all shadow-sm"
              >
                <FileSpreadsheet className="w-4 h-4 text-emerald-400" />
                <span>Importar Excel</span>
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Lista / Tabela de Colaboradores */}
      <Card className="border-border/60 bg-card/60 overflow-hidden shadow-xl">
        <CardHeader className="p-4 sm:p-5 border-b border-border/60 flex flex-row items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
              <Users className="w-5 h-5" />
            </div>
            <div>
              <CardTitle className="text-base sm:text-lg font-bold">Quadro Geral de Colaboradores</CardTitle>
              <p className="text-xs text-muted-foreground">
                Exibindo {colaboradoresFiltrados.length} de {todosColaboradores.length} colaboradores
              </p>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-0">
          {colaboradoresFiltrados.length === 0 ? (
            <div className="p-12 text-center flex flex-col items-center justify-center">
              <div className="w-16 h-16 rounded-full bg-muted/30 border border-border flex items-center justify-center mb-3">
                <Users className="w-8 h-8 text-muted-foreground/60" />
              </div>
              <p className="text-base font-semibold text-foreground">Nenhum colaborador encontrado</p>
              <p className="text-xs text-muted-foreground mt-1 max-w-sm">
                Tente ajustar os termos de busca ou remover os filtros de status e unidade regional.
              </p>
              <div className="mt-4 flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setSearch('');
