                    setFilterRegional('todas');
                  }}
                  className="rounded-xl text-xs"
                >
                  Limpar Filtros
                </Button>
                <Button
                  size="sm"
                  onClick={() => {
                    setFormErro(null);
                    setNovaFoto('');
                    setModalNovoColaboradorAberto(true);
                  }}
                  className="rounded-xl text-xs bg-primary gap-1.5"
                >
                  <Plus className="w-3.5 h-3.5" />
                  Cadastrar Colaborador
                </Button>
              </div>
