        const idxCargo = cabecalhos.findIndex((c) => c.includes('cargo') || c.includes('função') || c.includes('funcao') || c.includes('posto'));
        const idxUnidade = cabecalhos.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo') || c.includes('base') || c.includes('cidade'));
        const idxMatricula = cabecalhos.findIndex((c) => c.includes('matricula') || c.includes('matrícula') || c.includes('registro') || c.includes('id') || c.includes('re'));
        const idxTelefone = cabecalhos.findIndex((c) => c.includes('telefone') || c.includes('celular') || c.includes('contato') || c.includes('fone'));

        const parsed: RegistroImportado[] = [];

        for (let i = 1; i < linhas.length; i++) {
          const colunas = linhas[i].split(separador).map((val) => val.trim().replace(/^["']|["']$/g, ''));
          if (colunas.length === 0 || !colunas[0]) continue;

          const nomeVal = idxNome !== -1 ? colunas[idxNome] : colunas[0];
          const cargoVal = idxCargo !== -1 ? colunas[idxCargo] : (colunas[1] || 'Operador Florestal');
          const unidadeStr = (idxUnidade !== -1 ? colunas[idxUnidade] : (colunas[2] || 'ribas')).toLowerCase();

          let unidadeFinal: 'ribas' | 'agua_clara' = 'ribas';
          if (unidadeStr.includes('agua') || unidadeStr.includes('água') || unidadeStr.includes('clara') || unidadeStr.includes('agc')) {
