  const unidadeAtual = REGIONAIS.find((r) => r.id === selectedRegional) || REGIONAIS[0];

  // Fechar dropdowns ao clicar fora
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownUnidadeRef.current &&
        !dropdownUnidadeRef.current.contains(event.target as Node)
      ) {
        setDropdownUnidadeAberto(false);
      }
      if (
        dropdownDataRef.current &&
        !dropdownDataRef.current.contains(event.target as Node)
      ) {
        setDropdownDataAberto(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleTabSelect = (tab: 'veiculos' | 'colaboradores' | 'equipes' | 'relatorios') => {
    if (typeof onTabChange === 'function') {
      onTabChange(tab);
    }
  };

  const navItems = [
    { id: 'veiculos' as const, label: 'Veículos & Escala', icon: Car },
    { id: 'colaboradores' as const, label: 'Colaboradores', icon: Users },
    { id: 'equipes' as const, label: 'Equipes', icon: Layers },
    { id: 'relatorios' as const, label: 'Relatórios & Histórico', icon: FileSpreadsheet },
  ];

  const formatarDataExibicao = (date: Date) => {
    if (!date || isNaN(date.getTime())) return 'Hoje';
    return date.toLocaleDateString('pt-BR', {
      weekday: 'short',
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  };

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border/80 bg-background/95 backdrop-blur-xl supports-[backdrop-filter]:bg-background/80 shadow-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Linha Superior: Logo + Seletor de Unidades + Seletor de Data + Ações */}
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 py-3 border-b border-border/40">

          {/* Lado Esquerdo: Brand + Seletor de Unidades Dedicado */}
          <div className="flex flex-wrap items-center gap-3">
            {/* Logo / Título Principal */}
            <div className="flex items-center gap-2.5">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-primary/60 flex items-center justify-center shadow-lg shadow-primary/20 ring-2 ring-primary/20 shrink-0">
                <Car className="w-5 h-5 text-primary-foreground" />
              </div>
              <div className="flex flex-col">
                <div className="flex items-center gap-2">
                  <span className="font-extrabold text-base sm:text-lg tracking-tight bg-gradient-to-r from-foreground via-foreground/90 to-muted-foreground bg-clip-text text-transparent">
                    Controle de Faltas
                  </span>
                  <Badge variant="outline" className="hidden sm:inline-flex text-[10px] py-0 px-1.5 border-primary/30 text-primary font-bold">
                    PRO
                  </Badge>
                </div>
                <span className="text-[11px] text-muted-foreground font-medium flex items-center gap-1">
                  Gestão Operacional de Campo
                </span>
              </div>
            </div>

            {/* Separador Visual */}
            <div className="hidden sm:block h-7 w-[1px] bg-border/80 mx-1" />

            {/* Seletor Dropdown de Unidades Operacionais */}
            <div className="relative" ref={dropdownUnidadeRef}>
              <button
                type="button"
                onClick={() => {
                  setDropdownUnidadeAberto(!dropdownUnidadeAberto);
                  setDropdownDataAberto(false);
                }}
                className={cn(
                  'flex items-center gap-2 px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all duration-200 shadow-sm cursor-pointer',
                  'bg-card/90 hover:bg-card hover:border-primary/50 focus:outline-none focus:ring-2 focus:ring-primary/30',
                  dropdownUnidadeAberto ? 'border-primary ring-2 ring-primary/20 bg-primary/5' : 'border-border/80'
                )}
              >
                <div className="flex items-center gap-1.5">
                  <Building2 className="w-3.5 h-3.5 text-primary" />
                  <span className="text-muted-foreground font-normal">Unidade:</span>
                  <span className="text-foreground font-bold">{unidadeAtual.label}</span>
                </div>
                <span className={cn('w-2 h-2 rounded-full ring-2 ring-background shrink-0', unidadeAtual.dotColor)} />
                <ChevronDown
                  className={cn(
                    'w-3.5 h-3.5 text-muted-foreground transition-transform duration-200 ml-0.5',
                    dropdownUnidadeAberto && 'rotate-180 text-primary'
                  )}
                />
              </button>

              {/* Menu Dropdown de Unidades */}
              {dropdownUnidadeAberto && (
                <div className="absolute left-0 top-full mt-2 w-72 rounded-2xl border border-border bg-card/95 backdrop-blur-xl shadow-2xl p-2 z-50 animate-in fade-in zoom-in-95 duration-150">
                  <div className="px-3 py-2 text-[11px] font-bold tracking-wider uppercase text-muted-foreground border-b border-border/50 mb-1 flex items-center justify-between">
                    <span>Selecionar Unidade</span>
                    <MapPin className="w-3.5 h-3.5 text-primary" />
                  </div>
                  <div className="space-y-1">
                    {REGIONAIS.map((reg) => {
                      const isSelected = selectedRegional === reg.id;
                      return (
                        <button
                          key={reg.id}
                          type="button"
                          onClick={() => {
                            onRegionalChange(reg.id);
                            setDropdownUnidadeAberto(false);
                          }}
                          className={cn(
                            'w-full flex items-center justify-between p-2.5 rounded-xl text-left text-xs transition-all cursor-pointer',
                            isSelected
                              ? 'bg-primary/15 text-primary font-bold shadow-sm'
                              : 'hover:bg-muted/60 text-foreground'
                          )}
                        >
                          <div className="flex items-center gap-2.5">
                            <span className={cn('w-2.5 h-2.5 rounded-full ring-2 ring-background', reg.dotColor)} />
                            <div>
                              <div className="font-semibold text-xs text-foreground flex items-center gap-1.5">
                                {reg.label}
                                <span className="text-[10px] px-1.5 py-0.2 rounded bg-muted text-muted-foreground font-normal">
                                  {reg.tag}
                                </span>
                              </div>
                              <div className="text-[10px] text-muted-foreground line-clamp-1">
                                {reg.description}
                              </div>
                            </div>
                          </div>
                          {isSelected && <Check className="w-4 h-4 text-primary shrink-0 ml-2" />}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Lado Direito: Seletor de Data + Botões de Ação */}
          <div className="flex items-center justify-end gap-2.5 flex-wrap">

            {/* Seletor de Data com Espaçamento Seguro e Popover Dedicado */}
            <div className="relative" ref={dropdownDataRef}>
              <button
                type="button"
                onClick={() => {
                  setDropdownDataAberto(!dropdownDataAberto);
                  setDropdownUnidadeAberto(false);
                }}
                className={cn(
                  'flex items-center gap-2 px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all duration-200 shadow-sm cursor-pointer',
                  'bg-card/90 hover:bg-card hover:border-primary/50 focus:outline-none focus:ring-2 focus:ring-primary/30',
                  dropdownDataAberto ? 'border-primary ring-2 ring-primary/20 bg-primary/5' : 'border-border/80'
                )}
              >
                <Calendar className="w-3.5 h-3.5 text-primary" />
                <span className="text-muted-foreground font-normal hidden sm:inline">Data:</span>
                <span className="text-foreground capitalize font-bold">
                  {formatarDataExibicao(selectedDate)}
                </span>
                <ChevronDown
                  className={cn(
                    'w-3.5 h-3.5 text-muted-foreground transition-transform duration-200',
                    dropdownDataAberto && 'rotate-180 text-primary'
                  )}
                />
              </button>

              {/* Popover de Seleção de Data */}
              {dropdownDataAberto && (
                <div className="absolute right-0 top-full mt-2 w-72 rounded-2xl border border-border bg-card/95 backdrop-blur-xl shadow-2xl p-4 z-50 animate-in fade-in zoom-in-95 duration-150">
                  <div className="flex items-center justify-between pb-2 mb-3 border-b border-border/50">
                    <span className="text-xs font-bold text-foreground">Alterar Data de Operação</span>
                    <Calendar className="w-4 h-4 text-primary" />
                  </div>

                  <div className="space-y-3">
                    <div>
                      <label className="text-[11px] text-muted-foreground font-medium block mb-1">
                        Escolha o dia de trabalho:
                      </label>
                      <input
                        type="date"
                        value={
                          selectedDate instanceof Date && !isNaN(selectedDate.getTime())
                            ? selectedDate.toISOString().split('T')[0]
                            : new Date().toISOString().split('T')[0]
                        }
                        onChange={(e) => {
                          if (e.target.value) {
                            const [year, month, day] = e.target.value.split('-').map(Number);
                            const novaData = new Date(year, month - 1, day);
                            onDateChange(novaData);
                            setDropdownDataAberto(false);
                          }
                        }}
                        className="w-full h-10 px-3 text-xs bg-muted/50 border border-border rounded-xl text-foreground font-medium focus:outline-none focus:ring-2 focus:ring-primary"
                      />
                    </div>

                    <div className="flex items-center gap-2 pt-1">
                      <button
                        type="button"
                        onClick={() => {
                          onDateChange(new Date());
                          setDropdownDataAberto(false);
                        }}
                        className="flex-1 py-1.5 text-xs font-semibold rounded-lg bg-primary/10 text-primary hover:bg-primary/20 transition-colors"
                      >
                        Hoje
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          const ontem = new Date();
                          ontem.setDate(ontem.getDate() - 1);
                          onDateChange(ontem);
                          setDropdownDataAberto(false);
                        }}
                        className="flex-1 py-1.5 text-xs font-semibold rounded-lg bg-muted text-muted-foreground hover:bg-muted/80 hover:text-foreground transition-colors"
                      >
                        Ontem
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Ação Opcional de Nova Equipe se fornecida */}
            {onNovaEquipeClick && (
              <Button
                size="sm"
                onClick={onNovaEquipeClick}
                className="gap-1.5 h-8 px-3 rounded-xl bg-primary hover:bg-primary/90 text-primary-foreground text-xs font-semibold shadow-sm"
              >
                <Sparkles className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">Nova Equipe</span>
              </Button>
            )}
          </div>
        </div>

        {/* Linha Inferior: Abas de Navegação SPA */}
        <nav className="flex items-center gap-1 sm:gap-2 py-2 overflow-x-auto no-scrollbar">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => handleTabSelect(item.id)}
                className={cn(
                  'flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs sm:text-sm font-semibold transition-all whitespace-nowrap cursor-pointer',
                  isActive
                    ? 'bg-primary text-primary-foreground shadow-md shadow-primary/25 font-bold scale-[1.01]'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
                )}
              >
                <Icon className={cn('w-4 h-4', isActive ? 'text-primary-foreground' : 'text-muted-foreground')} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>
    </header>
  );
};

