import React, { useState } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement, ColaboradorCompleto } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Regional, StatusPresenca, MotivoFalta, Colaborador, Veiculo } from './types';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [colaboradoresReserva, setColaboradoresReserva] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [modalNovaEquipeAberto, setModalNovaEquipeAberto] = useState(false);

  // Atualiza status de presença ou substituição de um colaborador em um veículo
  const handleUpdateStatus = (
    veiculoId: string,
    colaboradorId: string,
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    substituto?: Colaborador
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;

        const assentos = { ...v.assentos };
        const chaves: Array<keyof typeof assentos> = ['motorista', 'frenteDir', 'trasEsq', 'trasDir'];

        chaves.forEach((chave) => {
          if (assentos[chave]?.id === colaboradorId) {
            assentos[chave] = {
              ...assentos[chave],
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              substitutoId: novoStatus === 'substituto' ? substituto?.id : undefined,
              substitutoNome: novoStatus === 'substituto' ? substituto?.nome : undefined,
            };
          }
        });

        return { ...v, assentos };
      })
    );
  };

  // Cadastro de nova equipe
  const handleCreateTeam = (dados: {
    prefixo: string;
    placa: string;
    modelo: string;
    regional: 'ribas' | 'agua_clara';
    equipe1Codigo: string;
    equipe2Codigo: string;
    colaboradores: {
      motorista: { nome: string; cargo: string; telefone: string };
      frenteDir: { nome: string; cargo: string; telefone: string };
      trasEsq: { nome: string; cargo: string; telefone: string };
      trasDir: { nome: string; cargo: string; telefone: string };
    };
  }) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: dados.prefixo,
      placa: dados.placa,
      modelo: dados.modelo,
      ano: new Date().getFullYear(),
      regional: dados.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: dados.equipe1Codigo,
      equipe2Codigo: dados.equipe2Codigo,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: dados.colaboradores.motorista.nome,
          cargo: dados.colaboradores.motorista.cargo,
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80',
          telefone: dados.colaboradores.motorista.telefone,
          status: 'presente',
          equipeId: dados.equipe1Codigo,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: dados.colaboradores.frenteDir.nome,
          cargo: dados.colaboradores.frenteDir.cargo,
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=150&auto=format&fit=crop&q=80',
          telefone: dados.colaboradores.frenteDir.telefone,
          status: 'presente',
          equipeId: dados.equipe1Codigo,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: dados.colaboradores.trasEsq.nome,
          cargo: dados.colaboradores.trasEsq.cargo,
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=150&auto=format&fit=crop&q=80',
          telefone: dados.colaboradores.trasEsq.telefone,
          status: 'presente',
          equipeId: dados.equipe2Codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: dados.colaboradores.trasDir.nome,
          cargo: dados.colaboradores.trasDir.cargo,
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=150&auto=format&fit=crop&q=80',
          telefone: dados.colaboradores.trasDir.telefone,
          status: 'presente',
          equipeId: dados.equipe2Codigo,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
    setModalNovaEquipeAberto(false);
  };

  // Importação em massa de colaboradores
  const handleImportarColaboradores = (novosColabs: ColaboradorCompleto[]) => {
    const novosReserva: Colaborador[] = novosColabs.map((c) => ({
      id: c.id,
      nome: c.nome,
      cargo: c.cargo,
      matricula: c.matricula,
      foto: c.foto,
      telefone: c.telefone,
      status: c.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    }));

    setColaboradoresReserva((prev) => [...prev, ...novosReserva]);
  };

  // Adição manual de colaborador
  const handleAdicionarColaborador = (novo: ColaboradorCompleto) => {
    const novoReserva: Colaborador = {
      id: novo.id,
      nome: novo.nome,
      cargo: novo.cargo,
      matricula: novo.matricula,
      foto: novo.foto,
      telefone: novo.telefone,
      status: novo.status,
      equipeId: 'reserva',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
    };

    setColaboradoresReserva((prev) => [novoReserva, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col antialiased">
      {/* Navbar com Seletor de Unidades e Seletor de Data independentes e sem sobreposição */}
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
      />

      {/* Conteúdo Principal */}
      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {/* Indicadores / Métricas do Topo */}
        <MetricsHeader
          veiculos={veiculos}
          selectedRegional={selectedRegional}
        />

        {/* Visão de Veículos & Presença */}
        {activeTab === 'veiculos' && (
          <VehicleCardGrid
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onUpdateStatus={handleUpdateStatus}
            colaboradoresReserva={colaboradoresReserva}
          />
        )}

        {/* Gestão de Colaboradores */}
        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            onImportarColaboradores={handleImportarColaboradores}
            onAdicionarColaborador={handleAdicionarColaborador}
          />
        )}

        {/* Gestão de Equipes */}
        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setModalNovaEquipeAberto(true)}
          />
        )}

        {/* Relatórios e Exportação */}
        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            colaboradoresReserva={colaboradoresReserva}
            selectedRegional={selectedRegional}
            selectedDate={selectedDate}
          />
        )}
      </main>

      {/* Modal de Criação de Nova Equipe */}
      {modalNovaEquipeAberto && (
        <NewTeamModal
          isOpen={modalNovaEquipeAberto}
          onClose={() => setModalNovaEquipeAberto(false)}
          onCreateTeam={handleCreateTeam}
        />
      )}
    </div>
  );
}

export default App;

