                </Badge>
                <span className="text-xs text-muted-foreground">Faltas acumuladas no mês</span>
              </div>
              <CardTitle className="text-lg font-bold text-foreground">
                Gráfico de Quem Faltou Mais
              </CardTitle>
              <CardDescription>
                Visualize colaboradores com maior índice de ausência acumulado por período e unidade.
              </CardDescription>
            </div>

            {/* Controles do Gráfico: Mês e Unidade */}
            <div className="flex flex-wrap items-center gap-2">
              {/* Seletor de Mês */}
              <select
                value={mesSelecionado}
                onChange={(e) => setMesSelecionado(Number(e.target.value))}
                className="h-9 px-3 text-xs font-semibold rounded-xl border border-border/80 bg-card/90 text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 cursor-pointer"
              >
                {MESES.map((m, idx) => (
                  <option key={m} value={idx}>
                    {m}
                  </option>
                ))}
              </select>

              {/* Seletor de Unidade para o Gráfico */}
              <div className="inline-flex rounded-xl border border-border/80 p-0.5 bg-muted/30">
                {(['todas', 'ribas', 'agua_clara'] as Regional[]).map((reg) => (
                  <button
                    key={reg}
                    type="button"
                    onClick={() => setFiltroGraficoRegional(reg)}
                    className={cn(
                      'px-2.5 py-1 text-xs font-semibold rounded-lg transition-all cursor-pointer',
                      filtroGraficoRegional === reg
                        ? 'bg-emerald-600 text-white shadow-sm'
                        : 'text-muted-foreground hover:text-foreground hover:bg-muted/40'
                    )}
                  >
                    {reg === 'todas' ? 'Todas' : reg === 'ribas' ? 'Ribas' : 'Água Clara'}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-6 space-y-5">
          {dadosGraficoFaltas.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground text-sm">
              Nenhum registro de falta no período selecionado.
            </div>
          ) : (
            <div className="space-y-4">
              {dadosGraficoFaltas.map((item, index) => {
                const percentual = Math.round((item.totalFaltas / maxFaltasMes) * 100);
                const isPrimeiroLugar = index === 0;

                return (
                  <div
                    key={`${item.nome}-${index}`}
                    className="p-3.5 rounded-xl border border-border/40 bg-card/40 hover:bg-card/70 transition-all space-y-2 group"
                  >
                    <div className="flex items-center justify-between gap-3 flex-wrap">
                      <div className="flex items-center gap-2.5">
                        <div
                          className={cn(
                            'w-7 h-7 rounded-lg flex items-center justify-center text-xs font-black shrink-0',
                            isPrimeiroLugar
                              ? 'bg-rose-500 text-white ring-2 ring-rose-500/30'
                              : index === 1
                              ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30'
                              : 'bg-muted text-muted-foreground'
                          )}
                        >
                          {index + 1}º
                        </div>
                        <div>
                          <p className="text-xs sm:text-sm font-bold text-foreground flex items-center gap-1.5">
                            {item.nome}
                            {isPrimeiroLugar && (
                              <Badge className="bg-rose-500/20 text-rose-300 border border-rose-500/40 text-[9px] py-0 px-1 font-bold">
                                Maior índice
                              </Badge>
                            )}
                          </p>
                          <p className="text-[11px] text-muted-foreground flex items-center gap-1">
                            <span>{item.cargo}</span>
                            <span>•</span>
                            <span className="text-emerald-400/90">{item.regional}</span>
                          </p>
                        </div>
                      </div>

                      <div className="text-right">
                        <span className="text-sm sm:text-base font-black text-rose-400 group-hover:scale-105 transition-transform inline-block">
                          {item.totalFaltas} {item.totalFaltas === 1 ? 'falta' : 'faltas'}
                        </span>
                        <span className="block text-[10px] text-muted-foreground">no mês de {MESES[mesSelecionado]}</span>
                      </div>
                    </div>

                    {/* Barra de Progresso Visual */}
                    <div className="w-full h-2.5 bg-muted/60 rounded-full overflow-hidden p-0.5">
                      <div
                        className={cn(
                          'h-full rounded-full transition-all duration-700',
                          isPrimeiroLugar
                            ? 'bg-gradient-to-r from-amber-500 to-rose-500'
                            : index === 1
                            ? 'bg-gradient-to-r from-amber-400 to-rose-400'
                            : 'bg-gradient-to-r from-emerald-500 to-teal-400'
                        )}
                        style={{ width: `${percentual}%` }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

