interface FaltaDoDia {
  id: string;
  nome: string;
  matricula: string;
  cargo: string;
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
  regionalNome: string;
  equipeNumero: number;
  motivoFalta: string;
  substitutoNome?: string;
  observacao?: string;
}

export const ExportReports: React.FC<ExportReportsProps> = ({
  veiculos = [],
  selectedRegional = 'todas',
  selectedDate = new Date(),
}) => {
  const [mesSelecionado, setMesSelecionado] = useState<number>(selectedDate.getMonth());
  const [filtroGraficoRegional, setFiltroGraficoRegional] = useState<Regional>(selectedRegional);
  const [downloadSucesso, setDownloadSucesso] = useState<string | null>(null);

  // Formatação da data atual para exibição e relatórios
  const dataFormatada = useMemo(() => {
    return selectedDate.toLocaleDateString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    });
  }, [selectedDate]);

  const dataNomeAmigavel = useMemo(() => {
    return selectedDate.toLocaleDateString('pt-BR', {
      weekday: 'long',
      day: '2-digit',
      month: 'long',
      year: 'numeric',
    });
  }, [selectedDate]);

  // Lista de faltas exclusivamente do dia selecionado e conforme a unidade selecionada
  const faltasDoDiaFiltradas: FaltaDoDia[] = useMemo(() => {
    const faltas: FaltaDoDia[] = [];

    (veiculos || []).forEach((veic) => {
      if (!veic) return;

      // Filtro de regional
      if (selectedRegional !== 'todas' && veic.regional !== selectedRegional) {
        return;
      }

      const regionalTexto = veic.regional === 'ribas' ? 'Ribas do Rio Pardo' : 'Água Clara';
      const assentos = [
        { colab: veic.assentos?.motorista, eq: 1 },
        { colab: veic.assentos?.frenteDir, eq: 1 },
        { colab: veic.assentos?.trasEsq, eq: 2 },
        { colab: veic.assentos?.trasDir, eq: 2 },
      ];

      assentos.forEach(({ colab, eq }) => {
        if (!colab) return;
        if (colab.status === 'falta') {
          faltas.push({
            id: colab.id,
            nome: colab.nome || 'Não informado',
            matricula: colab.matricula || 'S/N',
            cargo: colab.cargo || 'Operador',
            veiculoPrefixo: veic.prefixo || 'N/A',
            veiculoPlaca: veic.placa || 'N/A',
            regional: veic.regional,
            regionalNome: regionalTexto,
            equipeNumero: colab.equipeNumero || eq,
            motivoFalta: colab.motivoFalta || 'Falta Injustificada',
            substitutoNome: colab.substitutoNome,
            observacao: colab.observacao,
          });
        }
      });
    });

    return faltas;
  }, [veiculos, selectedRegional]);

  // Dados consolidados do gráfico: Ranking de quem mais faltou no mês selecionado
  const dadosGraficoFaltas = useMemo(() => {
    const mesObj = HISTORICO_MENSAL_FALTAS.find((m) => m.mesIndex === mesSelecionado) || HISTORICO_MENSAL_FALTAS[0];
    let lista = mesObj.faltas;

    if (filtroGraficoRegional !== 'todas') {
      lista = lista.filter((f) => f.regionalKey === filtroGraficoRegional);
    }

    // Ordena decrescente pelo número de faltas
    return [...lista].sort((a, b) => b.totalFaltas - a.totalFaltas);
  }, [mesSelecionado, filtroGraficoRegional]);

  const maxFaltasMes = useMemo(() => {
    if (!dadosGraficoFaltas.length) return 1;
    return Math.max(...dadosGraficoFaltas.map((d) => d.totalFaltas), 1);
  }, [dadosGraficoFaltas]);

  // Função para exportar EXCLUSIVAMENTE as faltas do dia filtradas em formato CSV compatível com Excel
  const exportarFaltasDoDiaCSV = () => {
    if (faltasDoDiaFiltradas.length === 0) {
      alert(`Nenhuma falta registrada no dia ${dataFormatada} para o filtro "${regionalLabel[selectedRegional]}".`);
      return;
    }

    const separador = ';';
    const cabecalho = [
      'Data',
      'Unidade',
      'Nome do Colaborador',
      'Matrícula',
      'Cargo / Função',
      'Veículo',
      'Placa',
      'Equipe',
      'Motivo da Ausência',
      'Substituto Alocado',
      'Observação',
    ].join(separador);

    const linhas = faltasDoDiaFiltradas.map((f) => {
      const escape = (str?: string) => `"${(str || '').replace(/"/g, '""')}"`;
      return [
        escape(dataFormatada),
        escape(f.regionalNome),
        escape(f.nome),
        escape(f.matricula),
        escape(f.cargo),
        escape(f.veiculoPrefixo),
        escape(f.veiculoPlaca),
        escape(`Equipe ${f.equipeNumero}`),
        escape(f.motivoFalta),
        escape(f.substitutoNome || 'Sem substituto'),
        escape(f.observacao || '-'),
      ].join(separador);
    });

    // Adiciona BOM UTF-8 (\uFEFF) para que o Excel brasileiro abra sem problemas de acentuação
    const conteudoCompleto = '\uFEFF' + [cabecalho, ...linhas].join('\r\n');
    const blob = new Blob([conteudoCompleto], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const regionalTag = selectedRegional === 'todas' ? 'TODAS_UNIDADES' : selectedRegional.toUpperCase();
    const dataSlug = dataFormatada.replace(/\//g, '-');
    link.href = url;
    link.setAttribute('download', `RELATORIO_FALTAS_${regionalTag}_${dataSlug}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setDownloadSucesso(`Arquivo gerado com sucesso! (${faltasDoDiaFiltradas.length} faltas exportadas)`);
    setTimeout(() => setDownloadSucesso(null), 4000);
  };

  // Função para imprimir/gerar PDF limpo com apenas os colaboradores faltosos
  const imprimirRelatorioFaltas = () => {
    window.print();
  };

  return (
    <div className="space-y-6">
      {/* Banner / Card Principal de Exportação de Faltas do Dia */}
      <Card className="border-border/60 bg-gradient-to-br from-card via-card/90 to-card/60 shadow-xl overflow-hidden">
