                  <UserX className="w-3.5 h-3.5 mr-1" />
                  RELATÓRIO DE FALTAS DO DIA
                </Badge>
                <Badge variant="outline" className="border-border/60 text-muted-foreground text-xs">
                  {regionalLabel[selectedRegional]}
                </Badge>
              </div>
              <h2 className="text-xl sm:text-2xl font-black text-foreground tracking-tight">
                Exportar Apenas Faltas do Dia
              </h2>
              <p className="text-xs sm:text-sm text-muted-foreground">
                Gere o arquivo consolidado contendo <strong className="text-foreground">apenas os colaboradores ausentes</strong> na data <strong className="text-foreground">{dataFormatada}</strong> ({dataNomeAmigavel}) e conforme o filtro de unidade ativo.
              </p>
            </div>

            <div className="flex flex-wrap items-center gap-2.5">
              <Button
                type="button"
                onClick={exportarFaltasDoDiaCSV}
                className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold gap-2 px-5 py-2.5 rounded-xl shadow-lg shadow-emerald-900/30 hover:scale-[1.02] transition-all cursor-pointer"
              >
                <FileSpreadsheet className="w-4 h-4" />
                Baixar Faltas (Excel / CSV)
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={imprimirRelatorioFaltas}
                className="border-border/80 hover:bg-muted/60 text-foreground font-semibold gap-2 px-4 py-2.5 rounded-xl cursor-pointer"
              >
                <Printer className="w-4 h-4" />
                Imprimir Lista
              </Button>
            </div>
          </div>

          {downloadSucesso && (
            <div className="mt-4 p-3 rounded-xl bg-emerald-500/15 border border-emerald-500/30 text-emerald-300 text-xs font-semibold flex items-center gap-2 animate-in fade-in slide-in-from-top-2 duration-300">
              <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
