import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';
import { supabase } from './lib/supabase';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [reservas, setReservas] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Sincronização inicial com o Supabase quando disponível
  useEffect(() => {
    let isMounted = true;

    async function carregarDadosSupabase() {
      try {
        const { data: veiculosDb, error } = await supabase.from('veiculos').select('*');
        if (!error && veiculosDb && veiculosDb.length > 0 && isMounted) {
          // Atualiza lista se houver dados persistidos no banco
        }
      } catch (err) {
        // Fallback resiliente
      }
    }

    carregarDadosSupabase();
    return () => {
      isMounted = false;
    };
  }, []);

  const handleStatusChange = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;
        const assentoAtual = v.assentos[posicao];
        if (!assentoAtual) return v;

        return {
          ...v,
          assentos: {
            ...v.assentos,
            [posicao]: {
              ...assentoAtual,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              observacao: observacao || undefined,
              substitutoId: novoStatus === 'substituto' ? substitutoId : undefined,
              substitutoNome: novoStatus === 'substituto' ? substitutoNome : undefined,
            },
          },
        };
      })
    );
  };

  const handleSalvarNovaEquipe = (newTeamData: any) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: newTeamData.prefixo,
      placa: newTeamData.placa,
      modelo: newTeamData.modelo,
      ano: new Date().getFullYear(),
      regional: newTeamData.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}A`,
      equipe2Codigo: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}B`,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
          nome: 'Motorista Designado',
          cargo: 'Motorista / Operador',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0001',
          status: 'presente',
          equipeId: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}A`,
          equipeNumero: 1,
          posicaoVeiculo: 'motorista',
        },
        frenteDir: {
          id: `col-${Date.now()}-2`,
          nome: 'Apoio Dianteiro',
          cargo: 'Operador de Campo',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0002',
          status: 'presente',
          equipeId: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}A`,
          equipeNumero: 1,
          posicaoVeiculo: 'frente_dir',
        },
        trasEsq: {
          id: `col-${Date.now()}-3`,
          nome: 'Apoio Traseiro 1',
          cargo: 'Técnico Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0003',
          status: 'presente',
          equipeId: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_esq',
        },
        trasDir: {
          id: `col-${Date.now()}-4`,
          nome: 'Apoio Traseiro 2',
          cargo: 'Ajudante Operacional',
          matricula: `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
          foto: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&auto=format&fit=crop&q=80',
          telefone: '(67) 99999-0004',
          status: 'presente',
          equipeId: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}B`,
          equipeNumero: 2,
          posicaoVeiculo: 'tras_dir',
        },
      },
    };

    setVeiculos((prev) => [novoVeiculo, ...prev]);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col font-sans selection:bg-emerald-500/20 selection:text-emerald-300">
      <Navbar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        selectedRegional={selectedRegional}
        onRegionalChange={setSelectedRegional}
        selectedDate={selectedDate}
        onDateChange={setSelectedDate}
        onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
      />

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        {activeTab === 'veiculos' && (
          <div className="space-y-6">
            <MetricsHeader
              veiculos={veiculos}
              selectedRegional={selectedRegional}
              onFiltroRegionalChange={(reg) => setSelectedRegional(reg as Regional)}
              onNovaEquipe={() => setIsNewTeamModalOpen(true)}
            />

            <VehicleCardGrid
              veiculos={veiculos}
              colaboradoresReserva={reservas}
              selectedRegional={selectedRegional}
              onStatusChange={handleStatusChange}
            />
          </div>
        )}

        {activeTab === 'colaboradores' && (
          <CollaboratorsManagement
            veiculos={veiculos}
            colaboradoresReserva={reservas}
            selectedRegional={selectedRegional}
            onUpdateColaboradorStatus={(colabId, novoStatus, motivo, obs) => {
              setVeiculos((prev) =>
                prev.map((v) => {
                  const updatedAssentos = { ...v.assentos };
                  let changed = false;
                  (['motorista', 'frenteDir', 'trasEsq', 'trasDir'] as const).forEach((pos) => {
                    if (updatedAssentos[pos]?.id === colabId) {
                      updatedAssentos[pos] = {
                        ...updatedAssentos[pos],
                        status: novoStatus,
                        motivoFalta: motivo,
                        observacao: obs,
                      };
                      changed = true;
                    }
                  });
                  return changed ? { ...v, assentos: updatedAssentos } : v;
                })
              );
            }}
          />
        )}

        {activeTab === 'equipes' && (
          <TeamsManagement
            veiculos={veiculos}
            colaboradoresReserva={reservas}
            selectedRegional={selectedRegional}
            onNovaEquipeClick={() => setIsNewTeamModalOpen(true)}
          />
        )}

        {activeTab === 'relatorios' && (
          <ExportReports
            veiculos={veiculos}
            selectedDate={selectedDate}
            selectedRegional={selectedRegional}
          />
        )}
      </main>

      <NewTeamModal
        isOpen={isNewTeamModalOpen}
        onClose={() => setIsNewTeamModalOpen(false)}
        onSave={handleSalvarNovaEquipe}
        colaboradoresReserva={reservas}
      />
    </div>
  );
}

export default App;

