                    </span>
                    <span className="text-muted-foreground text-[11px]">Pronto para importar</span>
                  </div>

                  <div className="max-h-48 overflow-y-auto rounded-xl border border-border/60 bg-muted/20 p-2 space-y-1 text-xs">
