import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { MetricsHeader } from './components/MetricsHeader';
import { VehicleCardGrid } from './components/VehicleCardGrid';
import { CollaboratorsManagement } from './components/CollaboratorsManagement';
import { TeamsManagement } from './components/TeamsManagement';
import { ExportReports } from './components/ExportReports';
import { NewTeamModal } from './components/NewTeamModal';
import { VEICULOS_INICIAIS, COLABORADORES_RESERVA } from './data/mockData';
import { Veiculo, Colaborador, Regional, StatusPresenca, MotivoFalta } from './types';
import { supabase } from './lib/supabase';

export function App() {
  const [activeTab, setActiveTab] = useState<'veiculos' | 'colaboradores' | 'equipes' | 'relatorios'>('veiculos');
  const [selectedRegional, setSelectedRegional] = useState<Regional>('todas');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [veiculos, setVeiculos] = useState<Veiculo[]>(VEICULOS_INICIAIS);
  const [reservas, setReservas] = useState<Colaborador[]>(COLABORADORES_RESERVA);
  const [isNewTeamModalOpen, setIsNewTeamModalOpen] = useState(false);

  // Sincronização inicial com o Supabase quando disponível
  useEffect(() => {
    let isMounted = true;

    async function carregarDadosSupabase() {
      try {
        const { data: veiculosDb, error } = await supabase.from('veiculos').select('*');
        if (!error && veiculosDb && veiculosDb.length > 0 && isMounted) {
          // Atualiza lista se houver dados persistidos no banco
        }
      } catch (err) {
        // Fallback resiliente
      }
    }

    carregarDadosSupabase();
    return () => {
      isMounted = false;
    };
  }, []);

  const handleStatusChange = (
    veiculoId: string,
    posicao: 'motorista' | 'frenteDir' | 'trasEsq' | 'trasDir',
    novoStatus: StatusPresenca,
    motivoFalta?: MotivoFalta,
    observacao?: string,
    substitutoId?: string,
    substitutoNome?: string
  ) => {
    setVeiculos((prev) =>
      prev.map((v) => {
        if (v.id !== veiculoId) return v;
        const assentoAtual = v.assentos[posicao];
        if (!assentoAtual) return v;

        return {
          ...v,
          assentos: {
            ...v.assentos,
            [posicao]: {
              ...assentoAtual,
              status: novoStatus,
              motivoFalta: novoStatus === 'falta' ? motivoFalta : undefined,
              observacao: observacao || undefined,
              substitutoId: novoStatus === 'substituto' ? substitutoId : undefined,
              substitutoNome: novoStatus === 'substituto' ? substitutoNome : undefined,
            },
          },
        };
      })
    );
  };

  const handleSalvarNovaEquipe = (newTeamData: any) => {
    const novoVeiculo: Veiculo = {
      id: `vtr-${Date.now()}`,
      prefixo: newTeamData.prefixo,
      placa: newTeamData.placa,
      modelo: newTeamData.modelo,
      ano: new Date().getFullYear(),
      regional: newTeamData.regional,
      statusOperacional: 'ativo',
      equipe1Codigo: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}A`,
      equipe2Codigo: `EQ-${newTeamData.prefixo.replace(/\D/g, '') || '01'}B`,
      assentos: {
        motorista: {
          id: `col-${Date.now()}-1`,
