                <div className="absolute left-0 sm:left-auto sm:right-0 mt-2 w-72 rounded-2xl border border-border/80 bg-popover/95 backdrop-blur-xl p-3 shadow-2xl z-50 animate-in fade-in-50 zoom-in-95">
                  <div className="px-2 py-1 text-[11px] font-semibold text-muted-foreground border-b border-border/40 mb-2">
                    Alterar Data da Escala
                  </div>
                  <div className="space-y-3">
                    <input
                      type="date"
                      value={formatarDataInput(selectedDate)}
                      onChange={handleDataChangeFromInput}
                      className="w-full h-10 px-3 rounded-xl border border-input bg-card text-xs text-foreground focus:outline-none focus:ring-2 focus:ring-emerald-500/30 cursor-pointer"
                    />
                    <div className="flex items-center gap-1.5">
                      <button
                        type="button"
                        onClick={() => {
                          onDateChange(new Date());
                          setDropdownDataAberto(false);
                        }}
                        className="flex-1 py-1.5 px-2 rounded-lg bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-300 border border-emerald-500/30 text-[11px] font-semibold transition-colors"
                      >
                        Hoje
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          const ontem = new Date();
                          ontem.setDate(ontem.getDate() - 1);
                          onDateChange(ontem);
                          setDropdownDataAberto(false);
                        }}
                        className="flex-1 py-1.5 px-2 rounded-lg bg-muted/40 hover:bg-muted/70 text-muted-foreground hover:text-foreground text-[11px] font-medium transition-colors"
                      >
                        Ontem
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Abas de Navegação */}
        <div className="flex items-center gap-1.5 overflow-x-auto py-2 no-scrollbar">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => handleTabSelect(item.id)}
                className={cn(
                  'flex items-center gap-2 px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all duration-150 cursor-pointer',
                  isActive
                    ? 'bg-emerald-500/15 text-emerald-300 border border-emerald-500/30 shadow-sm'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/40 border border-transparent'
                )}
              >
                <Icon className={cn('w-4 h-4', isActive ? 'text-emerald-400' : 'text-muted-foreground')} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </div>
      </div>
    </header>
  );
};

