import React, { useState, useMemo, useRef } from 'react';
import {
  Users,
  Search,
  Phone,
  MapPin,
  ChevronDown,
  ChevronUp,
  UserCheck,
  UserX,
  RefreshCw,
  UploadCloud,
  FileSpreadsheet,
  Download,
  CheckCircle2,
  AlertCircle,
  X,
  Plus,
  Camera,
  Trash2,
  IdCard,
  Building2,
  Briefcase,
  FileCheck,
} from 'lucide-react';
import { Card, CardContent } from './ui/card';
import { Badge } from './ui/badge';
import { Input } from './ui/input';
import { Button } from './ui/button';
import { cn } from '@/lib/utils';
import { Colaborador, Veiculo, StatusPresenca, MotivoFalta, Regional } from '../types';

export interface ColaboradorCompleto {
  id: string;
  nome: string;
  cargo: string;
  matricula: string;
  foto: string;
  telefone: string;
  status: StatusPresenca;
  motivoFalta?: MotivoFalta;
  observacao?: string;
  substitutoNome?: string;
  equipeId: string;
  equipeNumero: 1 | 2;
  posicaoVeiculo: 'motorista' | 'frente_dir' | 'tras_esq' | 'tras_dir';
  veiculoPrefixo: string;
  veiculoPlaca: string;
  regional: 'ribas' | 'agua_clara';
}

export interface CollaboratorsManagementProps {
  veiculos?: Veiculo[];
  colaboradoresReserva?: Colaborador[];
  selectedRegional?: Regional;
  onUpdateColaboradorStatus?: (
    colabId: string,
    novoStatus: StatusPresenca,
    motivo?: MotivoFalta,
    obs?: string
  ) => void;
  onImportarColaboradores?: (novosColaboradores: ColaboradorCompleto[]) => void;
  onAdicionarColaborador?: (novoColaborador: ColaboradorCompleto) => void;
}

const statusConfig: Record<StatusPresenca, { label: string; className: string }> = {
  presente: { label: 'Presente', className: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' },
  falta: { label: 'Falta', className: 'bg-rose-500/20 text-rose-400 border-rose-500/30' },
  substituto: { label: 'Substituto', className: 'bg-amber-500/20 text-amber-400 border-amber-500/30' },
};

const regionalLabel: Record<string, string> = {
  ribas: 'Ribas do Rio Pardo',
  agua_clara: 'Água Clara',
};

interface RegistroImportado {
  nome: string;
  cargo: string;
  unidade: 'ribas' | 'agua_clara';
  matricula?: string;
  telefone?: string;
}

export const CollaboratorsManagement: React.FC<CollaboratorsManagementProps> = ({
  veiculos = [],
  colaboradoresReserva = [],
  selectedRegional = 'todas',
  onUpdateColaboradorStatus,
  onImportarColaboradores,
  onAdicionarColaborador,
}) => {
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<StatusPresenca | 'todos'>('todos');
  const [filterRegional, setFilterRegional] = useState<Regional | 'todas'>(selectedRegional);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Estados do Modal de Cadastro Manual de Colaborador
  const [modalNovoColaboradorAberto, setModalNovoColaboradorAberto] = useState(false);
  const [novoNome, setNovoNome] = useState('');
  const [novoCargo, setNovoCargo] = useState('');
  const [novaMatricula, setNovaMatricula] = useState('');
  const [novoTelefone, setNovoTelefone] = useState('');
  const [novaFoto, setNovaFoto] = useState<string>('');
  const [novaUnidade, setNovaUnidade] = useState<'ribas' | 'agua_clara'>('ribas');
  const [novoStatus, setNovoStatus] = useState<StatusPresenca>('presente');
  const [formErro, setFormErro] = useState<string | null>(null);
  const fotoInputRef = useRef<HTMLInputElement>(null);

  // Estados do Modal de Importação Excel / CSV
  const [modalImportAberto, setModalImportAberto] = useState(false);
  const [arquivoNome, setArquivoNome] = useState('');
  const [registrosPrevia, setRegistrosPrevia] = useState<RegistroImportado[]>([]);
  const [erroImportacao, setErroImportacao] = useState<string | null>(null);
  const [sucessoMsg, setSucessoMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Lista de colaboradores extraídos dos veículos e lista reserva
  const colaboradoresBase: ColaboradorCompleto[] = useMemo(() => {
    const lista: ColaboradorCompleto[] = [];
    (veiculos || []).forEach((v) => {
      if (!v || !v.assentos) return;
      const assentos: Array<{ colab?: Colaborador; pos: ColaboradorCompleto['posicaoVeiculo'] }> = [
        { colab: v.assentos.motorista, pos: 'motorista' },
        { colab: v.assentos.frenteDir, pos: 'frente_dir' },
        { colab: v.assentos.trasEsq, pos: 'tras_esq' },
        { colab: v.assentos.trasDir, pos: 'tras_dir' },
      ];
      assentos.forEach(({ colab, pos }) => {
        if (!colab) return;
        lista.push({
          id: colab.id,
          nome: colab.nome || 'Sem Nome',
          cargo: colab.cargo || 'Operador',
          matricula: colab.matricula ?? '',
          foto: colab.foto ?? '',
          telefone: colab.telefone ?? '',
          status: colab.status || 'presente',
          motivoFalta: colab.motivoFalta,
          observacao: colab.observacao,
          substitutoNome: colab.substitutoNome,
          equipeId: colab.equipeId || '',
          equipeNumero: colab.equipeNumero || 1,
          posicaoVeiculo: pos,
          veiculoPrefixo: v.prefixo || '',
          veiculoPlaca: v.placa || '',
          regional: v.regional || 'ribas',
        });
      });
    });

    // Adiciona colaboradores reserva se houver
    (colaboradoresReserva || []).forEach((r, idx) => {
      if (!r) return;
      lista.push({
        id: r.id || `res-${idx}`,
        nome: r.nome || 'Colaborador Reserva',
        cargo: r.cargo || 'Reserva Operacional',
        matricula: r.matricula || '',
        foto: r.foto || '',
        telefone: r.telefone || '',
        status: r.status || 'presente',
        motivoFalta: r.motivoFalta,
        observacao: r.observacao,
        substitutoNome: r.substitutoNome,
        equipeId: 'reserva',
        equipeNumero: 1,
        posicaoVeiculo: 'motorista',
        veiculoPrefixo: 'Banco de Reserva',
        veiculoPlaca: '-',
        regional: 'ribas',
      });
    });

    return lista;
  }, [veiculos, colaboradoresReserva]);

  const [colaboradoresAdicionados, setColaboradoresAdicionados] = useState<ColaboradorCompleto[]>([]);

  const todosColaboradores = useMemo(() => {
    return [...colaboradoresBase, ...colaboradoresAdicionados];
  }, [colaboradoresBase, colaboradoresAdicionados]);

  const colaboradoresFiltrados = useMemo(() => {
    return todosColaboradores.filter((c) => {
      if (!c) return false;
      const matchSearch =
        !search ||
        (c.nome || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.cargo || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.matricula || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPlaca || '').toLowerCase().includes(search.toLowerCase()) ||
        (c.veiculoPrefixo || '').toLowerCase().includes(search.toLowerCase());

      const matchStatus = filterStatus === 'todos' || c.status === filterStatus;
      const matchRegional = filterRegional === 'todas' || c.regional === filterRegional;

      return matchSearch && matchStatus && matchRegional;
    });
  }, [todosColaboradores, search, filterStatus, filterRegional]);

  const stats = useMemo(() => {
    const presentes = todosColaboradores.filter((c) => c.status === 'presente').length;
    const faltas = todosColaboradores.filter((c) => c.status === 'falta').length;
    const substitutos = todosColaboradores.filter((c) => c.status === 'substituto').length;
    return { presentes, faltas, substitutos, total: todosColaboradores.length };
  }, [todosColaboradores]);

  const handleFotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setFormErro('Por favor, selecione um arquivo de imagem válido (PNG, JPG, JPEG, WEBP).');
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setFormErro('A imagem selecionada deve ter no máximo 5MB.');
      return;
    }

    setFormErro(null);
    const reader = new FileReader();
    reader.onload = (event) => {
      if (event.target?.result) {
        setNovaFoto(event.target.result as string);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleRemoverFoto = () => {
    setNovaFoto('');
    if (fotoInputRef.current) {
      fotoInputRef.current.value = '';
    }
  };

  const handleCriarColaborador = (e: React.FormEvent) => {
    e.preventDefault();
    if (!novoNome.trim()) {
      setFormErro('O nome do colaborador é obrigatório.');
      return;
    }
    if (!novoCargo.trim()) {
      setFormErro('O cargo do colaborador é obrigatório.');
      return;
    }

    const novoItem: ColaboradorCompleto = {
      id: `colab-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      nome: novoNome.trim(),
      cargo: novoCargo.trim(),
      matricula: novaMatricula.trim() || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      telefone: novoTelefone.trim() || '(67) 99999-0000',
      foto: novaFoto || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
      status: novoStatus,
      regional: novaUnidade,
      equipeId: 'banco',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Banco Operacional',
      veiculoPlaca: 'BNC-0000',
    };

    setColaboradoresAdicionados((prev) => [novoItem, ...prev]);
    onAdicionarColaborador?.(novoItem);

    setNovoNome('');
    setNovoCargo('');
    setNovaMatricula('');
    setNovoTelefone('');
    setNovaFoto('');
    setFormErro(null);
    setModalNovoColaboradorAberto(false);
  };

  const parsePlanilhaLinhas = (conteudoTexto: string): RegistroImportado[] => {
    const linhas = conteudoTexto.split(/\r?\n/).map((l) => l.trim()).filter((l) => l.length > 0);
    if (linhas.length < 2) return [];

    const delimitador = linhas[0].includes(';') ? ';' : linhas[0].includes('\t') ? '\t' : ',';
    const cabecalho = linhas[0].split(delimitador).map((c) => c.replace(/["']/g, '').trim().toLowerCase());

    const idxNome = cabecalho.findIndex((c) => c.includes('nome') || c.includes('colaborador'));
    const idxCargo = cabecalho.findIndex((c) => c.includes('cargo') || c.includes('funcao') || c.includes('função'));
    const idxUnidade = cabecalho.findIndex((c) => c.includes('unidade') || c.includes('regional') || c.includes('polo'));
    const idxMatricula = cabecalho.findIndex((c) => c.includes('matricula') || c.includes('matrícula') || c.includes('id'));
    const idxTelefone = cabecalho.findIndex((c) => c.includes('telefone') || c.includes('celular') || c.includes('contato'));

    const lista: RegistroImportado[] = [];

    for (let i = 1; i < linhas.length; i++) {
      const colunas = linhas[i].split(delimitador).map((c) => c.replace(/["']/g, '').trim());
      if (colunas.length === 0 || !colunas[0]) continue;

      const nome = idxNome >= 0 ? colunas[idxNome] : colunas[0];
      const cargo = idxCargo >= 0 ? colunas[idxCargo] : (colunas[1] || 'Operador Florestal');
      const unidadeBruta = (idxUnidade >= 0 ? colunas[idxUnidade] : (colunas[2] || 'Ribas')).toLowerCase();
      const matricula = idxMatricula >= 0 ? colunas[idxMatricula] : undefined;
      const telefone = idxTelefone >= 0 ? colunas[idxTelefone] : undefined;

      if (!nome) continue;

      const unidadeFinal: 'ribas' | 'agua_clara' =
        unidadeBruta.includes('agua') || unidadeBruta.includes('água') || unidadeBruta.includes('clara')
          ? 'agua_clara'
          : 'ribas';

      lista.push({
        nome,
        cargo: cargo || 'Operador Florestal',
        unidade: unidadeFinal,
        matricula: matricula || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
        telefone: telefone || '(67) 99999-0000',
      });
    }

    return lista;
  };

  const handleArquivoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErroImportacao(null);
    setSucessoMsg(null);
    setArquivoNome(file.name);

    const extensao = file.name.split('.').pop()?.toLowerCase();
    if (extensao !== 'csv' && extensao !== 'txt' && extensao !== 'tsv') {
      setErroImportacao('Por gentileza, salve a planilha como arquivo (.CSV separado por vírgula ou ponto-e-vírgula) para processamento instantâneo.');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const conteudo = event.target?.result as string;
        const registros = parsePlanilhaLinhas(conteudo);

        if (registros.length === 0) {
          setErroImportacao('Nenhum registro legível foi encontrado. Verifique se o arquivo possui colunas: Nome, Função/Cargo, Unidade.');
          setRegistrosPrevia([]);
          return;
        }

        setRegistrosPrevia(registros);
      } catch {
        setErroImportacao('Erro ao ler os dados do arquivo selecionado.');
      }
    };
    reader.onerror = () => {
      setErroImportacao('Não foi possível ler o arquivo.');
    };
    reader.readAsText(file);
  };

  const handleConfirmarImportacao = () => {
    if (registrosPrevia.length === 0) return;

    const novos: ColaboradorCompleto[] = registrosPrevia.map((reg, idx) => ({
      id: `import-${Date.now()}-${idx}`,
      nome: reg.nome,
      cargo: reg.cargo,
      matricula: reg.matricula || `MAT-${Math.floor(1000 + Math.random() * 9000)}`,
      telefone: reg.telefone || '(67) 99999-0000',
      foto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
      status: 'presente',
      regional: reg.unidade,
      equipeId: 'planilha',
      equipeNumero: 1,
      posicaoVeiculo: 'motorista',
      veiculoPrefixo: 'Importado',
      veiculoPlaca: 'IMP-0000',
    }));

    setColaboradoresAdicionados((prev) => [...novos, ...prev]);
    onImportarColaboradores?.(novos);

    setSucessoMsg(`${novos.length} colaboradores foram importados com sucesso!`);
    setRegistrosPrevia([]);
    setArquivoNome('');
    setTimeout(() => {
      setModalImportAberto(false);
      setSucessoMsg(null);
    }, 1500);
  };

  const baixarModeloCSV = () => {
    const csvContent = 'Nome,Cargo,Unidade,Matricula,Telefone\n' +
      'Carlos Eduardo Santos,Mecânico Florestal,Ribas do Rio Pardo,MAT-1029,(67) 99841-2233\n' +
      'Lucas Gabriel Costa,Motorista de Apoio,Água Clara,MAT-1044,(67) 99755-4411\n' +
      'Pedro Henrique Silva,Ajudante Geral,Ribas do Rio Pardo,MAT-2033,(67) 99612-8822\n';

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', 'modelo_importacao_colaboradores.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6">
      {/* Barra de Topo com Estatísticas e Botões de Ação */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <Users className="w-5 h-5 text-emerald-400" />
            Quadro Geral de Colaboradores
          </h2>
          <p className="text-xs text-muted-foreground mt-0.5">
            Gerencie operadores, status diário, dados cadastrais e importação em lote
          </p>
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setModalImportAberto(true)}
            className="flex-1 sm:flex-none border-border/80 hover:bg-emerald-500/10 hover:border-emerald-500/40 text-xs font-semibold gap-1.5"
          >
            <UploadCloud className="w-4 h-4 text-emerald-400" />
            Subir Planilha Excel
          </Button>

          <Button
            size="sm"
            onClick={() => setModalNovoColaboradorAberto(true)}
            className="flex-1 sm:flex-none bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold gap-1.5 shadow-md"
          >
            <Plus className="w-4 h-4" />
            Novo Colaborador
          </Button>
        </div>
